/// Encode the strict single-token Q6_K x Q8_K GEMV used by Gemma 4's tied
/// head. `scalar` carries `n_superblocks` at byte 0 and `rows` at byte 4.
/// `weight_offset` permits a file-backed, page-aligned Metal buffer window to
/// expose a tensor that starts after the beginning of that window.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_q6k_ordered_single(
    encoder: &metal::ComputeCommandEncoderRef,
    kernel: &MetalLinearKernel,
    input_scales: &Buffer,
    input_quants: &Buffer,
    weight: &Buffer,
    weight_offset: u64,
    output: &Buffer,
    _scalar: &Buffer,
    n_superblocks: usize,
    rows: usize,
    input_scales_offset: u64,
    input_quants_offset: u64,
    output_offset: u64,
) {
    let turbo_pipeline = (!std::env::var("CAMELID_GEMMA4_GHOST_METAL_TURBO")
        .is_ok_and(|v| v == "0" || v.eq_ignore_ascii_case("false")))
    .then(|| admitted_32_lane_pipeline(kernel.q6k_linear_turbo_pipeline.as_ref()))
    .flatten();
    encoder
        .set_compute_pipeline_state(turbo_pipeline.unwrap_or(&kernel.q6k_linear_ordered_pipeline));
    encoder.set_buffer(0, Some(input_scales), input_scales_offset);
    encoder.set_buffer(1, Some(input_quants), input_quants_offset);
    encoder.set_buffer(2, Some(weight), weight_offset);
    encoder.set_buffer(3, Some(output), output_offset);
    let n_sb_u32 = n_superblocks as u32;
    let rows_u32 = rows as u32;
    encoder.set_bytes(4, 4, &n_sb_u32 as *const u32 as *const _);
    encoder.set_bytes(5, 4, &rows_u32 as *const u32 as *const _);
    if turbo_pipeline.is_some() {
        dispatch_q6k_turbo_rows(encoder, rows);
        return;
    }
    let scratch_bytes = (n_superblocks * 8 * std::mem::size_of::<i32>()).next_multiple_of(16);
    assert_threadgroup_fits(
        &kernel.device,
        scratch_bytes,
        "ordered Gemma 4 Q6_K tied-head scratch",
    );
    encoder.set_threadgroup_memory_length(0, scratch_bytes as u64);
    encoder.dispatch_thread_groups(
        metal::MTLSize {
            width: rows as u64,
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: 32,
            height: 1,
            depth: 1,
        },
    );
}

/// [`encode_q6k_ordered_batch`] with byte offsets into the batch-major
/// scales/quants/logits buffers, so a K>8 chunk can run as slabs of <=8 rows
/// through the SAME batch pipelines the K<=8 path uses (identical per-row
/// arithmetic flavor). Callers guarantee `k_batch <= 8`.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_q6k_ordered_batch_at(
    encoder: &metal::ComputeCommandEncoderRef,
    kernel: &MetalLinearKernel,
    input_scales: &Buffer,
    input_scales_offset: u64,
    input_quants: &Buffer,
    input_quants_offset: u64,
    weight: &Buffer,
    weight_offset: u64,
    output: &Buffer,
    output_offset: u64,
    scalar: &Buffer,
    n_superblocks: usize,
    rows: usize,
    k_batch: usize,
    hidden: usize,
    softcap: f32,
) {
    debug_assert!((1..=8).contains(&k_batch));
    let specialized_k8 = (k_batch == 8 && !head_k8_generic())
        .then_some(kernel.q6k_linear_turbo_batch_k8_pipeline.as_ref())
        .flatten();
    let is_specialized_k8 = specialized_k8.is_some();
    let turbo_batch_pipeline = (!std::env::var("CAMELID_GEMMA4_GHOST_METAL_TURBO")
        .is_ok_and(|v| v == "0" || v.eq_ignore_ascii_case("false")))
    .then(|| {
        specialized_k8.or_else(|| {
            admitted_32_lane_pipeline(kernel.q6k_linear_turbo_batch_k_pipeline.as_ref())
        })
    })
    .flatten();
    let _ = hidden;
    let _ = scalar;
    if let Some(pipeline) = turbo_batch_pipeline {
        encoder.set_compute_pipeline_state(pipeline);
        encoder.set_buffer(0, Some(input_scales), input_scales_offset);
        encoder.set_buffer(1, Some(input_quants), input_quants_offset);
        encoder.set_buffer(2, Some(weight), weight_offset);
        encoder.set_buffer(3, Some(output), output_offset);
        let n_sb_u32 = n_superblocks as u32;
        let rows_u32 = rows as u32;
        let k_u32 = k_batch as u32;
        let softcap_f32 = softcap;
        encoder.set_bytes(4, 4, &n_sb_u32 as *const u32 as *const _);
        encoder.set_bytes(5, 4, &rows_u32 as *const u32 as *const _);
        encoder.set_bytes(6, 4, &k_u32 as *const u32 as *const _);
        encoder.set_bytes(7, 4, &softcap_f32 as *const f32 as *const _);
        if is_specialized_k8 {
            encoder.dispatch_thread_groups(
                metal::MTLSize {
                    width: rows.div_ceil(4) as u64,
                    height: 1,
                    depth: 1,
                },
                metal::MTLSize {
                    width: 128,
                    height: 1,
                    depth: 1,
                },
            );
        } else {
            dispatch_q6k_turbo_rows(encoder, rows);
        }
        return;
    }
    if let Some(pipeline) = kernel.q6k_linear_ordered_batch_k_pipeline.as_ref() {
        encoder.set_compute_pipeline_state(pipeline);
        encoder.set_buffer(0, Some(input_scales), input_scales_offset);
        encoder.set_buffer(1, Some(input_quants), input_quants_offset);
        encoder.set_buffer(2, Some(weight), weight_offset);
        encoder.set_buffer(3, Some(output), output_offset);
        let n_sb_u32 = n_superblocks as u32;
        let rows_u32 = rows as u32;
        let k_u32 = k_batch as u32;
        let softcap_f32 = softcap;
        encoder.set_bytes(4, 4, &n_sb_u32 as *const u32 as *const _);
        encoder.set_bytes(5, 4, &rows_u32 as *const u32 as *const _);
        encoder.set_bytes(6, 4, &k_u32 as *const u32 as *const _);
        encoder.set_bytes(7, 4, &softcap_f32 as *const f32 as *const _);
        let scratch_bytes =
            (k_batch * n_superblocks * 8 * std::mem::size_of::<i32>()).next_multiple_of(16);
        assert_threadgroup_fits(
            &kernel.device,
            scratch_bytes,
            "ordered Gemma 4 Q6_K tile-once head scratch",
        );
        encoder.set_threadgroup_memory_length(0, scratch_bytes as u64);
        encoder.dispatch_thread_groups(
            metal::MTLSize {
                width: rows as u64,
                height: 1,
                depth: 1,
            },
            metal::MTLSize {
                width: 32,
                height: 1,
                depth: 1,
            },
        );
    }
}

/// Encode K candidate Q6_K GEMVs. Prefers a tile-once kernel that matches the
/// same per-token reduction `encode_q6k_ordered_single` / `forward()` uses
/// (turbo simd_sum when that lane is live, otherwise ordered lane-zero fold).
/// Falls back to K serial GEMVs in this command buffer if the batch pipeline
/// is missing or K>8.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_q6k_ordered_batch(
    encoder: &metal::ComputeCommandEncoderRef,
    kernel: &MetalLinearKernel,
    input_scales: &Buffer,
    input_quants: &Buffer,
    weight: &Buffer,
    weight_offset: u64,
    output: &Buffer,
    scalar: &Buffer,
    n_superblocks: usize,
    rows: usize,
    k_batch: usize,
    hidden: usize,
    softcap: f32,
) {
    if k_batch == 1 {
        encode_q6k_ordered_single(
            encoder,
            kernel,
            input_scales,
            input_quants,
            weight,
            weight_offset,
            output,
            scalar,
            n_superblocks,
            rows,
            0,
            0,
            0,
        );
        return;
    }
    if k_batch <= 8 {
        // The K=8 specialization uses one vocab row per simdgroup, while every
        // other width (and the K=1 kernel) uses four rows per simdgroup. That is
        // a different reduction shape, so a row's logits can differ between a
        // K=8 round and a K=1 round — which would break the speculative stream's
        // equality with the greedy stream at K=8 only. Set
        // CAMELID_GEMMA4_HEAD_K8_GENERIC=1 to route K=8 through the same
        // four-row kernel as every other width.
        let specialized_k8 = (k_batch == 8 && !head_k8_generic())
            .then_some(kernel.q6k_linear_turbo_batch_k8_pipeline.as_ref())
            .flatten();
        let is_specialized_k8 = specialized_k8.is_some();
        let turbo_batch_pipeline = (!std::env::var("CAMELID_GEMMA4_GHOST_METAL_TURBO")
            .is_ok_and(|v| v == "0" || v.eq_ignore_ascii_case("false")))
        .then(|| {
            specialized_k8.or_else(|| {
                admitted_32_lane_pipeline(kernel.q6k_linear_turbo_batch_k_pipeline.as_ref())
            })
        })
        .flatten();
        if let Some(pipeline) = turbo_batch_pipeline {
            encoder.set_compute_pipeline_state(pipeline);
            encoder.set_buffer(0, Some(input_scales), 0);
            encoder.set_buffer(1, Some(input_quants), 0);
            encoder.set_buffer(2, Some(weight), weight_offset);
            encoder.set_buffer(3, Some(output), 0);
            let n_sb_u32 = n_superblocks as u32;
            let rows_u32 = rows as u32;
            let k_u32 = k_batch as u32;
            let softcap_f32 = softcap;
            encoder.set_bytes(4, 4, &n_sb_u32 as *const u32 as *const _);
            encoder.set_bytes(5, 4, &rows_u32 as *const u32 as *const _);
            encoder.set_bytes(6, 4, &k_u32 as *const u32 as *const _);
            encoder.set_bytes(7, 4, &softcap_f32 as *const f32 as *const _);
            if is_specialized_k8 {
                encoder.dispatch_thread_groups(
                    metal::MTLSize {
                        width: rows.div_ceil(4) as u64,
                        height: 1,
                        depth: 1,
                    },
                    metal::MTLSize {
                        width: 128,
                        height: 1,
                        depth: 1,
                    },
                );
            } else {
                dispatch_q6k_turbo_rows(encoder, rows);
            }
            return;
        }
        if let Some(pipeline) = kernel.q6k_linear_ordered_batch_k_pipeline.as_ref() {
            encoder.set_compute_pipeline_state(pipeline);
            encoder.set_buffer(0, Some(input_scales), 0);
            encoder.set_buffer(1, Some(input_quants), 0);
            encoder.set_buffer(2, Some(weight), weight_offset);
            encoder.set_buffer(3, Some(output), 0);
            let n_sb_u32 = n_superblocks as u32;
            let rows_u32 = rows as u32;
            let k_u32 = k_batch as u32;
            let softcap_f32 = softcap;
            encoder.set_bytes(4, 4, &n_sb_u32 as *const u32 as *const _);
            encoder.set_bytes(5, 4, &rows_u32 as *const u32 as *const _);
            encoder.set_bytes(6, 4, &k_u32 as *const u32 as *const _);
            encoder.set_bytes(7, 4, &softcap_f32 as *const f32 as *const _);
            let scratch_bytes =
                (k_batch * n_superblocks * 8 * std::mem::size_of::<i32>()).next_multiple_of(16);
            assert_threadgroup_fits(
                &kernel.device,
                scratch_bytes,
                "ordered Gemma 4 Q6_K tile-once head scratch",
            );
            encoder.set_threadgroup_memory_length(0, scratch_bytes as u64);
            encoder.dispatch_thread_groups(
                metal::MTLSize {
                    width: rows as u64,
                    height: 1,
                    depth: 1,
                },
                metal::MTLSize {
                    width: 32,
                    height: 1,
                    depth: 1,
                },
            );
            return;
        }
    }
    // K > 8: two slabs through the SAME batch kernels the K<=8 path uses.
    // The serial per-token fallback ran q6k_linear_turbo (the single-token
    // kernel), whose accumulation flavor measurably diverges from the batch
    // kernels (415/2048 rows, worst 512 ULP) and flips near-tied argmaxes
    // against the reference stream (measured: chunk widths 9..16 emitted 9430
    // where every width <= 8 and the llama.cpp oracle emit 2717). Slabbing
    // keeps every row on the batch flavor, which spec50's harness proved
    // mutually bitwise-consistent across batch_k / batch_k8 / spec50 for
    // every K in 1..=8, so per-row numerics are now chunk-width-independent.
    let mut done = 0usize;
    while done < k_batch {
        let slab = (k_batch - done).min(8);
        let scales_off = (done * n_superblocks * std::mem::size_of::<f32>()) as u64;
        let quants_off = (done * hidden) as u64;
        let logits_off = (done * rows * std::mem::size_of::<f32>()) as u64;
        encode_q6k_ordered_batch_at(
            encoder,
            kernel,
            input_scales,
            scales_off,
            input_quants,
            quants_off,
            weight,
            weight_offset,
            output,
            logits_off,
            scalar,
            n_superblocks,
            rows,
            slab,
            hidden,
            softcap,
        );
        done += slab;
    }
}
#[cfg(target_os = "macos")]
fn encode_q6k_batch_k(
    encoder: &metal::ComputeCommandEncoderRef,
    kernel: &MetalLinearKernel,
    input_scales: &Buffer,
    input_quants: &Buffer,
    weight_blocks: &Buffer,
    weight_offset: u64,
    output: &Buffer,
    scalar_buf: &Buffer,
    _n_sb: usize,
    rows: usize,
    _k_batch: usize,
) {
    if let Some(pipeline) = &kernel.q6k_linear_batch_k_pipeline {
        encoder.set_compute_pipeline_state(pipeline);
        encoder.set_buffer(0, Some(input_scales), 0);
        encoder.set_buffer(1, Some(input_quants), 0);
        encoder.set_buffer(2, Some(weight_blocks), weight_offset);
        encoder.set_buffer(3, Some(output), 0);
        encoder.set_buffer(4, Some(scalar_buf), 0);
        encoder.set_buffer(5, Some(scalar_buf), 4);
        encoder.set_buffer(6, Some(scalar_buf), 8);
        let thread_groups = metal::MTLSize {
            width: (rows as u64).div_ceil(16),
            height: 1,
            depth: 1,
        };
        let threads_per_group = metal::MTLSize {
            width: 128,
            height: 1,
            depth: 1,
        };
        encoder.dispatch_thread_groups(thread_groups, threads_per_group);
    }
}

/// NVFP4 wire GEMV on the GPU (GABBRO M3) — the NVFP4 counterpart of
/// [`try_gemma4_q4_0_matmul_f32y`]. `weight_wire` is `rows * blocks_per_row`
/// 36-byte NVFP4 superblocks; `y` is `blocks_per_row * 64` f32 activations (the
/// superblock is 64 values, unlike the 32-value Q8_0/Q4_0 blocks). Returns `rows`
/// f32 outputs (f32 activation × inline-decoded NVFP4 weight). For validating the
/// NVFP4 GPU kernel against the CPU `nvfp4_wire_block_dequant` reference.
#[cfg(target_os = "macos")]
pub fn try_gemma4_nvfp4_matmul_f32y(
    y: &[f32],
    weight_wire: &[u8],
    rows: usize,
    blocks_per_row: usize,
) -> Option<Vec<f32>> {
    const WIRE: usize = 36;
    // The NVFP4 superblock is 64 values (block_elements), not 32 — the single
    // point where an NVFP4 row's activation stride differs from Q8_0/Q4_0.
    if rows == 0
        || blocks_per_row == 0
        || y.len() != blocks_per_row * GemmaWireFmt::Nvfp4.block_elements()
        || weight_wire.len() != rows * blocks_per_row * WIRE
    {
        return None;
    }
    let k = metal_linear_kernel()?;
    let y_buf = k.device.new_buffer(
        std::mem::size_of_val(y) as u64,
        MTLResourceOptions::StorageModeShared,
    );
    let w_buf = k.device.new_buffer(
        weight_wire.len() as u64,
        MTLResourceOptions::StorageModeShared,
    );
    let out_buf = k
        .device
        .new_buffer((rows * 4) as u64, MTLResourceOptions::StorageModeShared);
    let scalar_buf = k
        .device
        .new_buffer(8, MTLResourceOptions::StorageModeShared);
    write_buffer_f32(&y_buf, y);
    write_buffer_u8(&w_buf, weight_wire);
    unsafe {
        let p = scalar_buf.contents() as *mut u32;
        *p = blocks_per_row as u32;
        *p.add(1) = rows as u32;
    }
    let cb = k.queue.new_command_buffer();
    let e = cb.new_compute_command_encoder();
    encode_gemma4_nvfp4_matmul(e, k, &y_buf, &w_buf, &out_buf, &scalar_buf, rows);
    e.end_encoding();
    cb.commit();
    cb.wait_until_completed();
    let mut out = vec![0.0f32; rows];
    read_buffer_f32(&out_buf, &mut out);
    Some(out)
}

/// Standalone gemma4 FFN sub-block: builds buffers, runs the whole
/// [`encode_gemma4_ffn`] chain in one command buffer, reads back the hidden output.
/// `gate`/`up` are `ffn_dim` rows over `hidden` in; `down` is `hidden` rows over
/// `ffn_dim` in; weights are row-major 34-byte Q8 wire blocks. For validating the
/// FFN sub-graph against CPU. None if Metal unavailable or shapes are invalid.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
pub fn try_gemma4_ffn(
    fmt: GemmaWireFmt,
    h_in: &[f32],
    ffn_norm: &[f32],
    post_ffw_norm: &[f32],
    eps: f32,
    gate_wire: &[u8],
    up_wire: &[u8],
    down_wire: &[u8],
    ffn_dim: usize,
) -> Option<Vec<f32>> {
    let wire: usize = fmt.wire_bytes();
    let hidden = h_in.len();
    if hidden == 0
        || ffn_dim == 0
        || !hidden.is_multiple_of(32)
        || !ffn_dim.is_multiple_of(32)
        || ffn_norm.len() != hidden
        || post_ffw_norm.len() != hidden
    {
        return None;
    }
    let bpr_hidden = hidden / 32;
    let bpr_ffn = ffn_dim / 32;
    if gate_wire.len() != ffn_dim * bpr_hidden * wire
        || up_wire.len() != ffn_dim * bpr_hidden * wire
        || down_wire.len() != hidden * bpr_ffn * wire
    {
        return None;
    }
    let k = metal_linear_kernel()?;
    let mkbuf = |bytes: usize| {
        k.device
            .new_buffer(bytes as u64, MTLResourceOptions::StorageModeShared)
    };
    let in_buf = mkbuf(hidden * 4);
    let out_buf = mkbuf(hidden * 4);
    let gate_buf = mkbuf(gate_wire.len());
    let up_buf = mkbuf(up_wire.len());
    let down_buf = mkbuf(down_wire.len());
    write_buffer_f32(&in_buf, h_in);
    write_buffer_u8(&gate_buf, gate_wire);
    write_buffer_u8(&up_buf, up_wire);
    write_buffer_u8(&down_buf, down_wire);
    let mut keep = Vec::new();
    let cb = k.queue.new_command_buffer();
    let e = cb.new_compute_command_encoder();
    encode_gemma4_ffn(
        fmt,
        e,
        k,
        &mut keep,
        &in_buf,
        &out_buf,
        ffn_norm,
        post_ffw_norm,
        eps,
        &gate_buf,
        &up_buf,
        &down_buf,
        ffn_dim,
    );
    e.end_encoding();
    cb.commit();
    cb.wait_until_completed();
    let mut out = vec![0.0f32; hidden];
    read_buffer_f32(&out_buf, &mut out);
    drop(keep);
    Some(out)
}

/// Standalone gemma4 attention sub-block: builds buffers (incl. a caller-prefilled
/// KV cache laid out `[kv_head][max_positions][head_dim]`), runs the whole
/// [`encode_gemma4_attention`] chain in one command buffer, reads back the hidden
/// output. For validating the attention sub-graph against CPU. The current token's
/// K/V are scattered into the cache at `write_position`; attention covers the window
/// `[window_start .. filled)`. None if Metal unavailable or shapes invalid.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
pub fn try_gemma4_attention(
    fmt: GemmaWireFmt,
    h_in: &[f32],
    attn_norm: &[f32],
    q_norm: &[f32],
    k_norm: &[f32],
    post_attn_norm: &[f32],
    eps: f32,
    q_wire: &[u8],
    k_wire: &[u8],
    v_wire: Option<&[u8]>,
    o_wire: &[u8],
    cos_t: &[f32],
    sin_t: &[f32],
    cache_k_init: &[f32],
    cache_v_init: &[f32],
    max_positions: usize,
    write_position: usize,
    n_heads: usize,
    n_kv_heads: usize,
    head_dim: usize,
    filled: usize,
    window_start: usize,
    scale: f32,
    owns_kv: bool,
) -> Option<Vec<f32>> {
    let wire = fmt.wire_bytes();
    let hidden = h_in.len();
    let q_dim = n_heads * head_dim;
    let kv_dim = n_kv_heads * head_dim;
    let cache_len = n_kv_heads * max_positions * head_dim;
    if hidden == 0
        || !hidden.is_multiple_of(32)
        || !head_dim.is_multiple_of(2)
        || n_kv_heads == 0
        || !n_heads.is_multiple_of(n_kv_heads)
        || attn_norm.len() != hidden
        || post_attn_norm.len() != hidden
        || q_norm.len() != head_dim
        || k_norm.len() != head_dim
        || cos_t.len() != head_dim / 2
        || sin_t.len() != head_dim / 2
        || write_position >= filled
        || filled > max_positions
        || window_start >= filled
        || cache_k_init.len() != cache_len
        || cache_v_init.len() != cache_len
    {
        return None;
    }
    let bpr_hidden = hidden / 32;
    let bpr_q = q_dim / 32;
    if q_wire.len() != q_dim * bpr_hidden * wire
        || k_wire.len() != kv_dim * bpr_hidden * wire
        || v_wire.is_some_and(|w| w.len() != kv_dim * bpr_hidden * wire)
        || o_wire.len() != hidden * bpr_q * wire
    {
        return None;
    }
    let k = metal_linear_kernel()?;
    let mkbuf = |bytes: usize| {
        k.device
            .new_buffer(bytes as u64, MTLResourceOptions::StorageModeShared)
    };
    let in_buf = mkbuf(hidden * 4);
    let out_buf = mkbuf(hidden * 4);
    let q_buf = mkbuf(q_wire.len());
    let kw_buf = mkbuf(k_wire.len());
    let vw_buf = v_wire.map(|w| mkbuf(w.len()));
    let o_buf = mkbuf(o_wire.len());
    let cache_k = mkbuf(cache_len * 4);
    let cache_v = mkbuf(cache_len * 4);
    write_buffer_f32(&in_buf, h_in);
    write_buffer_u8(&q_buf, q_wire);
    write_buffer_u8(&kw_buf, k_wire);
    if let (Some(buf), Some(wire)) = (&vw_buf, v_wire) {
        write_buffer_u8(buf, wire);
    }
    write_buffer_u8(&o_buf, o_wire);
    write_buffer_f32(&cache_k, cache_k_init);
    write_buffer_f32(&cache_v, cache_v_init);
    let mut keep = Vec::new();
    let cb = k.queue.new_command_buffer();
    let e = cb.new_compute_command_encoder();
    encode_gemma4_attention(
        fmt,
        e,
        k,
        &mut keep,
        &in_buf,
        &out_buf,
        attn_norm,
        q_norm,
        k_norm,
        post_attn_norm,
        eps,
        &q_buf,
        &kw_buf,
        vw_buf.as_ref(),
        &o_buf,
        cos_t,
        sin_t,
        &cache_k,
        &cache_v,
        max_positions,
        write_position,
        n_heads,
        n_kv_heads,
        head_dim,
        filled,
        window_start,
        scale,
        owns_kv,
    );
    e.end_encoding();
    cb.commit();
    cb.wait_until_completed();
    let mut out = vec![0.0f32; hidden];
    read_buffer_f32(&out_buf, &mut out);
    drop(keep);
    Some(out)
}

/// Standalone gemma4 PLE per-layer injection: builds buffers, runs
/// [`encode_gemma4_ple`] in one command buffer, reads back the updated hidden.
/// `pli_l` is this layer's per-token Per-Layer-Embedding input (CPU-computed);
/// `ple_inp_gate` (output-major `[ple_dim][hidden]`) and `ple_proj`
/// (`[hidden][ple_dim]`) are the f32 PLE matrices. None if Metal unavailable or
/// shapes invalid.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
pub fn try_gemma4_ple(
    h_in: &[f32],
    pli_l: &[f32],
    ple_inp_gate: &[f32],
    ple_proj: &[f32],
    post_norm: &[f32],
    output_scale: f32,
    eps: f32,
    ple_dim: usize,
) -> Option<Vec<f32>> {
    let hidden = h_in.len();
    if hidden == 0
        || ple_dim == 0
        || pli_l.len() != ple_dim
        || ple_inp_gate.len() != ple_dim * hidden
        || ple_proj.len() != hidden * ple_dim
        || post_norm.len() != hidden
    {
        return None;
    }
    let k = metal_linear_kernel()?;
    let mkf = |v: &[f32]| {
        let b = k
            .device
            .new_buffer((v.len() * 4) as u64, MTLResourceOptions::StorageModeShared);
        write_buffer_f32(&b, v);
        b
    };
    let h_buf = mkf(h_in);
    let pli_buf = mkf(pli_l);
    let ig = mkf(ple_inp_gate);
    let pj = mkf(ple_proj);
    let pn = mkf(post_norm);
    let mut keep = Vec::new();
    let cb = k.queue.new_command_buffer();
    let e = cb.new_compute_command_encoder();
    encode_gemma4_ple(
        e,
        k,
        &mut keep,
        &h_buf,
        &pli_buf,
        0,
        &ig,
        &pj,
        &pn,
        output_scale,
        eps,
        hidden,
        ple_dim,
    );
    e.end_encoding();
    cb.commit();
    cb.wait_until_completed();
    let mut out = vec![0.0f32; hidden];
    read_buffer_f32(&h_buf, &mut out);
    drop(keep);
    Some(out)
}

/// Standalone gemma4 per-token `pli` on the GPU (the folded
/// [`encode_gemma4_pli`] path). Takes the RAW gemma tensors and folds the constants
/// internally. `proj` is `[ple_total][hidden]` (per_layer_model_proj), `proj_norm`
/// is `[ple_dim]`, `ti` is the `[ple_total]` per_layer_token_embd row for the token.
/// Returns `pli` `[ple_total]`. For validating the GPU pli vs the CPU prep.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
pub fn try_gemma4_pli(
    h0: &[f32],
    proj: &[f32],
    proj_norm: &[f32],
    ti: &[f32],
    hidden: usize,
    ple_dim: usize,
    n_layers: usize,
    eps: f32,
) -> Option<Vec<f32>> {
    let ple_total = n_layers * ple_dim;
    if h0.len() != hidden
        || proj.len() != ple_total * hidden
        || proj_norm.len() != ple_dim
        || ti.len() != ple_total
    {
        return None;
    }
    let frac = std::f32::consts::FRAC_1_SQRT_2;
    let proj_scale = (hidden as f32).powf(-0.5);
    let embed_scale = (ple_dim as f32).sqrt();
    // Fold the constants into the resident inputs.
    let proj_folded: Vec<f32> = proj.iter().map(|v| v * proj_scale).collect();
    let projnorm_folded: Vec<f32> = proj_norm.iter().map(|v| v * frac).collect();
    let ti_folded: Vec<f32> = ti.iter().map(|v| v * embed_scale * frac).collect();
    let k = metal_linear_kernel()?;
    let mkf = |v: &[f32]| {
        let b = k
            .device
            .new_buffer((v.len() * 4) as u64, MTLResourceOptions::StorageModeShared);
        write_buffer_f32(&b, v);
        b
    };
    let h0_buf = mkf(h0);
    let proj_buf = mkf(&proj_folded);
    let projnorm_buf = mkf(&projnorm_folded);
    let ti_buf = mkf(&ti_folded);
    let z = vec![0.0f32; ple_total];
    let ctx_buf = mkf(&z);
    let ctx_n_buf = mkf(&z);
    let pli_buf = mkf(&z);
    let mut keep = Vec::new();
    let cb = k.queue.new_command_buffer();
    let e = cb.new_compute_command_encoder();
    encode_gemma4_pli(
        e,
        k,
        &mut keep,
        &h0_buf,
        &proj_buf,
        &projnorm_buf,
        &ti_buf,
        &ctx_buf,
        &ctx_n_buf,
        &pli_buf,
        hidden,
        ple_total,
        ple_dim,
        n_layers,
        eps,
    );
    e.end_encoding();
    cb.commit();
    cb.wait_until_completed();
    let mut out = vec![0.0f32; ple_total];
    read_buffer_f32(&pli_buf, &mut out);
    Some(out)
}

/// Standalone gemma4 logits head: builds buffers, runs [`encode_gemma4_head`] in one
/// command buffer, reads back the `vocab` soft-capped logits. `token_embd_wire` is
/// the vocab-major Q8 embedding table in 34-byte wire blocks (`vocab * hidden/32`
/// blocks). None if Metal unavailable or shapes invalid.
#[cfg(target_os = "macos")]
pub fn try_gemma4_head(
    h_in: &[f32],
    output_norm: &[f32],
    token_embd_wire: &[u8],
    vocab: usize,
    softcap: f32,
    eps: f32,
) -> Option<Vec<f32>> {
    const WIRE: usize = 34;
    let hidden = h_in.len();
    if hidden == 0 || !hidden.is_multiple_of(32) || vocab == 0 || output_norm.len() != hidden {
        return None;
    }
    let bpr_hidden = hidden / 32;
    if token_embd_wire.len() != vocab * bpr_hidden * WIRE {
        return None;
    }
    let k = metal_linear_kernel()?;
    let h_buf = k
        .device
        .new_buffer((hidden * 4) as u64, MTLResourceOptions::StorageModeShared);
    let logits_buf = k
        .device
        .new_buffer((vocab * 4) as u64, MTLResourceOptions::StorageModeShared);
    let embd_buf = k.device.new_buffer(
        token_embd_wire.len() as u64,
        MTLResourceOptions::StorageModeShared,
    );
    write_buffer_f32(&h_buf, h_in);
    write_buffer_u8(&embd_buf, token_embd_wire);
    let mut keep = Vec::new();
    let cb = k.queue.new_command_buffer();
    let e = cb.new_compute_command_encoder();
    encode_gemma4_head(
        e,
        k,
        &mut keep,
        &h_buf,
        &logits_buf,
        output_norm,
        &embd_buf,
        vocab,
        softcap,
        eps,
    );
    e.end_encoding();
    cb.commit();
    cb.wait_until_completed();
    let mut out = vec![0.0f32; vocab];
    read_buffer_f32(&logits_buf, &mut out);
    drop(keep);
    Some(out)
}

/// Persistent no-copy Metal tied head for Gemma 4 QAT models whose embedding /
/// output table is Q6_K. The 26B Ghost-MoE artifact carries a 605 MB Q6_K tied
/// table; evaluating it on the CPU streams those bytes once per generated token.
/// This wrapper maps the GGUF tensor's file-backed pages directly into a Metal
/// buffer and keeps its activation/logit scratch resident. The parity-sensitive,
/// tiny stages stay on the CPU (2.8K-element RMSNorm + Q8_K quantization before
/// dispatch, scalar soft-cap after readback); the 605 MB ordered Q6_K GEMV runs
/// on Metal in one command buffer and is bit-exact with the CPU row-dot oracle.
///
/// The mapping is retained for the lifetime of the Metal buffer. There is no
/// anonymous 605 MB weight copy: under memory pressure these pages remain clean,
/// file-backed, and evictable. Calls are serialized because the scratch buffers
/// are reused in place; the serving runtime is single-request today, but keeping
/// that invariant here prevents accidental cross-request races later.
#[cfg(target_os = "macos")]
pub(crate) static GPU_HW_US: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
#[cfg(target_os = "macos")]
pub(crate) static KERNEL_HW_US: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

#[cfg(target_os = "macos")]
pub(crate) struct Gemma4Q6KHead {
    inner: Mutex<Gemma4Q6KHeadInner>,
    _mmap: std::sync::Arc<crate::wire_mmap::GgufWireMmap>,
    weight_window_aligned_offset: usize,
    weight_window_bytes: usize,
    weight_file_backed_no_copy: bool,
}

#[cfg(target_os = "macos")]
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub(crate) struct Gemma4Q6KHeadLoadLedger {
    pub(crate) wire_payload_bytes: u64,
    pub(crate) page_window_bytes: u64,
    pub(crate) scratch_capacity_bytes: u64,
    pub(crate) scratch_explicitly_touched_bytes: u64,
}

#[cfg(target_os = "macos")]
struct Gemma4Q6KHeadInner {
    weight: Buffer,
    weight_offset: usize,
    q8k_scales: Buffer,
    q8k_quants: Buffer,
    logits: Buffer,
    matmul_scalar: Buffer,
    q8k_scales_batch: Buffer,
    q8k_quants_batch: Buffer,
    logits_batch: Buffer,
    activation_perm: Buffer,
    batch_matmul_scalar: Buffer,
    out_id: Buffer,
    count_buf: Buffer,
    argmax_ids_batch: Buffer,
    argmax_vals_batch: Buffer,
    output_norm: Vec<f32>,
    eps: f32,
    hidden: usize,
    vocab: usize,
    softcap: f32,
}

#[cfg(target_os = "macos")]
impl Gemma4Q6KHead {
    /// Borrow the no-copy Q6_K token table for the opt-in MTP device chain.
    ///
    /// This refuses every geometry except the exact Gemma 4 26B-A4B target and
    /// keeps the head mutex (and therefore the mmap-owning `self`) borrowed for
    /// the complete callback. The callback must complete its Metal command
    /// buffer before returning; the view is not an ownership-transfer API.
    pub(crate) fn with_mtp_target_embedding<R>(
        &self,
        use_view: impl for<'view> FnOnce(Gemma4MtpTargetEmbeddingView<'view>) -> R,
    ) -> Option<R> {
        const TARGET_HIDDEN: usize = 2_816;
        const TARGET_VOCAB: usize = 262_144;
        const Q6K_VALUES: usize = 256;
        const Q6K_WIRE: usize = 210;

        let state = self.inner.lock().ok()?;
        if !self.weight_file_backed_no_copy
            || state.hidden != TARGET_HIDDEN
            || state.vocab != TARGET_VOCAB
            || !state.hidden.is_multiple_of(Q6K_VALUES)
        {
            return None;
        }
        let byte_len = state
            .vocab
            .checked_mul(state.hidden / Q6K_VALUES)?
            .checked_mul(Q6K_WIRE)?;
        let byte_end = state.weight_offset.checked_add(byte_len)?;
        if !state
            .weight_offset
            .is_multiple_of(std::mem::align_of::<u16>())
            || byte_end > usize::try_from(state.weight.length()).ok()?
        {
            return None;
        }
        Some(use_view(Gemma4MtpTargetEmbeddingView {
            buffer: &state.weight,
            byte_offset: state.weight_offset,
            byte_len,
            hidden: state.hidden,
            vocab: state.vocab,
            format: Gemma4MtpTargetEmbeddingFormat::Q6K,
        }))
    }

    /// Wrap one vocab-major Q6_K tensor in the existing GGUF mmap. `absolute_offset`
    /// and `byte_len` come from its descriptor. Returns `None` on unavailable Metal,
    /// an invalid tensor shape/range, or a device buffer-size limit smaller than the
    /// tensor. The caller then keeps the established CPU head as a safe fallback.
    #[allow(clippy::too_many_arguments)]
    pub(crate) fn new(
        mmap: std::sync::Arc<crate::wire_mmap::GgufWireMmap>,
        absolute_offset: u64,
        byte_len: usize,
        output_norm: &[f32],
        vocab: usize,
        softcap: f32,
        eps: f32,
    ) -> Option<Self> {
        // Default: file-backed no-copy. A resident copy of the 605 MB table
        // competes with the expert-slot slab. Production retains its existing
        // explicit opt-in; the observed load-only constructor below always
        // overrides this to no-copy.
        let resident_head = std::env::var("CAMELID_GEMMA4_GHOST_METAL_HEAD_RESIDENT")
            .is_ok_and(|value| value == "1" || value.eq_ignore_ascii_case("true"));
        Self::new_inner(
            mmap,
            absolute_offset,
            byte_len,
            output_norm,
            vocab,
            softcap,
            eps,
            resident_head,
        )
        .map(|(head, _)| head)
    }

    /// Construct a fail-closed file-backed head for the load-only residency
    /// probe, ignoring the ambient resident-copy opt-in.
    #[allow(clippy::too_many_arguments)]
    pub(crate) fn new_file_backed(
        mmap: std::sync::Arc<crate::wire_mmap::GgufWireMmap>,
        absolute_offset: u64,
        byte_len: usize,
        output_norm: &[f32],
        vocab: usize,
        softcap: f32,
        eps: f32,
    ) -> Option<(Self, Gemma4Q6KHeadLoadLedger)> {
        Self::new_inner(
            mmap,
            absolute_offset,
            byte_len,
            output_norm,
            vocab,
            softcap,
            eps,
            false,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn new_inner(
        mmap: std::sync::Arc<crate::wire_mmap::GgufWireMmap>,
        absolute_offset: u64,
        byte_len: usize,
        output_norm: &[f32],
        vocab: usize,
        softcap: f32,
        eps: f32,
        resident_head: bool,
    ) -> Option<(Self, Gemma4Q6KHeadLoadLedger)> {
        const Q6K_VALUES: usize = 256;
        const Q6K_WIRE: usize = 210;
        let hidden = output_norm.len();
        if hidden == 0
            || vocab == 0
            || !hidden.is_multiple_of(Q6K_VALUES)
            || byte_len
                != vocab
                    .checked_mul(hidden / Q6K_VALUES)?
                    .checked_mul(Q6K_WIRE)?
        {
            return None;
        }

        let kernel = metal_linear_kernel()?;
        let tensor = crate::wire_mmap::wire_mmap_tensors(
            &mmap,
            &[(absolute_offset, byte_len)],
            kernel.device.max_buffer_length() as usize,
        )
        .ok()?
        .pop()?;
        // SAFETY: `wire_mmap_tensors` returns a page-aligned window entirely
        // inside `mmap`, which this struct retains for the buffer's lifetime.
        let weight_ptr = unsafe { mmap.base_ptr().add(tensor.window.aligned_offset as usize) };
        let weight = if resident_head {
            let owned = kernel.device.new_buffer(
                tensor.window.len as u64,
                MTLResourceOptions::StorageModeShared,
            );
            // SAFETY: source window is `len` readable bytes inside the mmap;
            // destination is a fresh shared buffer of exactly `len` bytes.
            unsafe {
                std::ptr::copy_nonoverlapping(
                    weight_ptr,
                    owned.contents().cast::<u8>(),
                    tensor.window.len as usize,
                );
            }
            owned
        } else {
            kernel.device.new_buffer_with_bytes_no_copy(
                weight_ptr.cast(),
                tensor.window.len as u64,
                MTLResourceOptions::StorageModeShared,
                None,
            )
        };
        let shared = |bytes: usize| {
            kernel
                .device
                .new_buffer(bytes as u64, MTLResourceOptions::StorageModeShared)
        };
        let n_superblocks = hidden / Q6K_VALUES;
        let q8k_scales = shared(n_superblocks * std::mem::size_of::<f32>());
        let q8k_quants = shared(hidden);
        let logits = shared(vocab * std::mem::size_of::<f32>());
        let matmul_scalar = shared(12);
        let out_id = shared(std::mem::size_of::<u32>());
        let count_buf = shared(std::mem::size_of::<u32>());
        unsafe {
            let m = matmul_scalar.contents() as *mut u32;
            *m = n_superblocks as u32;
            *m.add(1) = vocab as u32;
            *m.add(2) = 1;
            *(count_buf.contents() as *mut u32) = vocab as u32;
        }
        let max_k = 16;
        let q8k_scales_batch = shared(max_k * n_superblocks * std::mem::size_of::<f32>());
        let q8k_quants_batch = shared(max_k * hidden);
        let logits_batch = shared(max_k * vocab * std::mem::size_of::<f32>());
        let argmax_ids_batch = shared(max_k * std::mem::size_of::<u32>());
        let argmax_vals_batch = shared(max_k * std::mem::size_of::<f32>());
        // Coalescing repack of the Q8_K activation quants for the spec50 head
        // kernel. The head was activation-access bound, not weight-bandwidth
        // bound: at K=8 the strided int8 fetch cost more than the 605 MB weight
        // stream. This scratch holds the permuted copy the kernel reads.
        let activation_perm = shared(spec50_activation_scratch_bytes(max_k, hidden));
        let batch_matmul_scalar = shared(16);
        unsafe {
            let bm = batch_matmul_scalar.contents() as *mut u32;
            *bm = n_superblocks as u32;
            *bm.add(1) = vocab as u32;
            *bm.add(2) = 1;
        }
        let scratch_capacity_bytes = [
            &q8k_scales,
            &q8k_quants,
            &logits,
            &matmul_scalar,
            &q8k_scales_batch,
            &q8k_quants_batch,
            &logits_batch,
            &activation_perm,
            &batch_matmul_scalar,
            &out_id,
            &count_buf,
            &argmax_ids_batch,
            &argmax_vals_batch,
        ]
        .into_iter()
        .map(|buffer| buffer.length())
        .sum();
        let ledger = Gemma4Q6KHeadLoadLedger {
            wire_payload_bytes: byte_len as u64,
            page_window_bytes: tensor.window.len as u64,
            scratch_capacity_bytes,
            // matmul_scalar (12), count (4), and the first three words of the
            // 16-byte batch scalar are initialized during construction.
            scratch_explicitly_touched_bytes: 12 + 4 + 12,
        };
        Some((
            Self {
                inner: Mutex::new(Gemma4Q6KHeadInner {
                    weight,
                    weight_offset: tensor.window_offset,
                    q8k_scales,
                    q8k_quants,
                    logits,
                    matmul_scalar,
                    q8k_scales_batch,
                    q8k_quants_batch,
                    logits_batch,
                    activation_perm,
                    batch_matmul_scalar,
                    out_id,
                    count_buf,
                    argmax_ids_batch,
                    argmax_vals_batch,
                    output_norm: output_norm.to_vec(),
                    eps,
                    hidden,
                    vocab,
                    softcap,
                }),
                _mmap: mmap,
                weight_window_aligned_offset: tensor.window.aligned_offset as usize,
                weight_window_bytes: tensor.window.len as usize,
                weight_file_backed_no_copy: !resident_head,
            },
            ledger,
        ))
    }

    /// Fault only the aligned tied-head window, one volatile byte per page,
    /// then return its non-faulting range-residency snapshot.
    pub(crate) fn fault_weight_pages(
        &self,
    ) -> crate::Result<crate::wire_mmap::WireMmapResidencySnapshot> {
        self._mmap
            .fault_pages_range(self.weight_window_aligned_offset, self.weight_window_bytes)?;
        self.weight_residency_snapshot()
    }

    pub(crate) fn weight_residency_snapshot(
        &self,
    ) -> crate::Result<crate::wire_mmap::WireMmapResidencySnapshot> {
        self._mmap
            .residency_snapshot_range(self.weight_window_aligned_offset, self.weight_window_bytes)
    }

    /// Evaluate the final hidden state through the tied head. `None` is a soft
    /// failure: callers preserve the CPU implementation as the correctness path.
    pub(crate) fn forward(&self, hidden: &[f32]) -> Option<Vec<f32>> {
        let state = self.inner.lock().ok()?;
        if hidden.len() != state.hidden {
            return None;
        }
        let kernel = metal_linear_kernel()?;
        // Keep the 2.8K-element norm on the CPU: its established scalar
        // left-fold is the Gemma 4 parity oracle, whereas a tree-reduced GPU
        // norm can move Q8_K scales by one ULP and flip a near-tied argmax.
        // The 605 MB Q6_K projection remains entirely on Metal.
        let normalized =
            crate::gemma4_runtime::rms_norm(hidden, Some(&state.output_norm), state.eps);
        // The strict Metal quantizer reproduces every Q8_K integer code, but its
        // reciprocal can still differ by one ULP from Rust on Apple GPUs. Upload
        // the CPU-oracle activation instead (11 scales + 2816 bytes on the 26B
        // row) so exact ties retain the CPU greedy choice. The 605 MB projection
        // itself remains entirely on Metal.
        let q8 = crate::inference::quantize_q8_k_blocks(&normalized);
        let scales: Vec<f32> = q8.iter().map(|block| block.d).collect();
        let mut quants = Vec::with_capacity(state.hidden);
        for block in &q8 {
            quants.extend_from_slice(&block.qs);
        }
        write_buffer_f32(&state.q8k_scales, &scales);
        unsafe {
            std::ptr::copy_nonoverlapping(
                quants.as_ptr(),
                state.q8k_quants.contents().cast::<i8>(),
                quants.len(),
            );
        }
        let started = std::time::Instant::now();
        let cb = kernel.queue.new_command_buffer();
        let encoder = cb.new_compute_command_encoder();
        let n_superblocks = state.hidden / 256;
        encode_q6k_ordered_single(
            encoder,
            kernel,
            &state.q8k_scales,
            &state.q8k_quants,
            &state.weight,
            state.weight_offset as u64,
            &state.logits,
            &state.matmul_scalar,
            n_superblocks,
            state.vocab,
            0,
            0,
            0,
        );
        encoder.end_encoding();
        cb.commit();
        cb.wait_until_completed();
        if cb.status() != metal::MTLCommandBufferStatus::Completed {
            return None;
        }

        if std::env::var("CAMELID_GEMMA4_METAL_HEAD_TIMING")
            .is_ok_and(|value| value == "1" || value.eq_ignore_ascii_case("true"))
        {
            let (gpu_us, kernel_us) = command_buffer_gpu_times_us(cb);
            eprintln!(
                "[gemma4-metal-head] Q6_K vocab={} wall={}us gpu={}us kernel={}us",
                state.vocab,
                started.elapsed().as_micros(),
                gpu_us,
                kernel_us,
            );
        }
        {
            use std::sync::atomic::Ordering::Relaxed;
            let (gpu_us, _) = command_buffer_gpu_times_us(cb);
            HEAD_WALL_US.fetch_add(started.elapsed().as_micros() as u64, Relaxed);
            HEAD_GPU_US.fetch_add(gpu_us as u64, Relaxed);
            HEAD_CALLS.fetch_add(1, Relaxed);
            HEAD_ROWS.fetch_add(1, Relaxed);
        }
        let mut output = vec![0.0f32; state.vocab];
        read_buffer_f32(&state.logits, &mut output);
        // Rust's scalar tanh is the established Gemma 4 oracle. Metal's tanh
        // differs by a few ULP and can alter the lowest-index tie-break after
        // saturation, even when the pre-cap Q6_K projection agrees. This 1 MB
        // elementwise tail is tiny beside the 605 MB matrix sweep.
        if state.softcap.is_finite() && state.softcap > 0.0 {
            crate::inference::gemma4::soft_cap_in_place(&mut output, state.softcap);
        }
        Some(output)
    }

    /// Batched evaluation of K candidate rows through the Q6_K tied head in ONE single GPU command buffer.
    pub(crate) fn forward_batch(&self, hidden_rows: &[Vec<f32>]) -> Option<Vec<Vec<f32>>> {
        let k = hidden_rows.len();
        if k == 0 || k > 16 {
            return None;
        }
        if k == 1 {
            return self.forward(&hidden_rows[0]).map(|l| vec![l]);
        }
        use rayon::prelude::*;
        let state = self.inner.lock().ok()?;
        let kernel = metal_linear_kernel()?;
        let n_superblocks = state.hidden / 256;
        let hidden = state.hidden;
        let eps = state.eps;
        let output_norm = &state.output_norm;
        let scales_raw = state.q8k_scales_batch.contents() as usize;
        let quants_raw = state.q8k_quants_batch.contents() as usize;
        let t_all = std::time::Instant::now();

        hidden_rows.par_iter().enumerate().for_each(|(i, h)| {
            let normalized = crate::gemma4_runtime::rms_norm(h, Some(output_norm), eps);
            let q8 = crate::inference::quantize_q8_k_blocks(&normalized);
            let scales_offset = i * n_superblocks * std::mem::size_of::<f32>();
            let quants_offset = i * hidden;
            unsafe {
                let s_dst = (scales_raw + scales_offset) as *mut f32;
                for (sb, block) in q8.iter().enumerate() {
                    *s_dst.add(sb) = block.d;
                }
                let q_dst = (quants_raw + quants_offset) as *mut i8;
                for (sb, block) in q8.iter().enumerate() {
                    std::ptr::copy_nonoverlapping(block.qs.as_ptr(), q_dst.add(sb * 256), 256);
                }
            }
        });
        let quant_us = t_all.elapsed().as_micros();

        let cb = kernel.queue.new_command_buffer();
        let encoder = cb.new_compute_command_encoder();
        let vocab = state.vocab;
        // Tile-once when a batch kernel exists that preserves `forward()`'s
        // per-token fold; otherwise K serial GEMVs in this same command buffer.
        encode_q6k_ordered_batch(
            encoder,
            kernel,
            &state.q8k_scales_batch,
            &state.q8k_quants_batch,
            &state.weight,
            state.weight_offset as u64,
            &state.logits_batch,
            &state.batch_matmul_scalar,
            n_superblocks,
            vocab,
            k,
            hidden,
            state.softcap,
        );
        encoder.end_encoding();
        cb.commit();
        cb.wait_until_completed();
        if cb.status() != metal::MTLCommandBufferStatus::Completed {
            return None;
        }
        let after_gpu = t_all.elapsed().as_micros();
        let (gpu_us, kernel_us) = command_buffer_gpu_times_us(cb);

        let logits_ptr = state.logits_batch.contents() as usize;
        let mut results: Vec<Vec<f32>> = (0..k)
            .map(|_| {
                let mut row = Vec::with_capacity(vocab);
                // SAFETY: immediately overwritten from the mapped slab.
                unsafe {
                    row.set_len(vocab);
                }
                row
            })
            .collect();
        results
            .par_iter_mut()
            .enumerate()
            .for_each(|(i, row)| unsafe {
                std::ptr::copy_nonoverlapping(
                    (logits_ptr as *const f32).add(i * vocab),
                    row.as_mut_ptr(),
                    vocab,
                );
            });
        if std::env::var("CAMELID_GEMMA4_METAL_HEAD_TIMING")
            .is_ok_and(|value| value == "1" || value.eq_ignore_ascii_case("true"))
        {
            eprintln!(
                "[gemma4-metal-head] K={} vocab={} quant={}us gpu_wait={}us gpu={}us kernel={}us copy_softcap={}us wall={}us",
                k,
                vocab,
                quant_us,
                after_gpu.saturating_sub(quant_us),
                gpu_us,
                kernel_us,
                t_all.elapsed().as_micros().saturating_sub(after_gpu),
                t_all.elapsed().as_micros(),
            );
        }
        Some(results)
    }

    /// Batched speculative evaluation: runs Q6_K tied head for K rows,
    /// performs in-place argmax on the mapped shared logits buffer to evaluate
    /// against `drafts`, and copies ONLY row `j` (the accepted/divergent step) to CPU memory.
    pub(crate) fn forward_batch_speculative(
        &self,
        hidden_rows: &[Vec<f32>],
        drafts: &[u32],
    ) -> Option<(usize, Vec<f32>)> {
        let k = hidden_rows.len();
        if k == 0 || k > 16 {
            return None;
        }
        if k == 1 {
            let logit = self.forward(&hidden_rows[0])?;
            return Some((0, logit));
        }
        let t_head = std::time::Instant::now();
        use rayon::prelude::*;
        let state = self.inner.lock().ok()?;
        let kernel = metal_linear_kernel()?;
        let n_superblocks = state.hidden / 256;
        let hidden = state.hidden;
        let eps = state.eps;
        let output_norm = &state.output_norm;
        let scales_raw = state.q8k_scales_batch.contents() as usize;
        let quants_raw = state.q8k_quants_batch.contents() as usize;

        hidden_rows.par_iter().enumerate().for_each(|(i, h)| {
            let normalized = crate::gemma4_runtime::rms_norm(h, Some(output_norm), eps);
            let q8 = crate::inference::quantize_q8_k_blocks(&normalized);
            let scales_offset = i * n_superblocks * std::mem::size_of::<f32>();
            let quants_offset = i * hidden;
            unsafe {
                let s_dst = (scales_raw + scales_offset) as *mut f32;
                for (sb, block) in q8.iter().enumerate() {
                    *s_dst.add(sb) = block.d;
                }
                let q_dst = (quants_raw + quants_offset) as *mut i8;
                for (sb, block) in q8.iter().enumerate() {
                    std::ptr::copy_nonoverlapping(block.qs.as_ptr(), q_dst.add(sb * 256), 256);
                }
            }
        });

        let cb = kernel.queue.new_command_buffer();
        let encoder = cb.new_compute_command_encoder();
        let vocab = state.vocab;
        // The spec50 kernel is asserted bitwise identical to encode_q6k_ordered_batch
        // for every K in 1..=8 (see spec50_batch_is_bitwise_identical_to_reference),
        // so this swap changes timing only, never a token. It falls back on its own
        // when its pipelines are unavailable. Reached only for k >= 2; k == 1
        // delegates to forward() above and keeps the single-token kernel, which has
        // its own (fma-contraction) numerics that we deliberately do not disturb here.
        // spec50's k<=8 table is bitwise-proven against the batch reference;
        // the k>8 wide table was anchored to the single-token kernel's flavor
        // (which diverges from the oracle stream on near-ties). Wide chunks
        // therefore run as one canonical K8 tile plus a canonical K<=8 tail,
        // matching encode_q6k_ordered_batch's target-authoritative slabs while
        // retaining spec50's faster tied-head projection.
        let head_kernels = spec50_head_kernels();
        let used_spec50 = !head_spec50_disabled()
            && head_kernels.is_some_and(|kernels| {
                if k <= 8 {
                    encode_q6k_spec50_batch(
                        encoder,
                        kernels,
                        &state.q8k_scales_batch,
                        &state.q8k_quants_batch,
                        &state.activation_perm,
                        &state.weight,
                        state.weight_offset as u64,
                        &state.logits_batch,
                        n_superblocks,
                        vocab,
                        k,
                        hidden,
                        state.softcap,
                    )
                } else {
                    encode_q6k_spec50_batch_tiled(
                        encoder,
                        kernels,
                        &state.q8k_scales_batch,
                        &state.q8k_quants_batch,
                        &state.activation_perm,
                        &state.weight,
                        state.weight_offset as u64,
                        &state.logits_batch,
                        n_superblocks,
                        vocab,
                        k,
                        hidden,
                        state.softcap,
                    )
                }
            });
        if !used_spec50 {
            encode_q6k_ordered_batch(
                encoder,
                kernel,
                &state.q8k_scales_batch,
                &state.q8k_quants_batch,
                &state.weight,
                state.weight_offset as u64,
                &state.logits_batch,
                &state.batch_matmul_scalar,
                n_superblocks,
                vocab,
                k,
                hidden,
                state.softcap,
            );
        }
        let used_gpu_argmax = !head_gpu_argmax_disabled()
            && head_kernels.is_some_and(|kernels| {
                encode_q6k_spec50_argmax(
                    encoder,
                    kernels,
                    &state.logits_batch,
                    &state.argmax_ids_batch,
                    &state.argmax_vals_batch,
                    vocab,
                    k,
                );
                true
            });
        encoder.end_encoding();
        cb.commit();
        cb.wait_until_completed();
        if cb.status() != metal::MTLCommandBufferStatus::Completed {
            return None;
        }

        {
            use std::sync::atomic::Ordering::Relaxed;
            let (gpu_us, kernel_us) = command_buffer_gpu_times_us(cb);
            HEAD_WALL_US.fetch_add(t_head.elapsed().as_micros() as u64, Relaxed);
            HEAD_GPU_US.fetch_add(gpu_us as u64, Relaxed);
            HEAD_CALLS.fetch_add(1, Relaxed);
            HEAD_ROWS.fetch_add(k as u64, Relaxed);
            if std::env::var("CAMELID_GEMMA4_METAL_HEAD_TIMING")
                .is_ok_and(|value| value == "1" || value.eq_ignore_ascii_case("true"))
            {
                eprintln!(
                    "[gemma4-metal-head] speculative K={k} vocab={vocab} gpu={gpu_us}us kernel={kernel_us}us"
                );
            }
        }
        let logits_ptr = state.logits_batch.contents() as *const f32;
        let argmax_ids = used_gpu_argmax.then(|| unsafe {
            std::slice::from_raw_parts(state.argmax_ids_batch.contents().cast::<u32>(), k)
        });
        let mut accepted_j = drafts.len();
        for (i, &draft_tok) in drafts.iter().enumerate() {
            let best_tok = if let Some(ids) = argmax_ids {
                ids[i]
            } else {
                let row_ptr = unsafe { logits_ptr.add(i * vocab) };
                let slice = unsafe { std::slice::from_raw_parts(row_ptr, vocab) };
                let mut best_tok = 0u32;
                let mut best_val = slice[0];
                for (v_idx, &v) in slice.iter().enumerate() {
                    if v > best_val {
                        best_val = v;
                        best_tok = v_idx as u32;
                    }
                }
                best_tok
            };
            if best_tok != draft_tok {
                accepted_j = i;
                break;
            }
        }

        let mut next_logits = Vec::with_capacity(vocab);
        unsafe {
            next_logits.set_len(vocab);
            std::ptr::copy_nonoverlapping(
                logits_ptr.add(accepted_j * vocab),
                next_logits.as_mut_ptr(),
                vocab,
            );
        }
        Some((accepted_j, next_logits))
    }

    /// Direct GPU argmax reduction: runs Q6_K projection and argmax in a single
    /// command buffer and reads back only the 4-byte token ID.
    pub(crate) fn forward_argmax(&self, hidden: &[f32]) -> Option<u32> {
        let state = self.inner.lock().ok()?;
        if hidden.len() != state.hidden {
            return None;
        }
        let kernel = metal_linear_kernel()?;
        let normalized =
            crate::gemma4_runtime::rms_norm(hidden, Some(&state.output_norm), state.eps);
        let q8 = crate::inference::quantize_q8_k_blocks(&normalized);
        let scales: Vec<f32> = q8.iter().map(|block| block.d).collect();
        let mut quants = Vec::with_capacity(state.hidden);
        for block in &q8 {
            quants.extend_from_slice(&block.qs);
        }
        write_buffer_f32(&state.q8k_scales, &scales);
        unsafe {
            std::ptr::copy_nonoverlapping(
                quants.as_ptr(),
                state.q8k_quants.contents().cast::<i8>(),
                quants.len(),
            );
        }
        let cb = kernel.queue.new_command_buffer();
        let encoder = cb.new_compute_command_encoder();
        let n_superblocks = state.hidden / 256;
        encode_q6k_ordered_single(
            encoder,
            kernel,
            &state.q8k_scales,
            &state.q8k_quants,
            &state.weight,
            state.weight_offset as u64,
            &state.logits,
            &state.matmul_scalar,
            n_superblocks,
            state.vocab,
            0,
            0,
            0,
        );

        encoder.set_compute_pipeline_state(&kernel.argmax_f32_greedy_pipeline);
        encoder.set_buffer(0, Some(&state.logits), 0);
        encoder.set_buffer(1, Some(&state.out_id), 0);
        encoder.set_buffer(2, Some(&state.count_buf), 0);
        encoder.dispatch_thread_groups(
            metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
            metal::MTLSize {
                width: 1024,
                height: 1,
                depth: 1,
            },
        );

        encoder.end_encoding();
        cb.commit();
        cb.wait_until_completed();
        if cb.status() != metal::MTLCommandBufferStatus::Completed {
            return None;
        }

        let next_tok = unsafe { *(state.out_id.contents() as *const u32) };
        Some(next_tok)
    }
}

/// A resident gemma4 model ready to decode: all weights (layers + tied `token_embd`)
/// stay GPU-resident, the per-owning-layer KV caches PERSIST across tokens (allocated
/// once, scattered one slot per token), and the hidden/logits buffers are reused. Each
/// [`Gemma4ResidentModel::forward_token`] runs the whole token graph in ONE command
/// buffer with no per-token weight copy — unlike [`try_gemma4_forward`] (a stateless
/// test helper that rebuilds the cache and re-copies the 0.7GB embedding every call).
/// Resident state for computing the per-token PLE input `pli` ON the GPU (replacing
/// the ~12ms/token CPU prep — a 110MB f32 matvec). `proj`/`projnorm` have the gemma
/// constants folded in (proj * hidden^-0.5, proj_norm * FRAC_1_SQRT_2); `ti` is
/// written per token (the per_layer_token_embd row * ple_dim^0.5 * FRAC_1_SQRT_2).
#[cfg(target_os = "macos")]
struct Gemma4PliResident {
    proj: Buffer,
    projnorm: Buffer,
    ti: Buffer,
    ctx: Buffer,
    ctx_n: Buffer,
    pli: Buffer,
    ple_total: usize,
    ple_dim: usize,
}

#[cfg(target_os = "macos")]
pub struct Gemma4ResidentModel {
    layers: Vec<Gemma4ResidentLayer>,
    ple: Vec<Option<Gemma4ResidentPle>>,
    /// Per-layer `layer_output_scale` (1.0 when the tensor is absent). E-series
    /// layers apply it inside the PLE encode (`Gemma4ResidentPle.output_scale`,
    /// same tensor); dense rows (12B-class, no PLE) apply it standalone at the
    /// end of the layer — the reference multiplies it UNCONDITIONALLY.
    layer_scales: Vec<f32>,
    /// Per-layer resident PLE matrix buffers (inp_gate, proj, post_norm), uploaded
    /// once so forward_token doesn't re-copy ~220MB of f32 matrices every token.
    ple_bufs: Vec<Option<(Buffer, Buffer, Buffer)>>,
    /// Resident PLE `pli` computation (set via `set_pli`); when present, forward_token
    /// computes `pli` on the GPU from the input embedding instead of on the CPU.
    pli_res: Option<Gemma4PliResident>,
    owns_kv: Vec<bool>,
    kv_source: Vec<usize>,
    caches: Vec<Option<(Buffer, Buffer)>>,
    token_embd: Buffer,
    output_norm: Vec<f32>,
    buf_a: Buffer,
    buf_b: Buffer,
    mid: Buffer,
    logits: Buffer,
    hidden: usize,
    vocab: usize,
    softcap: f32,
    eps: f32,
    max_positions: usize,
    scale: f32,
}

#[derive(Debug, Clone, Copy, Default)]
pub struct Gemma4VerifyTimings {
    pub cpu_encode_us: u128,
    pub gpu_wait_us: u128,
    pub gpu_hw_us: u128,
    pub readback_us: u128,
}

#[cfg(target_os = "macos")]
impl Gemma4ResidentModel {
    pub(crate) fn forward_token_fused_argmax(
        &self,
        h0: &[f32],
        inputs: &[Gemma4TokenLayerInput],
        ti: &[f32],
        position: usize,
        q6k_head: &Gemma4Q6KHead,
    ) -> Option<u32> {
        let n = self.layers.len();
        if h0.len() != self.hidden || inputs.len() != n || position >= self.max_positions {
            return None;
        }
        let k = metal_linear_kernel()?;
        let filled = position + 1;
        write_buffer_f32(&self.buf_a, h0);
        let mut keep = Vec::new();
        let cb = k.queue.new_command_buffer();
        let e = cb.new_compute_command_encoder();
        if let Some(p) = &self.pli_res {
            if ti.len() != p.ple_total {
                return None;
            }
            write_buffer_f32(&p.ti, ti);
            encode_gemma4_pli(
                e,
                k,
                &mut keep,
                &self.buf_a,
                &p.proj,
                &p.projnorm,
                &p.ti,
                &p.ctx,
                &p.ctx_n,
                &p.pli,
                self.hidden,
                p.ple_total,
                p.ple_dim,
                n,
                self.eps,
            );
        }
        let mut from_a = true;
        for l in 0..n {
            let (in_buf, out_buf) = if from_a {
                (&self.buf_a, &self.buf_b)
            } else {
                (&self.buf_b, &self.buf_a)
            };
            let src = if self.owns_kv[l] {
                l
            } else {
                self.kv_source[l]
            };
            let (ck, cv) = self.caches[src].as_ref()?;
            let inp = &inputs[l];
            encode_gemma4_layer(
                e,
                k,
                &mut keep,
                &self.layers[l],
                in_buf,
                &self.mid,
                out_buf,
                &inp.cos_t,
                &inp.sin_t,
                ck,
                cv,
                self.max_positions,
                position,
                filled,
                inp.window_start,
                self.scale,
                self.owns_kv[l],
            );
            if let (Some(p), Some((ig, pj, pn)), Some(pr)) =
                (&self.ple[l], &self.ple_bufs[l], &self.pli_res)
            {
                encode_gemma4_ple(
                    e,
                    k,
                    &mut keep,
                    out_buf,
                    &pr.pli,
                    l * pr.ple_dim,
                    ig,
                    pj,
                    pn,
                    p.output_scale,
                    self.eps,
                    self.hidden,
                    pr.ple_dim,
                );
            } else if self.layer_scales[l] != 1.0 {
                let sc = pool_get(k, 8);
                unsafe {
                    let p = sc.contents() as *mut u8;
                    *(p as *mut u32) = self.hidden as u32;
                    *(p.add(4) as *mut f32) = self.layer_scales[l];
                }
                encode_scale_f32(e, k, out_buf, out_buf, &sc, self.hidden);
                keep.push(sc);
            }
            from_a = !from_a;
        }
        let final_buf = if from_a { &self.buf_a } else { &self.buf_b };
        e.end_encoding();
        cb.commit();
        cb.wait_until_completed();
        pool_recycle(k, keep);
        let mut h = vec![0.0f32; self.hidden];
        read_buffer_f32(final_buf, &mut h);
        q6k_head.forward_argmax(&h)
    }

    pub(crate) fn profile_subkernels(
        &self,
        _h0: &[f32],
        _inputs: &[Gemma4TokenLayerInput],
        _ti: &[f32],
        _position: usize,
        _q6k_head: &Gemma4Q6KHead,
    ) {
    }

    pub(crate) fn profile_verify_batch_subkernels(
        &self,
        _h0: &[f32],
        _ti: &[f32],
        _base_position: usize,
        _k_tokens: usize,
        _q6k_head: &Gemma4Q6KHead,
    ) {
    }

    pub(crate) fn verify_batch_fused_argmax_slab(
        &self,
        _h0: &[f32],
        _ti: &[f32],
        _base_position: usize,
        _k_tokens: usize,
        _q6k_head: &Gemma4Q6KHead,
    ) -> Option<(Vec<u32>, Gemma4VerifyTimings)> {
        None
    }

    /// Build the resident model. `token_embd_wire` is the vocab-major Q8 table in
    /// 34-byte wire blocks for the GPU logits head (copied once into a resident buffer;
    /// in the production runtime pass a nocopy WirePages buffer instead). Pass an EMPTY
    /// slice on the QAT hybrid lane (Q6_K head runs on the CPU) — no head buffer is
    /// allocated and only `forward_token_hidden` is valid. KV caches are allocated for
    /// owning layers (`owns_kv[l]`) sized to that layer's head_dim. None on bad shapes.
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        layers: Vec<Gemma4ResidentLayer>,
        ple: Vec<Option<Gemma4ResidentPle>>,
        layer_scales: Vec<f32>,
        owns_kv: Vec<bool>,
        kv_source: Vec<usize>,
        token_embd_wire: &[u8],
        output_norm: Vec<f32>,
        hidden: usize,
        vocab: usize,
        softcap: f32,
        eps: f32,
        max_positions: usize,
        scale: f32,
    ) -> Option<Self> {
        let n = layers.len();
        if n == 0
            || ple.len() != n
            || layer_scales.len() != n
            || owns_kv.len() != n
            || kv_source.len() != n
            || output_norm.len() != hidden
            || vocab == 0
            || max_positions == 0
        {
            return None;
        }
        let k = metal_linear_kernel()?;
        let mkbuf = |bytes: usize| {
            k.device
                .new_buffer(bytes as u64, MTLResourceOptions::StorageModeShared)
        };
        let mut caches = Vec::with_capacity(n);
        for (l, layer) in layers.iter().enumerate() {
            if owns_kv[l] {
                let len = layer.n_kv_heads * max_positions * layer.head_dim;
                caches.push(Some((mkbuf(len * 4), mkbuf(len * 4))));
            } else {
                caches.push(None);
            }
        }
        // Empty wire = QAT hybrid lane: the Q6_K head runs on the CPU, so don't upload
        // the (large) tied table to the GPU. A 1-byte placeholder keeps the field valid;
        // forward_inner only reads it on the want_head path, which the hybrid never takes.
        let token_embd = mkbuf(token_embd_wire.len().max(1));
        if !token_embd_wire.is_empty() {
            write_buffer_u8(&token_embd, token_embd_wire);
        }
        // Upload each layer's PLE matrices once into resident buffers.
        let upload = |v: &[f32]| {
            let b = mkbuf(v.len() * 4);
            write_buffer_f32(&b, v);
            b
        };
        let ple_bufs: Vec<Option<(Buffer, Buffer, Buffer)>> = ple
            .iter()
            .map(|p| {
                p.as_ref()
                    .map(|p| (upload(&p.inp_gate), upload(&p.proj), upload(&p.post_norm)))
            })
            .collect();
        Some(Self {
            layers,
            ple,
            layer_scales,
            ple_bufs,
            pli_res: None,
            owns_kv,
            kv_source,
            caches,
            token_embd,
            output_norm,
            buf_a: mkbuf(hidden * 4),
            buf_b: mkbuf(hidden * 4),
            mid: mkbuf(hidden * 4),
            logits: mkbuf(vocab * 4),
            hidden,
            vocab,
            softcap,
            eps,
            max_positions,
            scale,
        })
    }

    /// Enable on-GPU `pli` computation: uploads the (constant-folded) PLE projection
    /// matrices once. After this, `forward_token` computes `pli` from the input
    /// embedding on the GPU (passing `ti` per token) instead of relying on CPU prep.
    /// `proj` = per_layer_model_proj `[ple_total][hidden]`, `proj_norm` = `[ple_dim]`.
    pub fn set_pli(&mut self, proj: &[f32], proj_norm: &[f32], ple_dim: usize) -> bool {
        let n_layers = self.layers.len();
        let ple_total = n_layers * ple_dim;
        if proj.len() != ple_total * self.hidden || proj_norm.len() != ple_dim {
            return false;
        }
        let Some(k) = metal_linear_kernel() else {
            return false;
        };
        let frac = std::f32::consts::FRAC_1_SQRT_2;
        let proj_scale = (self.hidden as f32).powf(-0.5);
        let proj_folded: Vec<f32> = proj.iter().map(|v| v * proj_scale).collect();
        let projnorm_folded: Vec<f32> = proj_norm.iter().map(|v| v * frac).collect();
        let up = |v: &[f32]| {
            let b = k
                .device
                .new_buffer((v.len() * 4) as u64, MTLResourceOptions::StorageModeShared);
            write_buffer_f32(&b, v);
            b
        };
        let alloc = |n: usize| {
            k.device
                .new_buffer((n * 4) as u64, MTLResourceOptions::StorageModeShared)
        };
        self.pli_res = Some(Gemma4PliResident {
            proj: up(&proj_folded),
            projnorm: up(&projnorm_folded),
            ti: alloc(ple_total),
            ctx: alloc(ple_total),
            ctx_n: alloc(ple_total),
            pli: alloc(ple_total),
            ple_total,
            ple_dim,
        });
        true
    }

    /// Decode one token at absolute `position`: writes `h0` (the position's scaled
    /// input embedding) into the resident hidden buffer, runs all layers (each scatters
    /// its K/V into the PERSISTENT cache at `position`) + PLE + head in ONE command
    /// buffer, and returns the `vocab` soft-capped logits. `inputs[l]` carries this
    /// layer's RoPE tables, `pli`, and window start (CPU-computed for `position`).
    pub fn forward_token(
        &self,
        h0: &[f32],
        inputs: &[Gemma4TokenLayerInput],
        ti: &[f32],
        position: usize,
    ) -> Option<Vec<f32>> {
        self.forward_inner(h0, inputs, ti, position, true)
    }

    /// Like [`Self::forward_token`] but stops BEFORE the GPU logits head and returns the
    /// final decoder hidden state (the head's input). The QAT hybrid lane uses this: the
    /// tied head is Q6_K, which has no GPU kernel, so the head runs on the CPU instead.
    pub fn forward_token_hidden(
        &self,
        h0: &[f32],
        inputs: &[Gemma4TokenLayerInput],
        ti: &[f32],
        position: usize,
    ) -> Option<Vec<f32>> {
        self.forward_inner(h0, inputs, ti, position, false)
    }

    #[allow(clippy::needless_range_loop)] // layer index `l` indexes several parallel arrays
    fn forward_inner(
        &self,
        h0: &[f32],
        inputs: &[Gemma4TokenLayerInput],
        ti: &[f32],
        position: usize,
        want_head: bool,
    ) -> Option<Vec<f32>> {
        let n = self.layers.len();
        if h0.len() != self.hidden || inputs.len() != n || position >= self.max_positions {
            return None;
        }
        let k = metal_linear_kernel()?;
        let filled = position + 1;
        write_buffer_f32(&self.buf_a, h0);
        let mut keep = Vec::new();
        let cb = k.queue.new_command_buffer();
        let e = cb.new_compute_command_encoder();
        // Compute this token's pli on the GPU (folded constants) before the layers.
        if let Some(p) = &self.pli_res {
            if ti.len() != p.ple_total {
                return None;
            }
            write_buffer_f32(&p.ti, ti);
            encode_gemma4_pli(
                e,
                k,
                &mut keep,
                &self.buf_a,
                &p.proj,
                &p.projnorm,
                &p.ti,
                &p.ctx,
                &p.ctx_n,
                &p.pli,
                self.hidden,
                p.ple_total,
                p.ple_dim,
                n,
                self.eps,
            );
        }
        let mut from_a = true;
        for l in 0..n {
            let (in_buf, out_buf) = if from_a {
                (&self.buf_a, &self.buf_b)
            } else {
                (&self.buf_b, &self.buf_a)
            };
            let src = if self.owns_kv[l] {
                l
            } else {
                self.kv_source[l]
            };
            let (ck, cv) = self.caches[src].as_ref()?;
            let inp = &inputs[l];
            encode_gemma4_layer(
                e,
                k,
                &mut keep,
                &self.layers[l],
                in_buf,
                &self.mid,
                out_buf,
                &inp.cos_t,
                &inp.sin_t,
                ck,
                cv,
                self.max_positions,
                position,
                filled,
                inp.window_start,
                self.scale,
                self.owns_kv[l],
            );
            if let (Some(p), Some((ig, pj, pn)), Some(pr)) =
                (&self.ple[l], &self.ple_bufs[l], &self.pli_res)
            {
                encode_gemma4_ple(
                    e,
                    k,
                    &mut keep,
                    out_buf,
                    &pr.pli,
                    l * pr.ple_dim,
                    ig,
                    pj,
                    pn,
                    p.output_scale,
                    self.eps,
                    self.hidden,
                    pr.ple_dim,
                );
            } else if self.layer_scales[l] != 1.0 {
                // Dense rows (no PLE) still carry layer_output_scale — the
                // reference multiplies the layer output unconditionally.
                let sc = pool_get(k, 8);
                unsafe {
                    let p = sc.contents() as *mut u8;
                    *(p as *mut u32) = self.hidden as u32;
                    *(p.add(4) as *mut f32) = self.layer_scales[l];
                }
                encode_scale_f32(e, k, out_buf, out_buf, &sc, self.hidden);
                keep.push(sc);
            }
            from_a = !from_a;
        }
        let final_buf = if from_a { &self.buf_a } else { &self.buf_b };
        // QAT hybrid (`want_head == false`): skip the GPU head and read the final hidden
        // back so the CPU can run the Q6_K tied head. Otherwise encode the Q8 head and
        // read the soft-capped logits.
        if want_head {
            encode_gemma4_head(
                e,
                k,
                &mut keep,
                final_buf,
                &self.logits,
                &self.output_norm,
                &self.token_embd,
                self.vocab,
                self.softcap,
                self.eps,
            );
        }
        e.end_encoding();
        cb.commit();
        cb.wait_until_completed();
        let out = if want_head {
            let mut out = vec![0.0f32; self.vocab];
            read_buffer_f32(&self.logits, &mut out);
            out
        } else {
            let mut h = vec![0.0f32; self.hidden];
            read_buffer_f32(final_buf, &mut h);
            h
        };
        // Return the per-token scratch to the pool so the next token reuses it instead
        // of allocating ~hundreds of fresh Metal buffers (safe: the command buffer has
        // completed). Persistent weights/caches/token_embd are NOT in `keep`.
        pool_recycle(k, keep);
        Some(out)
    }
}

/// One layer's f32 PLE matrices (E-series only; `None` per layer for dense models).
/// Output-major like the CPU `f32_matvec`: `inp_gate` is `[ple_dim][hidden]`, `proj`
/// is `[hidden][ple_dim]`, `post_norm` is `[hidden]`.
pub struct Gemma4ResidentPle {
    pub inp_gate: Vec<f32>,
    pub proj: Vec<f32>,
    pub post_norm: Vec<f32>,
    pub output_scale: f32,
}

/// Per-token CPU-computed inputs the GPU forward needs for one layer: the dual-θ
/// RoPE tables for this position, the PLE per-layer input `pli`, and the resolved
/// attention window start (`max(0, filled-window)` for sliding, 0 for global).
#[derive(Clone)]
pub struct Gemma4TokenLayerInput {
    pub cos_t: Vec<f32>,
    pub sin_t: Vec<f32>,
    pub pli: Vec<f32>,
    pub window_start: usize,
}

/// Drive a full gemma4 token forward on the GPU in ONE command buffer:
/// `h0` (the position's scaled input embedding) → N decoder layers (each
/// [`encode_gemma4_layer`] + optional [`encode_gemma4_ple`]) → [`encode_gemma4_head`]
/// → soft-capped logits. Cross-layer KV sharing: owning layers (`owns_kv[l]`) hold
/// their own cache (built from `cache_k_init[l]`/`cache_v_init[l]`); shared layers
/// read `kv_source[l]`'s cache. The caller computes per-token data (embedding,
/// RoPE tables, `pli`, window starts) on the CPU — see [`Gemma4TokenLayerInput`].
/// Returns the `vocab` logits. None if Metal unavailable or shapes invalid.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
pub fn try_gemma4_forward(
    layers: &[Gemma4ResidentLayer],
    ple: &[Option<Gemma4ResidentPle>],
    owns_kv: &[bool],
    kv_source: &[usize],
    inputs: &[Gemma4TokenLayerInput],
    cache_k_init: &[Option<Vec<f32>>],
    cache_v_init: &[Option<Vec<f32>>],
    h0: &[f32],
    output_norm: &[f32],
    token_embd_wire: &[u8],
    vocab: usize,
    softcap: f32,
    eps: f32,
    max_positions: usize,
    write_position: usize,
    filled: usize,
    scale: f32,
) -> Option<Vec<f32>> {
    let n = layers.len();
    let hidden = h0.len();
    if n == 0
        || hidden == 0
        || ple.len() != n
        || owns_kv.len() != n
        || kv_source.len() != n
        || inputs.len() != n
        || cache_k_init.len() != n
        || cache_v_init.len() != n
        || output_norm.len() != hidden
    {
        return None;
    }
    let k = metal_linear_kernel()?;
    let mkbuf = |bytes: usize| {
        k.device
            .new_buffer(bytes as u64, MTLResourceOptions::StorageModeShared)
    };
    // Build a cache buffer pair for each owning layer; shared layers reuse a source's.
    let mut caches: Vec<Option<(Buffer, Buffer)>> = Vec::with_capacity(n);
    for l in 0..n {
        if owns_kv[l] {
            let ck = cache_k_init[l].as_ref()?;
            let cv = cache_v_init[l].as_ref()?;
            let len = layers[l].n_kv_heads * max_positions * layers[l].head_dim;
            if ck.len() != len || cv.len() != len {
                return None;
            }
            let ckb = mkbuf(len * 4);
            let cvb = mkbuf(len * 4);
            write_buffer_f32(&ckb, ck);
            write_buffer_f32(&cvb, cv);
            caches.push(Some((ckb, cvb)));
        } else {
            caches.push(None);
        }
    }
    let buf_a = mkbuf(hidden * 4);
    let buf_b = mkbuf(hidden * 4);
    let mid = mkbuf(hidden * 4);
    let logits_buf = mkbuf(vocab * 4);
    let embd_buf = mkbuf(token_embd_wire.len());
    write_buffer_f32(&buf_a, h0);
    write_buffer_u8(&embd_buf, token_embd_wire);

    let mut max_q_dim = 0;
    let mut max_kv_dim = 0;
    let mut max_ffn_dim = 0;
    let mut max_heads = 0;
    for layer in layers {
        max_q_dim = max_q_dim.max(layer.n_heads * layer.head_dim);
        max_kv_dim = max_kv_dim.max(layer.n_kv_heads * layer.head_dim);
        max_ffn_dim = max_ffn_dim.max(layer.ffn_dim);
        max_heads = max_heads.max(layer.n_heads);
    }
    let ple_dim = ple
        .iter()
        .find_map(|p| p.as_ref().map(|p| p.post_norm.len()))
        .unwrap_or(64);
    let _scratch = Gemma4ResidentScratch::new(
        k,
        hidden,
        max_q_dim,
        max_kv_dim,
        max_ffn_dim,
        max_heads,
        max_positions,
        ple_dim,
    );

    let mut keep = Vec::new();
    let cb = k.queue.new_command_buffer();
    let e = cb.new_compute_command_encoder();
    let mut from_a = true;
    for l in 0..n {
        let (in_buf, out_buf) = if from_a {
            (&buf_a, &buf_b)
        } else {
            (&buf_b, &buf_a)
        };
        let src = if owns_kv[l] { l } else { kv_source[l] };
        let (ck, cv) = caches[src].as_ref()?;
        let inp = &inputs[l];
        encode_gemma4_layer(
            e,
            k,
            &mut keep,
            &layers[l],
            in_buf,
            &mid,
            out_buf,
            &inp.cos_t,
            &inp.sin_t,
            ck,
            cv,
            max_positions,
            write_position,
            filled,
            inp.window_start,
            scale,
            owns_kv[l],
        );
        if let Some(p) = &ple[l] {
            let mkf = |v: &[f32]| {
                let b = k
                    .device
                    .new_buffer((v.len() * 4) as u64, MTLResourceOptions::StorageModeShared);
                write_buffer_f32(&b, v);
                b
            };
            let pli_buf = mkf(&inp.pli);
            let ig_buf = mkf(&p.inp_gate);
            let proj_buf = mkf(&p.proj);
            let pn_buf = mkf(&p.post_norm);
            encode_gemma4_ple(
                e,
                k,
                &mut keep,
                out_buf,
                &pli_buf,
                0,
                &ig_buf,
                &proj_buf,
                &pn_buf,
                p.output_scale,
                eps,
                hidden,
                inp.pli.len(),
            );
            keep.push(pli_buf);
            keep.push(ig_buf);
            keep.push(proj_buf);
            keep.push(pn_buf);
        }
        from_a = !from_a;
    }
    // After n layers the final hidden is the last out_buf (buf_b iff n is odd).
    let final_buf = if from_a { &buf_a } else { &buf_b };
    encode_gemma4_head(
        e,
        k,
        &mut keep,
        final_buf,
        &logits_buf,
        output_norm,
        &embd_buf,
        vocab,
        softcap,
        eps,
    );
    e.end_encoding();
    cb.commit();
    cb.wait_until_completed();
    let mut out = vec![0.0f32; vocab];
    read_buffer_f32(&logits_buf, &mut out);
    drop(keep);
    Some(out)
}

/// Standalone full gemma4 layer: builds buffers (incl. a prefilled cache), runs
/// [`encode_gemma4_layer`] (attention → FFN) in one command buffer, reads back the
/// hidden output. For validating the full-layer chain against CPU. None if Metal
/// unavailable or shapes invalid.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
pub fn try_gemma4_layer(
    layer: &Gemma4ResidentLayer,
    h_in: &[f32],
    cos_t: &[f32],
    sin_t: &[f32],
    cache_k_init: &[f32],
    cache_v_init: &[f32],
    max_positions: usize,
    write_position: usize,
    filled: usize,
    window_start: usize,
    scale: f32,
    owns_kv: bool,
) -> Option<Vec<f32>> {
    let hidden = h_in.len();
    let cache_len = layer.n_kv_heads * max_positions * layer.head_dim;
    if hidden == 0 || cache_k_init.len() != cache_len || cache_v_init.len() != cache_len {
        return None;
    }
    let k = metal_linear_kernel()?;
    let mkbuf = |bytes: usize| {
        k.device
            .new_buffer(bytes as u64, MTLResourceOptions::StorageModeShared)
    };
    let in_buf = mkbuf(hidden * 4);
    let mid_buf = mkbuf(hidden * 4);
    let out_buf = mkbuf(hidden * 4);
    let cache_k = mkbuf(cache_len * 4);
    let cache_v = mkbuf(cache_len * 4);
    write_buffer_f32(&in_buf, h_in);
    write_buffer_f32(&cache_k, cache_k_init);
    write_buffer_f32(&cache_v, cache_v_init);
    let _scratch = Gemma4ResidentScratch::new(
        k,
        hidden,
        layer.n_heads * layer.head_dim,
        layer.n_kv_heads * layer.head_dim,
        layer.ffn_dim,
        layer.n_heads,
        max_positions,
        0,
    );
    let mut keep = Vec::new();
    let cb = k.queue.new_command_buffer();
    let e = cb.new_compute_command_encoder();
    encode_gemma4_layer(
        e,
        k,
        &mut keep,
        layer,
        &in_buf,
        &mid_buf,
        &out_buf,
        cos_t,
        sin_t,
        &cache_k,
        &cache_v,
        max_positions,
        write_position,
        filled,
        window_start,
        scale,
        owns_kv,
    );
    e.end_encoding();
    cb.commit();
    cb.wait_until_completed();
    let mut out = vec![0.0f32; hidden];
    read_buffer_f32(&out_buf, &mut out);
    Some(out)
}

/// GPU elementwise binary op helper for residual add / silu-mul (same buffer shape).
#[cfg(target_os = "macos")]
fn try_binary_elementwise_f32(
    pipeline: &ComputePipelineState,
    lhs: &[f32],
    rhs: &[f32],
) -> Option<Vec<f32>> {
    if lhs.is_empty() || lhs.len() != rhs.len() {
        return None;
    }
    let kernel = metal_linear_kernel()?;
    let n = lhs.len();
    let byte_len = std::mem::size_of_val(lhs) as u64;
    let lhs_buf = kernel
        .device
        .new_buffer(byte_len, MTLResourceOptions::StorageModeShared);
    let rhs_buf = kernel
        .device
        .new_buffer(byte_len, MTLResourceOptions::StorageModeShared);
    let out_buf = kernel
        .device
        .new_buffer(byte_len, MTLResourceOptions::StorageModeShared);
    let n_buf = kernel
        .device
        .new_buffer(4, MTLResourceOptions::StorageModeShared);
    write_buffer_f32(&lhs_buf, lhs);
    write_buffer_f32(&rhs_buf, rhs);
    unsafe {
        *(n_buf.contents() as *mut u32) = n as u32;
    }
    let command_buffer = kernel.queue.new_command_buffer();
    let encoder = command_buffer.new_compute_command_encoder();
    encoder.set_compute_pipeline_state(pipeline);
    encoder.set_buffer(0, Some(&lhs_buf), 0);
    encoder.set_buffer(1, Some(&rhs_buf), 0);
    encoder.set_buffer(2, Some(&out_buf), 0);
    encoder.set_buffer(3, Some(&n_buf), 0);
    let width = pipeline.thread_execution_width().max(1);
    let threads_per_group = metal::MTLSize {
        width,
        height: 1,
        depth: 1,
    };
    let threadgroups = metal::MTLSize {
        width: (n as u64).div_ceil(width),
        height: 1,
        depth: 1,
    };
    encoder.dispatch_thread_groups(threadgroups, threads_per_group);
    encoder.end_encoding();
    command_buffer.commit();
    command_buffer.wait_until_completed();
    let mut out = vec![0.0f32; n];
    read_buffer_f32(&out_buf, &mut out);
    Some(out)
}

/// GPU residual add: output = a + b. None if Metal unavailable.
#[cfg(target_os = "macos")]
pub fn try_residual_add_f32(a: &[f32], b: &[f32]) -> Option<Vec<f32>> {
    let kernel = metal_linear_kernel()?;
    try_binary_elementwise_f32(&kernel.residual_add_pipeline, a, b)
}

/// GPU gated activation: output = (gate / (1 + e^-gate)) * up. None if Metal unavailable.
#[cfg(target_os = "macos")]
pub fn try_silu_mul_f32(gate: &[f32], up: &[f32]) -> Option<Vec<f32>> {
    let kernel = metal_linear_kernel()?;
    try_binary_elementwise_f32(&kernel.silu_mul_pipeline, gate, up)
}

/// GPU GeGLU activation (Gemma MLP): output = gelu_pytorch_tanh(gate) * up. Same
/// buffer shape as silu-mul. None if Metal unavailable.
#[cfg(target_os = "macos")]
pub fn try_gelu_mul_f32(gate: &[f32], up: &[f32]) -> Option<Vec<f32>> {
    let kernel = metal_linear_kernel()?;
    try_binary_elementwise_f32(&kernel.gelu_mul_pipeline, gate, up)
}

/// GPU final-logit soft-cap: output = cap * tanh(input / cap). A non-finite or
/// non-positive cap returns the input unchanged (matches the CPU reference). None
/// if Metal unavailable.
#[cfg(target_os = "macos")]
pub fn try_soft_cap_f32(input: &[f32], cap: f32) -> Option<Vec<f32>> {
    if input.is_empty() {
        return None;
    }
    if !cap.is_finite() || cap <= 0.0 {
        return Some(input.to_vec());
    }
    let kernel = metal_linear_kernel()?;
    let n = input.len();
    let byte_len = std::mem::size_of_val(input) as u64;
    let in_buf = kernel
        .device
        .new_buffer(byte_len, MTLResourceOptions::StorageModeShared);
    let out_buf = kernel
        .device
        .new_buffer(byte_len, MTLResourceOptions::StorageModeShared);
    let n_buf = kernel
        .device
        .new_buffer(4, MTLResourceOptions::StorageModeShared);
    let cap_buf = kernel
        .device
        .new_buffer(4, MTLResourceOptions::StorageModeShared);
    write_buffer_f32(&in_buf, input);
    unsafe {
        *(n_buf.contents() as *mut u32) = n as u32;
        *(cap_buf.contents() as *mut f32) = cap;
    }
    let command_buffer = kernel.queue.new_command_buffer();
    let encoder = command_buffer.new_compute_command_encoder();
    encoder.set_compute_pipeline_state(&kernel.soft_cap_pipeline);
    encoder.set_buffer(0, Some(&in_buf), 0);
    encoder.set_buffer(1, Some(&out_buf), 0);
    encoder.set_buffer(2, Some(&n_buf), 0);
    encoder.set_buffer(3, Some(&cap_buf), 0);
    let width = kernel.soft_cap_pipeline.thread_execution_width().max(1);
    let threads_per_group = metal::MTLSize {
        width,
        height: 1,
        depth: 1,
    };
    let threadgroups = metal::MTLSize {
        width: (n as u64).div_ceil(width),
        height: 1,
        depth: 1,
    };
    encoder.dispatch_thread_groups(threadgroups, threads_per_group);
    encoder.end_encoding();
    command_buffer.commit();
    command_buffer.wait_until_completed();
    let mut out = vec![0.0f32; n];
    read_buffer_f32(&out_buf, &mut out);
    Some(out)
}

/// GPU forward RoPE rotation across all heads, applied to a copy of `data`. The
/// cos/sin tables (one entry per rotated pair) come from the CPU's frequency/scaling
/// math; this only performs the rotation. `split_half_pairing` selects split-half vs
/// adjacent even/odd. None if Metal is unavailable.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
pub fn try_rope_rotate_f32(
    data: &[f32],
    cos_table: &[f32],
    sin_table: &[f32],
    head_count: usize,
    head_dim: usize,
    half_rope: usize,
    split_half_pairing: bool,
) -> Option<Vec<f32>> {
    if head_count == 0
        || half_rope == 0
        || data.len() != head_count * head_dim
        || cos_table.len() != half_rope
        || sin_table.len() != half_rope
        || half_rope * 2 > head_dim
    {
        return None;
    }
    let kernel = metal_linear_kernel()?;
    let data_bytes = std::mem::size_of_val(data) as u64;
    let table_bytes = std::mem::size_of_val(cos_table) as u64;
    let data_buf = kernel
        .device
        .new_buffer(data_bytes, MTLResourceOptions::StorageModeShared);
    let cos_buf = kernel
        .device
        .new_buffer(table_bytes, MTLResourceOptions::StorageModeShared);
    let sin_buf = kernel
        .device
        .new_buffer(table_bytes, MTLResourceOptions::StorageModeShared);
    let scalar_buf = kernel
        .device
        .new_buffer(16, MTLResourceOptions::StorageModeShared);
    write_buffer_f32(&data_buf, data);
    write_buffer_f32(&cos_buf, cos_table);
    write_buffer_f32(&sin_buf, sin_table);
    unsafe {
        let p = scalar_buf.contents() as *mut u32;
        *p = head_count as u32;
        *p.add(1) = head_dim as u32;
        *p.add(2) = half_rope as u32;
        *p.add(3) = u32::from(split_half_pairing);
    }
    let command_buffer = kernel.queue.new_command_buffer();
    let encoder = command_buffer.new_compute_command_encoder();
    encoder.set_compute_pipeline_state(&kernel.rope_rotate_pipeline);
    encoder.set_buffer(0, Some(&data_buf), 0);
    encoder.set_buffer(1, Some(&cos_buf), 0);
    encoder.set_buffer(2, Some(&sin_buf), 0);
    encoder.set_buffer(3, Some(&scalar_buf), 0);
    encoder.set_buffer(4, Some(&scalar_buf), 4);
    encoder.set_buffer(5, Some(&scalar_buf), 8);
    encoder.set_buffer(6, Some(&scalar_buf), 12);
    let total = (head_count * half_rope) as u64;
    let width = kernel.rope_rotate_pipeline.thread_execution_width().max(1);
    let threads_per_group = metal::MTLSize {
        width,
        height: 1,
        depth: 1,
    };
    let threadgroups = metal::MTLSize {
        width: total.div_ceil(width),
        height: 1,
        depth: 1,
    };
    encoder.dispatch_thread_groups(threadgroups, threads_per_group);
    encoder.end_encoding();
    command_buffer.commit();
    command_buffer.wait_until_completed();
    let mut out = vec![0.0f32; data.len()];
    read_buffer_f32(&data_buf, &mut out);
    Some(out)
}

/// GPU single-query (decode) causal attention over a contiguous KV cache laid out
/// [kv_head][position][head_dim]. GQA via `group = n_heads / n_kv_heads`. Returns the
/// per-head context [n_heads*head_dim], or None if Metal is unavailable. Mirrors
/// attention_context_for_head_into. Thin wrapper over `try_attention_decode_strided_f32`.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
pub fn try_attention_decode_f32(
    query: &[f32],
    keys: &[f32],
    values: &[f32],
    n_heads: usize,
    n_kv_heads: usize,
    head_dim: usize,
    position_count: usize,
    scale: f32,
) -> Option<Vec<f32>> {
    if head_dim == 0
        || position_count == 0
        || keys.len() != n_kv_heads * position_count * head_dim
        || values.len() != keys.len()
    {
        return None;
    }
    try_attention_decode_strided_f32(
        query,
        keys,
        values,
        n_heads,
        n_kv_heads,
        head_dim,
        position_count,
        scale,
        head_dim,
        position_count * head_dim,
        0,
    )
}

/// GPU single-query (decode) causal attention reading the KV cache with explicit strides:
/// the K/V element at (kv_head, position, d) is at `kv_base_offset + kv_head*kv_head_stride
/// + position*position_stride + d` (strides in floats) in `keys`/`values`. This lets the
/// kernel read a per-layer slice of an interleaved `[position][layer][kv_head][head_dim]`
/// cache directly, with no CPU repack. GQA via `group = n_heads / n_kv_heads`. Returns the
/// per-head context `[n_heads*head_dim]`, or None if Metal is unavailable / inputs invalid.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
pub fn try_attention_decode_strided_f32(
    query: &[f32],
    keys: &[f32],
    values: &[f32],
    n_heads: usize,
    n_kv_heads: usize,
    head_dim: usize,
    position_count: usize,
    scale: f32,
    position_stride: usize,
    kv_head_stride: usize,
    kv_base_offset: usize,
) -> Option<Vec<f32>> {
    attention_decode_strided_f32_variant(
        query,
        keys,
        values,
        n_heads,
        n_kv_heads,
        head_dim,
        position_count,
        scale,
        position_stride,
        kv_head_stride,
        kv_base_offset,
        false,
    )
}

/// Same computation as [`try_attention_decode_strided_f32`], forced through the
/// three-dispatch `encode_attention_split3` encode. Test-only: production picks the
/// encode via `attn_split3_enabled()`, and the two must agree bit-for-bit.
#[cfg(all(target_os = "macos", test))]
#[allow(clippy::too_many_arguments)]
fn try_attention_decode_strided_split3_f32(
    query: &[f32],
    keys: &[f32],
    values: &[f32],
    n_heads: usize,
    n_kv_heads: usize,
    head_dim: usize,
    position_count: usize,
    scale: f32,
    position_stride: usize,
    kv_head_stride: usize,
    kv_base_offset: usize,
) -> Option<Vec<f32>> {
    attention_decode_strided_f32_variant(
        query,
        keys,
        values,
        n_heads,
        n_kv_heads,
        head_dim,
        position_count,
        scale,
        position_stride,
        kv_head_stride,
        kv_base_offset,
        true,
    )
}

#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn attention_decode_strided_f32_variant(
    query: &[f32],
    keys: &[f32],
    values: &[f32],
    n_heads: usize,
    n_kv_heads: usize,
    head_dim: usize,
    position_count: usize,
    scale: f32,
    position_stride: usize,
    kv_head_stride: usize,
    kv_base_offset: usize,
    split3: bool,
) -> Option<Vec<f32>> {
    // Largest float index the kernel will touch in keys/values (last head, last position).
    // saturating_sub keeps this panic-free for zero inputs, which the checks below reject.
    let max_index = kv_base_offset
        + n_kv_heads.saturating_sub(1) * kv_head_stride
        + position_count.saturating_sub(1) * position_stride
        + head_dim.saturating_sub(1);
    if n_heads == 0
        || n_kv_heads == 0
        || head_dim == 0
        || position_count == 0
        || !n_heads.is_multiple_of(n_kv_heads)
        || query.len() != n_heads * head_dim
        || values.len() != keys.len()
        || keys.len() <= max_index
    {
        return None;
    }
    let kernel = metal_linear_kernel()?;
    let group = (n_heads / n_kv_heads) as u32;
    let new = |bytes: u64| {
        kernel
            .device
            .new_buffer(bytes, MTLResourceOptions::StorageModeShared)
    };
    let query_buf = new(std::mem::size_of_val(query) as u64);
    let keys_buf = new(std::mem::size_of_val(keys) as u64);
    let values_buf = new(std::mem::size_of_val(values) as u64);
    let scores_buf = new((n_heads * position_count * 4) as u64);
    let output_buf = new((n_heads * head_dim * 4) as u64);
    let scalar_buf = new(32);
    write_buffer_f32(&query_buf, query);
    write_buffer_f32(&keys_buf, keys);
    write_buffer_f32(&values_buf, values);
    unsafe {
        let p = scalar_buf.contents() as *mut u8;
        *(p as *mut u32) = n_heads as u32;
        *(p.add(4) as *mut u32) = head_dim as u32;
        *(p.add(8) as *mut u32) = position_count as u32;
        *(p.add(12) as *mut u32) = group;
        *(p.add(16) as *mut f32) = scale;
        *(p.add(20) as *mut u32) = position_stride as u32;
        *(p.add(24) as *mut u32) = kv_head_stride as u32;
        *(p.add(28) as *mut u32) = kv_base_offset as u32;
    }
    let command_buffer = kernel.queue.new_command_buffer();
    let encoder = command_buffer.new_compute_command_encoder();
    if split3 {
        let denom_buf = new((n_heads * 4).max(4) as u64);
        let blocks_buf = new(8);
        encode_attention_split3(
            encoder,
            kernel,
            &query_buf,
            &keys_buf,
            &values_buf,
            &scores_buf,
            &denom_buf,
            &output_buf,
            &scalar_buf,
            &blocks_buf,
            n_heads,
            head_dim,
            position_count,
            0,
            0,
        );
        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();
        let mut out = vec![0.0f32; n_heads * head_dim];
        read_buffer_f32(&output_buf, &mut out);
        return Some(out);
    }
    encoder.set_compute_pipeline_state(&kernel.attention_decode_pipeline);
    encoder.set_buffer(0, Some(&query_buf), 0);
    encoder.set_buffer(1, Some(&keys_buf), 0);
    encoder.set_buffer(2, Some(&values_buf), 0);
    encoder.set_buffer(3, Some(&scores_buf), 0);
    encoder.set_buffer(4, Some(&output_buf), 0);
    encoder.set_buffer(5, Some(&scalar_buf), 0);
    encoder.set_buffer(6, Some(&scalar_buf), 4);
    encoder.set_buffer(7, Some(&scalar_buf), 8);
    encoder.set_buffer(8, Some(&scalar_buf), 12);
    encoder.set_buffer(9, Some(&scalar_buf), 16);
    encoder.set_buffer(10, Some(&scalar_buf), 20);
    encoder.set_buffer(11, Some(&scalar_buf), 24);
    encoder.set_buffer(12, Some(&scalar_buf), 28);
    // One threadgroup per head, a single 32-lane SIMD group cooperating within it.
    encoder.dispatch_thread_groups(
        metal::MTLSize {
            width: n_heads as u64,
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: 32,
            height: 1,
            depth: 1,
        },
    );
    encoder.end_encoding();
    command_buffer.commit();
    command_buffer.wait_until_completed();
    let mut out = vec![0.0f32; n_heads * head_dim];
    read_buffer_f32(&output_buf, &mut out);
    Some(out)
}

/// GPU Q8_0 quantization of an f32 row (length a multiple of 32). Returns the per-block
/// scales (f32) and quants (i8) in the layout the Q8 block matmul consumes — the
/// on-GPU equivalent of the CPU activation quantizer, so activations produced on-GPU
/// can feed the matmul without a CPU round-trip. None if Metal is unavailable.
#[cfg(target_os = "macos")]
pub fn try_quantize_q8_0_f32(input: &[f32]) -> Option<(Vec<f32>, Vec<i8>)> {
    if input.is_empty() || !input.len().is_multiple_of(32) {
        return None;
    }
    let kernel = metal_linear_kernel()?;
    let n_blocks = input.len() / 32;
    let in_buf = kernel.device.new_buffer(
        std::mem::size_of_val(input) as u64,
        MTLResourceOptions::StorageModeShared,
    );
    let scales_buf = kernel
        .device
        .new_buffer((n_blocks * 4) as u64, MTLResourceOptions::StorageModeShared);
    let quants_buf = kernel
        .device
        .new_buffer(input.len() as u64, MTLResourceOptions::StorageModeShared);
    let n_buf = kernel
        .device
        .new_buffer(4, MTLResourceOptions::StorageModeShared);
    write_buffer_f32(&in_buf, input);
    unsafe {
        *(n_buf.contents() as *mut u32) = n_blocks as u32;
    }
    let command_buffer = kernel.queue.new_command_buffer();
    let encoder = command_buffer.new_compute_command_encoder();
    encoder.set_compute_pipeline_state(&kernel.quantize_q8_0_pipeline);
    encoder.set_buffer(0, Some(&in_buf), 0);
    encoder.set_buffer(1, Some(&scales_buf), 0);
    encoder.set_buffer(2, Some(&quants_buf), 0);
    encoder.set_buffer(3, Some(&n_buf), 0);
    let width = kernel
        .quantize_q8_0_pipeline
        .thread_execution_width()
        .max(1);
    let threads_per_group = metal::MTLSize {
        width,
        height: 1,
        depth: 1,
    };
    let threadgroups = metal::MTLSize {
        width: (n_blocks as u64).div_ceil(width),
        height: 1,
        depth: 1,
    };
    encoder.dispatch_thread_groups(threadgroups, threads_per_group);
    encoder.end_encoding();
    command_buffer.commit();
    command_buffer.wait_until_completed();
    let mut scales = vec![0.0f32; n_blocks];
    read_buffer_f32(&scales_buf, &mut scales);
    let mut quants = vec![0i8; input.len()];
    read_buffer_i8(&quants_buf, &mut quants);
    Some((scales, quants))
}

/// GPU-resident `quantize -> Q8 matmul` chain in a single command buffer: quantize the
/// f32 input activation and matmul it against a Q8_0 weight (36-byte blocks), passing
/// the quantized scales/quants between the two kernels via GPU buffers with no CPU
/// readback. This is the core decode primitive and the proof that resident buffer
/// chaining works; it is bit-identical to running the two standalone kernels. None if
/// Metal is unavailable. `weight_blocks` is [output_width * blocks_per_row * 36] bytes.
#[cfg(target_os = "macos")]
pub fn try_quantized_matmul_resident(
    input: &[f32],
    weight_blocks: &[u8],
    output_width: usize,
) -> Option<Vec<f32>> {
    if input.is_empty() || !input.len().is_multiple_of(32) || output_width == 0 {
        return None;
    }
    let blocks_per_row = input.len() / 32;
    if weight_blocks.len() != output_width * blocks_per_row * 36 {
        return None;
    }
    let kernel = metal_linear_kernel()?;
    let new = |bytes: u64| {
        kernel
            .device
            .new_buffer(bytes, MTLResourceOptions::StorageModeShared)
    };
    let in_buf = new(std::mem::size_of_val(input) as u64);
    let scales_buf = new((blocks_per_row * 4) as u64);
    let quants_buf = new(input.len() as u64);
    let weight_buf = new(weight_blocks.len() as u64);
    let out_buf = new((output_width * 4) as u64);
    let n_blocks_buf = new(4);
    let mm_scalar_buf = new(8);
    write_buffer_f32(&in_buf, input);
    write_buffer_u8(&weight_buf, weight_blocks);
    unsafe {
        *(n_blocks_buf.contents() as *mut u32) = blocks_per_row as u32;
        let p = mm_scalar_buf.contents() as *mut u32;
        *p = blocks_per_row as u32;
        *p.add(1) = output_width as u32;
    }
    let command_buffer = kernel.queue.new_command_buffer();

    // Stage 1: quantize the activation into scales_buf / quants_buf.
    let q_enc = command_buffer.new_compute_command_encoder();
    q_enc.set_compute_pipeline_state(&kernel.quantize_q8_0_pipeline);
    q_enc.set_buffer(0, Some(&in_buf), 0);
    q_enc.set_buffer(1, Some(&scales_buf), 0);
    q_enc.set_buffer(2, Some(&quants_buf), 0);
    q_enc.set_buffer(3, Some(&n_blocks_buf), 0);
    let qw = kernel
        .quantize_q8_0_pipeline
        .thread_execution_width()
        .max(1);
    q_enc.dispatch_thread_groups(
        metal::MTLSize {
            width: (blocks_per_row as u64).div_ceil(qw),
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: qw,
            height: 1,
            depth: 1,
        },
    );
    q_enc.end_encoding();

    // Stage 2: matmul reads the quantized buffers stage 1 just wrote (same command
    // buffer; ordered, hazard-tracked for shared buffers).
    let m_enc = command_buffer.new_compute_command_encoder();
    m_enc.set_compute_pipeline_state(&kernel.q8_0_block_pipeline);
    m_enc.set_buffer(0, Some(&scales_buf), 0);
    m_enc.set_buffer(1, Some(&quants_buf), 0);
    m_enc.set_buffer(2, Some(&weight_buf), 0);
    m_enc.set_buffer(3, Some(&out_buf), 0);
    m_enc.set_buffer(4, Some(&mm_scalar_buf), 0);
    m_enc.set_buffer(5, Some(&mm_scalar_buf), 4);
    let mw = kernel.q8_0_block_pipeline.thread_execution_width().max(1);
    m_enc.dispatch_thread_groups(
        metal::MTLSize {
            width: (output_width as u64).div_ceil(mw),
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: mw,
            height: 1,
            depth: 1,
        },
    );
    m_enc.end_encoding();

    command_buffer.commit();
    command_buffer.wait_until_completed();
    let mut out = vec![0.0f32; output_width];
    read_buffer_f32(&out_buf, &mut out);
    Some(out)
}

// --- Resident-buffer encode helpers: encode one kernel into a shared command buffer,
// operating on GPU buffers with no readback. Reusable building blocks for the
// GPU-resident forward pass (KV cache + per-token chaining build on these). ---

#[cfg(target_os = "macos")]
fn dispatch_1d(
    encoder: &metal::ComputeCommandEncoderRef,
    pipeline: &ComputePipelineState,
    n: usize,
) {
    let w = pipeline.thread_execution_width().max(1);
    encoder.dispatch_thread_groups(
        metal::MTLSize {
            width: (n as u64).div_ceil(w),
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: w,
            height: 1,
            depth: 1,
        },
    );
}

#[cfg(target_os = "macos")]
fn admitted_32_lane_pipeline(
    pipeline: Option<&ComputePipelineState>,
) -> Option<&ComputePipelineState> {
    pipeline.filter(|pipeline| {
        pipeline.thread_execution_width() == 32
            && pipeline.max_total_threads_per_threadgroup() >= 32
    })
}

/// Opt-in reassociated-summation kernels for the experimental Ghost-MoE lane.
/// Cached once: the flag participates in per-layer per-token dispatch choices.
#[cfg(target_os = "macos")]
pub(crate) fn gemma4_ghost_turbo_enabled() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| {
        std::env::var("CAMELID_GEMMA4_GHOST_METAL_TURBO")
            .is_ok_and(|value| value == "1" || value.eq_ignore_ascii_case("true"))
    })
}

/// One admission decision covers the generic common-core row dot and both
/// fixed-geometry expert row dots. Fused-fast falls back as a unit when any
/// optional SIMD pipeline is unavailable or the device does not expose the
/// 32-lane execution width compiled into their indexing contract.
#[cfg(target_os = "macos")]
fn gemma4_q4_simd_fast_available(kernel: &MetalLinearKernel) -> bool {
    const MAX_COMMON_BLOCKS: usize = GEMMA4_GHOST_26B_HEADS * GEMMA4_GHOST_26B_GLOBAL_HEAD_DIM / 32;
    threadgroup_alloc_fits(
        &kernel.device,
        MAX_COMMON_BLOCKS * std::mem::size_of::<f32>(),
    ) && admitted_32_lane_pipeline(kernel.q4_0_q8_ordered_simd_pipeline.as_ref()).is_some()
        && admitted_32_lane_pipeline(kernel.gemma4_q4_expert_gate_up_geglu_simd_pipeline.as_ref())
            .is_some()
        && admitted_32_lane_pipeline(kernel.gemma4_q4_expert_down_reduce_simd_pipeline.as_ref())
            .is_some()
}

#[cfg(target_os = "macos")]
fn dispatch_one_simdgroup_per_row(encoder: &metal::ComputeCommandEncoderRef, rows: usize) {
    encoder.dispatch_thread_groups(
        metal::MTLSize {
            width: rows as u64,
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: 32,
            height: 1,
            depth: 1,
        },
    );
}

/// Turbo-kernel geometry: four SIMD groups per 128-wide threadgroup, four
/// output rows per SIMD group (sixteen rows per threadgroup). The row batching
/// amortizes shared-activation reads across weight rows; the width keeps
/// enough traffic in flight to hide device-memory latency.
#[cfg(target_os = "macos")]
fn dispatch_four_simdgroup_rows(encoder: &metal::ComputeCommandEncoderRef, rows: usize) {
    encoder.dispatch_thread_groups(
        metal::MTLSize {
            width: rows.div_ceil(16) as u64,
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: 128,
            height: 1,
            depth: 1,
        },
    );
}

#[cfg(target_os = "macos")]
fn dispatch_q6k_turbo_rows(encoder: &metal::ComputeCommandEncoderRef, rows: usize) {
    encoder.dispatch_thread_groups(
        metal::MTLSize {
            width: rows.div_ceil(16) as u64,
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: 128,
            height: 1,
            depth: 1,
        },
    );
}

/// Fused rms_norm + Q8_0 quantize: reads `input`, emits the quantized normed row directly
/// into `scales`/`quants` (one dispatch, no intermediate normed buffer). `scalar` holds
/// width (u32) then eps (f32), like `encode_rms_norm`.
#[cfg(target_os = "macos")]
fn encode_rms_norm_quantize(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    input: &Buffer,
    weight: &Buffer,
    scales: &Buffer,
    quants: &Buffer,
    scalar: &Buffer,
) {
    e.set_compute_pipeline_state(&k.rms_norm_quantize_pipeline);
    e.set_buffer(0, Some(input), 0);
    e.set_buffer(1, Some(weight), 0);
    e.set_buffer(2, Some(scales), 0);
    e.set_buffer(3, Some(quants), 0);
    e.set_buffer(4, Some(scalar), 0);
    e.set_buffer(5, Some(scalar), 4);
    e.dispatch_thread_groups(
        metal::MTLSize {
            width: 1,
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: 256,
            height: 1,
            depth: 1,
        },
    );
}

/// Fused SiLU-mul + Q8_0 quantize: reads `gate`/`up`, emits the quantized activation row
/// directly into `scales`/`quants` (one dispatch, no intermediate activation buffer).
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_silu_mul_quantize(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    gate: &Buffer,
    up: &Buffer,
    scales: &Buffer,
    quants: &Buffer,
    nblocks_buf: &Buffer,
    n_blocks: usize,
) {
    e.set_compute_pipeline_state(&k.silu_mul_quantize_pipeline);
    e.set_buffer(0, Some(gate), 0);
    e.set_buffer(1, Some(up), 0);
    e.set_buffer(2, Some(scales), 0);
    e.set_buffer(3, Some(quants), 0);
    e.set_buffer(4, Some(nblocks_buf), 0);
    dispatch_1d(e, &k.silu_mul_quantize_pipeline, n_blocks);
}

#[cfg(target_os = "macos")]
pub(crate) fn encode_gemma4_fused_post_ffw_residual_batch(
    encoder: &metal::ComputeCommandEncoderRef,
    kernel: &MetalLinearKernel,
    down_in: &Buffer,
    post_ffw_weight: &Buffer,
    resid_out: &Buffer,
    width: usize,
    eps: f32,
    k_tokens: usize,
) -> Option<()> {
    let pipeline = kernel.gemma4_fused_post_ffw_residual_pipeline.as_ref()?;
    encoder.set_compute_pipeline_state(pipeline);
    encoder.set_buffer(0, Some(down_in), 0);
    encoder.set_buffer(1, Some(post_ffw_weight), 0);
    encoder.set_buffer(2, Some(resid_out), 0);
    let width_u32 = width as u32;
    encoder.set_bytes(3, 4, &width_u32 as *const u32 as *const _);
    encoder.set_bytes(4, 4, &eps as *const f32 as *const _);
    encoder.dispatch_thread_groups(
        metal::MTLSize {
            width: k_tokens as u64,
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: 256,
            height: 1,
            depth: 1,
        },
    );
    Some(())
}

#[cfg(target_os = "macos")]
pub fn encode_gemma4_router_batch_k(
    encoder: &metal::ComputeCommandEncoderRef,
    kernel: &MetalLinearKernel,
    input: &Buffer,
    gate_inp_scale: &Buffer,
    gate_inp_weights: &Buffer,
    out_logits: &Buffer,
    hidden: usize,
    eps: f32,
    num_experts: usize,
    k_tokens: usize,
    out_logits_offset: u64,
) -> Option<()> {
    let pipeline = kernel.gemma4_router_batch_k_pipeline.as_ref()?;
    encoder.set_compute_pipeline_state(pipeline);
    encoder.set_buffer(0, Some(input), 0);
    encoder.set_buffer(1, Some(gate_inp_scale), 0);
    encoder.set_buffer(2, Some(gate_inp_weights), 0);
    encoder.set_buffer(3, Some(out_logits), out_logits_offset);
    let hidden_u32 = hidden as u32;
    let num_experts_u32 = num_experts as u32;
    let k_tokens_u32 = k_tokens as u32;
    encoder.set_bytes(4, 4, &hidden_u32 as *const u32 as *const _);
    encoder.set_bytes(5, 4, &eps as *const f32 as *const _);
    encoder.set_bytes(6, 4, &num_experts_u32 as *const u32 as *const _);
    encoder.set_bytes(7, 4, &k_tokens_u32 as *const u32 as *const _);
    encoder.dispatch_thread_groups(
        metal::MTLSize {
            width: k_tokens as u64,
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: 256,
            height: 1,
            depth: 1,
        },
    );
    Some(())
}

#[cfg(target_os = "macos")]
