/// Non-macOS stub: there is no Metal stack, so wire mode is never active.
#[cfg(not(target_os = "macos"))]
pub fn wire_mode_active() -> bool {
    false
}

#[cfg(not(target_os = "macos"))]
pub fn kquant_resident_enabled() -> bool {
    false
}

/// Prefill GEMMs use the simdgroup-matrix tiled kernel (numerically equivalent to the
/// scalar k-split GEMM but not byte-exact: tile MMA accumulation order). Default on via
/// the fast stack; CAMELID_METAL_MM=0 restores the byte-exact scalar GEMM.
#[cfg(target_os = "macos")]
/// Scratch budget for the attention-as-matmul prefill's materialized S/P panels
/// (n_heads x n_pad^2, half each; the 4-byte factor in the gate covers both). The
/// budget directly sets how deep the fast prefill path reaches: 256 MiB admits
/// ~1.6k-token prompts at 24 heads, 2 GiB admits ~4.7k (anchored-recall checked
/// through 4k). Default is RAM-aware — an eighth of physical memory, capped at
/// 2 GiB — because the panels are transient prefill scratch in unified memory;
/// CAMELID_METAL_ATTN_MM_CAP_MB overrides explicitly. Prompts past the admitted
/// depth take the v3 attention path (correct, slower).
#[cfg(target_os = "macos")]
fn attn_mm_scratch_cap_bytes() -> usize {
    static CAP: OnceLock<usize> = OnceLock::new();
    *CAP.get_or_init(|| {
        if let Some(mb) = std::env::var("CAMELID_METAL_ATTN_MM_CAP_MB")
            .ok()
            .and_then(|v| v.parse::<usize>().ok())
        {
            return mb * 1024 * 1024;
        }
        let mut memsize: u64 = 0;
        let mut len = std::mem::size_of::<u64>();
        let name = std::ffi::CString::new("hw.memsize").expect("static name");
        let rc = unsafe {
            libc::sysctlbyname(
                name.as_ptr(),
                &mut memsize as *mut u64 as *mut libc::c_void,
                &mut len,
                std::ptr::null_mut(),
                0,
            )
        };
        let phys = if rc == 0 { memsize as usize } else { 0 };
        (phys / 8).clamp(256 * 1024 * 1024, 2048 * 1024 * 1024)
    })
}

#[cfg(target_os = "macos")]
fn mm_prefill_enabled() -> bool {
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| {
        !std::env::var("CAMELID_METAL_MM").is_ok_and(|v| {
            matches!(
                v.trim().to_ascii_lowercase().as_str(),
                "0" | "off" | "false" | "no" | "disabled"
            )
        })
    })
}

/// K-split GEMV over an f32 activation vector (see q8_0_block_linear_row_ksplit_f32y).
/// The weight buffer must match the active format: decoded 36-byte blocks normally, wire
/// 34-byte blocks when CAMELID_METAL_WIRE is on (prepare_token resolves accordingly).
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_q8_matmul_f32y(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    y: &Buffer,
    weight: &Buffer,
    out: &Buffer,
    scalar: &Buffer,
    rows: usize,
    wire: bool,
) {
    let nsg8 = wire_nsg8_enabled();
    let pipeline = if wire && nsg8 {
        &k.q8_0_block_ksplit_f32y_wire_nsg8_pipeline
    } else if wire {
        &k.q8_0_block_ksplit_f32y_wire_pipeline
    } else {
        &k.q8_0_block_ksplit_f32y_pipeline
    };
    let threads_per_tg = if wire && nsg8 { 256 } else { 128 };
    e.set_compute_pipeline_state(pipeline);
    e.set_buffer(0, Some(y), 0);
    e.set_buffer(2, Some(weight), 0);
    e.set_buffer(3, Some(out), 0);
    e.set_buffer(4, Some(scalar), 0);
    e.set_buffer(5, Some(scalar), 4);
    e.set_threadgroup_memory_length(0, 2 * 32 * 4);
    e.dispatch_thread_groups(
        metal::MTLSize {
            width: (rows as u64).div_ceil(2),
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: threads_per_tg,
            height: 1,
            depth: 1,
        },
    );
}

#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_resident_matmul_f32(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    keep: &mut Vec<Buffer>,
    y: &Buffer,
    weight: &ResidentLinearWeight,
    out: &Buffer,
    scalar: &Buffer,
    input_width: usize,
    rows: usize,
    n_tokens: usize,
) {
    match weight.format {
        ResidentWeightFormat::DenseF32 | ResidentWeightFormat::DenseF16 => {
            unsafe {
                let p = scalar.contents() as *mut u32;
                *p = input_width as u32;
                *p.add(1) = rows as u32;
                *p.add(2) = n_tokens as u32;
            }
            let pipeline = if weight.format == ResidentWeightFormat::DenseF16 {
                &k.dense_f16_linear_pipeline
            } else {
                &k.dense_f32_linear_pipeline
            };
            e.set_compute_pipeline_state(pipeline);
            e.set_buffer(0, Some(y), 0);
            e.set_buffer(1, Some(&weight.buffer), 0);
            e.set_buffer(2, Some(out), 0);
            e.set_buffer(3, Some(scalar), 0);
            e.set_buffer(4, Some(scalar), 4);
            e.set_buffer(5, Some(scalar), 8);
            let (groups, threads) = if weight.format == ResidentWeightFormat::Q1_0 {
                (rows.div_ceil(8), 32)
            } else {
                (rows, 32)
            };
            e.dispatch_thread_groups(
                metal::MTLSize {
                    width: groups as u64,
                    height: n_tokens as u64,
                    depth: 1,
                },
                metal::MTLSize {
                    width: threads,
                    height: 1,
                    depth: 1,
                },
            );
        }
        ResidentWeightFormat::Q8_0 => {
            unsafe {
                let p = scalar.contents() as *mut u32;
                *p = (input_width / 32) as u32;
                *p.add(1) = rows as u32;
                *p.add(2) = n_tokens as u32;
            }
            if n_tokens == 1 {
                encode_q8_matmul_f32y(e, k, y, &weight.buffer, out, scalar, rows, weight.q8_wire);
            } else {
                debug_assert!(
                    weight.q8_wire,
                    "batched Q8 projection requires 34-byte wire weights"
                );
                encode_q8_matmul_f32y_batched(e, k, y, &weight.buffer, out, scalar, rows, n_tokens);
            }
        }
        ResidentWeightFormat::Q4K | ResidentWeightFormat::Q6K => {
            let n_sb = input_width / 256;
            let scales = pool_get(k, (n_tokens * n_sb * 4) as u64);
            let quants = pool_get(k, (n_tokens * input_width) as u64);
            encode_resident_kquant_matmul_f32(
                e,
                k,
                y,
                weight,
                out,
                scalar,
                &scales,
                &quants,
                input_width,
                rows,
                n_tokens,
                true,
            );
            keep.extend([scales, quants]);
        }
        ResidentWeightFormat::Q1_0
        | ResidentWeightFormat::Q2_0G64
        | ResidentWeightFormat::Q2_0G128 => {
            let values_per_block = weight.format.values_per_block();
            unsafe {
                let p = scalar.contents() as *mut u32;
                *p = (input_width / values_per_block) as u32;
                *p.add(1) = rows as u32;
                *p.add(2) = n_tokens as u32;
            }
            let pipeline = match weight.format {
                ResidentWeightFormat::Q1_0 => &k.q1_0_linear_pipeline,
                ResidentWeightFormat::Q2_0G64 => &k.q2_0_g64_linear_pipeline,
                ResidentWeightFormat::Q2_0G128 => &k.q2_0_g128_linear_pipeline,
                _ => unreachable!(),
            };
            e.set_compute_pipeline_state(pipeline);
            e.set_buffer(0, Some(y), 0);
            e.set_buffer(2, Some(&weight.buffer), 0);
            e.set_buffer(3, Some(out), 0);
            e.set_buffer(4, Some(scalar), 0);
            e.set_buffer(5, Some(scalar), 4);
            e.set_buffer(6, Some(scalar), 8);
            e.dispatch_thread_groups(
                metal::MTLSize {
                    width: rows as u64,
                    height: n_tokens as u64,
                    depth: 1,
                },
                metal::MTLSize {
                    width: 32,
                    height: 1,
                    depth: 1,
                },
            );
        }
    }
}

#[cfg(target_os = "macos")]
static BITNET_METAL_RUN_COUNT: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

/// Number of canonical I2_S projections completed by the cleanroom Metal kernel.
#[cfg(target_os = "macos")]
pub fn metal_bitnet_run_count() -> u64 {
    BITNET_METAL_RUN_COUNT.load(std::sync::atomic::Ordering::Relaxed)
}

#[cfg(not(target_os = "macos"))]
pub fn metal_bitnet_run_count() -> u64 {
    0
}

#[cfg(target_os = "macos")]
pub(crate) fn try_bitnet_i2_s_matvec_f32(
    input: &[f32],
    pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
    output_rows: usize,
    mode: u32,
) -> Option<Vec<f32>> {
    try_bitnet_i2_s_matmul_flat(input, input.len(), 1, pages, output_rows, mode)
}

#[cfg(target_os = "macos")]
pub(crate) fn try_bitnet_i2_s_matmul_f32(
    inputs: &[Vec<f32>],
    pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
    output_rows: usize,
    mode: u32,
) -> Option<Vec<Vec<f32>>> {
    let input_width = inputs.first()?.len();
    if input_width == 0 || inputs.iter().any(|input| input.len() != input_width) {
        return None;
    }
    let flat = inputs.iter().flatten().copied().collect::<Vec<_>>();
    let output =
        try_bitnet_i2_s_matmul_flat(&flat, input_width, inputs.len(), pages, output_rows, mode)?;
    Some(
        output
            .chunks_exact(output_rows)
            .map(<[f32]>::to_vec)
            .collect(),
    )
}

#[cfg(target_os = "macos")]
fn try_bitnet_i2_s_matmul_flat(
    input: &[f32],
    input_width: usize,
    input_rows: usize,
    pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
    output_rows: usize,
    mode: u32,
) -> Option<Vec<f32>> {
    let elements = input_width.checked_mul(output_rows)?;
    let output_elements = input_rows.checked_mul(output_rows)?;
    if input_width == 0
        || input_rows == 0
        || output_rows == 0
        || !elements.is_multiple_of(128)
        || input.len() != input_width.checked_mul(input_rows)?
        || output_elements > u32::MAX as usize
        || pages.byte_len() != elements / 4 + 32
        || mode > 2
    {
        return None;
    }
    let packed_len = elements / 4;
    let scale = f32::from_le_bytes(pages.bytes()[packed_len..packed_len + 4].try_into().ok()?);
    if !scale.is_finite() {
        return None;
    }
    let (quantized_input, activation_scales) =
        crate::bitnet_kernels::quantize_activation_rows(input, input_width).ok()?;

    let kernel = metal_linear_kernel()?;
    let input_buffer = kernel.device.new_buffer(
        quantized_input.len() as u64,
        MTLResourceOptions::StorageModeShared,
    );
    let activation_scales_buffer = kernel.device.new_buffer(
        std::mem::size_of_val(activation_scales.as_slice()) as u64,
        MTLResourceOptions::StorageModeShared,
    );
    let output_buffer = kernel.device.new_buffer(
        (output_elements * std::mem::size_of::<f32>()) as u64,
        MTLResourceOptions::StorageModeShared,
    );
    let scalar_buffer = kernel
        .device
        .new_buffer(16, MTLResourceOptions::StorageModeShared);
    write_buffer_i8(&input_buffer, &quantized_input);
    write_buffer_f32(&activation_scales_buffer, &activation_scales);
    unsafe {
        let scalars = scalar_buffer.contents().cast::<u32>();
        *scalars = input_width as u32;
        *scalars.add(1) = output_rows as u32;
        *scalars.add(2) = input_rows as u32;
        *scalars.add(3) = mode;
    }
    let weights = {
        let mut cache = METAL_LINEAR_CACHE
            .get_or_init(|| Mutex::new(MetalLinearCache::new()))
            .lock()
            .ok()?;
        cache.q8_wire_nocopy_buffer(&kernel.device, pages)
    };
    let command_buffer = kernel.queue.new_command_buffer();
    let encoder = command_buffer.new_compute_command_encoder();
    encoder.set_compute_pipeline_state(&kernel.bitnet_i2_s_linear_pipeline);
    encoder.set_buffer(0, Some(&input_buffer), 0);
    encoder.set_buffer(1, Some(&weights), 0);
    encoder.set_buffer(2, Some(&output_buffer), 0);
    encoder.set_buffer(3, Some(&scalar_buffer), 0);
    encoder.set_buffer(4, Some(&scalar_buffer), 4);
    encoder.set_buffer(5, Some(&scalar_buffer), 8);
    encoder.set_buffer(6, Some(&scalar_buffer), 12);
    encoder.set_buffer(7, Some(&activation_scales_buffer), 0);
    let width = kernel
        .bitnet_i2_s_linear_pipeline
        .thread_execution_width()
        .max(1);
    encoder.dispatch_thread_groups(
        metal::MTLSize {
            width: (output_elements as u64).div_ceil(width),
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width,
            height: 1,
            depth: 1,
        },
    );
    encoder.end_encoding();
    command_buffer.commit();
    command_buffer.wait_until_completed();

    let mut output = vec![0.0_f32; output_elements];
    read_buffer_f32(&output_buffer, &mut output);
    BITNET_METAL_RUN_COUNT.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    static LOGGED: std::sync::OnceLock<()> = std::sync::OnceLock::new();
    LOGGED.get_or_init(|| {
        eprintln!(
            "[bitnet] Metal I2_S cleanroom kernel active (mode={})",
            match mode {
                1 => "tl1",
                2 => "tl2",
                _ => "i2_s",
            }
        );
    });
    Some(output)
}

/// Run one packed Prism projection against a page-backed Q1/Q2 matrix.
///
/// Originally the 27B Qwen3.5 bring-up bridge, now the hybrid CPU-fallback path:
/// on macOS the default is the fully resident Metal graph ([`Qwen35MetalDecode`];
/// opt-out `CAMELID_QWEN35_METAL=0`, and a resident-build error also lands here).
/// When the fallback runs, the recurrent graph stays in the runnable
/// implementation while Q1/Q2 projections execute through the same native Metal
/// kernels and the same NoCopy buffer cache as the fully resident dense engine.
/// Keeping this small API here avoids a second packed decoder or a second Metal
/// allocation of the weights.
#[cfg(target_os = "macos")]
pub(crate) fn try_prism_wire_matvec_f32(
    input: &[f32],
    pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
    format: ResidentWeightFormat,
    output_rows: usize,
) -> Option<Vec<f32>> {
    try_prism_wire_matmul_flat(input, input.len(), 1, pages, format, output_rows)
}

/// Batched form of [`try_prism_wire_matvec_f32`]. The Prism kernels dispatch
/// one `(output row, token)` threadgroup, so prompt positions share one command
/// buffer and stream the same resident matrix without host round-trips.
#[cfg(target_os = "macos")]
pub(crate) fn try_prism_wire_matmul_f32(
    inputs: &[Vec<f32>],
    pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
    format: ResidentWeightFormat,
    output_rows: usize,
) -> Option<Vec<Vec<f32>>> {
    let input_width = inputs.first()?.len();
    if input_width == 0 || inputs.iter().any(|input| input.len() != input_width) {
        return None;
    }
    let mut flat = Vec::with_capacity(inputs.len() * input_width);
    for input in inputs {
        flat.extend_from_slice(input);
    }
    let output =
        try_prism_wire_matmul_flat(&flat, input_width, inputs.len(), pages, format, output_rows)?;
    Some(
        output
            .chunks_exact(output_rows)
            .map(<[f32]>::to_vec)
            .collect(),
    )
}

#[cfg(target_os = "macos")]
fn try_prism_wire_matmul_flat(
    input: &[f32],
    input_width: usize,
    n_tokens: usize,
    pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
    format: ResidentWeightFormat,
    output_rows: usize,
) -> Option<Vec<f32>> {
    if input.is_empty()
        || input.len() != input_width.checked_mul(n_tokens)?
        || n_tokens == 0
        || output_rows == 0
        || !format.hybrid_prism_wire_supported()
    {
        return None;
    }
    let weight = ResidentWeightBytes::WirePages { format, pages };
    if !weight.matches_shape(input_width, output_rows) {
        return None;
    }

    let kernel = metal_linear_kernel()?;
    let input_buf = kernel.device.new_buffer(
        std::mem::size_of_val(input) as u64,
        MTLResourceOptions::StorageModeShared,
    );
    let output_buf = kernel.device.new_buffer(
        (n_tokens * output_rows * std::mem::size_of::<f32>()) as u64,
        MTLResourceOptions::StorageModeShared,
    );
    let scalar_buf = kernel
        .device
        .new_buffer(12, MTLResourceOptions::StorageModeShared);
    write_buffer_f32(&input_buf, input);

    let resident = {
        let mut cache = METAL_LINEAR_CACHE
            .get_or_init(|| Mutex::new(MetalLinearCache::new()))
            .lock()
            .ok()?;
        resolve_resident_weight(&mut cache, &kernel.device, &weight, true)?
    };

    let command_buffer = kernel.queue.new_command_buffer();
    let encoder = command_buffer.new_compute_command_encoder();
    let mut keep = Vec::new();
    encode_resident_matmul_f32(
        encoder,
        kernel,
        &mut keep,
        &input_buf,
        &resident,
        &output_buf,
        &scalar_buf,
        input_width,
        output_rows,
        n_tokens,
    );
    encoder.end_encoding();
    command_buffer.commit();
    command_buffer.wait_until_completed();

    let mut output = vec![0.0_f32; n_tokens * output_rows];
    read_buffer_f32(&output_buf, &mut output);
    Some(output)
}

/// The Q4_K/Q6_K half of [`encode_resident_matmul_f32`] with the activation-quant
/// scratch supplied by the caller.
///
/// Batched callers (prefill) hand in ONE `scales`/`quants` pair per contraction
/// width and reuse it for every projection in the command buffer: dispatches on a
/// `MTLComputeCommandEncoder` are serial by default, so the quantize kernel's
/// output is fully consumed by its GEMM before the next projection overwrites it.
/// Allocating a fresh pair per dispatch instead makes transient scratch scale with
/// `n_tokens * sum(input_width) * n_layers` — gigabytes for an 8B model on a long
/// prompt — where `n_tokens * sum(input_width)` is sufficient.
///
/// `quantize_input = false` is valid only when an earlier dispatch on this same
/// serial encoder populated `scales`/`quants` from the identical `y` rows. It
/// skips only that conversion; the projection kernel and its reduction order
/// are unchanged.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_resident_kquant_matmul_f32(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    y: &Buffer,
    weight: &ResidentLinearWeight,
    out: &Buffer,
    scalar: &Buffer,
    scales: &Buffer,
    quants: &Buffer,
    input_width: usize,
    rows: usize,
    n_tokens: usize,
    quantize_input: bool,
) {
    let n_sb = input_width / 256;
    unsafe {
        let p = scalar.contents() as *mut u32;
        *p = n_sb as u32;
        *p.add(1) = rows as u32;
        *p.add(2) = n_tokens as u32;
    }
    if quantize_input {
        let parallel_quant = kquant_parallel_quant_enabled();
        let quantize_pipeline = if parallel_quant {
            &k.quantize_q8k_rows_parallel_pipeline
        } else {
            &k.quantize_q8k_rows_pipeline
        };
        e.set_compute_pipeline_state(quantize_pipeline);
        e.set_buffer(0, Some(y), 0);
        e.set_buffer(1, Some(scales), 0);
        e.set_buffer(2, Some(quants), 0);
        e.set_buffer(3, Some(scalar), 0);
        e.set_buffer(4, Some(scalar), 8);
        if parallel_quant {
            e.dispatch_thread_groups(
                metal::MTLSize {
                    width: (n_tokens * n_sb) as u64,
                    height: 1,
                    depth: 1,
                },
                metal::MTLSize {
                    width: 256,
                    height: 1,
                    depth: 1,
                },
            );
        } else {
            dispatch_1d(e, quantize_pipeline, n_tokens * n_sb);
        }
    }

    let pipeline = match (weight.format, n_tokens == 1) {
        (ResidentWeightFormat::Q4K, true) => &k.q4k_linear_simd_pipeline,
        (ResidentWeightFormat::Q6K, true) => &k.q6k_linear_simd_pipeline,
        (ResidentWeightFormat::Q4K, false) => &k.q4k_linear_tiled_pipeline,
        (ResidentWeightFormat::Q6K, false) => &k.q6k_linear_tiled_pipeline,
        (ResidentWeightFormat::Q8_0, _)
        | (ResidentWeightFormat::DenseF32, _)
        | (ResidentWeightFormat::DenseF16, _)
        | (ResidentWeightFormat::Q1_0, _)
        | (ResidentWeightFormat::Q2_0G64, _)
        | (ResidentWeightFormat::Q2_0G128, _) => unreachable!(),
    };
    e.set_compute_pipeline_state(pipeline);
    e.set_buffer(0, Some(scales), 0);
    e.set_buffer(1, Some(quants), 0);
    e.set_buffer(2, Some(&weight.buffer), 0);
    e.set_buffer(3, Some(out), 0);
    e.set_buffer(4, Some(scalar), 0);
    e.set_buffer(5, Some(scalar), 4);
    e.set_buffer(6, Some(scalar), 8);
    if n_tokens == 1 {
        let scratch_ints = n_sb
            * match weight.format {
                ResidentWeightFormat::Q4K => 9,
                ResidentWeightFormat::Q6K => 8,
                ResidentWeightFormat::Q8_0
                | ResidentWeightFormat::DenseF32
                | ResidentWeightFormat::DenseF16
                | ResidentWeightFormat::Q1_0
                | ResidentWeightFormat::Q2_0G64
                | ResidentWeightFormat::Q2_0G128 => unreachable!(),
            };
        // `setThreadgroupMemoryLength:` requires a multiple of 16 bytes
        // (MTLDebugComputeCommandEncoder hard-asserts otherwise). `n_sb` is odd
        // or 2 mod 4 for plenty of real shapes — Llama-2-7B ffn_dim 11008 gives
        // n_sb 43, Qwen3-4B hidden 2560 gives n_sb 10 — so round the allocation
        // up. The kernel only ever indexes the first `scratch_ints` words.
        let kq_tg_bytes = (scratch_ints * 4).next_multiple_of(16);
        assert_threadgroup_fits(&k.device, kq_tg_bytes, "K-quant resident GEMV scratch");
        e.set_threadgroup_memory_length(0, kq_tg_bytes as u64);
        e.dispatch_thread_groups(
            metal::MTLSize {
                width: rows as u64,
                height: 1,
                depth: 1,
            },
            metal::MTLSize {
                width: 32,
                height: 1,
                depth: 1,
            },
        );
    } else {
        if weight.format == ResidentWeightFormat::Q6K {
            dispatch_1d(e, pipeline, rows * n_tokens.div_ceil(8));
            return;
        }
        let scratch_ints_per_block = match weight.format {
            ResidentWeightFormat::Q4K => 9,
            ResidentWeightFormat::Q6K => unreachable!(),
            ResidentWeightFormat::Q8_0
            | ResidentWeightFormat::DenseF32
            | ResidentWeightFormat::DenseF16
            | ResidentWeightFormat::Q1_0
            | ResidentWeightFormat::Q2_0G64
            | ResidentWeightFormat::Q2_0G128 => unreachable!(),
        };
        let scratch_bytes = (8 * n_sb * scratch_ints_per_block * 4).next_multiple_of(16);
        assert_threadgroup_fits(&k.device, scratch_bytes, "K-quant batched GEMM scratch");
        e.set_threadgroup_memory_length(0, scratch_bytes as u64);
        e.dispatch_thread_groups(
            metal::MTLSize {
                width: rows as u64,
                height: n_tokens.div_ceil(8) as u64,
                depth: 1,
            },
            metal::MTLSize {
                width: 32,
                height: 1,
                depth: 1,
            },
        );
    }
}

/// Q4_K simdgroup-matrix contraction over a pre-rounded half activation panel.
/// This is used only by the Qwen3.5 prompt path; decode and parity-sensitive
/// single-token projections keep their established Q8_K dot kernels.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_q4k_mm_half(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    half_input: &Buffer,
    weight: &ResidentLinearWeight,
    out: &Buffer,
    scalar: &Buffer,
    input_width: usize,
    rows: usize,
    n_tokens: usize,
) {
    debug_assert_eq!(weight.format, ResidentWeightFormat::Q4K);
    unsafe {
        let p = scalar.contents() as *mut u32;
        *p = (input_width / 256) as u32;
        *p.add(1) = rows as u32;
        *p.add(2) = n_tokens as u32;
    }
    e.set_compute_pipeline_state(&k.q4k_linear_mm_pipeline);
    e.set_buffer(0, Some(half_input), 0);
    e.set_buffer(2, Some(&weight.buffer), 0);
    e.set_buffer(3, Some(out), 0);
    e.set_buffer(4, Some(scalar), 0);
    e.set_buffer(5, Some(scalar), 4);
    e.set_buffer(6, Some(scalar), 8);
    const SCRATCH_BYTES: usize = 64 * (144 + 16) + (64 * 32 + 128 * 32) * 2;
    assert_threadgroup_fits(&k.device, SCRATCH_BYTES, "Q4_K prefill matrix tile");
    e.set_threadgroup_memory_length(0, SCRATCH_BYTES as u64);
    e.dispatch_thread_groups(
        metal::MTLSize {
            width: rows.div_ceil(64) as u64,
            height: n_tokens.div_ceil(128) as u64,
            depth: 1,
        },
        metal::MTLSize {
            width: 256,
            height: 1,
            depth: 1,
        },
    );
}

#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_q6k_mm_half(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    half_input: &Buffer,
    weight: &ResidentLinearWeight,
    out: &Buffer,
    scalar: &Buffer,
    input_width: usize,
    rows: usize,
    n_tokens: usize,
) {
    debug_assert_eq!(weight.format, ResidentWeightFormat::Q6K);
    unsafe {
        let p = scalar.contents() as *mut u32;
        *p = (input_width / 256) as u32;
        *p.add(1) = rows as u32;
        *p.add(2) = n_tokens as u32;
    }
    e.set_compute_pipeline_state(&k.q6k_linear_mm_pipeline);
    e.set_buffer(0, Some(half_input), 0);
    e.set_buffer(2, Some(&weight.buffer), 0);
    e.set_buffer(3, Some(out), 0);
    e.set_buffer(4, Some(scalar), 0);
    e.set_buffer(5, Some(scalar), 4);
    e.set_buffer(6, Some(scalar), 8);
    const SCRATCH_BYTES: usize = 64 * 210 + (64 * 32 + 128 * 32) * 2;
    assert_threadgroup_fits(&k.device, SCRATCH_BYTES, "Q6_K prefill matrix tile");
    e.set_threadgroup_memory_length(0, SCRATCH_BYTES as u64);
    e.dispatch_thread_groups(
        metal::MTLSize {
            width: rows.div_ceil(64) as u64,
            height: n_tokens.div_ceil(128) as u64,
            depth: 1,
        },
        metal::MTLSize {
            width: 256,
            height: 1,
            depth: 1,
        },
    );
}

#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_kquant_mm_half(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    half_input: &Buffer,
    weight: &ResidentLinearWeight,
    out: &Buffer,
    scalar: &Buffer,
    input_width: usize,
    rows: usize,
    n_tokens: usize,
) {
    match weight.format {
        ResidentWeightFormat::Q4K => encode_q4k_mm_half(
            e,
            k,
            half_input,
            weight,
            out,
            scalar,
            input_width,
            rows,
            n_tokens,
        ),
        ResidentWeightFormat::Q6K => encode_q6k_mm_half(
            e,
            k,
            half_input,
            weight,
            out,
            scalar,
            input_width,
            rows,
            n_tokens,
        ),
        _ => unreachable!("Qwen3.5 matrix prefill accepts only K-quant weights"),
    }
}

#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_qwen35_matmul_batch(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    keep: &mut Vec<Buffer>,
    input: &Buffer,
    weight: &ResidentLinearWeight,
    output: &Buffer,
    scalar: &Buffer,
    input_width: usize,
    rows: usize,
    n_tokens: usize,
) {
    if n_tokens > 1
        && matches!(
            weight.format,
            ResidentWeightFormat::Q4K | ResidentWeightFormat::Q6K
        )
        && mm_prefill_enabled()
    {
        let half_input = pool_get(k, (n_tokens * input_width * 2) as u64);
        let count = pool_get(k, 4);
        unsafe { *(count.contents() as *mut u32) = (n_tokens * input_width) as u32 };
        e.set_compute_pipeline_state(&k.f32_to_f16_pipeline);
        e.set_buffer(0, Some(input), 0);
        e.set_buffer(1, Some(&half_input), 0);
        e.set_buffer(2, Some(&count), 0);
        dispatch_1d(e, &k.f32_to_f16_pipeline, n_tokens * input_width);
        encode_kquant_mm_half(
            e,
            k,
            &half_input,
            weight,
            output,
            scalar,
            input_width,
            rows,
            n_tokens,
        );
        keep.extend([half_input, count]);
    } else {
        encode_resident_matmul_f32(
            e,
            k,
            keep,
            input,
            weight,
            output,
            scalar,
            input_width,
            rows,
            n_tokens,
        );
    }
}

#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn try_encode_qwen35_shared_matmuls(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    keep: &mut Vec<Buffer>,
    input: &Buffer,
    input_width: usize,
    n_tokens: usize,
    projections: &[(&ResidentLinearWeight, &Buffer, &Buffer, usize)],
) -> bool {
    if n_tokens > 1
        && mm_prefill_enabled()
        && !projections.is_empty()
        && projections.iter().all(|(weight, _, _, _)| {
            matches!(
                weight.format,
                ResidentWeightFormat::Q4K | ResidentWeightFormat::Q6K
            )
        })
    {
        let half_input = pool_get(k, (n_tokens * input_width * 2) as u64);
        let count = pool_get(k, 4);
        unsafe { *(count.contents() as *mut u32) = (n_tokens * input_width) as u32 };
        e.set_compute_pipeline_state(&k.f32_to_f16_pipeline);
        e.set_buffer(0, Some(input), 0);
        e.set_buffer(1, Some(&half_input), 0);
        e.set_buffer(2, Some(&count), 0);
        dispatch_1d(e, &k.f32_to_f16_pipeline, n_tokens * input_width);
        for (weight, output, scalar, rows) in projections {
            encode_kquant_mm_half(
                e,
                k,
                &half_input,
                weight,
                output,
                scalar,
                input_width,
                *rows,
                n_tokens,
            );
        }
        keep.extend([half_input, count]);
        true
    } else {
        try_encode_shared_kquant_matmuls(e, k, keep, input, input_width, n_tokens, projections)
    }
}

/// Encode several K-quant projections that consume the same f32 activation,
/// quantizing that activation exactly once. Dispatches on the shared compute
/// encoder are serial, so every GEMV consumes the buffers before any later
/// command can overwrite them. Returns false without encoding when the A/B
/// gate is off or any projection is not Q4_K/Q6_K.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn try_encode_shared_kquant_matmuls(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    keep: &mut Vec<Buffer>,
    y: &Buffer,
    input_width: usize,
    n_tokens: usize,
    projections: &[(&ResidentLinearWeight, &Buffer, &Buffer, usize)],
) -> bool {
    if !kquant_quant_reuse_enabled()
        || projections.is_empty()
        || !projections.iter().all(|(weight, _, _, _)| {
            matches!(
                weight.format,
                ResidentWeightFormat::Q4K | ResidentWeightFormat::Q6K
            )
        })
    {
        return false;
    }

    let scales = pool_get(k, (n_tokens * (input_width / 256) * 4) as u64);
    let quants = pool_get(k, (n_tokens * input_width) as u64);
    for (index, (weight, out, scalar, rows)) in projections.iter().enumerate() {
        encode_resident_kquant_matmul_f32(
            e,
            k,
            y,
            weight,
            out,
            scalar,
            &scales,
            &quants,
            input_width,
            *rows,
            n_tokens,
            index == 0,
        );
    }
    keep.extend([scales, quants]);
    true
}

/// Batched-column mirror of [`encode_q8_matmul_f32y`]'s production NSG=8 wire GEMV.
/// Instead of dotting each weight block against one activation vector, it dots it
/// against all `n_rows_in` activation columns (the speculative-verify rows) before
/// moving on, so each weight is streamed once for the whole window rather than once
/// per token. `y` is row-major `[token][blocks_per_row*32]`; `out` is token-major
/// `[token][rows]` (matching the next GEMM's `[token][dim]` input). The bound kernel
/// keeps the single-token per-block `sumq` then `*w_scale` ordering and the exact
/// two-stage reduction, so each output column is BIT-IDENTICAL to the single-token
/// dispatch (proven by `metal_verify_gemv_batched_bit_identical`). `scalar` must be
/// at least 12 bytes with `blocks_per_row` @0 and `rows` @4 already written (same as
/// the single-token caller); the column count `n_rows_in` is written to @8 here.
// Consumed by the speculative-verify lane (a later checkpoint); for now exercised by
// the `metal_verify_gemv_batched_bit_identical` unit test, so it reads as dead in a
// non-test lib build.
#[cfg(target_os = "macos")]
#[allow(dead_code)]
#[allow(clippy::too_many_arguments)]
fn encode_q8_matmul_f32y_batched(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    y: &Buffer,
    weight: &Buffer,
    out: &Buffer,
    scalar: &Buffer,
    rows: usize,
    n_rows_in: usize,
) {
    unsafe {
        let p = scalar.contents() as *mut u8;
        *(p.add(8) as *mut u32) = n_rows_in as u32;
    }
    e.set_compute_pipeline_state(&k.q8_0_block_ksplit_f32y_wire_nsg8_verify_pipeline);
    e.set_buffer(0, Some(y), 0);
    e.set_buffer(2, Some(weight), 0);
    e.set_buffer(3, Some(out), 0);
    e.set_buffer(4, Some(scalar), 0);
    e.set_buffer(5, Some(scalar), 4);
    e.set_buffer(6, Some(scalar), 8);
    e.dispatch_thread_groups(
        metal::MTLSize {
            width: (rows as u64).div_ceil(2),
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: 32,
            height: 1,
            depth: 1,
        },
    );
}

/// Wire quant format of a gemma4 weight tensor for the GPU GEMV dispatch.
/// `Q8_0` = 34-byte blocks (f16 scale + 32 i8); `Q4_0` = 18-byte blocks (f16
/// scale + 16 nibble bytes). Un-gated so it can appear in the public
/// `try_gemma4_ffn` signature on every target.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum GemmaWireFmt {
    Q8_0,
    Q4_0,
    /// NVFP4 (GABBRO M3): 64-element superblocks, 36 wire bytes (`d[4]` UE4M3
    /// sub-block scales + `qs[32]` packed E2M1 nibbles). Unlike Q8_0/Q4_0
    /// (32-value blocks) this is a 64-value block, so callers must size
    /// `blocks_per_row` by [`GemmaWireFmt::block_elements`], never a hardcoded 32.
    Nvfp4,
}

impl GemmaWireFmt {
    /// Bytes per wire block: 34/18 over 32 values (Q8_0/Q4_0), 36 over 64 values
    /// (NVFP4 superblock).
    pub fn wire_bytes(self) -> usize {
        match self {
            GemmaWireFmt::Q8_0 => 34,
            GemmaWireFmt::Q4_0 => 18,
            GemmaWireFmt::Nvfp4 => 36,
        }
    }

    /// Weight values per wire block: 32 for Q8_0/Q4_0, 64 for the NVFP4
    /// superblock. Row block count is `in_dim / block_elements()`, so this is the
    /// single source of truth that keeps `blocks_per_row`, `row_stride`, and the
    /// kernel's activation stride consistent across formats.
    pub fn block_elements(self) -> usize {
        match self {
            GemmaWireFmt::Q8_0 | GemmaWireFmt::Q4_0 => 32,
            GemmaWireFmt::Nvfp4 => 64,
        }
    }
}

/// Dispatch the gemma4 GPU GEMV for the weight's wire format. Q8_0 and Q4_0
/// share the same `(y, weight, out, scalar, rows)` contract — only the kernel
/// (and the per-block byte stride it reads) differs — so callers in the resident
/// graph stay format-agnostic.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_gemma4_matmul(
    fmt: GemmaWireFmt,
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    y: &Buffer,
    weight: &Buffer,
    out: &Buffer,
    scalar: &Buffer,
    rows: usize,
) {
    match fmt {
        GemmaWireFmt::Q8_0 => encode_gemma4_q8_matmul(e, k, y, weight, out, scalar, rows),
        GemmaWireFmt::Q4_0 => encode_gemma4_q4_0_matmul(e, k, y, weight, out, scalar, rows),
        GemmaWireFmt::Nvfp4 => encode_gemma4_nvfp4_matmul(e, k, y, weight, out, scalar, rows),
    }
}

/// Encode one f32-activation × wire-Q8 GEMV into the shared encoder:
/// `out[r] = Σ_b w_scale[b] · Σ_j (w_i8[b][j] · y[b*32+j])`. The weight is the raw
/// 34-byte GGUF wire layout (f16 scale + 32 i8). Gemma's resident decode always
/// uses the nocopy wire weights, so — unlike [`encode_q8_matmul_f32y`] — this is
/// NOT gated on `CAMELID_METAL_WIRE`; it always binds the wire f32y K-split kernel.
/// `scalar` holds [blocks_per_row: u32 @0, rows: u32 @4].
#[cfg(target_os = "macos")]
fn encode_gemma4_q8_matmul(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    y: &Buffer,
    weight: &Buffer,
    out: &Buffer,
    scalar: &Buffer,
    rows: usize,
) {
    let nsg8 = wire_nsg8_enabled();
    let pipeline = if nsg8 {
        &k.q8_0_block_ksplit_f32y_wire_nsg8_pipeline
    } else {
        &k.q8_0_block_ksplit_f32y_wire_pipeline
    };
    let threads_per_tg = if nsg8 { 256 } else { 128 };
    e.set_compute_pipeline_state(pipeline);
    e.set_buffer(0, Some(y), 0);
    e.set_buffer(2, Some(weight), 0);
    e.set_buffer(3, Some(out), 0);
    e.set_buffer(4, Some(scalar), 0);
    e.set_buffer(5, Some(scalar), 4);
    e.set_threadgroup_memory_length(0, 2 * 32 * 4);
    e.dispatch_thread_groups(
        metal::MTLSize {
            width: (rows as u64).div_ceil(2),
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: threads_per_tg,
            height: 1,
            depth: 1,
        },
    );
}

/// Q4_0 wire GEMV — the QAT-row counterpart of [`encode_gemma4_q8_matmul`].
/// Identical dispatch (128 threads/TG, NR0=2 rows/TG, 2*32*4 threadgroup mem);
/// only the bound pipeline differs (it reads 18-byte Q4_0 wire blocks and
/// unpacks nibbles inline). `scalar` holds blocks_per_row at offset 0 and rows
/// at offset 4, exactly as the Q8 path.
#[cfg(target_os = "macos")]
fn encode_gemma4_q4_0_matmul(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    y: &Buffer,
    weight: &Buffer,
    out: &Buffer,
    scalar: &Buffer,
    rows: usize,
) {
    e.set_compute_pipeline_state(&k.q4_0_block_ksplit_f32y_wire_pipeline);
    e.set_buffer(0, Some(y), 0);
    e.set_buffer(2, Some(weight), 0);
    e.set_buffer(3, Some(out), 0);
    e.set_buffer(4, Some(scalar), 0);
    e.set_buffer(5, Some(scalar), 4);
    e.set_threadgroup_memory_length(0, 2 * 32 * 4);
    e.dispatch_thread_groups(
        metal::MTLSize {
            width: (rows as u64).div_ceil(2),
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: 128,
            height: 1,
            depth: 1,
        },
    );
}

#[cfg(target_os = "macos")]
fn encode_gemma4_q4_0_matmul_batch_k(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    y: &Buffer,
    weight: &Buffer,
    weight_offset: u64,
    output: &Buffer,
    rows: usize,
    scalar_buf: &Buffer,
    k_batch: usize,
) {
    // The k<=8 kernels below hold a fixed `float sums[4][8]`; a wider chunk
    // indexes past it and corrupts the round instead of failing. K in 9..=16
    // routes to the `_k16` twin (spec50_widen, `float sums[4][16]`); anything
    // wider is refused loudly.
    assert!(
        k_batch <= 16,
        "dense batch_k chunk {k_batch} exceeds the widened kernels' accumulator depth 16"
    );
    let bpr_u32 = unsafe { *(scalar_buf.contents() as *const u32) };
    let rows_u32 = rows as u32;
    let k_batch_u32 = k_batch as u32;

    if k_batch > GEMMA4_DENSE_BATCH_K_MAX {
        // K=9..16 capacity lane. Never fall back to the fixed-depth kernels:
        // if the widened library failed to compile, encode nothing (the same
        // failure mode as every missing-pipeline branch below).
        if let Some(widen) = spec50_widen_kernels() {
            encode_spec50_widen_plain(
                e,
                widen,
                y,
                weight,
                weight_offset,
                output,
                bpr_u32,
                rows,
                k_batch,
            );
        } else {
            eprintln!(
                "[metal] dense batch_k chunk {k_batch} > {GEMMA4_DENSE_BATCH_K_MAX} but the spec50_widen pipelines are unavailable; encoding nothing"
            );
        }
        return;
    }

    if k_batch == 8 && !dense_k8_generic() {
        if let Some(pipe) = &k.q4_0_block_batch_k8_pipeline {
            e.set_compute_pipeline_state(pipe);
            e.set_buffer(0, Some(y), 0);
            e.set_buffer(2, Some(weight), weight_offset);
            e.set_buffer(3, Some(output), 0);
            e.set_bytes(4, 4, &bpr_u32 as *const u32 as *const _);
            e.set_bytes(5, 4, &rows_u32 as *const u32 as *const _);
            e.set_bytes(6, 4, &k_batch_u32 as *const u32 as *const _);
            e.dispatch_thread_groups(
                metal::MTLSize {
                    width: (rows as u64).div_ceil(4),
                    height: 1,
                    depth: 1,
                },
                metal::MTLSize {
                    width: 32,
                    height: 1,
                    depth: 1,
                },
            );
            return;
        }
    }
    if k_batch == 6 {
        if let Some(pipe) = &k.q4_0_block_batch_k6_pipeline {
            e.set_compute_pipeline_state(pipe);
            e.set_buffer(0, Some(y), 0);
            e.set_buffer(2, Some(weight), weight_offset);
            e.set_buffer(3, Some(output), 0);
            e.set_bytes(4, 4, &bpr_u32 as *const u32 as *const _);
            e.set_bytes(5, 4, &rows_u32 as *const u32 as *const _);
            e.set_bytes(6, 4, &k_batch_u32 as *const u32 as *const _);
            e.dispatch_thread_groups(
                metal::MTLSize {
                    width: (rows as u64).div_ceil(4),
                    height: 1,
                    depth: 1,
                },
                metal::MTLSize {
                    width: 32,
                    height: 1,
                    depth: 1,
                },
            );
            return;
        }
    }
    if let Some(pipe) = &k.q4_0_block_batch_k_pipeline {
        e.set_compute_pipeline_state(pipe);
        e.set_buffer(0, Some(y), 0);
        e.set_buffer(2, Some(weight), weight_offset);
        e.set_buffer(3, Some(output), 0);
        e.set_bytes(4, 4, &bpr_u32 as *const u32 as *const _);
        e.set_bytes(5, 4, &rows_u32 as *const u32 as *const _);
        e.set_bytes(6, 4, &k_batch_u32 as *const u32 as *const _);
        e.dispatch_thread_groups(
            metal::MTLSize {
                width: (rows as u64).div_ceil(4),
                // Generic batch_k already loops k_batch after each weight tile
                // (threadgroup y is unused). height>1 relaunched the same rows.
                height: 1,
                depth: 1,
            },
            metal::MTLSize {
                width: 32,
                height: 1,
                depth: 1,
            },
        );
    }
}

#[cfg(target_os = "macos")]
fn encode_gemma4_q4_0_qkv_matmul_batch_k(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    y: &Buffer,
    q_weight: &Buffer,
    k_weight: &Buffer,
    v_weight: &Buffer,
    query_out: &Buffer,
    key_out: &Buffer,
    val_out: &Buffer,
    qkv_scalar: &Buffer,
    total_rows: usize,
    k_batch: usize,
) {
    // The k<=8 kernels below hold fixed `float sum0[8]/sum1[8]` accumulators;
    // a wider chunk indexes past them and corrupts the round instead of
    // failing. K in 9..=16 routes to the `_k16` twin (spec50_widen); anything
    // wider is refused loudly.
    assert!(
        k_batch <= 16,
        "dense batch_k chunk {k_batch} exceeds the widened kernels' accumulator depth 16"
    );
    let (bpr_u32, q_rows_u32, k_rows_u32, v_rows_u32) = unsafe {
        let ptr = qkv_scalar.contents() as *const u32;
        (*ptr, *ptr.add(1), *ptr.add(2), *ptr.add(3))
    };
    let k_batch_u32 = k_batch as u32;

    if k_batch > GEMMA4_DENSE_BATCH_K_MAX {
        if let Some(widen) = spec50_widen_kernels() {
            encode_spec50_widen_qkv(
                e,
                widen,
                y,
                q_weight,
                k_weight,
                v_weight,
                query_out,
                key_out,
                val_out,
                (bpr_u32, q_rows_u32, k_rows_u32, v_rows_u32),
                total_rows,
                k_batch,
            );
        } else {
            eprintln!(
                "[metal] QKV batch_k chunk {k_batch} > {GEMMA4_DENSE_BATCH_K_MAX} but the spec50_widen pipelines are unavailable; encoding nothing"
            );
        }
        return;
    }

    if k_batch == 8 && !dense_k8_generic() {
        if let Some(pipe) = &k.q4_0_qkv_block_batch_k8_pipeline {
            e.set_compute_pipeline_state(pipe);
            e.set_buffer(0, Some(y), 0);
            e.set_buffer(1, Some(q_weight), 0);
            e.set_buffer(2, Some(k_weight), 0);
            e.set_buffer(3, Some(v_weight), 0);
            e.set_buffer(4, Some(query_out), 0);
            e.set_buffer(5, Some(key_out), 0);
            e.set_buffer(6, Some(val_out), 0);
            e.set_bytes(7, 4, &bpr_u32 as *const u32 as *const _);
            e.set_bytes(8, 4, &q_rows_u32 as *const u32 as *const _);
            e.set_bytes(9, 4, &k_rows_u32 as *const u32 as *const _);
            e.set_bytes(10, 4, &v_rows_u32 as *const u32 as *const _);
            e.set_bytes(11, 4, &k_batch_u32 as *const u32 as *const _);
            e.dispatch_thread_groups(
                metal::MTLSize {
                    width: (total_rows as u64).div_ceil(4),
                    height: 1,
                    depth: 1,
                },
                metal::MTLSize {
                    width: 32,
                    height: 1,
                    depth: 1,
                },
            );
            return;
        }
    }
    if k_batch == 6 {
        if let Some(pipe) = &k.q4_0_qkv_block_batch_k6_pipeline {
            e.set_compute_pipeline_state(pipe);
            e.set_buffer(0, Some(y), 0);
            e.set_buffer(1, Some(q_weight), 0);
            e.set_buffer(2, Some(k_weight), 0);
            e.set_buffer(3, Some(v_weight), 0);
            e.set_buffer(4, Some(query_out), 0);
            e.set_buffer(5, Some(key_out), 0);
            e.set_buffer(6, Some(val_out), 0);
            e.set_bytes(7, 4, &bpr_u32 as *const u32 as *const _);
            e.set_bytes(8, 4, &q_rows_u32 as *const u32 as *const _);
            e.set_bytes(9, 4, &k_rows_u32 as *const u32 as *const _);
            e.set_bytes(10, 4, &v_rows_u32 as *const u32 as *const _);
            e.set_bytes(11, 4, &k_batch_u32 as *const u32 as *const _);
            e.dispatch_thread_groups(
                metal::MTLSize {
                    width: (total_rows as u64).div_ceil(4),
                    height: 1,
                    depth: 1,
                },
                metal::MTLSize {
                    width: 32,
                    height: 1,
                    depth: 1,
                },
            );
            return;
        }
    }
    if let Some(pipe) = &k.q4_0_qkv_block_batch_k_pipeline {
        e.set_compute_pipeline_state(pipe);
        e.set_buffer(0, Some(y), 0);
        e.set_buffer(1, Some(q_weight), 0);
        e.set_buffer(2, Some(k_weight), 0);
        e.set_buffer(3, Some(v_weight), 0);
        e.set_buffer(4, Some(query_out), 0);
        e.set_buffer(5, Some(key_out), 0);
        e.set_buffer(6, Some(val_out), 0);
        e.set_bytes(7, 4, &bpr_u32 as *const u32 as *const _);
        e.set_bytes(8, 4, &q_rows_u32 as *const u32 as *const _);
        e.set_bytes(9, 4, &k_rows_u32 as *const u32 as *const _);
        e.set_bytes(10, 4, &v_rows_u32 as *const u32 as *const _);
        e.set_bytes(11, 4, &k_batch_u32 as *const u32 as *const _);
        e.dispatch_thread_groups(
            metal::MTLSize {
                width: (total_rows as u64).div_ceil(2),
                height: 1,
                depth: 1,
            },
            metal::MTLSize {
                width: 32,
                height: 1,
                depth: 1,
            },
        );
    }
}

#[cfg(target_os = "macos")]
fn encode_gemma4_q4_0_qkv_matmul_batch_k_fused_rms(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    x: &Buffer,
    rms_weight: &Buffer,
    inv_rms: &Buffer,
    q_weight: &Buffer,
    k_weight: &Buffer,
    v_weight: &Buffer,
    query_out: &Buffer,
    key_out: &Buffer,
    val_out: &Buffer,
    qkv_scalar: &Buffer,
    k_batch: usize,
) -> bool {
    assert!(
        k_batch <= 16,
        "dense batch_k chunk {k_batch} exceeds the widened kernels' accumulator depth 16"
    );
    if k_batch > GEMMA4_DENSE_BATCH_K_MAX {
        // No widened twin for the fused-RMS kernel: a verbatim `_k16` copy
        // measured up to 492 ULP off the k<=8 kernel at k_batch=8 (widening
        // the accumulator array shifted the compiled FMA contraction of the
        // `(w * rms) * scale` chain), so it cannot satisfy the bitwise pinning
        // contract. Returning false keeps the caller on its fallback
        // (separate RMS + QKV), whose K>8 kernel IS bitwise-verified.
        return false;
    }
    let Some(pipe) = k.q4_0_qkv_block_batch_k_fused_rms_pipeline.as_ref() else {
        return false;
    };
    let (bpr_u32, q_rows_u32, k_rows_u32, v_rows_u32) = unsafe {
        let ptr = qkv_scalar.contents() as *const u32;
        (*ptr, *ptr.add(1), *ptr.add(2), *ptr.add(3))
    };
    let k_batch_u32 = k_batch as u32;
    let disp = (q_rows_u32 as usize) + (k_rows_u32 as usize) + (v_rows_u32 as usize);
    e.set_compute_pipeline_state(pipe);
    e.set_buffer(0, Some(x), 0);
    e.set_buffer(1, Some(q_weight), 0);
    e.set_buffer(2, Some(k_weight), 0);
    e.set_buffer(3, Some(v_weight), 0);
    e.set_buffer(4, Some(query_out), 0);
    e.set_buffer(5, Some(key_out), 0);
    e.set_buffer(6, Some(val_out), 0);
    e.set_bytes(7, 4, &bpr_u32 as *const u32 as *const _);
    e.set_bytes(8, 4, &q_rows_u32 as *const u32 as *const _);
    e.set_bytes(9, 4, &k_rows_u32 as *const u32 as *const _);
    e.set_bytes(10, 4, &v_rows_u32 as *const u32 as *const _);
    e.set_bytes(11, 4, &k_batch_u32 as *const u32 as *const _);
    e.set_buffer(12, Some(rms_weight), 0);
    e.set_buffer(13, Some(inv_rms), 0);
    e.dispatch_thread_groups(
        metal::MTLSize {
            width: (disp as u64).div_ceil(4),
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: 32,
            height: 1,
            depth: 1,
        },
    );
    true
}

#[cfg(target_os = "macos")]
fn encode_gemma4_q4_0_gateup_matmul_batch_k(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    y: &Buffer,
    gate_weight: &Buffer,
    up_weight: &Buffer,
    act_output: &Buffer,
    gateup_scalar: &Buffer,
    rows: usize,
    k_batch: usize,
) {
    // The k<=8 kernels below hold fixed `float g_sums/u_sums[4][8]`
    // accumulators; a wider chunk indexes past them and corrupts the round
    // instead of failing. K in 9..=16 routes to the `_k16` twin
    // (spec50_widen); anything wider is refused loudly.
    assert!(
        k_batch <= 16,
        "dense batch_k chunk {k_batch} exceeds the widened kernels' accumulator depth 16"
    );
    let bpr_u32 = unsafe { *(gateup_scalar.contents() as *const u32) };
    let rows_u32 = rows as u32;
    let k_batch_u32 = k_batch as u32;

    if k_batch > GEMMA4_DENSE_BATCH_K_MAX {
        if let Some(widen) = spec50_widen_kernels() {
            encode_spec50_widen_gateup(
                e,
                widen,
                y,
                gate_weight,
                up_weight,
                act_output,
                bpr_u32,
                rows,
                k_batch,
            );
        } else {
            eprintln!(
                "[metal] gateup batch_k chunk {k_batch} > {GEMMA4_DENSE_BATCH_K_MAX} but the spec50_widen pipelines are unavailable; encoding nothing"
            );
        }
        return;
    }

    // The shared-MLP GateUp has 2,112 rows, so every four-row SIMD group is
    // complete. The packed twin removes only the never-taken row-tail
    // predicate. Unlike the legacy fixed-K8 plain and QKV kernels, its K8
    // output is raw-bit identical to the runtime-width GateUp oracle at both
    // stress and production shapes, so exact-partition mode may retain this
    // one independently proven specialization. K<8 keeps its existing path;
    // K>8 returned through spec50_widen above.
    let exact_partition = dense_k8_generic();
    if spec50_packed_gateup_row_complete_eligible(rows, k_batch)
        && spec50_packed_gateup_row_complete_enabled()
    {
        if let Some(packed) = spec50_packed_gateup_kernels() {
            if exact_partition {
                static EXACT_PACKED_GATEUP_RECEIPT: std::sync::Once = std::sync::Once::new();
                EXACT_PACKED_GATEUP_RECEIPT.call_once(|| {
                    eprintln!(
                        "[gemma4 exact partition] packed_k8_gateup=row_complete runtime_width_oracle=raw_bit_exact"
                    );
                });
            }
            encode_spec50_packed_gateup_row_complete(
                e,
                packed,
                y,
                gate_weight,
                up_weight,
                act_output,
                bpr_u32,
                rows,
                k_batch,
            );
            return;
        }
    }

    if k_batch == 8 && !exact_partition {
        if let Some(pipe) = &k.q4_0_gateup_geglu_block_batch_k8_pipeline {
            e.set_compute_pipeline_state(pipe);
            e.set_buffer(0, Some(y), 0);
            e.set_buffer(1, Some(gate_weight), 0);
            e.set_buffer(2, Some(up_weight), 0);
            e.set_buffer(3, Some(act_output), 0);
            e.set_bytes(4, 4, &bpr_u32 as *const u32 as *const _);
            e.set_bytes(5, 4, &rows_u32 as *const u32 as *const _);
            e.set_bytes(6, 4, &k_batch_u32 as *const u32 as *const _);
            e.dispatch_thread_groups(
                metal::MTLSize {
                    width: (rows as u64).div_ceil(4),
                    height: 1,
                    depth: 1,
                },
                metal::MTLSize {
                    width: 32,
                    height: 1,
                    depth: 1,
                },
            );
            return;
        }
    }
    if k_batch == 6 {
        if let Some(pipe) = &k.q4_0_gateup_geglu_block_batch_k6_pipeline {
            e.set_compute_pipeline_state(pipe);
            e.set_buffer(0, Some(y), 0);
            e.set_buffer(1, Some(gate_weight), 0);
            e.set_buffer(2, Some(up_weight), 0);
            e.set_buffer(3, Some(act_output), 0);
            e.set_bytes(4, 4, &bpr_u32 as *const u32 as *const _);
            e.set_bytes(5, 4, &rows_u32 as *const u32 as *const _);
            e.set_bytes(6, 4, &k_batch_u32 as *const u32 as *const _);
            e.dispatch_thread_groups(
                metal::MTLSize {
                    width: (rows as u64).div_ceil(4),
                    height: 1,
                    depth: 1,
                },
                metal::MTLSize {
                    width: 32,
                    height: 1,
                    depth: 1,
                },
            );
            return;
        }
    }
    if let Some(pipe) = &k.q4_0_gateup_geglu_block_batch_k_pipeline {
        e.set_compute_pipeline_state(pipe);
        e.set_buffer(0, Some(y), 0);
        e.set_buffer(1, Some(gate_weight), 0);
        e.set_buffer(2, Some(up_weight), 0);
        e.set_buffer(3, Some(act_output), 0);
        e.set_bytes(4, 4, &bpr_u32 as *const u32 as *const _);
        e.set_bytes(5, 4, &rows_u32 as *const u32 as *const _);
        e.set_bytes(6, 4, &k_batch_u32 as *const u32 as *const _);
        e.dispatch_thread_groups(
            metal::MTLSize {
                width: (rows as u64).div_ceil(4),
                height: 1,
                depth: 1,
            },
            metal::MTLSize {
                width: 32,
                height: 1,
                depth: 1,
            },
        );
    }
}

/// Encode one ordered Q4_0 x Q8_0 GEMV for a single activation row.
///
/// This is the resident-buffer sibling of
/// [`try_gemma4_q4_0_matmul_q8_batch`]. `scalar` is three consecutive u32s:
/// `[blocks_per_row, rows, 1]`. The strict shader keeps the CPU Gemma 4 wire
/// comparator's integer dot and increasing-block f32 accumulation order. Ghost
/// common-core attention and the shared expert use this path instead of the
/// older f32-activation Q4_0 reduction.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_gemma4_q4_0_q8_ordered_single(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    input_scales: &Buffer,
    input_quants: &Buffer,
    weight: &Buffer,
    output: &Buffer,
    scalar: &Buffer,
    rows: usize,
    blocks_per_row: usize,
    fused_fast: bool,
) {
    let turbo_pipeline = (fused_fast && gemma4_ghost_turbo_enabled())
        .then(|| admitted_32_lane_pipeline(k.q4_0_q8_turbo_pipeline.as_ref()))
        .flatten();
    let simd_scratch_bytes = blocks_per_row.checked_mul(std::mem::size_of::<f32>());
    let simd_pipeline = (fused_fast
        && turbo_pipeline.is_none()
        && simd_scratch_bytes.is_some_and(|bytes| threadgroup_alloc_fits(&k.device, bytes)))
    .then(|| admitted_32_lane_pipeline(k.q4_0_q8_ordered_simd_pipeline.as_ref()))
    .flatten();
    let pipeline = turbo_pipeline
        .or(simd_pipeline)
        .unwrap_or(&k.q4_0_q8_ordered_pipeline);
    e.set_compute_pipeline_state(pipeline);
    e.set_buffer(0, Some(input_scales), 0);
    e.set_buffer(1, Some(input_quants), 0);
    e.set_buffer(2, Some(weight), 0);
    e.set_buffer(3, Some(output), 0);
    e.set_buffer(4, Some(scalar), 0);
    e.set_buffer(5, Some(scalar), 4);
    e.set_buffer(6, Some(scalar), 8);
    if turbo_pipeline.is_some() {
        dispatch_four_simdgroup_rows(e, rows);
    } else if simd_pipeline.is_some() {
        e.set_threadgroup_memory_length(
            0,
            simd_scratch_bytes.expect("admitted SIMD Q4 scratch length") as u64,
        );
        dispatch_one_simdgroup_per_row(e, rows);
    } else {
        dispatch_1d(e, pipeline, rows);
    }
}

#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_gemma4_q4_0_q8_ordered_single_offset(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    input_scales: &Buffer,
    input_scales_offset: u64,
    input_quants: &Buffer,
    input_quants_offset: u64,
    weight: &Buffer,
    weight_offset: u64,
    output: &Buffer,
    output_offset: u64,
    scalar: &Buffer,
    rows: usize,
    blocks_per_row: usize,
    fused_fast: bool,
) {
    let turbo_pipeline = (fused_fast && gemma4_ghost_turbo_enabled())
        .then(|| admitted_32_lane_pipeline(k.q4_0_q8_turbo_pipeline.as_ref()))
        .flatten();
    let simd_scratch_bytes = blocks_per_row.checked_mul(std::mem::size_of::<f32>());
    let simd_pipeline = (fused_fast
        && turbo_pipeline.is_none()
        && simd_scratch_bytes.is_some_and(|bytes| threadgroup_alloc_fits(&k.device, bytes)))
    .then(|| admitted_32_lane_pipeline(k.q4_0_q8_ordered_simd_pipeline.as_ref()))
    .flatten();
    let pipeline = turbo_pipeline
        .or(simd_pipeline)
        .unwrap_or(&k.q4_0_q8_ordered_pipeline);
    e.set_compute_pipeline_state(pipeline);
    e.set_buffer(0, Some(input_scales), input_scales_offset);
    e.set_buffer(1, Some(input_quants), input_quants_offset);
    e.set_buffer(2, Some(weight), weight_offset);
    e.set_buffer(3, Some(output), output_offset);
    e.set_buffer(4, Some(scalar), 0);
    e.set_buffer(5, Some(scalar), 4);
    e.set_buffer(6, Some(scalar), 8);
    if turbo_pipeline.is_some() {
        dispatch_four_simdgroup_rows(e, rows);
    } else if simd_pipeline.is_some() {
        e.set_threadgroup_memory_length(
            0,
            simd_scratch_bytes.expect("admitted SIMD Q4 scratch length") as u64,
        );
        dispatch_one_simdgroup_per_row(e, rows);
    } else {
        dispatch_1d(e, pipeline, rows);
    }
}

/// Encode one f32-activation × wire-NVFP4 GEMV (GABBRO M3). Same dispatch shape as
/// the Q8/Q4_0 paths (128 threads/TG, NR0=2 rows/TG, 2*32*4 threadgroup mem); only
/// the bound pipeline differs — it reads 36-byte NVFP4 superblocks (64 values:
/// `d[4]` UE4M3 sub-block scales + `qs[32]` E2M1 nibbles) and reproduces the CPU
/// oracle `nvfp4_wire_block_dequant` bit-for-bit. `scalar` holds
/// [blocks_per_row: u32 @0, rows: u32 @4] where blocks_per_row counts 64-value
/// superblocks (in_dim / 64), so `row_stride = blocks_per_row * 36` is exact.
#[cfg(target_os = "macos")]
fn encode_gemma4_nvfp4_matmul(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    y: &Buffer,
    weight: &Buffer,
    out: &Buffer,
    scalar: &Buffer,
    rows: usize,
) {
    e.set_compute_pipeline_state(&k.nvfp4_block_ksplit_f32y_wire_pipeline);
    e.set_buffer(0, Some(y), 0);
    e.set_buffer(2, Some(weight), 0);
    e.set_buffer(3, Some(out), 0);
    e.set_buffer(4, Some(scalar), 0);
    e.set_buffer(5, Some(scalar), 4);
    e.set_threadgroup_memory_length(0, 2 * 32 * 4);
    e.dispatch_thread_groups(
        metal::MTLSize {
            width: (rows as u64).div_ceil(2),
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: 128,
            height: 1,
            depth: 1,
        },
    );
}

/// Encode the gemma4 FFN sub-block into the (serial) encoder with no commit/readback:
/// reads `in_buf` (hidden), writes the residual sum into `out_buf` (hidden):
///   normf = rms_norm(in_buf, ffn_norm)
///   gate  = normf · gate_w   (ffn_dim rows)
///   up    = normf · up_w     (ffn_dim rows)
///   act   = gelu_tanh(gate) * up            (GeGLU)
///   down  = act · down_w     (hidden rows)
///   dn    = rms_norm(down, post_ffw_norm)
///   out   = in_buf + dn
/// vs Llama's FFN this swaps SwiGLU→GeGLU and adds the extra `post_ffw_norm` before
/// the residual. Scratch buffers are pushed into `keep` so they outlive the command
/// buffer. The encoder is serial, so the dependent dispatches need no manual barriers.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_gemma4_ffn(
    fmt: GemmaWireFmt,
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    keep: &mut Vec<Buffer>,
    in_buf: &Buffer,
    out_buf: &Buffer,
    ffn_norm: &[f32],
    post_ffw_norm: &[f32],
    eps: f32,
    gate_w: &Buffer,
    up_w: &Buffer,
    down_w: &Buffer,
    ffn_dim: usize,
) {
    let hidden = ffn_norm.len();
    // GABBRO M3-followup: blocks_per_row counts wire blocks, whose element width is
    // format-specific (32 for Q8_0/Q4_0, 64 for the NVFP4 superblock). The resident
    // NVFP4 GEMV reads row_stride = blocks_per_row * 36, so a hardcoded /32 would
    // double the stride and read past each row.
    let bpr_hidden = hidden / fmt.block_elements();
    let bpr_ffn = ffn_dim / fmt.block_elements();
    let nb = |bytes: u64| pool_get(k, bytes);
    let norm_w = nb((hidden * 4) as u64);
    let postnorm_w = nb((hidden * 4) as u64);
    let rms_scalar = nb(8);
    let gateup_scalar = nb(12);
    let down_scalar = nb(12);
    let geglu_n = nb(4);
    let resid_n = nb(4);
    let normf = nb((hidden * 4) as u64);
    let gate_buf = nb((ffn_dim * 4) as u64);
    let up_buf = nb((ffn_dim * 4) as u64);
    let act_buf = nb((ffn_dim * 4) as u64);
    let down_buf = nb((hidden * 4) as u64);
    let dn_buf = nb((hidden * 4) as u64);

    write_buffer_f32(&norm_w, ffn_norm);
    write_buffer_f32(&postnorm_w, post_ffw_norm);
    unsafe {
        let p = rms_scalar.contents() as *mut u8;
        *(p as *mut u32) = hidden as u32;
        *(p.add(4) as *mut f32) = eps;
        let g = gateup_scalar.contents() as *mut u32;
        *g = bpr_hidden as u32;
        *g.add(1) = ffn_dim as u32;
        let d = down_scalar.contents() as *mut u32;
        *d = bpr_ffn as u32;
        *d.add(1) = hidden as u32;
        *(geglu_n.contents() as *mut u32) = ffn_dim as u32;
        *(resid_n.contents() as *mut u32) = hidden as u32;
    }

    encode_rms_norm_f32(e, k, in_buf, &norm_w, &normf, &rms_scalar);
    encode_gemma4_matmul(
        fmt,
        e,
        k,
        &normf,
        gate_w,
        &gate_buf,
        &gateup_scalar,
        ffn_dim,
    );
    encode_gemma4_matmul(fmt, e, k, &normf, up_w, &up_buf, &gateup_scalar, ffn_dim);
    encode_binary(
        e,
        &k.gelu_mul_pipeline,
        &gate_buf,
        &up_buf,
        &act_buf,
        &geglu_n,
        ffn_dim,
    );
    encode_gemma4_matmul(fmt, e, k, &act_buf, down_w, &down_buf, &down_scalar, hidden);
    encode_rms_norm_f32(e, k, &down_buf, &postnorm_w, &dn_buf, &rms_scalar);
    encode_binary(
        e,
        &k.residual_add_pipeline,
        in_buf,
        &dn_buf,
        out_buf,
        &resid_n,
        hidden,
    );

    keep.extend([
        norm_w,
        postnorm_w,
        rms_scalar,
        gateup_scalar,
        down_scalar,
        geglu_n,
        resid_n,
        normf,
        gate_buf,
        up_buf,
        act_buf,
        down_buf,
        dn_buf,
    ]);
}

/// Encode a per-head RMSNorm (Gemma QK-norm / weightless V-norm) into the encoder:
/// one threadgroup per head normalizes that head's `head_dim` chunk. `scalar` is
/// [head_dim: u32 @0, eps: f32 @4, use_weight: u32 @8]; `weight` may be a dummy when
/// use_weight is 0.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_rms_norm_per_head(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    input: &Buffer,
    weight: &Buffer,
    output: &Buffer,
    scalar: &Buffer,
    head_count: usize,
    // Byte offset applied to the (in-place) input/output buffer so the per-head norm
    // can run on an arbitrary verify row; the per-head `base = head*head_dim` indexing
    // is relative to the bound offset, so the arithmetic is unchanged. Default 0 for all
    // pre-verify callers (no behavior change).
    row_off: u64,
) {
    e.set_compute_pipeline_state(&k.rms_norm_per_head_pipeline);
    e.set_buffer(0, Some(input), row_off);
    e.set_buffer(1, Some(weight), 0);
    e.set_buffer(2, Some(output), row_off);
    e.set_buffer(3, Some(scalar), 0);
    e.set_buffer(4, Some(scalar), 4);
    e.set_buffer(5, Some(scalar), 8);
    e.dispatch_thread_groups(
        metal::MTLSize {
            width: head_count as u64,
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: 256,
            height: 1,
            depth: 1,
        },
    );
}

/// Encode the gemma4 attention sub-block into the (serial) encoder, no readback:
/// reads `in_buf` (hidden), writes the residual sum into `out_buf`:
///   normf = rms_norm(in_buf, attn_norm)
///   q/k/v = normf · {q,k,v}_w
///   per-head QK-norm (q_norm/k_norm) + weightless per-head V-norm
///   RoPE(q), RoPE(k)   (split-half pairing; cos/sin precomputed on CPU for this θ+pos)
///   scatter (roped) k + (normed) v into the cache at `write_position`
///   ctx = decode_attention(q, cache) over the window [window_start .. filled)
///   o   = ctx · o_w
///   out = in_buf + rms_norm(o, post_attn_norm)
/// vs Llama's attention this adds the QK/V per-head norms and the post-attn norm, is
/// always f32y, and windows via `window_start` (sliding layers; 0 = global). The
/// caller owns the weight + cache buffers; scratch goes into `keep`. The basic
/// one-simdgroup-per-head decode kernel is used (gemma head_dim 256/512 > the v2 cap).
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_gemma4_attention(
    fmt: GemmaWireFmt,
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    keep: &mut Vec<Buffer>,
    in_buf: &Buffer,
    out_buf: &Buffer,
    attn_norm: &[f32],
    q_norm: &[f32],
    k_norm: &[f32],
    post_attn_norm: &[f32],
    eps: f32,
    q_w: &Buffer,
    k_w: &Buffer,
    v_w: Option<&Buffer>,
    o_w: &Buffer,
    cos_t: &[f32],
    sin_t: &[f32],
    cache_k_buf: &Buffer,
    cache_v_buf: &Buffer,
    max_positions: usize,
    write_position: usize,
    n_heads: usize,
    n_kv_heads: usize,
    head_dim: usize,
    filled: usize,
    window_start: usize,
    scale: f32,
    owns_kv: bool,
) {
    let hidden = attn_norm.len();
    let q_dim = n_heads * head_dim;
    let kv_dim = n_kv_heads * head_dim;
    let half_rope = cos_t.len();
    // GABBRO M3-followup: format-aware block count (see encode_gemma4_ffn) — /64 for
    // the NVFP4 superblock, /32 for Q8_0/Q4_0 (block_elements()).
    let bpr_hidden = hidden / fmt.block_elements();
    let bpr_q = q_dim / fmt.block_elements();
    let group = (n_heads / n_kv_heads) as u32;
    let position_count = filled - window_start;
    let kv_base_offset = window_start * head_dim;

    let nb = |bytes: u64| pool_get(k, bytes);
    let f32b = |n: usize| nb((n * 4) as u64);
    let norm_w = f32b(hidden);
    let qnorm_w = f32b(head_dim);
    let knorm_w = f32b(head_dim);
    let postnorm_w = f32b(hidden);
    let rms_scalar = nb(8);
    let post_rms_scalar = nb(8);
    let perhead_q = nb(12);
    let perhead_k = nb(12);
    let perhead_v = nb(12);
    let q_mm = nb(8);
    let kv_mm = nb(8);
    let o_mm = nb(8);
    let rope_q = nb(16);
    let rope_k = nb(16);
    let attn_scalar = nb(32);
    let scatter_scalar = nb(16);
    let kv16_write = nb(4);
    let resid_n = nb(4);
    let cos_buf = f32b(half_rope);
    let sin_buf = f32b(half_rope);
    let normf = f32b(hidden);
    let query_buf = f32b(q_dim);
    let key_buf = f32b(kv_dim);
    let val_buf = f32b(kv_dim);
    let qn_buf = f32b(q_dim);
    let kn_buf = f32b(kv_dim);
    let vn_buf = f32b(kv_dim);
    let scores_buf = f32b(n_heads * position_count);
    let ctx_buf = f32b(q_dim);
    let o_buf = f32b(hidden);
    let on_buf = f32b(hidden);

    write_buffer_f32(&norm_w, attn_norm);
    write_buffer_f32(&qnorm_w, q_norm);
    write_buffer_f32(&knorm_w, k_norm);
    write_buffer_f32(&postnorm_w, post_attn_norm);
    write_buffer_f32(&cos_buf, cos_t);
    write_buffer_f32(&sin_buf, sin_t);
    unsafe {
        let set_rms = |buf: &Buffer| {
            let p = buf.contents() as *mut u8;
            *(p as *mut u32) = hidden as u32;
            *(p.add(4) as *mut f32) = eps;
        };
        set_rms(&rms_scalar);
        set_rms(&post_rms_scalar);
        let set_perhead = |buf: &Buffer, use_w: u32| {
            let p = buf.contents() as *mut u8;
            *(p as *mut u32) = head_dim as u32;
            *(p.add(4) as *mut f32) = eps;
            *(p.add(8) as *mut u32) = use_w;
        };
        set_perhead(&perhead_q, 1);
        set_perhead(&perhead_k, 1);
        set_perhead(&perhead_v, 0);
        let set_mm = |buf: &Buffer, bpr: usize, rows: usize| {
            let p = buf.contents() as *mut u32;
            *p = bpr as u32;
            *p.add(1) = rows as u32;
        };
        set_mm(&q_mm, bpr_hidden, q_dim);
        set_mm(&kv_mm, bpr_hidden, kv_dim);
        set_mm(&o_mm, bpr_q, hidden);
        let set_rope = |buf: &Buffer, hc: usize| {
            let r = buf.contents() as *mut u32;
            *r = hc as u32;
            *r.add(1) = head_dim as u32;
            *r.add(2) = half_rope as u32;
            *r.add(3) = 1; // gemma uses split-half pairing
        };
        set_rope(&rope_q, n_heads);
        set_rope(&rope_k, n_kv_heads);
        let a = attn_scalar.contents() as *mut u8;
        *(a as *mut u32) = n_heads as u32;
        *(a.add(4) as *mut u32) = head_dim as u32;
        *(a.add(8) as *mut u32) = position_count as u32;
        *(a.add(12) as *mut u32) = group;
        *(a.add(16) as *mut f32) = scale;
        *(a.add(20) as *mut u32) = head_dim as u32; // position stride
        *(a.add(24) as *mut u32) = (max_positions * head_dim) as u32; // kv_head stride
        *(a.add(28) as *mut u32) = kv_base_offset as u32; // window start offset
        let s = scatter_scalar.contents() as *mut u32;
        *s = head_dim as u32;
        *s.add(1) = max_positions as u32;
        *s.add(2) = write_position as u32;
        *s.add(3) = kv_dim as u32;
        *(kv16_write.contents() as *mut u32) = 0; // gemma keeps the f32 cache
        *(resid_n.contents() as *mut u32) = hidden as u32;
    }

    encode_rms_norm_f32(e, k, in_buf, &norm_w, &normf, &rms_scalar);
    encode_gemma4_matmul(fmt, e, k, &normf, q_w, &query_buf, &q_mm, q_dim);
    encode_rms_norm_per_head(e, k, &query_buf, &qnorm_w, &qn_buf, &perhead_q, n_heads, 0);
    encode_rope(
        e, k, &qn_buf, &cos_buf, &sin_buf, &rope_q, n_heads, half_rope, 0, 0,
    );
    // Owning layers project + cache their own K/V; the trailing cross-shared layers
    // skip all of that and run attention against the source layer's cache
    // (`cache_k_buf`/`cache_v_buf` are the source's, already holding this token).
    if owns_kv {
        encode_gemma4_matmul(fmt, e, k, &normf, k_w, &key_buf, &kv_mm, kv_dim);
        // V source: the layer's own V projection, or — on V-less layers (12B-class
        // full attention, no attn_v tensor) — the RAW K projection output, before
        // k_norm/RoPE touch it (reference: `if v_proj is not present, use Kcur as
        // Vcur`). `key_buf` is never mutated (norms/rope write to kn_buf), so
        // reading it as the V source is safe in the serial encoder.
        let v_src = if let Some(v_w) = v_w {
            encode_gemma4_matmul(fmt, e, k, &normf, v_w, &val_buf, &kv_mm, kv_dim);
            &val_buf
        } else {
            &key_buf
        };
        encode_rms_norm_per_head(e, k, &key_buf, &knorm_w, &kn_buf, &perhead_k, n_kv_heads, 0);
        // Weightless V-norm: qnorm_w is bound as a dummy (use_weight = 0, never read).
        encode_rms_norm_per_head(e, k, v_src, &qnorm_w, &vn_buf, &perhead_v, n_kv_heads, 0);
        encode_rope(
            e, k, &kn_buf, &cos_buf, &sin_buf, &rope_k, n_kv_heads, half_rope, 0, 0,
        );
        // Scatter the roped K and normed V into the cache at write_position. f32 cache
        // only: bind the kv16 mirror slots to a placeholder with the write flag at 0.
        e.set_compute_pipeline_state(&k.kv_scatter_pipeline);
        e.set_buffer(0, Some(&kn_buf), 0);
        e.set_buffer(1, Some(&vn_buf), 0);
        e.set_buffer(2, Some(cache_k_buf), 0);
        e.set_buffer(3, Some(cache_v_buf), 0);
        e.set_buffer(4, Some(&scatter_scalar), 0);
        e.set_buffer(5, Some(&scatter_scalar), 4);
        e.set_buffer(6, Some(&scatter_scalar), 8);
        e.set_buffer(7, Some(&scatter_scalar), 12);
        e.set_buffer(8, Some(&scatter_scalar), 0);
        e.set_buffer(9, Some(&scatter_scalar), 0);
        e.set_buffer(10, Some(&kv16_write), 0);
        dispatch_1d(e, &k.kv_scatter_pipeline, kv_dim);
    }
    encode_attention(
        e,
        k,
        keep,
        &qn_buf,
        cache_k_buf,
        cache_v_buf,
        None,
        &scores_buf,
        &ctx_buf,
        &attn_scalar,
        n_heads,
        n_kv_heads,
        head_dim,
        position_count,
        0,
        0,
    );
    encode_gemma4_matmul(fmt, e, k, &ctx_buf, o_w, &o_buf, &o_mm, hidden);
    encode_rms_norm_f32(e, k, &o_buf, &postnorm_w, &on_buf, &post_rms_scalar);
    encode_binary(
        e,
        &k.residual_add_pipeline,
        in_buf,
        &on_buf,
        out_buf,
        &resid_n,
        hidden,
    );

    keep.extend([
        norm_w,
        qnorm_w,
        knorm_w,
        postnorm_w,
        rms_scalar,
        post_rms_scalar,
        perhead_q,
        perhead_k,
        perhead_v,
        q_mm,
        kv_mm,
        o_mm,
        rope_q,
        rope_k,
        attn_scalar,
        scatter_scalar,
        kv16_write,
        resid_n,
        cos_buf,
        sin_buf,
        normf,
        query_buf,
        key_buf,
        val_buf,
        qn_buf,
        kn_buf,
        vn_buf,
        scores_buf,
        ctx_buf,
        o_buf,
        on_buf,
    ]);
}

/// One gemma4 layer's resident weights: the six f32 norms plus the seven Q8 wire
/// weight buffers (q/k/v/o/gate/up/down) and the layer's dims. Bundling them keeps
/// [`encode_gemma4_layer`] from being a 40-argument call. The weight buffers are
/// built once and reused across tokens. (`from_wire` copies the wire bytes into
/// shared buffers; the production runtime will swap in `q8_wire_nocopy_buffer` over
/// `WirePages` so the 8GB stays single-copy.)
/// One gemma4 layer's resident weights: the six f32 norms plus the seven Q8 wire
/// weight buffers (q/k/v/o/gate/up/down) and the layer's dims. Bundling them keeps
/// [`encode_gemma4_layer`] from being a 40-argument call. The weight buffers are
/// built once and reused across tokens. (`from_wire` copies the wire bytes into
/// shared buffers; the production runtime will swap in `q8_wire_nocopy_buffer` over
/// `WirePages` so the 8GB stays single-copy.)
#[cfg(target_os = "macos")]
pub struct Gemma4ResidentLayer {
    pub attn_norm: Vec<f32>,
    pub q_norm: Vec<f32>,
    pub k_norm: Vec<f32>,
    pub post_attn_norm: Vec<f32>,
    pub ffn_norm: Vec<f32>,
    pub post_ffw_norm: Vec<f32>,
    pub attn_norm_buf: Buffer,
    pub q_norm_buf: Buffer,
    pub k_norm_buf: Buffer,
    pub post_attn_norm_buf: Buffer,
    pub ffn_norm_buf: Buffer,
    pub post_ffw_norm_buf: Buffer,
    pub rms_scalar: Buffer,
    pub post_rms_scalar: Buffer,
    pub perhead_q: Buffer,
    pub perhead_k: Buffer,
    pub perhead_v: Buffer,
    pub q_mm: Buffer,
    pub kv_mm: Buffer,
    pub qkv_scalar: Buffer,
    pub qkv_scalar_batch: Buffer,
    pub o_mm: Buffer,
    pub o_mm_batch: Buffer,
    pub gateup_scalar: Buffer,
    pub gateup_scalar_batch: Buffer,
    pub down_scalar: Buffer,
    pub down_scalar_batch: Buffer,
    pub resid_n: Buffer,
    pub resid_n_batch: Buffer,
    pub geglu_n: Buffer,
    pub rope_q: Buffer,
    pub rope_k: Buffer,
    pub cos_buf: Buffer,
    pub sin_buf: Buffer,
    pub attn_scalar: Buffer,
    pub scatter_scalar: Buffer,
    pub denom_buf: Buffer,
    pub blocks_buf: Buffer,
    pub sliding_window: Option<usize>,
    q_w: Buffer,
    k_w: Buffer,
    /// `None` on V-less layers (12B-class full attention): V is the raw K
    /// projection output, weightless-normed — the reference's `if v_proj is
    /// not present, use Kcur as Vcur`.
    v_w: Option<Buffer>,
    o_w: Buffer,
    gate_w: Buffer,
    up_w: Buffer,
    down_w: Buffer,
    /// Wire format of the q/k/v/o/gate/up/down projection weights. Q8_0 for the
    /// supported dense rows; Q4_0 for QAT rows (the GPU GEMV dispatches on this).
    fmt: GemmaWireFmt,
    pub n_heads: usize,
    pub n_kv_heads: usize,
    pub head_dim: usize,
    pub ffn_dim: usize,
    pub eps: f32,
    /// Lifecycle-owned NoCopy backing used by reloadable Ghost common cores.
    /// The ordinary resident-model constructor still uses the process cache;
    /// this vector is empty there.
    _owned_wire_pages: Vec<std::sync::Arc<crate::wire_mmap::WirePages>>,
}

/// Retained and construction-transient allocations owned solely by one
/// `Gemma4ResidentLayer`, excluding its Q4 `WirePages`. The common-core loader
/// reports these at a phase distinct from both the Q4 pages and the later
/// `Gemma4GhostCommonMetal` KV/router/scratch allocations.
#[cfg(target_os = "macos")]
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub(crate) struct Gemma4ResidentLayerAuxAllocationLedger {
    pub(crate) retained_capacity_bytes: u64,
    pub(crate) retained_explicitly_touched_bytes: u64,
    pub(crate) transient_peak_capacity_bytes: u64,
    pub(crate) transient_peak_explicitly_touched_bytes: u64,
}

#[cfg(target_os = "macos")]
impl Gemma4ResidentLayer {
    /// Exact requested capacities and constructor-side touches for every
    /// non-Q4 allocation retained by this layer. Buffer capacity is the Metal
    /// buffer length; host-vector capacity is `Vec::capacity()`. The transient
    /// peak includes the host RoPE staging vectors used while uploading the
    /// retained cos/sin buffers and, when requested, the generated inverse-
    /// frequency vector. It is not additive with retained capacity.
    pub(crate) fn auxiliary_allocation_ledger(
        &self,
        generated_rope_inv_freqs: bool,
    ) -> Option<Gemma4ResidentLayerAuxAllocationLedger> {
        let host_norm_capacity_bytes = [
            &self.attn_norm,
            &self.q_norm,
            &self.k_norm,
            &self.post_attn_norm,
            &self.ffn_norm,
            &self.post_ffw_norm,
        ]
        .into_iter()
        .try_fold(0u64, |total, values| {
            let bytes = values.capacity().checked_mul(std::mem::size_of::<f32>())?;
            total.checked_add(u64::try_from(bytes).ok()?)
        })?;
        let host_norm_touched_bytes = [
            &self.attn_norm,
            &self.q_norm,
            &self.k_norm,
            &self.post_attn_norm,
            &self.ffn_norm,
            &self.post_ffw_norm,
        ]
        .into_iter()
        .try_fold(0u64, |total, values| {
            let bytes = values.len().checked_mul(std::mem::size_of::<f32>())?;
            total.checked_add(u64::try_from(bytes).ok()?)
        })?;
        let wire_owner_capacity_bytes = self
            ._owned_wire_pages
            .capacity()
            .checked_mul(std::mem::size_of::<
                std::sync::Arc<crate::wire_mmap::WirePages>,
            >())
            .and_then(|bytes| u64::try_from(bytes).ok())?;
        let wire_owner_touched_bytes = self
            ._owned_wire_pages
            .len()
            .checked_mul(std::mem::size_of::<
                std::sync::Arc<crate::wire_mmap::WirePages>,
            >())
            .and_then(|bytes| u64::try_from(bytes).ok())?;

        let norm_buffers = [
            &self.attn_norm_buf,
            &self.q_norm_buf,
            &self.k_norm_buf,
            &self.post_attn_norm_buf,
            &self.ffn_norm_buf,
            &self.post_ffw_norm_buf,
        ];
        let norm_buffer_capacity_bytes = norm_buffers
            .into_iter()
            .try_fold(0u64, |total, buffer| total.checked_add(buffer.length()))?;
        // All six norm buffers are uploaded from the host vectors in full.
        let norm_buffer_touched_bytes = host_norm_touched_bytes;

        let rope_capacity_bytes = self.cos_buf.length().checked_add(self.sin_buf.length())?;
        // Both retained RoPE buffers are uploaded in full.
        let rope_touched_bytes = rope_capacity_bytes;

        let scalar_and_scratch = [
            &self.rms_scalar,
            &self.post_rms_scalar,
            &self.perhead_q,
            &self.perhead_k,
            &self.perhead_v,
            &self.q_mm,
            &self.kv_mm,
            &self.qkv_scalar,
            &self.qkv_scalar_batch,
            &self.o_mm,
            &self.o_mm_batch,
            &self.gateup_scalar,
            &self.gateup_scalar_batch,
            &self.down_scalar,
            &self.down_scalar_batch,
            &self.resid_n,
            &self.resid_n_batch,
            &self.geglu_n,
            &self.rope_q,
            &self.rope_k,
            &self.attn_scalar,
            &self.scatter_scalar,
            &self.denom_buf,
            &self.blocks_buf,
        ];
        let scalar_and_scratch_capacity_bytes = scalar_and_scratch
            .into_iter()
            .try_fold(0u64, |total, buffer| total.checked_add(buffer.length()))?;
        // init_layer_resident_buffers writes: two 8-byte RMS blocks; three
        // 12-byte per-head blocks; q/kv MM (8 each); QKV scalar/batch (16/20);
        // O, gate-up, and down scalar/batch pairs (8/12 each); resid/geglu
        // counts (4 each); and two 16-byte RoPE blocks. The remaining scratch
        // buffers are allocated only until a target forward.
        let scalar_and_scratch_touched_bytes = 204u64;

        let retained_capacity_bytes = host_norm_capacity_bytes
            .checked_add(wire_owner_capacity_bytes)?
            .checked_add(norm_buffer_capacity_bytes)?
            .checked_add(rope_capacity_bytes)?
            .checked_add(scalar_and_scratch_capacity_bytes)?;
        let retained_explicitly_touched_bytes = host_norm_touched_bytes
            .checked_add(wire_owner_touched_bytes)?
            .checked_add(norm_buffer_touched_bytes)?
            .checked_add(rope_touched_bytes)?
            .checked_add(scalar_and_scratch_touched_bytes)?;

        let generated_inv_freq_bytes = if generated_rope_inv_freqs {
            self.head_dim
                .checked_div(2)?
                .checked_mul(std::mem::size_of::<f32>())
                .and_then(|bytes| u64::try_from(bytes).ok())?
        } else {
            0
        };
        let transient_peak_capacity_bytes =
            rope_capacity_bytes.checked_add(generated_inv_freq_bytes)?;

        Some(Gemma4ResidentLayerAuxAllocationLedger {
            retained_capacity_bytes,
            retained_explicitly_touched_bytes,
            // init_layer_resident_buffers builds one host cos table and one host
            // sin table with exactly the retained buffers' element counts. The
            // default common path also generates one inverse-frequency vector.
            // They coexist only during this layer's construction and are freed.
            transient_peak_capacity_bytes,
            transient_peak_explicitly_touched_bytes: transient_peak_capacity_bytes,
        })
    }

    #[inline]
    pub fn window_start(&self, filled: usize) -> usize {
        if let Some(w) = self.sliding_window {
            filled.saturating_sub(w)
        } else {
            0
        }
    }

    /// Build a layer's resident weights from row-major wire bytes (34-byte Q8_0 or
    /// 18-byte Q4_0 blocks per `fmt`) and the f32 norms. None if Metal is unavailable.
    #[allow(clippy::too_many_arguments)]
    pub fn from_wire(
        fmt: GemmaWireFmt,
        attn_norm: Vec<f32>,
        q_norm: Vec<f32>,
        k_norm: Vec<f32>,
        post_attn_norm: Vec<f32>,
        ffn_norm: Vec<f32>,
        post_ffw_norm: Vec<f32>,
        q_wire: &[u8],
        k_wire: &[u8],
        v_wire: Option<&[u8]>,
        o_wire: &[u8],
        gate_wire: &[u8],
        up_wire: &[u8],
        down_wire: &[u8],
        n_heads: usize,
        n_kv_heads: usize,
        head_dim: usize,
        ffn_dim: usize,
        eps: f32,
    ) -> Option<Self> {
        Self::from_wire_with_rope(
            fmt,
            attn_norm,
            q_norm,
            k_norm,
            post_attn_norm,
            ffn_norm,
            post_ffw_norm,
            q_wire,
            k_wire,
            v_wire,
            o_wire,
            gate_wire,
            up_wire,
            down_wire,
            n_heads,
            n_kv_heads,
            head_dim,
            ffn_dim,
            eps,
            None,
            2048,
            None,
        )
    }

    #[allow(clippy::too_many_arguments)]
    pub fn from_wire_with_rope(
        fmt: GemmaWireFmt,
        attn_norm: Vec<f32>,
        q_norm: Vec<f32>,
        k_norm: Vec<f32>,
        post_attn_norm: Vec<f32>,
        ffn_norm: Vec<f32>,
        post_ffw_norm: Vec<f32>,
        q_wire: &[u8],
        k_wire: &[u8],
        v_wire: Option<&[u8]>,
        o_wire: &[u8],
        gate_wire: &[u8],
        up_wire: &[u8],
        down_wire: &[u8],
        n_heads: usize,
        n_kv_heads: usize,
        head_dim: usize,
        ffn_dim: usize,
        eps: f32,
        rope_inv_freqs: Option<&[f32]>,
        max_positions: usize,
        sliding_window: Option<usize>,
    ) -> Option<Self> {
        let k = metal_linear_kernel()?;
        let buf = |bytes: &[u8]| {
            let b = k
                .device
                .new_buffer(bytes.len() as u64, MTLResourceOptions::StorageModeShared);
            write_buffer_u8(&b, bytes);
            b
        };
        let hidden = attn_norm.len();
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv_heads * head_dim;
        let (
            attn_norm_buf,
            q_norm_buf,
            k_norm_buf,
            post_attn_norm_buf,
            ffn_norm_buf,
            post_ffw_norm_buf,
            rms_scalar,
            post_rms_scalar,
            perhead_q,
            perhead_k,
            perhead_v,
            q_mm,
            kv_mm,
            qkv_scalar,
            qkv_scalar_batch,
            o_mm,
            o_mm_batch,
            gateup_scalar,
            gateup_scalar_batch,
            down_scalar,
            down_scalar_batch,
            resid_n,
            resid_n_batch,
            geglu_n,
            rope_q,
            rope_k,
            cos_buf,
            sin_buf,
            attn_scalar,
            scatter_scalar,
            denom_buf,
            blocks_buf,
        ) = init_layer_resident_buffers(
            k,
            &attn_norm,
            &q_norm,
            &k_norm,
            &post_attn_norm,
            &ffn_norm,
            &post_ffw_norm,
            hidden,
            q_dim,
            kv_dim,
            head_dim,
            ffn_dim,
            n_heads,
            n_kv_heads,
            fmt,
            eps,
            rope_inv_freqs,
            max_positions,
        );
        Some(Self {
            attn_norm,
            q_norm,
            k_norm,
            post_attn_norm,
            ffn_norm,
            post_ffw_norm,
            attn_norm_buf,
            q_norm_buf,
            k_norm_buf,
            post_attn_norm_buf,
            ffn_norm_buf,
            post_ffw_norm_buf,
            rms_scalar,
            post_rms_scalar,
            perhead_q,
            perhead_k,
            perhead_v,
            q_mm,
            kv_mm,
            qkv_scalar,
            qkv_scalar_batch,
            o_mm,
            o_mm_batch,
            gateup_scalar,
            gateup_scalar_batch,
            down_scalar,
            down_scalar_batch,
            resid_n,
            resid_n_batch,
            geglu_n,
            rope_q,
            rope_k,
            cos_buf,
            sin_buf,
            attn_scalar,
            scatter_scalar,
            denom_buf,
            blocks_buf,
            sliding_window,
            q_w: buf(q_wire),
            k_w: buf(k_wire),
            v_w: v_wire.map(buf),
            o_w: buf(o_wire),
            gate_w: buf(gate_wire),
            up_w: buf(up_wire),
            down_w: buf(down_wire),
            fmt,
            n_heads,
            n_kv_heads,
            head_dim,
            ffn_dim,
            eps,
            _owned_wire_pages: Vec::new(),
        })
    }

    /// Build a layer's resident weights from per-tensor page-aligned `WirePages`: the
    /// GPU reads them in place via `new_buffer_with_bytes_no_copy` — NO 8GB copy. This
    /// is the production path on a 16GB box (the wire bytes are the single resident
    /// copy). The nocopy cache pins each `WirePages` Arc for the buffer's lifetime.
    #[allow(clippy::too_many_arguments)]
    pub fn from_wire_pages(
        fmt: GemmaWireFmt,
        attn_norm: Vec<f32>,
        q_norm: Vec<f32>,
        k_norm: Vec<f32>,
        post_attn_norm: Vec<f32>,
        ffn_norm: Vec<f32>,
        post_ffw_norm: Vec<f32>,
        q_pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
        k_pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
        v_pages: Option<&std::sync::Arc<crate::wire_mmap::WirePages>>,
        o_pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
        gate_pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
        up_pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
        down_pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
        n_heads: usize,
        n_kv_heads: usize,
        head_dim: usize,
        ffn_dim: usize,
        eps: f32,
    ) -> Option<Self> {
        Self::from_wire_pages_with_rope(
            fmt,
            attn_norm,
            q_norm,
            k_norm,
            post_attn_norm,
            ffn_norm,
            post_ffw_norm,
            q_pages,
            k_pages,
            v_pages,
            o_pages,
            gate_pages,
            up_pages,
            down_pages,
            n_heads,
            n_kv_heads,
            head_dim,
            ffn_dim,
            eps,
            None,
            2048,
            None,
        )
    }

    #[allow(clippy::too_many_arguments)]
    pub fn from_wire_pages_with_rope(
        fmt: GemmaWireFmt,
        attn_norm: Vec<f32>,
        q_norm: Vec<f32>,
        k_norm: Vec<f32>,
        post_attn_norm: Vec<f32>,
        ffn_norm: Vec<f32>,
        post_ffw_norm: Vec<f32>,
        q_pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
        k_pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
        v_pages: Option<&std::sync::Arc<crate::wire_mmap::WirePages>>,
        o_pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
        gate_pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
        up_pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
        down_pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
        n_heads: usize,
        n_kv_heads: usize,
        head_dim: usize,
        ffn_dim: usize,
        eps: f32,
        rope_inv_freqs: Option<&[f32]>,
        max_positions: usize,
        sliding_window: Option<usize>,
    ) -> Option<Self> {
        let k = metal_linear_kernel()?;
        let mut cache = metal_linear_cache().lock().ok()?;
        let mut buf = |pages: &std::sync::Arc<crate::wire_mmap::WirePages>| {
            cache.q8_wire_nocopy_buffer(&k.device, pages)
        };
        let hidden = attn_norm.len();
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv_heads * head_dim;
        let (
            attn_norm_buf,
            q_norm_buf,
            k_norm_buf,
            post_attn_norm_buf,
            ffn_norm_buf,
            post_ffw_norm_buf,
            rms_scalar,
            post_rms_scalar,
            perhead_q,
            perhead_k,
            perhead_v,
            q_mm,
            kv_mm,
            qkv_scalar,
            qkv_scalar_batch,
            o_mm,
            o_mm_batch,
            gateup_scalar,
            gateup_scalar_batch,
            down_scalar,
            down_scalar_batch,
            resid_n,
            resid_n_batch,
            geglu_n,
            rope_q,
            rope_k,
            cos_buf,
            sin_buf,
            attn_scalar,
            scatter_scalar,
            denom_buf,
            blocks_buf,
        ) = init_layer_resident_buffers(
            k,
            &attn_norm,
            &q_norm,
            &k_norm,
            &post_attn_norm,
            &ffn_norm,
            &post_ffw_norm,
            hidden,
            q_dim,
            kv_dim,
            head_dim,
            ffn_dim,
            n_heads,
            n_kv_heads,
            fmt,
            eps,
            rope_inv_freqs,
            max_positions,
        );
        Some(Self {
            attn_norm,
            q_norm,
            k_norm,
            post_attn_norm,
            ffn_norm,
            post_ffw_norm,
            attn_norm_buf,
            q_norm_buf,
            k_norm_buf,
            post_attn_norm_buf,
            ffn_norm_buf,
            post_ffw_norm_buf,
            rms_scalar,
            post_rms_scalar,
            perhead_q,
            perhead_k,
            perhead_v,
            q_mm,
            kv_mm,
            qkv_scalar,
            qkv_scalar_batch,
            o_mm,
            o_mm_batch,
            gateup_scalar,
            gateup_scalar_batch,
            down_scalar,
            down_scalar_batch,
            resid_n,
            resid_n_batch,
            geglu_n,
            rope_q,
            rope_k,
            cos_buf,
            sin_buf,
            attn_scalar,
            scatter_scalar,
            denom_buf,
            blocks_buf,
            sliding_window,
            q_w: buf(q_pages),
            k_w: buf(k_pages),
            v_w: v_pages.map(&mut buf),
            o_w: buf(o_pages),
            gate_w: buf(gate_pages),
            up_w: buf(up_pages),
            down_w: buf(down_pages),
            fmt,
            n_heads,
            n_kv_heads,
            head_dim,
            ffn_dim,
            eps,
            _owned_wire_pages: Vec::new(),
        })
    }

    /// Reload-safe sibling of [`Self::from_wire_pages`]. Each Metal buffer wraps
    /// the supplied page allocation directly and this layer owns the Arcs, so
    /// dropping a partially built or unloaded Ghost runtime releases both the
    /// buffers and their anonymous pages instead of pinning them in the global
    /// linear cache for the lifetime of the process.
    #[allow(clippy::too_many_arguments)]
    pub fn from_wire_pages_owned(
        fmt: GemmaWireFmt,
        attn_norm: Vec<f32>,
        q_norm: Vec<f32>,
        k_norm: Vec<f32>,
        post_attn_norm: Vec<f32>,
        ffn_norm: Vec<f32>,
        post_ffw_norm: Vec<f32>,
        q_pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
        k_pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
        v_pages: Option<&std::sync::Arc<crate::wire_mmap::WirePages>>,
        o_pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
        gate_pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
        up_pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
        down_pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
        n_heads: usize,
        n_kv_heads: usize,
        head_dim: usize,
        ffn_dim: usize,
        eps: f32,
    ) -> Option<Self> {
        Self::from_wire_pages_owned_with_rope(
            fmt,
            attn_norm,
            q_norm,
            k_norm,
            post_attn_norm,
            ffn_norm,
            post_ffw_norm,
            q_pages,
            k_pages,
            v_pages,
            o_pages,
            gate_pages,
            up_pages,
            down_pages,
            n_heads,
            n_kv_heads,
            head_dim,
            ffn_dim,
            eps,
            None,
            2048,
            None,
        )
    }

    #[allow(clippy::too_many_arguments)]
    pub fn from_wire_pages_owned_with_rope(
        fmt: GemmaWireFmt,
        attn_norm: Vec<f32>,
        q_norm: Vec<f32>,
        k_norm: Vec<f32>,
        post_attn_norm: Vec<f32>,
        ffn_norm: Vec<f32>,
        post_ffw_norm: Vec<f32>,
        q_pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
        k_pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
        v_pages: Option<&std::sync::Arc<crate::wire_mmap::WirePages>>,
        o_pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
        gate_pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
        up_pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
        down_pages: &std::sync::Arc<crate::wire_mmap::WirePages>,
        n_heads: usize,
        n_kv_heads: usize,
        head_dim: usize,
        ffn_dim: usize,
        eps: f32,
        rope_inv_freqs: Option<&[f32]>,
        max_positions: usize,
        sliding_window: Option<usize>,
    ) -> Option<Self> {
        let kernel = metal_linear_kernel()?;
        let mut owned_wire_pages = Vec::with_capacity(7);
        let mut buffer = |pages: &std::sync::Arc<crate::wire_mmap::WirePages>| {
            owned_wire_pages.push(std::sync::Arc::clone(pages));
            kernel.device.new_buffer_with_bytes_no_copy(
                pages.base_ptr().cast(),
                pages.alloc_len() as u64,
                MTLResourceOptions::StorageModeShared,
                None,
            )
        };
        let q_w = buffer(q_pages);
        let k_w = buffer(k_pages);
        let v_w = v_pages.map(&mut buffer);
        let o_w = buffer(o_pages);
        let gate_w = buffer(gate_pages);
        let up_w = buffer(up_pages);
        let down_w = buffer(down_pages);
        let hidden = attn_norm.len();
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv_heads * head_dim;
        let (
            attn_norm_buf,
            q_norm_buf,
            k_norm_buf,
            post_attn_norm_buf,
            ffn_norm_buf,
            post_ffw_norm_buf,
            rms_scalar,
            post_rms_scalar,
            perhead_q,
            perhead_k,
            perhead_v,
            q_mm,
            kv_mm,
            qkv_scalar,
            qkv_scalar_batch,
            o_mm,
            o_mm_batch,
            gateup_scalar,
            gateup_scalar_batch,
            down_scalar,
            down_scalar_batch,
            resid_n,
            resid_n_batch,
            geglu_n,
            rope_q,
            rope_k,
            cos_buf,
            sin_buf,
            attn_scalar,
            scatter_scalar,
            denom_buf,
            blocks_buf,
        ) = init_layer_resident_buffers(
            kernel,
            &attn_norm,
            &q_norm,
            &k_norm,
            &post_attn_norm,
            &ffn_norm,
            &post_ffw_norm,
            hidden,
            q_dim,
            kv_dim,
            head_dim,
            ffn_dim,
            n_heads,
            n_kv_heads,
            fmt,
            eps,
            rope_inv_freqs,
            max_positions,
        );
        Some(Self {
            attn_norm,
            q_norm,
            k_norm,
            post_attn_norm,
            ffn_norm,
            post_ffw_norm,
            attn_norm_buf,
            q_norm_buf,
            k_norm_buf,
            post_attn_norm_buf,
            ffn_norm_buf,
            post_ffw_norm_buf,
            rms_scalar,
            post_rms_scalar,
            perhead_q,
            perhead_k,
            perhead_v,
            q_mm,
            kv_mm,
            qkv_scalar,
            qkv_scalar_batch,
            o_mm,
            o_mm_batch,
            gateup_scalar,
            gateup_scalar_batch,
            down_scalar,
            down_scalar_batch,
            resid_n,
            resid_n_batch,
            geglu_n,
            rope_q,
            rope_k,
            cos_buf,
            sin_buf,
            attn_scalar,
            scatter_scalar,
            denom_buf,
            blocks_buf,
            sliding_window,
            q_w,
            k_w,
            v_w,
            o_w,
            gate_w,
            up_w,
            down_w,
            fmt,
            n_heads,
            n_kv_heads,
            head_dim,
            ffn_dim,
            eps,
            _owned_wire_pages: owned_wire_pages,
        })
    }
}

#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn init_layer_resident_buffers(
    k: &MetalLinearKernel,
    attn_norm: &[f32],
    q_norm: &[f32],
    k_norm: &[f32],
    post_attn_norm: &[f32],
    ffn_norm: &[f32],
    post_ffw_norm: &[f32],
    hidden: usize,
    q_dim: usize,
    kv_dim: usize,
    head_dim: usize,
    ffn_dim: usize,
    n_heads: usize,
    n_kv_heads: usize,
    fmt: GemmaWireFmt,
    eps: f32,
    rope_inv_freqs: Option<&[f32]>,
    max_positions: usize,
) -> (
    Buffer,
    Buffer,
    Buffer,
    Buffer,
    Buffer,
    Buffer,
    Buffer,
    Buffer,
    Buffer,
    Buffer,
    Buffer,
    Buffer,
    Buffer,
    Buffer,
    Buffer,
    Buffer,
    Buffer,
    Buffer,
    Buffer,
    Buffer,
    Buffer,
    Buffer,
    Buffer,
    Buffer,
    Buffer,
    Buffer,
    Buffer,
    Buffer,
    Buffer,
    Buffer,
    Buffer,
    Buffer,
) {
    let mkbuf = |bytes: usize| {
        k.device
            .new_buffer(bytes.max(16) as u64, MTLResourceOptions::StorageModeShared)
    };
    let upload = |v: &[f32]| {
        let b = mkbuf(v.len() * 4);
        write_buffer_f32(&b, v);
        b
    };
    let attn_norm_buf = upload(attn_norm);
    let q_norm_buf = upload(q_norm);
    let k_norm_buf = upload(k_norm);
    let post_attn_norm_buf = upload(post_attn_norm);
    let ffn_norm_buf = upload(ffn_norm);
    let post_ffw_norm_buf = upload(post_ffw_norm);

    let rms_scalar = mkbuf(8);
    let post_rms_scalar = mkbuf(8);
    let perhead_q = mkbuf(12);
    let perhead_k = mkbuf(12);
    let perhead_v = mkbuf(12);
    let q_mm = mkbuf(8);
    let kv_mm = mkbuf(8);
    let qkv_scalar = mkbuf(16);
    let qkv_scalar_batch = mkbuf(24);
    let o_mm = mkbuf(8);
    let o_mm_batch = mkbuf(16);
    let gateup_scalar = mkbuf(8);
    let gateup_scalar_batch = mkbuf(16);
    let down_scalar = mkbuf(8);
    let down_scalar_batch = mkbuf(16);
    let resid_n = mkbuf(4);
    let resid_n_batch = mkbuf(4);
    let geglu_n = mkbuf(4);
    let rope_q = mkbuf(16);
    let rope_k = mkbuf(16);
    let half_rope = head_dim / 2;
    let max_pos = max_positions.max(2048);
    let cos_buf = mkbuf(max_pos * half_rope * 4);
    let sin_buf = mkbuf(max_pos * half_rope * 4);
    let inv_freqs_storage: Vec<f32>;
    let inv_freqs: &[f32] = match rope_inv_freqs {
        Some(f) => f,
        None => {
            inv_freqs_storage = (0..half_rope)
                .map(|i| 10000.0f32.powf(-(2.0 * i as f32) / (head_dim as f32)))
                .collect();
            &inv_freqs_storage
        }
    };
    let mut cos_table = Vec::with_capacity(max_pos * half_rope);
    let mut sin_table = Vec::with_capacity(max_pos * half_rope);
    for pos in 0..max_pos {
        let pos_f = pos as f32;
        for &inv_f in inv_freqs {
            let (s, c) = (pos_f * inv_f).sin_cos();
            cos_table.push(c);
            sin_table.push(s);
        }
    }
    write_buffer_f32(&cos_buf, &cos_table);
    write_buffer_f32(&sin_buf, &sin_table);

    let attn_scalar = mkbuf(48);
    let scatter_scalar = mkbuf(16);
    // Batched decode softmax writes denom[cand * n_heads + head]. A single-token
    // buffer overflowed into adjacent GPU allocations at K>1, so even row 0's
    // later layers diverged from sequential step().
    let denom_buf = mkbuf(GEMMA4_RESIDENT_MAX_BATCH * n_heads * 4);
    let blocks_buf = mkbuf(8);

    let bpr_hidden = hidden / fmt.block_elements();
    let bpr_q = q_dim / fmt.block_elements();
    let bpr_ffn = ffn_dim / fmt.block_elements();

    unsafe {
        let set_rms = |buf: &Buffer| {
            let p = buf.contents() as *mut u8;
            *(p as *mut u32) = hidden as u32;
            *(p.add(4) as *mut f32) = eps;
        };
        set_rms(&rms_scalar);
        set_rms(&post_rms_scalar);
        let set_perhead = |buf: &Buffer, use_w: u32| {
            let p = buf.contents() as *mut u8;
            *(p as *mut u32) = head_dim as u32;
            *(p.add(4) as *mut f32) = eps;
            *(p.add(8) as *mut u32) = use_w;
        };
        set_perhead(&perhead_q, 1);
        set_perhead(&perhead_k, 1);
        set_perhead(&perhead_v, 0);
        let set_mm = |buf: &Buffer, bpr: usize, rows: usize| {
            let p = buf.contents() as *mut u32;
            *p = bpr as u32;
            *p.add(1) = rows as u32;
        };
        set_mm(&q_mm, bpr_hidden, q_dim);
        set_mm(&kv_mm, bpr_hidden, kv_dim);
        let qkv_p = qkv_scalar.contents() as *mut u32;
        *qkv_p = bpr_hidden as u32;
        *qkv_p.add(1) = q_dim as u32;
        *qkv_p.add(2) = kv_dim as u32;
        *qkv_p.add(3) = kv_dim as u32;
        let qkv_bp = qkv_scalar_batch.contents() as *mut u32;
        *qkv_bp = bpr_hidden as u32;
        *qkv_bp.add(1) = q_dim as u32;
        *qkv_bp.add(2) = kv_dim as u32;
        *qkv_bp.add(3) = kv_dim as u32;
        *qkv_bp.add(4) = 1;
        set_mm(&o_mm, bpr_q, hidden);
        let obp = o_mm_batch.contents() as *mut u32;
        *obp = bpr_q as u32;
        *obp.add(1) = hidden as u32;
        *obp.add(2) = 1;
        set_mm(&gateup_scalar, bpr_hidden, ffn_dim);
        let gbp = gateup_scalar_batch.contents() as *mut u32;
        *gbp = bpr_hidden as u32;
        *gbp.add(1) = ffn_dim as u32;
        *gbp.add(2) = 1;
        set_mm(&down_scalar, bpr_ffn, hidden);
        let dbp = down_scalar_batch.contents() as *mut u32;
        *dbp = bpr_ffn as u32;
        *dbp.add(1) = hidden as u32;
        *dbp.add(2) = 1;

        let set_rope = |buf: &Buffer, hc: usize| {
            let r = buf.contents() as *mut u32;
            *r = hc as u32;
            *r.add(1) = head_dim as u32;
            *r.add(2) = half_rope as u32;
            *r.add(3) = 1;
        };
        set_rope(&rope_q, n_heads);
        set_rope(&rope_k, n_kv_heads);

        *(resid_n.contents() as *mut u32) = hidden as u32;
        *(geglu_n.contents() as *mut u32) = ffn_dim as u32;
    }

    (
        attn_norm_buf,
        q_norm_buf,
        k_norm_buf,
        post_attn_norm_buf,
        ffn_norm_buf,
        post_ffw_norm_buf,
        rms_scalar,
        post_rms_scalar,
        perhead_q,
        perhead_k,
        perhead_v,
        q_mm,
        kv_mm,
        qkv_scalar,
        qkv_scalar_batch,
        o_mm,
        o_mm_batch,
        gateup_scalar,
        gateup_scalar_batch,
        down_scalar,
        down_scalar_batch,
        resid_n,
        resid_n_batch,
        geglu_n,
        rope_q,
        rope_k,
        cos_buf,
        sin_buf,
        attn_scalar,
        scatter_scalar,
        denom_buf,
        blocks_buf,
    )
}

pub(crate) const GEMMA4_RESIDENT_MAX_BATCH: usize = 64;

/// Default chunk ceiling for the speculative verify round.
///
/// The historical limit was the DENSE batch kernels, not the tied head. The
/// head allocates batch buffers for 16 rows and the resident lane would take
/// 64, but `q4_0_block_linear_batch_k`, `q4_0_qkv_block_linear_batch_k` and
/// `q4_0_gateup_geglu_block_linear_batch_k` each hold a fixed `float
/// sums[4][8]` accumulator and index it with `k_batch`, so any chunk wider than
/// 8 writes past the end of that array and silently corrupts the round.
/// Measured: raising this to 16 without new kernels produced a speculative
/// stream that diverged from greedy at K=9, caught by the lane parity gate.
///
/// K in 9..=16 is now supported by the `_k16` twins in `spec50_widen`
/// (`float sums[4][16]`), which the `encode_gemma4_q4_0_*_batch_k` fns verify
/// at dispatch: a chunk wider than 8 is routed to those pipelines and NEVER to
/// the fixed-depth kernels; a chunk wider than 16 is refused loudly. The
/// runtime ceiling is [`gemma4_max_spec_chunk`]; this constant is its default,
/// so default behavior is exactly the historical K<=8 round.
pub const GEMMA4_MAX_SPEC_CHUNK: usize = 8;

/// Largest speculative chunk implemented by the widened target, MoE, and
/// tied-head kernels.  Keep every user-facing parser tied to this executable
/// contract rather than the larger resident-scratch allocation ceiling.
pub const GEMMA4_MAX_WIDENED_SPEC_CHUNK: usize = 16;

fn parse_gemma4_max_spec_chunk(value: Option<&str>) -> usize {
    value
        .and_then(|raw| raw.parse::<usize>().ok())
        .map(|parsed| parsed.clamp(1, GEMMA4_MAX_WIDENED_SPEC_CHUNK))
        .unwrap_or(GEMMA4_MAX_SPEC_CHUNK)
}

/// Runtime chunk ceiling for the speculative verify round.
///
/// `CAMELID_GEMMA4_SPEC_CHUNK_MAX` (clamped to
/// 1..=[`GEMMA4_MAX_WIDENED_SPEC_CHUNK`]) opts into the widened
/// K=9..16 round; unset, the ceiling is [`GEMMA4_MAX_SPEC_CHUNK`] (8), i.e.
/// exactly today's behavior. Values above 8 require the `spec50_widen` `_k16`
/// pipelines, which the dense encode fns verify at dispatch.
pub fn gemma4_max_spec_chunk() -> usize {
    static CHUNK: std::sync::OnceLock<usize> = std::sync::OnceLock::new();
    *CHUNK.get_or_init(|| {
        let configured = std::env::var("CAMELID_GEMMA4_SPEC_CHUNK_MAX").ok();
        parse_gemma4_max_spec_chunk(configured.as_deref())
    })
}

/// Fixed accumulator depth of the dense `*_batch_k` kernels (`float sums[4][8]`).
pub(crate) const GEMMA4_DENSE_BATCH_K_MAX: usize = 8;

/// Pre-allocated resident activation scratch slab.
#[cfg(target_os = "macos")]
pub struct Gemma4ResidentScratch {
    pub normf: Buffer,
    pub query_buf: Buffer,
    pub key_buf: Buffer,
    pub val_buf: Buffer,
    pub qn_buf: Buffer,
    pub kn_buf: Buffer,
    pub vn_buf: Buffer,
    pub scores_buf: Buffer,
    pub ctx_buf: Buffer,
    pub o_buf: Buffer,
    pub on_buf: Buffer,
    pub gate_buf: Buffer,
    pub up_buf: Buffer,
    pub act_buf: Buffer,
    pub down_buf: Buffer,
    pub dn_buf: Buffer,
    pub normf_batch: Buffer,
    pub query_batch: Buffer,
    pub key_batch: Buffer,
    pub val_batch: Buffer,
    pub qn_batch: Buffer,
    pub kn_batch: Buffer,
    pub vn_batch: Buffer,
    pub ctx_batch: Buffer,
    pub o_batch: Buffer,
    pub on_batch: Buffer,
    pub act_batch: Buffer,
    pub down_batch: Buffer,
    pub dn_batch: Buffer,
    pub kv16_write: Buffer,
    pub ple_gate_buf: Buffer,
    pub ple_gated_buf: Buffer,
    pub ple_proj_out: Buffer,
    pub ple_pnv_buf: Buffer,
    pub ple_summed_buf: Buffer,
    pub cos_buf: Buffer,
    pub sin_buf: Buffer,
    pub cos_global_buf: Buffer,
    pub sin_global_buf: Buffer,
    pub router_logits_batch: Buffer,
    /// spec50 router GEMV scratch (per-token RMS factors + prepared r stream),
    /// sized for the widest chunk, rewritten per layer, shared by all layers.
    pub router_factors: Buffer,
    pub router_r_stage: Buffer,
    pub expert_input_scales_batch: Buffer,
    pub expert_input_quants_batch: Buffer,
    pub gpu_candidate_routes: Vec<Buffer>,
    pub gpu_work_list: Buffer,
    pub gpu_gateup_dispatch_args: Buffer,
    pub gpu_moe_activated: Buffer,
    pub gpu_moe_scales: Buffer,
    pub gpu_moe_quants: Buffer,
    pub gpu_moe_acc: Buffer,
    pub gpu_moe_acc_wave: Buffer,
    pub expert_slot_table_pong: Buffer,
    /// Per-layer wave-1 expert→slot tables so a round-level CB can bind a
    /// distinct table per layer without waiting to reuse `expert_slot_table_pong`.
    pub wave1_slot_tables: Vec<Buffer>,
    /// Per-token RMS inv scales for fused RMSNorm→QKV (K=batch).
    pub rms_inv_batch: Buffer,
}

#[cfg(target_os = "macos")]
impl Gemma4ResidentScratch {
    pub(crate) fn new(
        k: &MetalLinearKernel,
        hidden: usize,
        max_q_dim: usize,
        max_kv_dim: usize,
        max_ffn_dim: usize,
        max_heads: usize,
        max_positions: usize,
        ple_dim: usize,
    ) -> Self {
        let mkbuf = |bytes: usize| {
            k.device
                .new_buffer(bytes.max(16) as u64, MTLResourceOptions::StorageModeShared)
        };
        let f32b = |n: usize| mkbuf(n * 4);
        let kv16_write = mkbuf(4);
        unsafe {
            *(kv16_write.contents() as *mut u32) = 0;
        }
        let gpu_work_list = mkbuf(128 * std::mem::size_of::<Gemma4UniqueExpertWork>());
        let gpu_gateup_dispatch_args = mkbuf(3 * std::mem::size_of::<u32>());
        unsafe {
            let ptr = gpu_work_list.contents() as *mut Gemma4UniqueExpertWork;
            for u in 0..128 {
                *ptr.add(u) = Gemma4UniqueExpertWork {
                    candidate_mask: 0,
                    expert_weight_offset: 0,
                    slab_index: 0,
                };
            }
            let dispatch = gpu_gateup_dispatch_args.contents() as *mut u32;
            *dispatch = 0;
            *dispatch.add(1) = 1;
            *dispatch.add(2) = 1;
        }
        let mb = GEMMA4_RESIDENT_MAX_BATCH;
        let gpu_candidate_routes = (0..30)
            .map(|_| mkbuf(mb * 8 * std::mem::size_of::<Gemma4CandidateRouteEntry>()))
            .collect();
        let max_expert_ffn = 2048;
        Self {
            normf: f32b(hidden),
            query_buf: f32b(max_q_dim),
            key_buf: f32b(max_kv_dim),
            val_buf: f32b(max_kv_dim),
            qn_buf: f32b(max_q_dim),
            kn_buf: f32b(max_kv_dim),
            vn_buf: f32b(max_kv_dim),
            scores_buf: f32b(mb * max_heads * max_positions),
            ctx_buf: f32b(max_q_dim),
            o_buf: f32b(hidden),
            on_buf: f32b(hidden),
            gate_buf: f32b(max_ffn_dim),
            up_buf: f32b(max_ffn_dim),
            act_buf: f32b(max_ffn_dim),
            down_buf: f32b(hidden),
            dn_buf: f32b(hidden),
            normf_batch: f32b(mb * hidden),
            query_batch: f32b(mb * max_q_dim),
            key_batch: f32b(mb * max_kv_dim),
            val_batch: f32b(mb * max_kv_dim),
            qn_batch: f32b(mb * max_q_dim),
            kn_batch: f32b(mb * max_kv_dim),
            vn_batch: f32b(mb * max_kv_dim),
            ctx_batch: f32b(mb * max_q_dim),
            o_batch: f32b(mb * hidden),
            on_batch: f32b(mb * hidden),
            act_batch: f32b(mb * max_ffn_dim),
            down_batch: f32b(mb * hidden),
            dn_batch: f32b(mb * hidden),
            kv16_write,
            ple_gate_buf: f32b(ple_dim.max(1)),
            ple_gated_buf: f32b(ple_dim.max(1)),
            ple_proj_out: f32b(hidden),
            ple_pnv_buf: f32b(hidden),
            ple_summed_buf: f32b(hidden),
            cos_buf: f32b(mb * (max_q_dim / 2).max(128)),
            sin_buf: f32b(mb * (max_q_dim / 2).max(128)),
            cos_global_buf: f32b(mb * (max_q_dim / 2).max(128)),
            sin_global_buf: f32b(mb * (max_q_dim / 2).max(128)),
            router_logits_batch: f32b(30 * mb * 128),
            router_factors: mkbuf(spec50_router_factor_bytes(mb) as usize),
            router_r_stage: mkbuf(spec50_router_r_stage_bytes(mb, hidden) as usize),
            expert_input_scales_batch: f32b(mb * (hidden / 32)),
            expert_input_quants_batch: mkbuf(mb * hidden),
            gpu_candidate_routes,
            gpu_work_list,
            gpu_gateup_dispatch_args,
            gpu_moe_activated: f32b(128 * mb * max_expert_ffn),
            gpu_moe_scales: f32b(128 * mb * (max_expert_ffn / 32)),
            gpu_moe_quants: mkbuf(128 * mb * max_expert_ffn),
            gpu_moe_acc: f32b(mb * hidden),
            gpu_moe_acc_wave: f32b(mb * hidden),
            expert_slot_table_pong: mkbuf(128 * std::mem::size_of::<u32>()),
            wave1_slot_tables: (0..30)
                .map(|_| mkbuf(128 * std::mem::size_of::<u32>()))
                .collect(),
            rms_inv_batch: f32b(mb),
        }
    }

    fn allocation_capacity_bytes(&self) -> u64 {
        let fixed = [
            &self.normf,
            &self.query_buf,
            &self.key_buf,
            &self.val_buf,
            &self.qn_buf,
            &self.kn_buf,
            &self.vn_buf,
            &self.scores_buf,
            &self.ctx_buf,
            &self.o_buf,
            &self.on_buf,
            &self.gate_buf,
            &self.up_buf,
            &self.act_buf,
            &self.down_buf,
            &self.dn_buf,
            &self.normf_batch,
            &self.query_batch,
            &self.key_batch,
            &self.val_batch,
            &self.qn_batch,
            &self.kn_batch,
            &self.vn_batch,
            &self.ctx_batch,
            &self.o_batch,
            &self.on_batch,
            &self.act_batch,
            &self.down_batch,
            &self.dn_batch,
            &self.kv16_write,
            &self.ple_gate_buf,
            &self.ple_gated_buf,
            &self.ple_proj_out,
            &self.ple_pnv_buf,
            &self.ple_summed_buf,
            &self.cos_buf,
            &self.sin_buf,
            &self.cos_global_buf,
            &self.sin_global_buf,
            &self.router_logits_batch,
            &self.router_factors,
            &self.router_r_stage,
            &self.expert_input_scales_batch,
            &self.expert_input_quants_batch,
            &self.gpu_work_list,
            &self.gpu_gateup_dispatch_args,
            &self.gpu_moe_activated,
            &self.gpu_moe_scales,
            &self.gpu_moe_quants,
            &self.gpu_moe_acc,
            &self.gpu_moe_acc_wave,
            &self.expert_slot_table_pong,
            &self.rms_inv_batch,
        ];
        fixed.into_iter().map(|buffer| buffer.length()).sum::<u64>()
            + self
                .gpu_candidate_routes
                .iter()
                .chain(&self.wave1_slot_tables)
                .map(|buffer| buffer.length())
                .sum::<u64>()
    }

    fn explicitly_touched_bytes(&self) -> u64 {
        // Construction initializes the four-byte KV flag, every work-list
        // record, and only the three u32 dispatch arguments. All other scratch
        // buffers are merely allocated until an actual verifier dispatch.
        4 + self.gpu_work_list.length() + 3 * std::mem::size_of::<u32>() as u64
    }
}

// -----------------------------------------------------------------------------
// Gemma 4 26B Ghost-MoE resident common core (Phase 1)
// -----------------------------------------------------------------------------

#[cfg(target_os = "macos")]
const GEMMA4_GHOST_26B_LAYERS: usize = 30;
#[cfg(target_os = "macos")]
const GEMMA4_GHOST_26B_HIDDEN: usize = 2_816;
#[cfg(target_os = "macos")]
const GEMMA4_GHOST_26B_HEADS: usize = 16;
#[cfg(target_os = "macos")]
const GEMMA4_GHOST_26B_SHARED_FF: usize = 2_112;
#[cfg(target_os = "macos")]
const GEMMA4_GHOST_26B_SLIDING_WINDOW: usize = 1_024;
#[cfg(target_os = "macos")]
const GEMMA4_GHOST_26B_LOCAL_HEAD_DIM: usize = 256;
#[cfg(target_os = "macos")]
const GEMMA4_GHOST_26B_LOCAL_KV_HEADS: usize = 8;
#[cfg(target_os = "macos")]
const GEMMA4_GHOST_26B_GLOBAL_HEAD_DIM: usize = 512;
#[cfg(target_os = "macos")]
const GEMMA4_GHOST_26B_GLOBAL_KV_HEADS: usize = 2;
#[cfg(target_os = "macos")]
const GEMMA4_GHOST_26B_GLOBAL_LAYERS: [usize; 5] = [5, 11, 17, 23, 29];

// Official Gemma 4 MTP assistants borrow the final target layer of each
// attention flavor: layer 28 for sliding attention and layer 29 for full
// attention. Keep this mapping adjacent to the target geometry contract so a
// future schedule change cannot silently select unrelated cache storage.
#[cfg(target_os = "macos")]
const GEMMA4_GHOST_26B_MTP_SLIDING_LAYER: usize = GEMMA4_GHOST_26B_LAYERS - 2;
#[cfg(target_os = "macos")]
const GEMMA4_GHOST_26B_MTP_FULL_LAYER: usize = GEMMA4_GHOST_26B_LAYERS - 1;

#[cfg(target_os = "macos")]
fn gemma4_mtp_target_layer_indices(is_sliding: &[bool]) -> Option<(usize, usize)> {
    if is_sliding.len() != GEMMA4_GHOST_26B_LAYERS
        || !is_sliding[GEMMA4_GHOST_26B_MTP_SLIDING_LAYER]
        || is_sliding[GEMMA4_GHOST_26B_MTP_FULL_LAYER]
    {
        return None;
    }
    Some((
        GEMMA4_GHOST_26B_MTP_SLIDING_LAYER,
        GEMMA4_GHOST_26B_MTP_FULL_LAYER,
    ))
}

#[cfg(target_os = "macos")]
fn gemma4_mtp_logical_kv_len(next_position: &[usize], kv_capacity: usize) -> Option<usize> {
    let (&logical_len, rest) = next_position.split_first()?;
    (logical_len <= kv_capacity && rest.iter().all(|&position| position == logical_len))
        .then_some(logical_len)
}

/// Host-visible command-buffer stage emitted by [`Gemma4GhostCommonMetal`].
#[cfg(target_os = "macos")]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum Gemma4GhostCommonStage {
    Attention,
    AttentionRouter,
    Router,
    SharedBranch,
}

/// Timing and traffic evidence for one common-core command buffer. GPU/kernel
/// timestamps exclude any overlapped expert I/O; `wall_us` intentionally includes
/// the time between enqueue and wait so the caller can measure that overlap too.
#[cfg(target_os = "macos")]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct Gemma4GhostCommonDiagnostics {
    pub(crate) stage: Gemma4GhostCommonStage,
    pub(crate) layer: usize,
    pub(crate) position: usize,
    pub(crate) encode_us: u128,
    pub(crate) wait_us: u128,
    pub(crate) wall_us: u128,
    pub(crate) gpu_us: u128,
    pub(crate) kernel_us: u128,
    pub(crate) command_buffers: u32,
    pub(crate) dispatches: u32,
    pub(crate) streamed_weight_bytes: u64,
    pub(crate) readback_bytes: u64,
}

#[cfg(target_os = "macos")]
impl Gemma4GhostCommonDiagnostics {
    pub(crate) fn effective_gib_per_s(self) -> f64 {
        if self.gpu_us == 0 {
            return 0.0;
        }
        self.streamed_weight_bytes as f64
            / (1024.0 * 1024.0 * 1024.0)
            / (self.gpu_us as f64 / 1_000_000.0)
    }
}

