#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_vision_diagnostics(
    encoder: &metal::ComputeCommandEncoderRef,
    kernel: &MetalLinearKernel,
    values: &Buffer,
    metrics: &Buffer,
    scalars: &Buffer,
    total: usize,
    label: String,
    labels: &mut Vec<String>,
) {
    let slot = labels.len();
    unsafe {
        let p = (scalars.contents() as *mut u8).add(slot * 8) as *mut u32;
        *p = total as u32;
        *p.add(1) = slot as u32;
    }
    labels.push(label);
    encoder.set_compute_pipeline_state(&kernel.vision_diagnostics_pipeline);
    encoder.set_buffer(0, Some(values), 0);
    encoder.set_buffer(1, Some(metrics), 0);
    encoder.set_buffer(2, Some(scalars), (slot * 8) as u64);
    encoder.set_buffer(3, Some(scalars), (slot * 8 + 4) as u64);
    encoder.dispatch_thread_groups(
        metal::MTLSize {
            width: 1,
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: 1,
            height: 1,
            depth: 1,
        },
    );
}

#[cfg(target_os = "macos")]
impl PrismVisionMetalEncoder {
    #[allow(clippy::too_many_arguments)]
    pub(crate) fn new(
        config: PrismVisionMetalConfig,
        patch_0: ResidentWeightBytes<'_>,
        patch_1: ResidentWeightBytes<'_>,
        patch_bias: &[f32],
        layers: &[PrismVisionMetalLayerInput<'_>],
        post_weight: &[f32],
        post_bias: &[f32],
        merger_0: ResidentWeightBytes<'_>,
        merger_0_bias: &[f32],
        merger_2: ResidentWeightBytes<'_>,
        merger_2_bias: &[f32],
    ) -> Option<Self> {
        let c = config;
        let merged = c.hidden * c.merge * c.merge;
        if c.patch_input == 0
            || c.hidden == 0
            || c.ffn == 0
            || c.heads == 0
            || !c.hidden.is_multiple_of(c.heads)
            || c.merge != 2
            || c.projection == 0
            || patch_bias.len() != c.hidden
            || post_weight.len() != c.hidden
            || post_bias.len() != c.hidden
            || merger_0_bias.len() != merged
            || merger_2_bias.len() != c.projection
            || !patch_0.matches_shape(c.patch_input, c.hidden)
            || !patch_1.matches_shape(c.patch_input, c.hidden)
            || !merger_0.matches_shape(merged, merged)
            || !merger_2.matches_shape(merged, c.projection)
            || layers.is_empty()
        {
            return None;
        }
        let kernel = metal_linear_kernel()?;
        let mut cache = metal_linear_cache().lock().ok()?;
        let mut resident_layers = Vec::with_capacity(layers.len());
        for layer in layers {
            if layer.ln1_weight.len() != c.hidden
                || layer.ln1_bias.len() != c.hidden
                || layer.qkv_bias.len() != 3 * c.hidden
                || layer.attn_output_bias.len() != c.hidden
                || layer.ln2_weight.len() != c.hidden
                || layer.ln2_bias.len() != c.hidden
                || layer.ffn_up_bias.len() != c.ffn
                || layer.ffn_down_bias.len() != c.hidden
                || !layer.qkv.matches_shape(c.hidden, 3 * c.hidden)
                || !layer.attn_output.matches_shape(c.hidden, c.hidden)
                || !layer.ffn_up.matches_shape(c.hidden, c.ffn)
                || !layer.ffn_down.matches_shape(c.ffn, c.hidden)
            {
                return None;
            }
            resident_layers.push(PrismVisionMetalLayer {
                ln1_weight: qwen35_f32_buffer(kernel, layer.ln1_weight),
                ln1_bias: qwen35_f32_buffer(kernel, layer.ln1_bias),
                qkv: resolve_resident_weight(&mut cache, &kernel.device, &layer.qkv, true)?,
                qkv_bias: qwen35_f32_buffer(kernel, layer.qkv_bias),
                attn_output: resolve_resident_weight(
                    &mut cache,
                    &kernel.device,
                    &layer.attn_output,
                    true,
                )?,
                attn_output_bias: qwen35_f32_buffer(kernel, layer.attn_output_bias),
                ln2_weight: qwen35_f32_buffer(kernel, layer.ln2_weight),
                ln2_bias: qwen35_f32_buffer(kernel, layer.ln2_bias),
                ffn_up: resolve_resident_weight(&mut cache, &kernel.device, &layer.ffn_up, true)?,
                ffn_up_bias: qwen35_f32_buffer(kernel, layer.ffn_up_bias),
                ffn_down: resolve_resident_weight(
                    &mut cache,
                    &kernel.device,
                    &layer.ffn_down,
                    true,
                )?,
                ffn_down_bias: qwen35_f32_buffer(kernel, layer.ffn_down_bias),
            });
        }
        let patch_0 = resolve_resident_weight(&mut cache, &kernel.device, &patch_0, true)?;
        let patch_1 = resolve_resident_weight(&mut cache, &kernel.device, &patch_1, true)?;
        let merger_0 = resolve_resident_weight(&mut cache, &kernel.device, &merger_0, true)?;
        let merger_2 = resolve_resident_weight(&mut cache, &kernel.device, &merger_2, true)?;
        drop(cache);
        Some(Self {
            config,
            patch_0,
            patch_1,
            patch_bias: qwen35_f32_buffer(kernel, patch_bias),
            layers: resident_layers,
            post_weight: qwen35_f32_buffer(kernel, post_weight),
            post_bias: qwen35_f32_buffer(kernel, post_bias),
            merger_0,
            merger_0_bias: qwen35_f32_buffer(kernel, merger_0_bias),
            merger_2,
            merger_2_bias: qwen35_f32_buffer(kernel, merger_2_bias),
        })
    }

    pub(crate) fn encode(
        &mut self,
        patches: &[f32],
        position: &[f32],
        patch_width: usize,
        patch_height: usize,
    ) -> Option<Vec<Vec<f32>>> {
        let c = self.config;
        let tokens = patch_width.checked_mul(patch_height)?;
        if tokens == 0
            || tokens > 4096
            || !patch_width.is_multiple_of(c.merge)
            || !patch_height.is_multiple_of(c.merge)
            || patches.len() != tokens * c.patch_input
            || position.len() != tokens * c.hidden
        {
            return None;
        }
        let output_tokens = tokens / (c.merge * c.merge);
        let merged = c.hidden * c.merge * c.merge;
        let head_dim = c.hidden / c.heads;
        if !head_dim.is_multiple_of(2) {
            return None;
        }
        let kernel = metal_linear_kernel()?;
        let buffer = |floats: usize| qwen35_zero_buffer(kernel, floats * 4);
        let patch_input = qwen35_f32_buffer(kernel, patches);
        let position_buffer = qwen35_f32_buffer(kernel, position);
        let patch_first = buffer(tokens * c.hidden);
        let patch_second = buffer(tokens * c.hidden);
        let hidden_a = buffer(tokens * c.hidden);
        let hidden_b = buffer(tokens * c.hidden);
        let normalized = buffer(tokens * c.hidden);
        let qkv = buffer(tokens * 3 * c.hidden);
        let attention = buffer(tokens * c.hidden);
        let projected = buffer(tokens * c.hidden);
        let ffn = buffer(tokens * c.ffn);
        let merger_hidden = buffer(output_tokens * merged);
        let result = buffer(output_tokens * c.projection);

        let scalar = |input: usize, rows: usize, count: usize| {
            let value = qwen35_zero_buffer(kernel, 12);
            unsafe {
                let p = value.contents() as *mut u32;
                *p = input as u32;
                *p.add(1) = rows as u32;
                *p.add(2) = count as u32;
            }
            value
        };
        let patch_mm = scalar(c.patch_input, c.hidden, tokens);
        let qkv_mm = scalar(c.hidden, 3 * c.hidden, tokens);
        let hidden_mm = scalar(c.hidden, c.hidden, tokens);
        let ffn_up_mm = scalar(c.hidden, c.ffn, tokens);
        let ffn_down_mm = scalar(c.ffn, c.hidden, tokens);
        let merger_0_mm = scalar(merged, merged, output_tokens);
        let merger_2_mm = scalar(merged, c.projection, output_tokens);
        let element_scalar = |width: usize, total: usize| {
            let value = qwen35_zero_buffer(kernel, 8);
            unsafe {
                let p = value.contents() as *mut u32;
                *p = width as u32;
                *p.add(1) = total as u32;
            }
            value
        };
        let hidden_element = element_scalar(c.hidden, tokens * c.hidden);
        let qkv_element = element_scalar(3 * c.hidden, tokens * 3 * c.hidden);
        let ffn_element = element_scalar(c.ffn, tokens * c.ffn);
        let merged_element = element_scalar(merged, output_tokens * merged);
        let projection_element = element_scalar(c.projection, output_tokens * c.projection);
        let norm_scalar = qwen35_zero_buffer(kernel, 8);
        unsafe {
            let p = norm_scalar.contents() as *mut u8;
            *(p as *mut u32) = c.hidden as u32;
            *(p.add(4) as *mut f32) = c.eps;
        }
        let (cosine, sine) = vision_rope_tables(patch_width, patch_height, c.merge, head_dim);
        let cosine = qwen35_f32_buffer(kernel, &cosine);
        let sine = qwen35_f32_buffer(kernel, &sine);
        let rope_scalar = qwen35_zero_buffer(kernel, 16);
        unsafe {
            let p = rope_scalar.contents() as *mut u32;
            *p = c.hidden as u32;
            *p.add(1) = c.heads as u32;
            *p.add(2) = head_dim as u32;
            *p.add(3) = tokens as u32;
        }
        let attention_scalar = qwen35_zero_buffer(kernel, 28);
        unsafe {
            let p = attention_scalar.contents() as *mut u8;
            *(p as *mut u32) = c.hidden as u32;
            *(p.add(4) as *mut u32) = c.heads as u32;
            *(p.add(8) as *mut u32) = head_dim as u32;
            *(p.add(12) as *mut u32) = tokens as u32;
            *(p.add(16) as *mut f32) = 1.0 / (head_dim as f32).sqrt();
        }

        let command = kernel.queue.new_command_buffer();
        let encoder = command.new_compute_command_encoder();
        let mut keep = Vec::new();
        let trace = std::env::var("CAMELID_VISION_TRACE")
            .is_ok_and(|value| value == "1" || value.eq_ignore_ascii_case("true"));
        let max_trace_slots = 4 * self.layers.len() + 8;
        let trace_metrics = trace.then(|| buffer(max_trace_slots * 3));
        let trace_scalars = trace.then(|| qwen35_zero_buffer(kernel, max_trace_slots * 8));
        let mut trace_labels = Vec::new();
        encode_resident_matmul_f32(
            encoder,
            kernel,
            &mut keep,
            &patch_input,
            &self.patch_0,
            &patch_first,
            &patch_mm,
            c.patch_input,
            c.hidden,
            tokens,
        );
        encode_resident_matmul_f32(
            encoder,
            kernel,
            &mut keep,
            &patch_input,
            &self.patch_1,
            &patch_second,
            &patch_mm,
            c.patch_input,
            c.hidden,
            tokens,
        );
        encoder.set_compute_pipeline_state(&kernel.vision_patch_sum_pipeline);
        encoder.set_buffer(0, Some(&patch_first), 0);
        encoder.set_buffer(1, Some(&patch_second), 0);
        encoder.set_buffer(2, Some(&self.patch_bias), 0);
        encoder.set_buffer(3, Some(&position_buffer), 0);
        encoder.set_buffer(4, Some(&hidden_a), 0);
        encoder.set_buffer(5, Some(&hidden_element), 0);
        encoder.set_buffer(6, Some(&hidden_element), 4);
        dispatch_1d(
            encoder,
            &kernel.vision_patch_sum_pipeline,
            tokens * c.hidden,
        );
        if let (Some(metrics), Some(scalars)) = (&trace_metrics, &trace_scalars) {
            encode_vision_diagnostics(
                encoder,
                kernel,
                &hidden_a,
                metrics,
                scalars,
                tokens * c.hidden,
                "patch+position".into(),
                &mut trace_labels,
            );
        }

        let attention_scratch = (tokens + 1) * 4;
        assert_threadgroup_fits(
            &kernel.device,
            attention_scratch,
            "Qwen3-VL attention scores",
        );
        for (layer_index, layer) in self.layers.iter().enumerate() {
            encode_vision_layer_norm(
                encoder,
                kernel,
                &hidden_a,
                &layer.ln1_weight,
                &layer.ln1_bias,
                &normalized,
                &norm_scalar,
                tokens,
            );
            encode_resident_matmul_f32(
                encoder,
                kernel,
                &mut keep,
                &normalized,
                &layer.qkv,
                &qkv,
                &qkv_mm,
                c.hidden,
                3 * c.hidden,
                tokens,
            );
            encode_vision_bias(
                encoder,
                kernel,
                &qkv,
                &layer.qkv_bias,
                &qkv_element,
                tokens * 3 * c.hidden,
            );
            encoder.set_compute_pipeline_state(&kernel.vision_rope_pipeline);
            encoder.set_buffer(0, Some(&qkv), 0);
            encoder.set_buffer(1, Some(&cosine), 0);
            encoder.set_buffer(2, Some(&sine), 0);
            encoder.set_buffer(3, Some(&rope_scalar), 0);
            encoder.set_buffer(4, Some(&rope_scalar), 4);
            encoder.set_buffer(5, Some(&rope_scalar), 8);
            encoder.set_buffer(6, Some(&rope_scalar), 12);
            dispatch_1d(
                encoder,
                &kernel.vision_rope_pipeline,
                tokens * c.heads * (head_dim / 2),
            );
            if let (Some(metrics), Some(scalars)) = (&trace_metrics, &trace_scalars) {
                encode_vision_diagnostics(
                    encoder,
                    kernel,
                    &qkv,
                    metrics,
                    scalars,
                    tokens * 3 * c.hidden,
                    format!("layer {layer_index} qkv+rope"),
                    &mut trace_labels,
                );
            }
            encoder.set_compute_pipeline_state(&kernel.vision_attention_pipeline);
            encoder.set_buffer(0, Some(&qkv), 0);
            encoder.set_buffer(1, Some(&attention), 0);
            encoder.set_buffer(2, Some(&attention_scalar), 0);
            encoder.set_buffer(3, Some(&attention_scalar), 4);
            encoder.set_buffer(4, Some(&attention_scalar), 8);
            encoder.set_buffer(5, Some(&attention_scalar), 12);
            encoder.set_buffer(6, Some(&attention_scalar), 16);
            encoder.set_threadgroup_memory_length(0, attention_scratch as u64);
            encoder.dispatch_thread_groups(
                metal::MTLSize {
                    width: tokens as u64,
                    height: c.heads as u64,
                    depth: 1,
                },
                metal::MTLSize {
                    width: 128,
                    height: 1,
                    depth: 1,
                },
            );
            if let (Some(metrics), Some(scalars)) = (&trace_metrics, &trace_scalars) {
                encode_vision_diagnostics(
                    encoder,
                    kernel,
                    &attention,
                    metrics,
                    scalars,
                    tokens * c.hidden,
                    format!("layer {layer_index} attention"),
                    &mut trace_labels,
                );
            }
            encode_resident_matmul_f32(
                encoder,
                kernel,
                &mut keep,
                &attention,
                &layer.attn_output,
                &projected,
                &hidden_mm,
                c.hidden,
                c.hidden,
                tokens,
            );
            encode_vision_bias_residual(
                encoder,
                kernel,
                &hidden_a,
                &projected,
                &layer.attn_output_bias,
                &hidden_b,
                &hidden_element,
                tokens * c.hidden,
            );
            encode_vision_layer_norm(
                encoder,
                kernel,
                &hidden_b,
                &layer.ln2_weight,
                &layer.ln2_bias,
                &normalized,
                &norm_scalar,
                tokens,
            );
            encode_resident_matmul_f32(
                encoder,
                kernel,
                &mut keep,
                &normalized,
                &layer.ffn_up,
                &ffn,
                &ffn_up_mm,
                c.hidden,
                c.ffn,
                tokens,
            );
            encode_vision_bias_gelu(
                encoder,
                kernel,
                &ffn,
                &layer.ffn_up_bias,
                &ffn_element,
                tokens * c.ffn,
            );
            encode_resident_matmul_f32(
                encoder,
                kernel,
                &mut keep,
                &ffn,
                &layer.ffn_down,
                &projected,
                &ffn_down_mm,
                c.ffn,
                c.hidden,
                tokens,
            );
            encode_vision_bias_residual(
                encoder,
                kernel,
                &hidden_b,
                &projected,
                &layer.ffn_down_bias,
                &hidden_a,
                &hidden_element,
                tokens * c.hidden,
            );
            if let (Some(metrics), Some(scalars)) = (&trace_metrics, &trace_scalars) {
                encode_vision_diagnostics(
                    encoder,
                    kernel,
                    &hidden_a,
                    metrics,
                    scalars,
                    tokens * c.hidden,
                    format!("layer {layer_index} output"),
                    &mut trace_labels,
                );
            }
        }

        encode_vision_layer_norm(
            encoder,
            kernel,
            &hidden_a,
            &self.post_weight,
            &self.post_bias,
            &normalized,
            &norm_scalar,
            tokens,
        );
        if let (Some(metrics), Some(scalars)) = (&trace_metrics, &trace_scalars) {
            encode_vision_diagnostics(
                encoder,
                kernel,
                &normalized,
                metrics,
                scalars,
                tokens * c.hidden,
                "post norm".into(),
                &mut trace_labels,
            );
        }
        encode_resident_matmul_f32(
            encoder,
            kernel,
            &mut keep,
            &normalized,
            &self.merger_0,
            &merger_hidden,
            &merger_0_mm,
            merged,
            merged,
            output_tokens,
        );
        if let (Some(metrics), Some(scalars)) = (&trace_metrics, &trace_scalars) {
            encode_vision_diagnostics(
                encoder,
                kernel,
                &merger_hidden,
                metrics,
                scalars,
                output_tokens * merged,
                "merger linear".into(),
                &mut trace_labels,
            );
        }
        encode_vision_bias_gelu(
            encoder,
            kernel,
            &merger_hidden,
            &self.merger_0_bias,
            &merged_element,
            output_tokens * merged,
        );
        if let (Some(metrics), Some(scalars)) = (&trace_metrics, &trace_scalars) {
            encode_vision_diagnostics(
                encoder,
                kernel,
                &merger_hidden,
                metrics,
                scalars,
                output_tokens * merged,
                "merger gelu".into(),
                &mut trace_labels,
            );
        }
        encode_resident_matmul_f32(
            encoder,
            kernel,
            &mut keep,
            &merger_hidden,
            &self.merger_2,
            &result,
            &merger_2_mm,
            merged,
            c.projection,
            output_tokens,
        );
        encode_vision_bias(
            encoder,
            kernel,
            &result,
            &self.merger_2_bias,
            &projection_element,
            output_tokens * c.projection,
        );
        if let (Some(metrics), Some(scalars)) = (&trace_metrics, &trace_scalars) {
            encode_vision_diagnostics(
                encoder,
                kernel,
                &result,
                metrics,
                scalars,
                output_tokens * c.projection,
                "projected image".into(),
                &mut trace_labels,
            );
        }
        encoder.end_encoding();
        command.commit();
        command.wait_until_completed();
        let mut output = vec![0.0f32; output_tokens * c.projection];
        read_buffer_f32(&result, &mut output);
        if let Some(metrics) = &trace_metrics {
            let mut values = vec![0.0f32; trace_labels.len() * 3];
            read_buffer_f32(metrics, &mut values);
            for (label, metric) in trace_labels.iter().zip(values.chunks_exact(3)) {
                eprintln!(
                    "[qwen3vl trace] {label}: invalid={} max={:.6} l2={:.6}",
                    metric[0] as usize, metric[1], metric[2]
                );
            }
        }
        pool_recycle(kernel, keep);
        Some(
            output
                .chunks_exact(c.projection)
                .map(<[f32]>::to_vec)
                .collect(),
        )
    }
}

#[cfg(target_os = "macos")]
fn vision_rope_tables(
    patch_width: usize,
    patch_height: usize,
    merge: usize,
    head_dim: usize,
) -> (Vec<f32>, Vec<f32>) {
    let half = head_dim / 2;
    let section = half / 2;
    let mut cosine = Vec::with_capacity(patch_width * patch_height * half);
    let mut sine = Vec::with_capacity(cosine.capacity());
    for tile_y in (0..patch_height).step_by(merge) {
        for tile_x in (0..patch_width).step_by(merge) {
            for dy in 0..merge {
                for dx in 0..merge {
                    for pair in 0..half {
                        let (position, dimension) = if pair < section {
                            ((tile_y + dy) as f32, pair)
                        } else {
                            ((tile_x + dx) as f32, pair - section)
                        };
                        let angle =
                            position * 10_000.0f32.powf(-2.0 * dimension as f32 / half as f32);
                        cosine.push(angle.cos());
                        sine.push(angle.sin());
                    }
                }
            }
        }
    }
    (cosine, sine)
}

#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_qwen35_full_layer(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    keep: &mut Vec<Buffer>,
    input: &Buffer,
    output: &Buffer,
    layer: &Qwen35MetalLayer,
    cos: &Buffer,
    sin: &Buffer,
    c: Qwen35MetalConfig,
    max_positions: usize,
    position: usize,
) {
    let Qwen35MetalLayerKind::Full {
        q: q_weight,
        k: k_weight,
        v: v_weight,
        output: o_weight,
        q_norm,
        k_norm,
        cache_k,
        cache_v,
    } = &layer.kind
    else {
        unreachable!()
    };
    let q_dim = c.n_heads * c.head_dim;
    let kv_dim = c.n_kv_heads * c.head_dim;
    let filled = position + 1;
    let normed = pool_get(k, (c.hidden * 4) as u64);
    let q_fused = pool_get(k, (2 * q_dim * 4) as u64);
    let query = pool_get(k, (q_dim * 4) as u64);
    let gate = pool_get(k, (q_dim * 4) as u64);
    let key = pool_get(k, (kv_dim * 4) as u64);
    let value = pool_get(k, (kv_dim * 4) as u64);
    let scores = pool_get(k, (c.n_heads * filled * 4) as u64);
    let context = pool_get(k, (q_dim * 4) as u64);
    let mix = pool_get(k, (c.hidden * 4) as u64);
    let norm_scalar = pool_get(k, 8);
    let q_mm = pool_get(k, 12);
    let kv_mm = pool_get(k, 12);
    let o_mm = pool_get(k, 12);
    let split_scalar = pool_get(k, 8);
    let qk_norm_scalar = pool_get(k, 12);
    let q_rope = pool_get(k, 16);
    let k_rope = pool_get(k, 16);
    let scatter_scalar = pool_get(k, 16);
    let mirror_flag = pool_get(k, 4);
    let attn_scalar = pool_get(k, 32);
    let n_q = pool_get(k, 4);
    let n_hidden = pool_get(k, 4);
    unsafe {
        let p = norm_scalar.contents() as *mut u8;
        *(p as *mut u32) = c.hidden as u32;
        *(p.add(4) as *mut f32) = c.eps;
        let s = split_scalar.contents() as *mut u32;
        *s = c.head_dim as u32;
        *s.add(1) = q_dim as u32;
        let n = qk_norm_scalar.contents() as *mut u8;
        *(n as *mut u32) = c.head_dim as u32;
        *(n.add(4) as *mut f32) = c.eps;
        *(n.add(8) as *mut u32) = 1;
        let set_rope = |buffer: &Buffer, heads: usize| {
            let r = buffer.contents() as *mut u32;
            *r = heads as u32;
            *r.add(1) = c.head_dim as u32;
            *r.add(2) = (c.rope_dim / 2) as u32;
            *r.add(3) = 1;
        };
        set_rope(&q_rope, c.n_heads);
        set_rope(&k_rope, c.n_kv_heads);
        let sc = scatter_scalar.contents() as *mut u32;
        *sc = c.head_dim as u32;
        *sc.add(1) = max_positions as u32;
        *sc.add(2) = position as u32;
        *sc.add(3) = kv_dim as u32;
        *(mirror_flag.contents() as *mut u32) = 0;
        let a = attn_scalar.contents() as *mut u8;
        *(a as *mut u32) = c.n_heads as u32;
        *(a.add(4) as *mut u32) = c.head_dim as u32;
        *(a.add(8) as *mut u32) = filled as u32;
        *(a.add(12) as *mut u32) = (c.n_heads / c.n_kv_heads) as u32;
        *(a.add(16) as *mut f32) = 1.0 / (c.head_dim as f32).sqrt();
        *(a.add(20) as *mut u32) = c.head_dim as u32;
        *(a.add(24) as *mut u32) = (max_positions * c.head_dim) as u32;
        *(a.add(28) as *mut u32) = 0;
        *(n_q.contents() as *mut u32) = q_dim as u32;
        *(n_hidden.contents() as *mut u32) = c.hidden as u32;
    }
    encode_rms_norm_f32(e, k, input, &layer.attn_norm, &normed, &norm_scalar);
    encode_resident_matmul_f32(
        e,
        k,
        keep,
        &normed,
        q_weight,
        &q_fused,
        &q_mm,
        c.hidden,
        2 * q_dim,
        1,
    );
    encode_resident_matmul_f32(
        e, k, keep, &normed, k_weight, &key, &kv_mm, c.hidden, kv_dim, 1,
    );
    encode_resident_matmul_f32(
        e, k, keep, &normed, v_weight, &value, &kv_mm, c.hidden, kv_dim, 1,
    );
    e.set_compute_pipeline_state(&k.qwen35_deinterleave_qgate_pipeline);
    e.set_buffer(0, Some(&q_fused), 0);
    e.set_buffer(1, Some(&query), 0);
    e.set_buffer(2, Some(&gate), 0);
    e.set_buffer(3, Some(&split_scalar), 0);
    e.set_buffer(4, Some(&split_scalar), 4);
    dispatch_1d(e, &k.qwen35_deinterleave_qgate_pipeline, q_dim);
    encode_rms_norm_per_head(e, k, &query, q_norm, &query, &qk_norm_scalar, c.n_heads, 0);
    encode_rms_norm_per_head(e, k, &key, k_norm, &key, &qk_norm_scalar, c.n_kv_heads, 0);
    encode_rope(
        e,
        k,
        &query,
        cos,
        sin,
        &q_rope,
        c.n_heads,
        c.rope_dim / 2,
        0,
        0,
    );
    encode_rope(
        e,
        k,
        &key,
        cos,
        sin,
        &k_rope,
        c.n_kv_heads,
        c.rope_dim / 2,
        0,
        0,
    );
    e.set_compute_pipeline_state(&k.kv_scatter_pipeline);
    e.set_buffer(0, Some(&key), 0);
    e.set_buffer(1, Some(&value), 0);
    e.set_buffer(2, Some(cache_k), 0);
    e.set_buffer(3, Some(cache_v), 0);
    e.set_buffer(4, Some(&scatter_scalar), 0);
    e.set_buffer(5, Some(&scatter_scalar), 4);
    e.set_buffer(6, Some(&scatter_scalar), 8);
    e.set_buffer(7, Some(&scatter_scalar), 12);
    e.set_buffer(8, Some(&scatter_scalar), 0);
    e.set_buffer(9, Some(&scatter_scalar), 0);
    e.set_buffer(10, Some(&mirror_flag), 0);
    dispatch_1d(e, &k.kv_scatter_pipeline, kv_dim);
    encode_attention(
        e,
        k,
        keep,
        &query,
        cache_k,
        cache_v,
        None,
        &scores,
        &context,
        &attn_scalar,
        c.n_heads,
        c.n_kv_heads,
        c.head_dim,
        filled,
        0,
        0,
    );
    e.set_compute_pipeline_state(&k.qwen35_sigmoid_mul_pipeline);
    e.set_buffer(0, Some(&context), 0);
    e.set_buffer(1, Some(&gate), 0);
    e.set_buffer(2, Some(&n_q), 0);
    dispatch_1d(e, &k.qwen35_sigmoid_mul_pipeline, q_dim);
    encode_resident_matmul_f32(
        e, k, keep, &context, o_weight, &mix, &o_mm, q_dim, c.hidden, 1,
    );
    encode_binary(
        e,
        &k.residual_add_pipeline,
        input,
        &mix,
        output,
        &n_hidden,
        c.hidden,
    );
    keep.extend([
        normed,
        q_fused,
        query,
        gate,
        key,
        value,
        scores,
        context,
        mix,
        norm_scalar,
        q_mm,
        kv_mm,
        o_mm,
        split_scalar,
        qk_norm_scalar,
        q_rope,
        k_rope,
        scatter_scalar,
        mirror_flag,
        attn_scalar,
        n_q,
        n_hidden,
    ]);
}

#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_qwen35_ssm_layer(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    keep: &mut Vec<Buffer>,
    input: &Buffer,
    output: &Buffer,
    layer: &Qwen35MetalLayer,
    c: Qwen35MetalConfig,
) {
    let Qwen35MetalLayerKind::Ssm {
        qkv: qkv_weight,
        gate: gate_weight,
        beta: beta_weight,
        alpha: alpha_weight,
        output: output_weight,
        conv1d,
        dt_bias,
        a,
        norm,
        conv_state,
        state,
    } = &layer.kind
    else {
        unreachable!()
    };
    let normed = pool_get(k, (c.hidden * 4) as u64);
    let qkv = pool_get(k, (c.conv_dim * 4) as u64);
    let gate = pool_get(k, (c.value_dim * 4) as u64);
    let beta_raw = pool_get(k, (c.n_value_heads * 4) as u64);
    let alpha_raw = pool_get(k, (c.n_value_heads * 4) as u64);
    let beta = pool_get(k, (c.n_value_heads * 4) as u64);
    let glog = pool_get(k, (c.n_value_heads * 4) as u64);
    let conv_out = pool_get(k, (c.conv_dim * 4) as u64);
    let delta_out = pool_get(k, (c.value_dim * 4) as u64);
    let mix = pool_get(k, (c.hidden * 4) as u64);
    let norm_scalar = pool_get(k, 8);
    let hidden_mm = pool_get(k, 12);
    let gate_mm = pool_get(k, 12);
    let output_mm = pool_get(k, 12);
    let head_mm = pool_get(k, 12);
    let gate_heads = pool_get(k, 4);
    let conv_scalar = pool_get(k, 8);
    let l2_scalar = pool_get(k, 8);
    let delta_scalar = pool_get(k, 12);
    let n_hidden = pool_get(k, 4);
    unsafe {
        let p = norm_scalar.contents() as *mut u8;
        *(p as *mut u32) = c.hidden as u32;
        *(p.add(4) as *mut f32) = c.eps;
        *(gate_heads.contents() as *mut u32) = c.n_value_heads as u32;
        let cv = conv_scalar.contents() as *mut u32;
        *cv = c.conv_dim as u32;
        *cv.add(1) = c.d_conv as u32;
        let l2 = l2_scalar.contents() as *mut u8;
        *(l2 as *mut u32) = c.d_state as u32;
        *(l2.add(4) as *mut f32) = c.eps;
        let d = delta_scalar.contents() as *mut u8;
        *(d as *mut u32) = c.d_state as u32;
        *(d.add(4) as *mut u32) = c.n_key_heads as u32;
        *(d.add(8) as *mut f32) = c.eps;
        *(n_hidden.contents() as *mut u32) = c.hidden as u32;
    }
    encode_rms_norm_f32(e, k, input, &layer.attn_norm, &normed, &norm_scalar);
    encode_resident_matmul_f32(
        e, k, keep, &normed, qkv_weight, &qkv, &hidden_mm, c.hidden, c.conv_dim, 1,
    );
    encode_resident_matmul_f32(
        e,
        k,
        keep,
        &normed,
        gate_weight,
        &gate,
        &gate_mm,
        c.hidden,
        c.value_dim,
        1,
    );
    encode_resident_matmul_f32(
        e,
        k,
        keep,
        &normed,
        beta_weight,
        &beta_raw,
        &head_mm,
        c.hidden,
        c.n_value_heads,
        1,
    );
    encode_resident_matmul_f32(
        e,
        k,
        keep,
        &normed,
        alpha_weight,
        &alpha_raw,
        &head_mm,
        c.hidden,
        c.n_value_heads,
        1,
    );
    e.set_compute_pipeline_state(&k.qwen35_ssm_gates_pipeline);
    e.set_buffer(0, Some(&beta_raw), 0);
    e.set_buffer(1, Some(&alpha_raw), 0);
    e.set_buffer(2, Some(dt_bias), 0);
    e.set_buffer(3, Some(a), 0);
    e.set_buffer(4, Some(&beta), 0);
    e.set_buffer(5, Some(&glog), 0);
    e.set_buffer(6, Some(&gate_heads), 0);
    dispatch_1d(e, &k.qwen35_ssm_gates_pipeline, c.n_value_heads);
    e.set_compute_pipeline_state(&k.qwen35_conv1d_pipeline);
    e.set_buffer(0, Some(conv1d), 0);
    e.set_buffer(1, Some(&qkv), 0);
    e.set_buffer(2, Some(conv_state), 0);
    e.set_buffer(3, Some(&conv_out), 0);
    e.set_buffer(4, Some(&conv_scalar), 0);
    e.set_buffer(5, Some(&conv_scalar), 4);
    dispatch_1d(e, &k.qwen35_conv1d_pipeline, c.conv_dim);
    for offset in [0usize, c.key_dim] {
        e.set_compute_pipeline_state(&k.qwen35_l2_norm_pipeline);
        e.set_buffer(0, Some(&conv_out), (offset * 4) as u64);
        e.set_buffer(1, Some(&l2_scalar), 0);
        e.set_buffer(2, Some(&l2_scalar), 4);
        e.set_threadgroup_memory_length(0, ((c.d_state + 1) * 4) as u64);
        e.dispatch_thread_groups(
            metal::MTLSize {
                width: c.n_key_heads as u64,
                height: 1,
                depth: 1,
            },
            metal::MTLSize {
                width: 256,
                height: 1,
                depth: 1,
            },
        );
    }
    e.set_compute_pipeline_state(&k.qwen35_delta_rule_pipeline);
    e.set_buffer(0, Some(state), 0);
    e.set_buffer(1, Some(&conv_out), (c.key_dim * 4) as u64);
    e.set_buffer(2, Some(&conv_out), 0);
    e.set_buffer(3, Some(&conv_out), (2 * c.key_dim * 4) as u64);
    e.set_buffer(4, Some(&gate), 0);
    e.set_buffer(5, Some(&beta), 0);
    e.set_buffer(6, Some(&glog), 0);
    e.set_buffer(7, Some(norm), 0);
    e.set_buffer(8, Some(&delta_out), 0);
    e.set_buffer(9, Some(&delta_scalar), 0);
    e.set_buffer(10, Some(&delta_scalar), 4);
    e.set_buffer(11, Some(&delta_scalar), 8);
    e.set_threadgroup_memory_length(0, ((3 * c.d_state + 1) * 4) as u64);
    e.dispatch_thread_groups(
        metal::MTLSize {
            width: c.n_value_heads as u64,
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: c.d_state as u64,
            height: 1,
            depth: 1,
        },
    );
    encode_resident_matmul_f32(
        e,
        k,
        keep,
        &delta_out,
        output_weight,
        &mix,
        &output_mm,
        c.value_dim,
        c.hidden,
        1,
    );
    encode_binary(
        e,
        &k.residual_add_pipeline,
        input,
        &mix,
        output,
        &n_hidden,
        c.hidden,
    );
    keep.extend([
        normed,
        qkv,
        gate,
        beta_raw,
        alpha_raw,
        beta,
        glog,
        conv_out,
        delta_out,
        mix,
        norm_scalar,
        hidden_mm,
        gate_mm,
        output_mm,
        head_mm,
        gate_heads,
        conv_scalar,
        l2_scalar,
        delta_scalar,
        n_hidden,
    ]);
}

#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_qwen35_ffn(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    keep: &mut Vec<Buffer>,
    input: &Buffer,
    output: &Buffer,
    layer: &Qwen35MetalLayer,
    c: Qwen35MetalConfig,
) {
    let normed = pool_get(k, (c.hidden * 4) as u64);
    let norm_scalar = pool_get(k, 8);
    let gate = pool_get(k, (c.ffn_dim * 4) as u64);
    let up = pool_get(k, (c.ffn_dim * 4) as u64);
    let act = pool_get(k, (c.ffn_dim * 4) as u64);
    let down = pool_get(k, (c.hidden * 4) as u64);
    let hidden_mm = pool_get(k, 12);
    let down_mm = pool_get(k, 12);
    let n_ffn = pool_get(k, 4);
    let n_hidden = pool_get(k, 4);
    unsafe {
        let p = norm_scalar.contents() as *mut u8;
        *(p as *mut u32) = c.hidden as u32;
        *(p.add(4) as *mut f32) = c.eps;
        *(n_ffn.contents() as *mut u32) = c.ffn_dim as u32;
        *(n_hidden.contents() as *mut u32) = c.hidden as u32;
    }
    encode_rms_norm_f32(e, k, input, &layer.post_attn_norm, &normed, &norm_scalar);
    encode_resident_matmul_f32(
        e,
        k,
        keep,
        &normed,
        &layer.ffn_gate,
        &gate,
        &hidden_mm,
        c.hidden,
        c.ffn_dim,
        1,
    );
    encode_resident_matmul_f32(
        e,
        k,
        keep,
        &normed,
        &layer.ffn_up,
        &up,
        &hidden_mm,
        c.hidden,
        c.ffn_dim,
        1,
    );
    encode_binary(e, &k.silu_mul_pipeline, &gate, &up, &act, &n_ffn, c.ffn_dim);
    encode_resident_matmul_f32(
        e,
        k,
        keep,
        &act,
        &layer.ffn_down,
        &down,
        &down_mm,
        c.ffn_dim,
        c.hidden,
        1,
    );
    encode_binary(
        e,
        &k.residual_add_pipeline,
        input,
        &down,
        output,
        &n_hidden,
        c.hidden,
    );
    keep.extend([
        normed,
        norm_scalar,
        gate,
        up,
        act,
        down,
        hidden_mm,
        down_mm,
        n_ffn,
        n_hidden,
    ]);
}

#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_qwen35_full_layer_batch(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    keep: &mut Vec<Buffer>,
    input: &Buffer,
    output: &Buffer,
    layer: &Qwen35MetalLayer,
    cos: &Buffer,
    sin: &Buffer,
    c: Qwen35MetalConfig,
    max_positions: usize,
    base_position: usize,
    n_tokens: usize,
) {
    let Qwen35MetalLayerKind::Full {
        q: q_weight,
        k: k_weight,
        v: v_weight,
        output: o_weight,
        q_norm,
        k_norm,
        cache_k,
        cache_v,
    } = &layer.kind
    else {
        unreachable!()
    };
    let q_dim = c.n_heads * c.head_dim;
    let kv_dim = c.n_kv_heads * c.head_dim;
    let half_rope = c.rope_dim / 2;
    let normed = pool_get(k, (n_tokens * c.hidden * 4) as u64);
    let q_fused = pool_get(k, (n_tokens * 2 * q_dim * 4) as u64);
    let query = pool_get(k, (n_tokens * q_dim * 4) as u64);
    let gate = pool_get(k, (n_tokens * q_dim * 4) as u64);
    let key = pool_get(k, (n_tokens * kv_dim * 4) as u64);
    let value = pool_get(k, (n_tokens * kv_dim * 4) as u64);
    let context = pool_get(k, (n_tokens * q_dim * 4) as u64);
    let mix = pool_get(k, (n_tokens * c.hidden * 4) as u64);
    let norm_scalar = pool_get(k, 8);
    let q_mm = pool_get(k, 12);
    let kv_mm = pool_get(k, 12);
    let o_mm = pool_get(k, 12);
    let split_scalar = pool_get(k, 12);
    let qk_norm_scalar = pool_get(k, 12);
    let q_rope = pool_get(k, 16);
    let k_rope = pool_get(k, 16);
    let scatter_scalar = pool_get(k, 16);
    let mirror_flag = pool_get(k, 4);
    let n_q = pool_get(k, 4);
    let n_hidden = pool_get(k, 4);
    unsafe {
        let p = norm_scalar.contents() as *mut u8;
        *(p as *mut u32) = c.hidden as u32;
        *(p.add(4) as *mut f32) = c.eps;
        let split = split_scalar.contents() as *mut u32;
        *split = c.head_dim as u32;
        *split.add(1) = q_dim as u32;
        *split.add(2) = n_tokens as u32;
        let n = qk_norm_scalar.contents() as *mut u8;
        *(n as *mut u32) = c.head_dim as u32;
        *(n.add(4) as *mut f32) = c.eps;
        *(n.add(8) as *mut u32) = 1;
        let set_rope = |buffer: &Buffer, heads: usize| {
            let r = buffer.contents() as *mut u32;
            *r = heads as u32;
            *r.add(1) = c.head_dim as u32;
            *r.add(2) = half_rope as u32;
            *r.add(3) = 1;
        };
        set_rope(&q_rope, c.n_heads);
        set_rope(&k_rope, c.n_kv_heads);
        let sc = scatter_scalar.contents() as *mut u32;
        *sc = c.head_dim as u32;
        *sc.add(1) = max_positions as u32;
        *sc.add(2) = base_position as u32;
        *sc.add(3) = kv_dim as u32;
        *(mirror_flag.contents() as *mut u32) = 0;
        *(n_q.contents() as *mut u32) = (n_tokens * q_dim) as u32;
        *(n_hidden.contents() as *mut u32) = (n_tokens * c.hidden) as u32;
    }

    encode_rms_norm_batch(
        k,
        e,
        input,
        &layer.attn_norm,
        &normed,
        &norm_scalar,
        n_tokens,
    );
    if !try_encode_qwen35_shared_matmuls(
        e,
        k,
        keep,
        &normed,
        c.hidden,
        n_tokens,
        &[
            (q_weight, &q_fused, &q_mm, 2 * q_dim),
            (k_weight, &key, &kv_mm, kv_dim),
            (v_weight, &value, &kv_mm, kv_dim),
        ],
    ) {
        encode_qwen35_matmul_batch(
            e,
            k,
            keep,
            &normed,
            q_weight,
            &q_fused,
            &q_mm,
            c.hidden,
            2 * q_dim,
            n_tokens,
        );
        encode_qwen35_matmul_batch(
            e, k, keep, &normed, k_weight, &key, &kv_mm, c.hidden, kv_dim, n_tokens,
        );
        encode_qwen35_matmul_batch(
            e, k, keep, &normed, v_weight, &value, &kv_mm, c.hidden, kv_dim, n_tokens,
        );
    }
    e.set_compute_pipeline_state(&k.qwen35_deinterleave_qgate_batch_pipeline);
    e.set_buffer(0, Some(&q_fused), 0);
    e.set_buffer(1, Some(&query), 0);
    e.set_buffer(2, Some(&gate), 0);
    e.set_buffer(3, Some(&split_scalar), 0);
    e.set_buffer(4, Some(&split_scalar), 4);
    e.set_buffer(5, Some(&split_scalar), 8);
    let row_width = k
        .qwen35_deinterleave_qgate_batch_pipeline
        .thread_execution_width()
        .max(1);
    e.dispatch_thread_groups(
        metal::MTLSize {
            width: (q_dim as u64).div_ceil(row_width),
            height: n_tokens as u64,
            depth: 1,
        },
        metal::MTLSize {
            width: row_width,
            height: 1,
            depth: 1,
        },
    );
    encode_rms_norm_per_head(
        e,
        k,
        &query,
        q_norm,
        &query,
        &qk_norm_scalar,
        n_tokens * c.n_heads,
        0,
    );
    encode_rms_norm_per_head(
        e,
        k,
        &key,
        k_norm,
        &key,
        &qk_norm_scalar,
        n_tokens * c.n_kv_heads,
        0,
    );
    for (data, scalar, heads) in [(&query, &q_rope, c.n_heads), (&key, &k_rope, c.n_kv_heads)] {
        e.set_compute_pipeline_state(&k.rope_rotate_batch_pipeline);
        e.set_buffer(0, Some(data), 0);
        e.set_buffer(1, Some(cos), 0);
        e.set_buffer(2, Some(sin), 0);
        e.set_buffer(3, Some(scalar), 0);
        e.set_buffer(4, Some(scalar), 4);
        e.set_buffer(5, Some(scalar), 8);
        e.set_buffer(6, Some(scalar), 12);
        let width = k.rope_rotate_batch_pipeline.thread_execution_width().max(1);
        e.dispatch_thread_groups(
            metal::MTLSize {
                width: ((heads * half_rope) as u64).div_ceil(width),
                height: n_tokens as u64,
                depth: 1,
            },
            metal::MTLSize {
                width,
                height: 1,
                depth: 1,
            },
        );
    }
    e.set_compute_pipeline_state(&k.kv_scatter_batch_pipeline);
    e.set_buffer(0, Some(&key), 0);
    e.set_buffer(1, Some(&value), 0);
    e.set_buffer(2, Some(cache_k), 0);
    e.set_buffer(3, Some(cache_v), 0);
    e.set_buffer(4, Some(&scatter_scalar), 0);
    e.set_buffer(5, Some(&scatter_scalar), 4);
    e.set_buffer(6, Some(&scatter_scalar), 8);
    e.set_buffer(7, Some(&scatter_scalar), 12);
    e.set_buffer(8, Some(cache_k), 0);
    e.set_buffer(9, Some(cache_v), 0);
    e.set_buffer(10, Some(&mirror_flag), 0);
    let scatter_width = k.kv_scatter_batch_pipeline.thread_execution_width().max(1);
    e.dispatch_thread_groups(
        metal::MTLSize {
            width: (kv_dim as u64).div_ceil(scatter_width),
            height: n_tokens as u64,
            depth: 1,
        },
        metal::MTLSize {
            width: scatter_width,
            height: 1,
            depth: 1,
        },
    );
    for token in 0..n_tokens {
        let filled = base_position + token + 1;
        let q_off = (token * q_dim * 4) as u64;
        let scores = pool_get(k, (c.n_heads * filled * 4) as u64);
        let attn_scalar = pool_get(k, 32);
        unsafe {
            let a = attn_scalar.contents() as *mut u8;
            *(a as *mut u32) = c.n_heads as u32;
            *(a.add(4) as *mut u32) = c.head_dim as u32;
            *(a.add(8) as *mut u32) = filled as u32;
            *(a.add(12) as *mut u32) = (c.n_heads / c.n_kv_heads) as u32;
            *(a.add(16) as *mut f32) = 1.0 / (c.head_dim as f32).sqrt();
            *(a.add(20) as *mut u32) = c.head_dim as u32;
            *(a.add(24) as *mut u32) = (max_positions * c.head_dim) as u32;
            *(a.add(28) as *mut u32) = 0;
        }
        encode_attention(
            e,
            k,
            keep,
            &query,
            cache_k,
            cache_v,
            None,
            &scores,
            &context,
            &attn_scalar,
            c.n_heads,
            c.n_kv_heads,
            c.head_dim,
            filled,
            q_off,
            q_off,
        );
        keep.extend([scores, attn_scalar]);
    }
    e.set_compute_pipeline_state(&k.qwen35_sigmoid_mul_pipeline);
    e.set_buffer(0, Some(&context), 0);
    e.set_buffer(1, Some(&gate), 0);
    e.set_buffer(2, Some(&n_q), 0);
    dispatch_1d(e, &k.qwen35_sigmoid_mul_pipeline, n_tokens * q_dim);
    encode_qwen35_matmul_batch(
        e, k, keep, &context, o_weight, &mix, &o_mm, q_dim, c.hidden, n_tokens,
    );
    encode_binary(
        e,
        &k.residual_add_pipeline,
        input,
        &mix,
        output,
        &n_hidden,
        n_tokens * c.hidden,
    );
    keep.extend([
        normed,
        q_fused,
        query,
        gate,
        key,
        value,
        context,
        mix,
        norm_scalar,
        q_mm,
        kv_mm,
        o_mm,
        split_scalar,
        qk_norm_scalar,
        q_rope,
        k_rope,
        scatter_scalar,
        mirror_flag,
        n_q,
        n_hidden,
    ]);
}

#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_qwen35_ssm_layer_batch(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    keep: &mut Vec<Buffer>,
    input: &Buffer,
    output: &Buffer,
    layer: &Qwen35MetalLayer,
    c: Qwen35MetalConfig,
    n_tokens: usize,
) {
    let Qwen35MetalLayerKind::Ssm {
        qkv: qkv_weight,
        gate: gate_weight,
        beta: beta_weight,
        alpha: alpha_weight,
        output: output_weight,
        conv1d,
        dt_bias,
        a,
        norm,
        conv_state,
        state,
    } = &layer.kind
    else {
        unreachable!()
    };
    let normed = pool_get(k, (n_tokens * c.hidden * 4) as u64);
    let qkv = pool_get(k, (n_tokens * c.conv_dim * 4) as u64);
    let gate = pool_get(k, (n_tokens * c.value_dim * 4) as u64);
    let beta_raw = pool_get(k, (n_tokens * c.n_value_heads * 4) as u64);
    let alpha_raw = pool_get(k, (n_tokens * c.n_value_heads * 4) as u64);
    let beta = pool_get(k, (n_tokens * c.n_value_heads * 4) as u64);
    let glog = pool_get(k, (n_tokens * c.n_value_heads * 4) as u64);
    let conv_out = pool_get(k, (n_tokens * c.conv_dim * 4) as u64);
    let delta_out = pool_get(k, (n_tokens * c.value_dim * 4) as u64);
    let mix = pool_get(k, (n_tokens * c.hidden * 4) as u64);
    let norm_scalar = pool_get(k, 8);
    let hidden_mm = pool_get(k, 12);
    let gate_mm = pool_get(k, 12);
    let output_mm = pool_get(k, 12);
    let head_mm = pool_get(k, 12);
    let gate_scalar = pool_get(k, 8);
    let conv_scalar = pool_get(k, 12);
    let l2_q_scalar = pool_get(k, 16);
    let l2_k_scalar = pool_get(k, 16);
    let delta_scalar = pool_get(k, 20);
    let n_hidden = pool_get(k, 4);
    unsafe {
        let p = norm_scalar.contents() as *mut u8;
        *(p as *mut u32) = c.hidden as u32;
        *(p.add(4) as *mut f32) = c.eps;
        let gates = gate_scalar.contents() as *mut u32;
        *gates = c.n_value_heads as u32;
        *gates.add(1) = n_tokens as u32;
        let cv = conv_scalar.contents() as *mut u32;
        *cv = c.conv_dim as u32;
        *cv.add(1) = c.d_conv as u32;
        *cv.add(2) = n_tokens as u32;
        for (scalar, offset) in [(&l2_q_scalar, 0usize), (&l2_k_scalar, c.key_dim)] {
            let l2 = scalar.contents() as *mut u8;
            *(l2 as *mut u32) = c.d_state as u32;
            *(l2.add(4) as *mut u32) = c.conv_dim as u32;
            *(l2.add(8) as *mut u32) = offset as u32;
            *(l2.add(12) as *mut f32) = c.eps;
        }
        let d = delta_scalar.contents() as *mut u8;
        *(d as *mut u32) = c.d_state as u32;
        *(d.add(4) as *mut u32) = c.n_key_heads as u32;
        *(d.add(8) as *mut u32) = c.n_value_heads as u32;
        *(d.add(12) as *mut u32) = n_tokens as u32;
        *(d.add(16) as *mut f32) = c.eps;
        *(n_hidden.contents() as *mut u32) = (n_tokens * c.hidden) as u32;
    }
    encode_rms_norm_batch(
        k,
        e,
        input,
        &layer.attn_norm,
        &normed,
        &norm_scalar,
        n_tokens,
    );
    if !try_encode_qwen35_shared_matmuls(
        e,
        k,
        keep,
        &normed,
        c.hidden,
        n_tokens,
        &[
            (qkv_weight, &qkv, &hidden_mm, c.conv_dim),
            (gate_weight, &gate, &gate_mm, c.value_dim),
            (beta_weight, &beta_raw, &head_mm, c.n_value_heads),
            (alpha_weight, &alpha_raw, &head_mm, c.n_value_heads),
        ],
    ) {
        encode_qwen35_matmul_batch(
            e, k, keep, &normed, qkv_weight, &qkv, &hidden_mm, c.hidden, c.conv_dim, n_tokens,
        );
        encode_qwen35_matmul_batch(
            e,
            k,
            keep,
            &normed,
            gate_weight,
            &gate,
            &gate_mm,
            c.hidden,
            c.value_dim,
            n_tokens,
        );
        encode_qwen35_matmul_batch(
            e,
            k,
            keep,
            &normed,
            beta_weight,
            &beta_raw,
            &head_mm,
            c.hidden,
            c.n_value_heads,
            n_tokens,
        );
        encode_qwen35_matmul_batch(
            e,
            k,
            keep,
            &normed,
            alpha_weight,
            &alpha_raw,
            &head_mm,
            c.hidden,
            c.n_value_heads,
            n_tokens,
        );
    }
    e.set_compute_pipeline_state(&k.qwen35_ssm_gates_batch_pipeline);
    e.set_buffer(0, Some(&beta_raw), 0);
    e.set_buffer(1, Some(&alpha_raw), 0);
    e.set_buffer(2, Some(dt_bias), 0);
    e.set_buffer(3, Some(a), 0);
    e.set_buffer(4, Some(&beta), 0);
    e.set_buffer(5, Some(&glog), 0);
    e.set_buffer(6, Some(&gate_scalar), 0);
    e.set_buffer(7, Some(&gate_scalar), 4);
    dispatch_1d(
        e,
        &k.qwen35_ssm_gates_batch_pipeline,
        n_tokens * c.n_value_heads,
    );
    e.set_compute_pipeline_state(&k.qwen35_conv1d_batch_pipeline);
    e.set_buffer(0, Some(conv1d), 0);
    e.set_buffer(1, Some(&qkv), 0);
    e.set_buffer(2, Some(conv_state), 0);
    e.set_buffer(3, Some(&conv_out), 0);
    e.set_buffer(4, Some(&conv_scalar), 0);
    e.set_buffer(5, Some(&conv_scalar), 4);
    e.set_buffer(6, Some(&conv_scalar), 8);
    let conv_width = k
        .qwen35_conv1d_batch_pipeline
        .thread_execution_width()
        .max(1);
    e.dispatch_thread_groups(
        metal::MTLSize {
            width: (c.conv_dim as u64).div_ceil(conv_width),
            height: n_tokens as u64,
            depth: 1,
        },
        metal::MTLSize {
            width: conv_width,
            height: 1,
            depth: 1,
        },
    );
    e.set_compute_pipeline_state(&k.qwen35_conv1d_state_update_pipeline);
    e.set_buffer(0, Some(&qkv), 0);
    e.set_buffer(1, Some(conv_state), 0);
    e.set_buffer(2, Some(&conv_scalar), 0);
    e.set_buffer(3, Some(&conv_scalar), 4);
    e.set_buffer(4, Some(&conv_scalar), 8);
    dispatch_1d(e, &k.qwen35_conv1d_state_update_pipeline, c.conv_dim);
    for l2_scalar in [&l2_q_scalar, &l2_k_scalar] {
        e.set_compute_pipeline_state(&k.qwen35_l2_norm_strided_batch_pipeline);
        e.set_buffer(0, Some(&conv_out), 0);
        e.set_buffer(1, Some(l2_scalar), 0);
        e.set_buffer(2, Some(l2_scalar), 4);
        e.set_buffer(3, Some(l2_scalar), 8);
        e.set_buffer(4, Some(l2_scalar), 12);
        e.set_threadgroup_memory_length(0, ((c.d_state + 1) * 4) as u64);
        e.dispatch_thread_groups(
            metal::MTLSize {
                width: c.n_key_heads as u64,
                height: n_tokens as u64,
                depth: 1,
            },
            metal::MTLSize {
                width: 256,
                height: 1,
                depth: 1,
            },
        );
    }
    e.set_compute_pipeline_state(&k.qwen35_delta_rule_batch_pipeline);
    e.set_buffer(0, Some(state), 0);
    e.set_buffer(1, Some(&conv_out), 0);
    e.set_buffer(2, Some(&gate), 0);
    e.set_buffer(3, Some(&beta), 0);
    e.set_buffer(4, Some(&glog), 0);
    e.set_buffer(5, Some(norm), 0);
    e.set_buffer(6, Some(&delta_out), 0);
    e.set_buffer(7, Some(&delta_scalar), 0);
    e.set_buffer(8, Some(&delta_scalar), 4);
    e.set_buffer(9, Some(&delta_scalar), 8);
    e.set_buffer(10, Some(&delta_scalar), 12);
    e.set_buffer(11, Some(&delta_scalar), 16);
    e.set_threadgroup_memory_length(0, ((3 * c.d_state + 1) * 4) as u64);
    e.dispatch_thread_groups(
        metal::MTLSize {
            width: c.n_value_heads as u64,
            height: 1,
            depth: 1,
        },
        metal::MTLSize {
            width: c.d_state as u64,
            height: 1,
            depth: 1,
        },
    );
    encode_qwen35_matmul_batch(
        e,
        k,
        keep,
        &delta_out,
        output_weight,
        &mix,
        &output_mm,
        c.value_dim,
        c.hidden,
        n_tokens,
    );
    encode_binary(
        e,
        &k.residual_add_pipeline,
        input,
        &mix,
        output,
        &n_hidden,
        n_tokens * c.hidden,
    );
    keep.extend([
        normed,
        qkv,
        gate,
        beta_raw,
        alpha_raw,
        beta,
        glog,
        conv_out,
        delta_out,
        mix,
        norm_scalar,
        hidden_mm,
        gate_mm,
        output_mm,
        head_mm,
        gate_scalar,
        conv_scalar,
        l2_q_scalar,
        l2_k_scalar,
        delta_scalar,
        n_hidden,
    ]);
}

#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_qwen35_ffn_batch(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    keep: &mut Vec<Buffer>,
    input: &Buffer,
    output: &Buffer,
    layer: &Qwen35MetalLayer,
    c: Qwen35MetalConfig,
    n_tokens: usize,
) {
    let normed = pool_get(k, (n_tokens * c.hidden * 4) as u64);
    let gate = pool_get(k, (n_tokens * c.ffn_dim * 4) as u64);
    let up = pool_get(k, (n_tokens * c.ffn_dim * 4) as u64);
    let act = pool_get(k, (n_tokens * c.ffn_dim * 4) as u64);
    let down = pool_get(k, (n_tokens * c.hidden * 4) as u64);
    let norm_scalar = pool_get(k, 8);
    let hidden_mm = pool_get(k, 12);
    let down_mm = pool_get(k, 12);
    let n_ffn = pool_get(k, 4);
    let n_hidden = pool_get(k, 4);
    unsafe {
        let p = norm_scalar.contents() as *mut u8;
        *(p as *mut u32) = c.hidden as u32;
        *(p.add(4) as *mut f32) = c.eps;
        *(n_ffn.contents() as *mut u32) = (n_tokens * c.ffn_dim) as u32;
        *(n_hidden.contents() as *mut u32) = (n_tokens * c.hidden) as u32;
    }
    encode_rms_norm_batch(
        k,
        e,
        input,
        &layer.post_attn_norm,
        &normed,
        &norm_scalar,
        n_tokens,
    );
    if !try_encode_qwen35_shared_matmuls(
        e,
        k,
        keep,
        &normed,
        c.hidden,
        n_tokens,
        &[
            (&layer.ffn_gate, &gate, &hidden_mm, c.ffn_dim),
            (&layer.ffn_up, &up, &hidden_mm, c.ffn_dim),
        ],
    ) {
        encode_qwen35_matmul_batch(
            e,
            k,
            keep,
            &normed,
            &layer.ffn_gate,
            &gate,
            &hidden_mm,
            c.hidden,
            c.ffn_dim,
            n_tokens,
        );
        encode_qwen35_matmul_batch(
            e,
            k,
            keep,
            &normed,
            &layer.ffn_up,
            &up,
            &hidden_mm,
            c.hidden,
            c.ffn_dim,
            n_tokens,
        );
    }
    encode_binary(
        e,
        &k.silu_mul_pipeline,
        &gate,
        &up,
        &act,
        &n_ffn,
        n_tokens * c.ffn_dim,
    );
    encode_qwen35_matmul_batch(
        e,
        k,
        keep,
        &act,
        &layer.ffn_down,
        &down,
        &down_mm,
        c.ffn_dim,
        c.hidden,
        n_tokens,
    );
    encode_binary(
        e,
        &k.residual_add_pipeline,
        input,
        &down,
        output,
        &n_hidden,
        n_tokens * c.hidden,
    );
    keep.extend([
        normed,
        gate,
        up,
        act,
        down,
        norm_scalar,
        hidden_mm,
        down_mm,
        n_ffn,
        n_hidden,
    ]);
}

// ===================================================================================
// LFM2 / LFM2.5 — GPU-resident Metal decode graph.
//
// Structurally the qwen35 hybrid engine with a different mixer: every layer wears the
// same pre-norm 2-norm block (attn_norm -> mixer -> residual -> ffn_norm -> SwiGLU ->
// residual), and each layer is EITHER a short convolution or GQA attention. Putting the
// per-layer state inside the kind variant is what gives sparse KV for free: LFM2.5-2.6B
// attends on only 8 of 30 layers, and the 22 conv layers simply have no cache buffers.
//
// LFM2's attention differs from qwen35's in exactly two ways, both by SUBTRACTION: there
// is no fused query+gate projection (so no deinterleave) and no sigmoid output gate.
// ===================================================================================

#[cfg(target_os = "macos")]
#[derive(Clone, Copy)]
pub(crate) struct Lfm2MetalConfig {
    pub hidden: usize,
    pub ffn_dim: usize,
    pub n_heads: usize,
    pub n_kv_heads: usize,
    pub head_dim: usize,
    pub rope_dim: usize,
    /// Short-conv kernel width (`lfm2.shortconv.l_cache`, 3). The rolling per-channel
    /// state is `l_cache - 1` columns wide.
    pub l_cache: usize,
    pub vocab: usize,
    pub eps: f32,
}

#[cfg(target_os = "macos")]
pub(crate) enum Lfm2MetalLayerKindInput<'a> {
    Attn {
        q: ResidentWeightBytes<'a>,
        k: ResidentWeightBytes<'a>,
        v: ResidentWeightBytes<'a>,
        output: ResidentWeightBytes<'a>,
        q_norm: &'a [f32],
        k_norm: &'a [f32],
    },
    Conv {
        /// `shortconv.in_proj`: hidden -> 3 * hidden, laid out [B | C | X].
        in_proj: ResidentWeightBytes<'a>,
        out_proj: ResidentWeightBytes<'a>,
        /// `shortconv.conv.weight`, channel-major `[hidden, l_cache]` flattened as
        /// `conv[c * l_cache + tap]`.
        conv: &'a [f32],
    },
}

#[cfg(target_os = "macos")]
pub(crate) struct Lfm2MetalLayerInput<'a> {
    pub attn_norm: &'a [f32],
    pub ffn_norm: &'a [f32],
    pub ffn_gate: ResidentWeightBytes<'a>,
    pub ffn_up: ResidentWeightBytes<'a>,
    pub ffn_down: ResidentWeightBytes<'a>,
    pub kind: Lfm2MetalLayerKindInput<'a>,
}

#[cfg(target_os = "macos")]
enum Lfm2MetalLayerKind {
    Attn {
        q: ResidentLinearWeight,
        k: ResidentLinearWeight,
        v: ResidentLinearWeight,
        output: ResidentLinearWeight,
        q_norm: Buffer,
        k_norm: Buffer,
        cache_k: Buffer,
        cache_v: Buffer,
    },
    Conv {
        in_proj: ResidentLinearWeight,
        out_proj: ResidentLinearWeight,
        conv: Buffer,
        conv_state: Buffer,
    },
}

#[cfg(target_os = "macos")]
struct Lfm2MetalLayer {
    attn_norm: Buffer,
    ffn_norm: Buffer,
    ffn_gate: ResidentLinearWeight,
    ffn_up: ResidentLinearWeight,
    ffn_down: ResidentLinearWeight,
    kind: Lfm2MetalLayerKind,
}

/// Complete LFM2 token graph resident on Metal.
#[cfg(target_os = "macos")]
pub(crate) struct Lfm2MetalDecode {
    config: Lfm2MetalConfig,
    max_positions: usize,
    layers: Vec<Lfm2MetalLayer>,
    final_norm: Buffer,
    output: ResidentLinearWeight,
    hidden_a: Buffer,
    hidden_b: Buffer,
    filled: usize,
}

#[cfg(target_os = "macos")]
impl Lfm2MetalDecode {
    pub(crate) fn new(
        config: Lfm2MetalConfig,
        inputs: &[Lfm2MetalLayerInput<'_>],
        final_norm: &[f32],
        output: ResidentWeightBytes<'_>,
        max_positions: usize,
    ) -> Option<Self> {
        // Every guard returns None — a partially built engine must never exist,
        // because the caller's fallback is a full CPU replay.
        if config.hidden == 0
            || !config.hidden.is_multiple_of(32)
            || config.ffn_dim == 0
            || config.head_dim == 0
            || config.head_dim > 128
            || !config.head_dim.is_multiple_of(2)
            || config.rope_dim == 0
            || config.rope_dim > config.head_dim
            || !config.rope_dim.is_multiple_of(2)
            || config.n_heads == 0
            || config.n_kv_heads == 0
            || !config.n_heads.is_multiple_of(config.n_kv_heads)
            || config.n_heads * config.head_dim != config.hidden
            || config.l_cache < 2
            || config.vocab == 0
            || final_norm.len() != config.hidden
            || max_positions == 0
            || !output.matches_shape(config.hidden, config.vocab)
        {
            return None;
        }
        let k = metal_linear_kernel()?;
        let mut cache = metal_linear_cache().lock().ok()?;
        let mut layers = Vec::with_capacity(inputs.len());
        let mut attention_layers = 0usize;
        for input in inputs {
            if input.attn_norm.len() != config.hidden
                || input.ffn_norm.len() != config.hidden
                || !input.ffn_gate.matches_shape(config.hidden, config.ffn_dim)
                || !input.ffn_up.matches_shape(config.hidden, config.ffn_dim)
                || !input.ffn_down.matches_shape(config.ffn_dim, config.hidden)
            {
                return None;
            }
            let ffn_gate = resolve_resident_weight(&mut cache, &k.device, &input.ffn_gate, true)?;
            let ffn_up = resolve_resident_weight(&mut cache, &k.device, &input.ffn_up, true)?;
            let ffn_down = resolve_resident_weight(&mut cache, &k.device, &input.ffn_down, true)?;
            let kind = match &input.kind {
                Lfm2MetalLayerKindInput::Attn {
                    q,
                    k: kw,
                    v,
                    output,
                    q_norm,
                    k_norm,
                } => {
                    let q_dim = config.n_heads * config.head_dim;
                    let kv_dim = config.n_kv_heads * config.head_dim;
                    if q_norm.len() != config.head_dim
                        || k_norm.len() != config.head_dim
                        || !q.matches_shape(config.hidden, q_dim)
                        || !kw.matches_shape(config.hidden, kv_dim)
                        || !v.matches_shape(config.hidden, kv_dim)
                        || !output.matches_shape(q_dim, config.hidden)
                    {
                        return None;
                    }
                    attention_layers += 1;
                    Lfm2MetalLayerKind::Attn {
                        q: resolve_resident_weight(&mut cache, &k.device, q, true)?,
                        k: resolve_resident_weight(&mut cache, &k.device, kw, true)?,
                        v: resolve_resident_weight(&mut cache, &k.device, v, true)?,
                        output: resolve_resident_weight(&mut cache, &k.device, output, true)?,
                        q_norm: qwen35_f32_buffer(k, q_norm),
                        k_norm: qwen35_f32_buffer(k, k_norm),
                        cache_k: qwen35_zero_buffer(
                            k,
                            config.n_kv_heads * max_positions * config.head_dim * 4,
                        ),
                        cache_v: qwen35_zero_buffer(
                            k,
                            config.n_kv_heads * max_positions * config.head_dim * 4,
                        ),
                    }
                }
                Lfm2MetalLayerKindInput::Conv {
                    in_proj,
                    out_proj,
                    conv,
                } => {
                    if conv.len() != config.hidden * config.l_cache
                        || !in_proj.matches_shape(config.hidden, 3 * config.hidden)
                        || !out_proj.matches_shape(config.hidden, config.hidden)
                    {
                        return None;
                    }
                    Lfm2MetalLayerKind::Conv {
                        in_proj: resolve_resident_weight(&mut cache, &k.device, in_proj, true)?,
                        out_proj: resolve_resident_weight(&mut cache, &k.device, out_proj, true)?,
                        conv: qwen35_f32_buffer(k, conv),
                        conv_state: qwen35_zero_buffer(k, config.hidden * (config.l_cache - 1) * 4),
                    }
                }
            };
            layers.push(Lfm2MetalLayer {
                attn_norm: qwen35_f32_buffer(k, input.attn_norm),
                ffn_norm: qwen35_f32_buffer(k, input.ffn_norm),
                ffn_gate,
                ffn_up,
                ffn_down,
                kind,
            });
        }
        // A schedule with no attention layer would leave RoPE and the KV cache
        // meaningless; refuse rather than build a graph that cannot attend.
        if layers.is_empty() || attention_layers == 0 {
            return None;
        }
        let final_norm = qwen35_f32_buffer(k, final_norm);
        let output = resolve_resident_weight(&mut cache, &k.device, &output, true)?;
        let hidden_a = qwen35_zero_buffer(k, config.hidden * 4);
        let hidden_b = qwen35_zero_buffer(k, config.hidden * 4);
        Some(Self {
            config,
            max_positions,
            layers,
            final_norm,
            output,
            hidden_a,
            hidden_b,
            filled: 0,
        })
    }

    /// Clear every per-sequence buffer: the KV caches on attention layers and the
    /// rolling conv ring on conv layers. The ring MUST be zeroed — a stale window
    /// silently corrupts the first `l_cache - 1` positions of the next request.
    pub(crate) fn reset(&mut self) {
        // SAFETY: every buffer here is StorageModeShared and owned by this engine,
        // and `reset` is only reachable with no command buffer in flight.
        let wipe = |b: &Buffer| unsafe {
            std::ptr::write_bytes(b.contents() as *mut u8, 0, b.length() as usize);
        };
        for layer in &self.layers {
            match &layer.kind {
                Lfm2MetalLayerKind::Attn {
                    cache_k, cache_v, ..
                } => {
                    wipe(cache_k);
                    wipe(cache_v);
                }
                Lfm2MetalLayerKind::Conv { conv_state, .. } => wipe(conv_state),
            }
        }
        self.filled = 0;
    }

    /// One token through the whole resident stack. `position` must equal the number of
    /// positions already consumed — the conv ring is order-dependent, so a skipped or
    /// replayed position silently corrupts the state rather than erroring.
    fn forward_select(
        &mut self,
        embedding: &[f32],
        cos: &[f32],
        sin: &[f32],
        position: usize,
        selection: Qwen35MetalSelection,
    ) -> Option<Qwen35MetalStep> {
        let c = self.config;
        if embedding.len() != c.hidden
            || cos.len() != c.rope_dim / 2
            || sin.len() != c.rope_dim / 2
            || position != self.filled
            || position >= self.max_positions
        {
            return None;
        }
        let k = metal_linear_kernel()?;
        write_buffer_f32(&self.hidden_a, embedding);
        let cos_buf = qwen35_f32_buffer(k, cos);
        let sin_buf = qwen35_f32_buffer(k, sin);
        let cb = k.queue.new_command_buffer();
        let e = cb.new_compute_command_encoder();
        let mut keep = vec![cos_buf.to_owned(), sin_buf.to_owned()];
        for layer in &self.layers {
            match &layer.kind {
                Lfm2MetalLayerKind::Attn { .. } => encode_lfm2_attn_layer(
                    e,
                    k,
                    &mut keep,
                    &self.hidden_a,
                    &self.hidden_b,
                    layer,
                    &cos_buf,
                    &sin_buf,
                    c,
                    self.max_positions,
                    position,
                ),
                Lfm2MetalLayerKind::Conv { .. } => encode_lfm2_conv_layer(
                    e,
                    k,
                    &mut keep,
                    &self.hidden_a,
                    &self.hidden_b,
                    layer,
                    c,
                ),
            }
            encode_lfm2_ffn(e, k, &mut keep, &self.hidden_b, &self.hidden_a, layer, c);
        }

        let normed = pool_get(k, (c.hidden * 4) as u64);
        let norm_scalar = pool_get(k, 8);
        let logits = pool_get(k, (c.vocab * 4) as u64);
        let mm_scalar = pool_get(k, 12);
        unsafe {
            let p = norm_scalar.contents() as *mut u8;
            *(p as *mut u32) = c.hidden as u32;
            *(p.add(4) as *mut f32) = c.eps;
        }
        encode_rms_norm_f32(
            e,
            k,
            &self.hidden_a,
            &self.final_norm,
            &normed,
            &norm_scalar,
        );
        encode_resident_matmul_f32(
            e,
            k,
            &mut keep,
            &normed,
            &self.output,
            &logits,
            &mm_scalar,
            c.hidden,
            c.vocab,
            1,
        );
        let greedy_buffers = if matches!(selection, Qwen35MetalSelection::Greedy) {
            let selected = pool_get(k, 4);
            let vocab_scalar = pool_get(k, 4);
            unsafe { *(vocab_scalar.contents() as *mut u32) = c.vocab as u32 };
            e.set_compute_pipeline_state(&k.argmax_f32_greedy_pipeline);
            e.set_buffer(0, Some(&logits), 0);
            e.set_buffer(1, Some(&selected), 0);
            e.set_buffer(2, Some(&vocab_scalar), 0);
            e.dispatch_thread_groups(
                metal::MTLSize {
                    width: 1,
                    height: 1,
                    depth: 1,
                },
                metal::MTLSize {
                    width: 1024,
                    height: 1,
                    depth: 1,
                },
            );
            Some((selected, vocab_scalar))
        } else {
            None
        };
        e.end_encoding();
        cb.commit();
        cb.wait_until_completed();
        if cb.status() != metal::MTLCommandBufferStatus::Completed {
            // `selected` and `logits` come from the scratch pool, which never zeroes what
            // it hands back, and the only writer is a dispatch in THIS command buffer. On
            // an errored buffer that dispatch never ran, so reading them returns the
            // previous tenant of their size class. `pool_get` rounds to a power-of-two
            // class, so every 4/8/12-byte scalar in the engine (dims, eps, positions)
            // shares one bucket: the stale word is a small integer that lands inside the
            // vocabulary, decodes to a real token, and is fed straight back in as the next
            // input embedding. Refuse rather than invent a token.
            eprintln!(
                "[lfm2] Metal decode command buffer did not complete ({:?}); refusing the \
                 step rather than emitting a stale scratch word as a token id",
                cb.status()
            );
            keep.extend([normed, norm_scalar, logits, mm_scalar]);
            if let Some((selected, vocab_scalar)) = greedy_buffers {
                keep.extend([selected, vocab_scalar]);
            }
            pool_recycle(k, keep);
            return None;
        }
        let output = match &greedy_buffers {
            Some((selected, _)) => {
                Qwen35MetalStep::Token(unsafe { *(selected.contents() as *const u32) })
            }
            None => {
                let values = unsafe {
                    std::slice::from_raw_parts(logits.contents() as *const f32, c.vocab).to_vec()
                };
                Qwen35MetalStep::Logits(values)
            }
        };
        keep.extend([normed, norm_scalar, logits, mm_scalar]);
        if let Some((selected, vocab_scalar)) = greedy_buffers {
            keep.extend([selected, vocab_scalar]);
        }
        pool_recycle(k, keep);
        self.filled += 1;
        Some(output)
    }

    /// Prefill `k` consecutive positions in one command buffer.
    ///
    /// Every projection runs with `n_tokens = k`, so each weight is streamed ONCE
    /// per chunk instead of once per token — that is the whole point, because 90%
    /// of this model's per-token bytes are Q8_0 projections. Positional work that
    /// genuinely differs per row (RoPE, the KV scatter, and the causal attention
    /// span) stays per-row, exactly as `verify_batch_inner` does it.
    ///
    /// The LM head is skipped entirely: a prefill chunk's logits are discarded.
    /// The caller feeds the final prompt token through `forward_select` to get the
    /// first sampled position.
    ///
    /// Bit-identical to `k` sequential `forward_select` calls: the batched Q8 GEMV
    /// is exact per column, `rms_norm_batch_f32` is equal per row, and the batched
    /// conv preserves tap order and reads the pre-chunk state for every row.
    fn forward_prefill_chunk(
        &mut self,
        embeddings: &[f32],
        cos: &[f32],
        sin: &[f32],
        n_tokens: usize,
    ) -> Option<()> {
        let c = self.config;
        let half = c.rope_dim / 2;
        if n_tokens == 0
            || embeddings.len() != n_tokens * c.hidden
            || cos.len() != n_tokens * half
            || sin.len() != n_tokens * half
            || self.filled + n_tokens > self.max_positions
        {
            return None;
        }
        let k = metal_linear_kernel()?;
        let base = self.filled;
        let q_dim = c.n_heads * c.head_dim;
        let kv_dim = c.n_kv_heads * c.head_dim;

        // Tiled simdgroup-matrix GEMM for the prefill projections. The batched GEMV
        // re-reads every weight block once per 8 columns; `q8_0_block_wire_mm` reads
        // it once per 128 and stages both operands in threadgroup memory. It is NOT
        // bit-identical to the GEMV (half operand staging + tile-MMA accumulation
        // order), so it is gated and the greedy-parity fixtures are what admit it.
        let mm_ok = crate::runnable::lfm2_prefill_mm_enabled()
            && [3 * c.hidden, c.hidden, q_dim, kv_dim, c.ffn_dim]
                .iter()
                .all(|r| r.is_multiple_of(2 * PREFILL_MM_ROW_TILE))
            && [c.hidden, q_dim, c.ffn_dim]
                .iter()
                .all(|w| w.is_multiple_of(32))
            && threadgroup_alloc_fits(&k.device, PREFILL_MM_THREADGROUP_BYTES);
        // The kernel's direct device loads read whole 128-token tiles, so the half
        // activation panels are padded up to a tile. Padding rows only feed output
        // columns past `n_rows_in`, which are never stored.
        let pad = if mm_ok {
            n_tokens.next_multiple_of(PREFILL_MM_TOKEN_TILE)
        } else {
            n_tokens
        };

        let big_a = pool_get(k, (n_tokens * c.hidden * 4) as u64);
        let big_b = pool_get(k, (n_tokens * c.hidden * 4) as u64);
        write_buffer_f32(&big_a, embeddings);
        let cos_buf = qwen35_f32_buffer(k, cos);
        let sin_buf = qwen35_f32_buffer(k, sin);

        let cb = k.queue.new_command_buffer();
        let e = cb.new_compute_command_encoder();
        let mut keep = vec![
            big_a.to_owned(),
            big_b.to_owned(),
            cos_buf.to_owned(),
            sin_buf.to_owned(),
        ];

        let norm_scalar = pool_get(k, 8);
        unsafe {
            let p = norm_scalar.contents() as *mut u8;
            *(p as *mut u32) = c.hidden as u32;
            *(p.add(4) as *mut f32) = c.eps;
        }

        // Half staging panels, one per contraction width the prefill uses. Zeroed so
        // the padding tail is defined rather than whatever the pool handed back.
        let (half_hidden, half_ffn, stage_counts) = if mm_ok {
            let hh = pool_get(k, (pad * c.hidden * 2) as u64);
            let hf = pool_get(k, (pad * c.ffn_dim * 2) as u64);
            let counts = pool_get(k, 8);
            unsafe {
                std::ptr::write_bytes(hh.contents() as *mut u8, 0, pad * c.hidden * 2);
                std::ptr::write_bytes(hf.contents() as *mut u8, 0, pad * c.ffn_dim * 2);
                let p = counts.contents() as *mut u32;
                *p = (n_tokens * c.hidden) as u32;
                *p.add(1) = (n_tokens * c.ffn_dim) as u32;
            }
            (Some(hh), Some(hf), Some(counts))
        } else {
            (None, None, None)
        };

        // One projection. Uses the tiled MM when admitted, else the bit-exact batched
        // GEMV. `in_width` selects which half panel stages the activation.
        let gemm = |e: &metal::ComputeCommandEncoderRef,
                    keep: &mut Vec<Buffer>,
                    y: &Buffer,
                    w: &ResidentLinearWeight,
                    out: &Buffer,
                    scalar: &Buffer,
                    in_width: usize,
                    rows: usize| {
            if !mm_ok || w.format != ResidentWeightFormat::Q8_0 || !w.q8_wire {
                encode_resident_matmul_f32(e, k, keep, y, w, out, scalar, in_width, rows, n_tokens);
                return;
            }
            let (panel, count_off) = if in_width == c.ffn_dim {
                (half_ffn.as_ref().expect("ffn panel"), 4u64)
            } else {
                (half_hidden.as_ref().expect("hidden panel"), 0u64)
            };
            let counts = stage_counts.as_ref().expect("stage counts");
            e.set_compute_pipeline_state(&k.f32_to_f16_pipeline);
            e.set_buffer(0, Some(y), 0);
            e.set_buffer(1, Some(panel), 0);
            e.set_buffer(2, Some(counts), count_off);
            dispatch_1d(e, &k.f32_to_f16_pipeline, n_tokens * in_width);
            unsafe {
                let p = scalar.contents() as *mut u32;
                *p = (in_width / 32) as u32;
                *p.add(1) = rows as u32;
                *p.add(2) = n_tokens as u32;
            }
            e.set_compute_pipeline_state(&k.q8_0_block_wire_mm_pipeline);
            e.set_buffer(0, Some(panel), 0);
            e.set_buffer(2, Some(&w.buffer), 0);
            e.set_buffer(3, Some(out), 0);
            e.set_buffer(4, Some(scalar), 0);
            e.set_buffer(5, Some(scalar), 4);
            e.set_buffer(6, Some(scalar), 8);
            e.set_threadgroup_memory_length(0, PREFILL_MM_THREADGROUP_BYTES as u64);
            e.dispatch_thread_groups(
                metal::MTLSize {
                    width: (rows / PREFILL_MM_ROW_TILE) as u64,
                    height: (n_tokens as u64).div_ceil(PREFILL_MM_TOKEN_TILE as u64),
                    depth: 1,
                },
                metal::MTLSize {
                    width: 256,
                    height: 1,
                    depth: 1,
                },
            );
        };

        for layer in &self.layers {
            // ---- mixer ----
            let normed = pool_get(k, (n_tokens * c.hidden * 4) as u64);
            encode_rms_norm_batch(
                k,
                e,
                &big_a,
                &layer.attn_norm,
                &normed,
                &norm_scalar,
                n_tokens,
            );
            let mix = pool_get(k, (n_tokens * c.hidden * 4) as u64);

            match &layer.kind {
                Lfm2MetalLayerKind::Conv {
                    in_proj,
                    out_proj,
                    conv,
                    conv_state,
                } => {
                    let bcx = pool_get(k, (n_tokens * 3 * c.hidden * 4) as u64);
                    let mixed = pool_get(k, (n_tokens * c.hidden * 4) as u64);
                    let in_mm = pool_get(k, 12);
                    let out_mm = pool_get(k, 12);
                    let conv_scalar = pool_get(k, 12);
                    unsafe {
                        let s = conv_scalar.contents() as *mut u32;
                        *s = c.hidden as u32;
                        *s.add(1) = c.l_cache as u32;
                        *s.add(2) = n_tokens as u32;
                    }
                    gemm(
                        e,
                        &mut keep,
                        &normed,
                        in_proj,
                        &bcx,
                        &in_mm,
                        c.hidden,
                        3 * c.hidden,
                    );
                    e.set_compute_pipeline_state(&k.lfm2_shortconv_batch_pipeline);
                    e.set_buffer(0, Some(&bcx), 0);
                    e.set_buffer(1, Some(conv), 0);
                    e.set_buffer(2, Some(conv_state), 0);
                    e.set_buffer(3, Some(&mixed), 0);
                    e.set_buffer(4, Some(&conv_scalar), 0);
                    e.set_buffer(5, Some(&conv_scalar), 4);
                    e.set_buffer(6, Some(&conv_scalar), 8);
                    e.dispatch_thread_groups(
                        metal::MTLSize {
                            width: (c.hidden as u64).div_ceil(32),
                            height: n_tokens as u64,
                            depth: 1,
                        },
                        metal::MTLSize {
                            width: 32,
                            height: 1,
                            depth: 1,
                        },
                    );
                    // Advance the ring only after every row has read the pre-chunk state.
                    e.set_compute_pipeline_state(&k.lfm2_shortconv_state_update_pipeline);
                    e.set_buffer(0, Some(&bcx), 0);
                    e.set_buffer(1, Some(conv_state), 0);
                    e.set_buffer(2, Some(&conv_scalar), 0);
                    e.set_buffer(3, Some(&conv_scalar), 4);
                    e.set_buffer(4, Some(&conv_scalar), 8);
                    dispatch_1d(e, &k.lfm2_shortconv_state_update_pipeline, c.hidden);
                    gemm(
                        e, &mut keep, &mixed, out_proj, &mix, &out_mm, c.hidden, c.hidden,
                    );
                    keep.extend([bcx, mixed, in_mm, out_mm, conv_scalar]);
                }
                Lfm2MetalLayerKind::Attn {
                    q: qw,
                    k: kw,
                    v: vw,
                    output: ow,
                    q_norm,
                    k_norm,
                    cache_k,
                    cache_v,
                } => {
                    let query = pool_get(k, (n_tokens * q_dim * 4) as u64);
                    let key = pool_get(k, (n_tokens * kv_dim * 4) as u64);
                    let value = pool_get(k, (n_tokens * kv_dim * 4) as u64);
                    let context = pool_get(k, (n_tokens * q_dim * 4) as u64);
                    let q_mm = pool_get(k, 12);
                    let kv_mm = pool_get(k, 12);
                    let o_mm = pool_get(k, 12);
                    let qk_norm_scalar = pool_get(k, 12);
                    let mirror_flag = pool_get(k, 4);
                    unsafe {
                        let n = qk_norm_scalar.contents() as *mut u8;
                        *(n as *mut u32) = c.head_dim as u32;
                        *(n.add(4) as *mut f32) = c.eps;
                        *(n.add(8) as *mut u32) = 1;
                        *(mirror_flag.contents() as *mut u32) = 0;
                    }
                    gemm(e, &mut keep, &normed, qw, &query, &q_mm, c.hidden, q_dim);
                    gemm(e, &mut keep, &normed, kw, &key, &kv_mm, c.hidden, kv_dim);
                    gemm(e, &mut keep, &normed, vw, &value, &kv_mm, c.hidden, kv_dim);
                    // Per row from here: RoPE angle, cache slot and causal span all
                    // differ by position.
                    for i in 0..n_tokens {
                        let pos = base + i;
                        let q_off = (i * q_dim * 4) as u64;
                        let kv_off = (i * kv_dim * 4) as u64;
                        encode_rms_norm_per_head(
                            e,
                            k,
                            &query,
                            q_norm,
                            &query,
                            &qk_norm_scalar,
                            c.n_heads,
                            q_off,
                        );
                        encode_rms_norm_per_head(
                            e,
                            k,
                            &key,
                            k_norm,
                            &key,
                            &qk_norm_scalar,
                            c.n_kv_heads,
                            kv_off,
                        );
                        let q_rope = pool_get(k, 16);
                        let k_rope = pool_get(k, 16);
                        let scatter_scalar = pool_get(k, 16);
                        let attn_scalar = pool_get(k, 32);
                        let filled = pos + 1;
                        unsafe {
                            let set_rope = |buffer: &Buffer, heads: usize| {
                                let r = buffer.contents() as *mut u32;
                                *r = heads as u32;
                                *r.add(1) = c.head_dim as u32;
                                *r.add(2) = half as u32;
                                *r.add(3) = 1;
                            };
                            set_rope(&q_rope, c.n_heads);
                            set_rope(&k_rope, c.n_kv_heads);
                            let sc = scatter_scalar.contents() as *mut u32;
                            *sc = c.head_dim as u32;
                            *sc.add(1) = self.max_positions as u32;
                            *sc.add(2) = pos as u32;
                            *sc.add(3) = kv_dim as u32;
                            let a = attn_scalar.contents() as *mut u8;
                            *(a as *mut u32) = c.n_heads as u32;
                            *(a.add(4) as *mut u32) = c.head_dim as u32;
                            *(a.add(8) as *mut u32) = filled as u32;
                            *(a.add(12) as *mut u32) = (c.n_heads / c.n_kv_heads) as u32;
                            *(a.add(16) as *mut f32) = 1.0 / (c.head_dim as f32).sqrt();
                            *(a.add(20) as *mut u32) = c.head_dim as u32;
                            *(a.add(24) as *mut u32) = (self.max_positions * c.head_dim) as u32;
                            *(a.add(28) as *mut u32) = 0;
                        }
                        let row_cos = (i * half * 4) as u64;
                        encode_rope(
                            e, k, &query, &cos_buf, &sin_buf, &q_rope, c.n_heads, half, q_off,
                            row_cos,
                        );
                        encode_rope(
                            e,
                            k,
                            &key,
                            &cos_buf,
                            &sin_buf,
                            &k_rope,
                            c.n_kv_heads,
                            half,
                            kv_off,
                            row_cos,
                        );
                        e.set_compute_pipeline_state(&k.kv_scatter_pipeline);
                        e.set_buffer(0, Some(&key), kv_off);
                        e.set_buffer(1, Some(&value), kv_off);
                        e.set_buffer(2, Some(cache_k), 0);
                        e.set_buffer(3, Some(cache_v), 0);
                        e.set_buffer(4, Some(&scatter_scalar), 0);
                        e.set_buffer(5, Some(&scatter_scalar), 4);
                        e.set_buffer(6, Some(&scatter_scalar), 8);
                        e.set_buffer(7, Some(&scatter_scalar), 12);
                        e.set_buffer(8, Some(&scatter_scalar), 0);
                        e.set_buffer(9, Some(&scatter_scalar), 0);
                        e.set_buffer(10, Some(&mirror_flag), 0);
                        dispatch_1d(e, &k.kv_scatter_pipeline, kv_dim);
                        let scores = pool_get(k, (c.n_heads * filled * 4) as u64);
                        encode_attention(
                            e,
                            k,
                            &mut keep,
                            &query,
                            cache_k,
                            cache_v,
                            None,
                            &scores,
                            &context,
                            &attn_scalar,
                            c.n_heads,
                            c.n_kv_heads,
                            c.head_dim,
                            filled,
                            q_off,
                            q_off,
                        );
                        keep.extend([q_rope, k_rope, scatter_scalar, attn_scalar, scores]);
                    }
                    gemm(e, &mut keep, &context, ow, &mix, &o_mm, q_dim, c.hidden);
                    keep.extend([
                        query,
                        key,
                        value,
                        context,
                        q_mm,
                        kv_mm,
                        o_mm,
                        qk_norm_scalar,
                        mirror_flag,
                    ]);
                }
            }

            let n_hidden = pool_get(k, 4);
            unsafe { *(n_hidden.contents() as *mut u32) = (n_tokens * c.hidden) as u32 };
            encode_binary(
                e,
                &k.residual_add_pipeline,
                &big_a,
                &mix,
                &big_b,
                &n_hidden,
                n_tokens * c.hidden,
            );

            // ---- FFN ----
            let fnormed = pool_get(k, (n_tokens * c.hidden * 4) as u64);
            let gate = pool_get(k, (n_tokens * c.ffn_dim * 4) as u64);
            let up = pool_get(k, (n_tokens * c.ffn_dim * 4) as u64);
            let act = pool_get(k, (n_tokens * c.ffn_dim * 4) as u64);
            let down = pool_get(k, (n_tokens * c.hidden * 4) as u64);
            let hidden_mm = pool_get(k, 12);
            let down_mm = pool_get(k, 12);
            let n_ffn = pool_get(k, 4);
            unsafe { *(n_ffn.contents() as *mut u32) = (n_tokens * c.ffn_dim) as u32 };
            encode_rms_norm_batch(
                k,
                e,
                &big_b,
                &layer.ffn_norm,
                &fnormed,
                &norm_scalar,
                n_tokens,
            );
            gemm(
                e,
                &mut keep,
                &fnormed,
                &layer.ffn_gate,
                &gate,
                &hidden_mm,
                c.hidden,
                c.ffn_dim,
            );
            gemm(
                e,
                &mut keep,
                &fnormed,
                &layer.ffn_up,
                &up,
                &hidden_mm,
                c.hidden,
                c.ffn_dim,
            );
            encode_binary(
                e,
                &k.silu_mul_pipeline,
                &gate,
                &up,
                &act,
                &n_ffn,
                n_tokens * c.ffn_dim,
            );
            gemm(
                e,
                &mut keep,
                &act,
                &layer.ffn_down,
                &down,
                &down_mm,
                c.ffn_dim,
                c.hidden,
            );
            encode_binary(
                e,
                &k.residual_add_pipeline,
                &big_b,
                &down,
                &big_a,
                &n_hidden,
                n_tokens * c.hidden,
            );
            keep.extend([
                normed, mix, fnormed, gate, up, act, down, hidden_mm, down_mm, n_ffn, n_hidden,
            ]);
        }

        e.end_encoding();
        cb.commit();
        cb.wait_until_completed();
        // Same contract as the qwen35 prefill: an errored command buffer ran none of its
        // dispatches, so advancing `filled` would claim a prompt the caches never saw.
        // Fail closed and let the caller fall back rather than decode from empty state.
        let status = cb.status();
        let completed = status == metal::MTLCommandBufferStatus::Completed;
        keep.push(norm_scalar);
        pool_recycle(k, keep);
        if !completed {
            eprintln!(
                "[lfm2] Metal prefill command buffer did not complete ({status:?}); prompt not \
                 resident, falling back to the CPU lane for this request"
            );
            return None;
        }
        self.filled += n_tokens;
        Some(())
    }

    /// Chunked prompt prefill. Returns once every prompt position EXCEPT the last
    /// has been consumed; the caller runs the last one through a normal step so it
    /// produces logits.
    pub(crate) fn prefill_prompt(
        &mut self,
        embeddings: &[f32],
        cos: &[f32],
        sin: &[f32],
        n_tokens: usize,
        chunk: usize,
    ) -> Option<()> {
        let c = self.config;
        let half = c.rope_dim / 2;
        let chunk = chunk.max(1);
        let mut done = 0usize;
        while done < n_tokens {
            let take = chunk.min(n_tokens - done);
            self.forward_prefill_chunk(
                &embeddings[done * c.hidden..(done + take) * c.hidden],
                &cos[done * half..(done + take) * half],
                &sin[done * half..(done + take) * half],
                take,
            )?;
            done += take;
        }
        Some(())
    }

    /// Advance one position and return the greedy token id.
    pub(crate) fn step_greedy(
        &mut self,
        embedding: &[f32],
        cos: &[f32],
        sin: &[f32],
        position: usize,
    ) -> Option<u32> {
        match self.forward_select(embedding, cos, sin, position, Qwen35MetalSelection::Greedy)? {
            Qwen35MetalStep::Token(t) => Some(t),
            Qwen35MetalStep::Logits(_) => None,
        }
    }

    /// Advance one position and return the full logits row (for sampled requests).
    pub(crate) fn step_logits(
        &mut self,
        embedding: &[f32],
        cos: &[f32],
        sin: &[f32],
        position: usize,
    ) -> Option<Vec<f32>> {
        match self.forward_select(embedding, cos, sin, position, Qwen35MetalSelection::Logits)? {
            Qwen35MetalStep::Logits(v) => Some(v),
            Qwen35MetalStep::Token(_) => None,
        }
    }
}

/// LFM2 short-convolution layer: attn_norm -> in_proj -> shortconv -> out_proj -> residual.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_lfm2_conv_layer(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    keep: &mut Vec<Buffer>,
    input: &Buffer,
    output: &Buffer,
    layer: &Lfm2MetalLayer,
    c: Lfm2MetalConfig,
) {
    let Lfm2MetalLayerKind::Conv {
        in_proj,
        out_proj,
        conv,
        conv_state,
    } = &layer.kind
    else {
        unreachable!()
    };
    let normed = pool_get(k, (c.hidden * 4) as u64);
    let bcx = pool_get(k, (3 * c.hidden * 4) as u64);
    let mixed = pool_get(k, (c.hidden * 4) as u64);
    let mix = pool_get(k, (c.hidden * 4) as u64);
    let norm_scalar = pool_get(k, 8);
    let in_mm = pool_get(k, 12);
    let out_mm = pool_get(k, 12);
    let conv_scalar = pool_get(k, 8);
    let n_hidden = pool_get(k, 4);
    unsafe {
        let p = norm_scalar.contents() as *mut u8;
        *(p as *mut u32) = c.hidden as u32;
        *(p.add(4) as *mut f32) = c.eps;
        let s = conv_scalar.contents() as *mut u32;
        *s = c.hidden as u32;
        *s.add(1) = c.l_cache as u32;
        *(n_hidden.contents() as *mut u32) = c.hidden as u32;
    }
    encode_rms_norm_f32(e, k, input, &layer.attn_norm, &normed, &norm_scalar);
    encode_resident_matmul_f32(
        e,
        k,
        keep,
        &normed,
        in_proj,
        &bcx,
        &in_mm,
        c.hidden,
        3 * c.hidden,
        1,
    );
    e.set_compute_pipeline_state(&k.lfm2_shortconv_pipeline);
    e.set_buffer(0, Some(&bcx), 0);
    e.set_buffer(1, Some(conv), 0);
    e.set_buffer(2, Some(conv_state), 0);
    e.set_buffer(3, Some(&mixed), 0);
    e.set_buffer(4, Some(&conv_scalar), 0);
    e.set_buffer(5, Some(&conv_scalar), 4);
    dispatch_1d(e, &k.lfm2_shortconv_pipeline, c.hidden);
    encode_resident_matmul_f32(
        e, k, keep, &mixed, out_proj, &mix, &out_mm, c.hidden, c.hidden, 1,
    );
    encode_binary(
        e,
        &k.residual_add_pipeline,
        input,
        &mix,
        output,
        &n_hidden,
        c.hidden,
    );
    keep.extend([
        normed,
        bcx,
        mixed,
        mix,
        norm_scalar,
        in_mm,
        out_mm,
        conv_scalar,
        n_hidden,
    ]);
}

/// LFM2 GQA attention layer. `encode_qwen35_full_layer` minus the fused query+gate
/// projection (LFM2's `attn_q` is plain `hidden -> q_dim`) and minus the sigmoid output
/// gate. QK-norm runs BEFORE RoPE, per llama.cpp `src/models/lfm2.cpp` build_attn_block.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_lfm2_attn_layer(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    keep: &mut Vec<Buffer>,
    input: &Buffer,
    output: &Buffer,
    layer: &Lfm2MetalLayer,
    cos: &Buffer,
    sin: &Buffer,
    c: Lfm2MetalConfig,
    max_positions: usize,
    position: usize,
) {
    let Lfm2MetalLayerKind::Attn {
        q: q_weight,
        k: k_weight,
        v: v_weight,
        output: o_weight,
        q_norm,
        k_norm,
        cache_k,
        cache_v,
    } = &layer.kind
    else {
        unreachable!()
    };
    let q_dim = c.n_heads * c.head_dim;
    let kv_dim = c.n_kv_heads * c.head_dim;
    let filled = position + 1;
    let normed = pool_get(k, (c.hidden * 4) as u64);
    let query = pool_get(k, (q_dim * 4) as u64);
    let key = pool_get(k, (kv_dim * 4) as u64);
    let value = pool_get(k, (kv_dim * 4) as u64);
    let scores = pool_get(k, (c.n_heads * filled * 4) as u64);
    let context = pool_get(k, (q_dim * 4) as u64);
    let mix = pool_get(k, (c.hidden * 4) as u64);
    let norm_scalar = pool_get(k, 8);
    let q_mm = pool_get(k, 12);
    let kv_mm = pool_get(k, 12);
    let o_mm = pool_get(k, 12);
    let qk_norm_scalar = pool_get(k, 12);
    let q_rope = pool_get(k, 16);
    let k_rope = pool_get(k, 16);
    let scatter_scalar = pool_get(k, 16);
    let mirror_flag = pool_get(k, 4);
    let attn_scalar = pool_get(k, 32);
    let n_hidden = pool_get(k, 4);
    unsafe {
        let p = norm_scalar.contents() as *mut u8;
        *(p as *mut u32) = c.hidden as u32;
        *(p.add(4) as *mut f32) = c.eps;
        let n = qk_norm_scalar.contents() as *mut u8;
        *(n as *mut u32) = c.head_dim as u32;
        *(n.add(4) as *mut f32) = c.eps;
        *(n.add(8) as *mut u32) = 1;
        let set_rope = |buffer: &Buffer, heads: usize| {
            let r = buffer.contents() as *mut u32;
            *r = heads as u32;
            *r.add(1) = c.head_dim as u32;
            *r.add(2) = (c.rope_dim / 2) as u32;
            // pairing = 1 => NEOX split-half, which llama.cpp assigns LLM_ARCH_LFM2.
            *r.add(3) = 1;
        };
        set_rope(&q_rope, c.n_heads);
        set_rope(&k_rope, c.n_kv_heads);
        let sc = scatter_scalar.contents() as *mut u32;
        *sc = c.head_dim as u32;
        *sc.add(1) = max_positions as u32;
        *sc.add(2) = position as u32;
        *sc.add(3) = kv_dim as u32;
        *(mirror_flag.contents() as *mut u32) = 0;
        let a = attn_scalar.contents() as *mut u8;
        *(a as *mut u32) = c.n_heads as u32;
        *(a.add(4) as *mut u32) = c.head_dim as u32;
        *(a.add(8) as *mut u32) = filled as u32;
        *(a.add(12) as *mut u32) = (c.n_heads / c.n_kv_heads) as u32;
        *(a.add(16) as *mut f32) = 1.0 / (c.head_dim as f32).sqrt();
        *(a.add(20) as *mut u32) = c.head_dim as u32;
        *(a.add(24) as *mut u32) = (max_positions * c.head_dim) as u32;
        *(a.add(28) as *mut u32) = 0;
        *(n_hidden.contents() as *mut u32) = c.hidden as u32;
    }
    encode_rms_norm_f32(e, k, input, &layer.attn_norm, &normed, &norm_scalar);
    encode_resident_matmul_f32(
        e, k, keep, &normed, q_weight, &query, &q_mm, c.hidden, q_dim, 1,
    );
    encode_resident_matmul_f32(
        e, k, keep, &normed, k_weight, &key, &kv_mm, c.hidden, kv_dim, 1,
    );
    encode_resident_matmul_f32(
        e, k, keep, &normed, v_weight, &value, &kv_mm, c.hidden, kv_dim, 1,
    );
    encode_rms_norm_per_head(e, k, &query, q_norm, &query, &qk_norm_scalar, c.n_heads, 0);
    encode_rms_norm_per_head(e, k, &key, k_norm, &key, &qk_norm_scalar, c.n_kv_heads, 0);
    encode_rope(
        e,
        k,
        &query,
        cos,
        sin,
        &q_rope,
        c.n_heads,
        c.rope_dim / 2,
        0,
        0,
    );
    encode_rope(
        e,
        k,
        &key,
        cos,
        sin,
        &k_rope,
        c.n_kv_heads,
        c.rope_dim / 2,
        0,
        0,
    );
    e.set_compute_pipeline_state(&k.kv_scatter_pipeline);
    e.set_buffer(0, Some(&key), 0);
    e.set_buffer(1, Some(&value), 0);
    e.set_buffer(2, Some(cache_k), 0);
    e.set_buffer(3, Some(cache_v), 0);
    e.set_buffer(4, Some(&scatter_scalar), 0);
    e.set_buffer(5, Some(&scatter_scalar), 4);
    e.set_buffer(6, Some(&scatter_scalar), 8);
    e.set_buffer(7, Some(&scatter_scalar), 12);
    e.set_buffer(8, Some(&scatter_scalar), 0);
    e.set_buffer(9, Some(&scatter_scalar), 0);
    e.set_buffer(10, Some(&mirror_flag), 0);
    dispatch_1d(e, &k.kv_scatter_pipeline, kv_dim);
    encode_attention(
        e,
        k,
        keep,
        &query,
        cache_k,
        cache_v,
        None,
        &scores,
        &context,
        &attn_scalar,
        c.n_heads,
        c.n_kv_heads,
        c.head_dim,
        filled,
        0,
        0,
    );
    encode_resident_matmul_f32(
        e, k, keep, &context, o_weight, &mix, &o_mm, q_dim, c.hidden, 1,
    );
    encode_binary(
        e,
        &k.residual_add_pipeline,
        input,
        &mix,
        output,
        &n_hidden,
        c.hidden,
    );
    keep.extend([
        normed,
        query,
        key,
        value,
        scores,
        context,
        mix,
        norm_scalar,
        q_mm,
        kv_mm,
        o_mm,
        qk_norm_scalar,
        q_rope,
        k_rope,
        scatter_scalar,
        mirror_flag,
        attn_scalar,
        n_hidden,
    ]);
}

/// LFM2 SwiGLU FFN — `encode_qwen35_ffn` with `post_attn_norm` renamed to `ffn_norm`.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
fn encode_lfm2_ffn(
    e: &metal::ComputeCommandEncoderRef,
    k: &MetalLinearKernel,
    keep: &mut Vec<Buffer>,
    input: &Buffer,
    output: &Buffer,
    layer: &Lfm2MetalLayer,
    c: Lfm2MetalConfig,
) {
    let normed = pool_get(k, (c.hidden * 4) as u64);
    let norm_scalar = pool_get(k, 8);
    let gate = pool_get(k, (c.ffn_dim * 4) as u64);
    let up = pool_get(k, (c.ffn_dim * 4) as u64);
    let act = pool_get(k, (c.ffn_dim * 4) as u64);
    let down = pool_get(k, (c.hidden * 4) as u64);
    let hidden_mm = pool_get(k, 12);
    let down_mm = pool_get(k, 12);
    let n_ffn = pool_get(k, 4);
    let n_hidden = pool_get(k, 4);
    unsafe {
        let p = norm_scalar.contents() as *mut u8;
        *(p as *mut u32) = c.hidden as u32;
        *(p.add(4) as *mut f32) = c.eps;
        *(n_ffn.contents() as *mut u32) = c.ffn_dim as u32;
        *(n_hidden.contents() as *mut u32) = c.hidden as u32;
    }
    encode_rms_norm_f32(e, k, input, &layer.ffn_norm, &normed, &norm_scalar);
    encode_resident_matmul_f32(
        e,
        k,
        keep,
        &normed,
        &layer.ffn_gate,
        &gate,
        &hidden_mm,
        c.hidden,
        c.ffn_dim,
        1,
    );
    encode_resident_matmul_f32(
        e,
        k,
        keep,
        &normed,
        &layer.ffn_up,
        &up,
        &hidden_mm,
        c.hidden,
        c.ffn_dim,
        1,
    );
    encode_binary(e, &k.silu_mul_pipeline, &gate, &up, &act, &n_ffn, c.ffn_dim);
    encode_resident_matmul_f32(
        e,
        k,
        keep,
        &act,
        &layer.ffn_down,
        &down,
        &down_mm,
        c.ffn_dim,
        c.hidden,
        1,
    );
    encode_binary(
        e,
        &k.residual_add_pipeline,
        input,
        &down,
        output,
        &n_hidden,
        c.hidden,
    );
    keep.extend([
        normed,
        norm_scalar,
        gate,
        up,
        act,
        down,
        hidden_mm,
        down_mm,
        n_ffn,
        n_hidden,
    ]);
}

/// Hand out a scratch buffer of at least `bytes` from the recycle pool, or allocate a
/// fresh one at the pool's power-of-two class size. Pool-derived buffers are owned by the
/// per-token `keep` vec and MUST come back via `pool_recycle` only after the command
/// buffer that referenced them has completed.
#[cfg(target_os = "macos")]
fn pool_get(k: &MetalLinearKernel, bytes: u64) -> Buffer {
    let class = bytes.max(32).next_power_of_two();
    if let Some(buf) = k
        .scratch_pool
        .lock()
        .unwrap()
        .get_mut(&class)
        .and_then(|v| v.pop())
    {
        return buf;
    }
    k.device
        .new_buffer(class, MTLResourceOptions::StorageModeShared)
}

/// Return settled scratch buffers to the pool (keyed by their class-sized length).
#[cfg(target_os = "macos")]
fn pool_recycle<I: IntoIterator<Item = Buffer>>(k: &MetalLinearKernel, bufs: I) {
    let mut pool = k.scratch_pool.lock().unwrap();
    for b in bufs {
        pool.entry(b.length()).or_default().push(b);
    }
}

/// Allocate a fresh GPU buffer for a Q8_0 weight-block slice and upload it. Used by the
/// standalone block helpers, which (unlike the resident decode forward) do not keep weights
/// cached across calls.
#[cfg(target_os = "macos")]
fn upload_weight_buffer(k: &MetalLinearKernel, weight_blocks: &[u8]) -> Buffer {
    let buf = k.device.new_buffer(
        weight_blocks.len() as u64,
        MTLResourceOptions::StorageModeShared,
    );
    write_buffer_u8(&buf, weight_blocks);
    buf
}

/// Allocate a fresh f32 GPU buffer sized to `cache` and upload it. Used by the standalone
/// block helpers to hand `encode_attention_block` a transient per-call KV cache buffer
/// (`max_positions == position_count`); the resident decode session passes persistent
/// buffers instead.
#[cfg(target_os = "macos")]
fn upload_cache_buffer(k: &MetalLinearKernel, cache: &[f32]) -> Buffer {
    let buf = k.device.new_buffer(
        (cache.len() * 4) as u64,
        MTLResourceOptions::StorageModeShared,
    );
    write_buffer_f32(&buf, cache);
    buf
}

/// GPU-resident FFN block in a single command buffer (no CPU readback between ops):
/// rms_norm -> quantize -> gate & up matmul -> silu_mul -> quantize -> down matmul ->
/// residual add with the input. Weights are Q8_0 36-byte blocks (gate/up are
/// [ffn_dim x hidden/32], down is [hidden x ffn_dim/32]). Returns [hidden]; None if
/// Metal is unavailable. Bit-identical to running the standalone kernels in sequence.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
pub fn try_ffn_block_resident(
    input: &[f32],
    ffn_norm: &[f32],
    eps: f32,
    gate_weight_blocks: &[u8],
    up_weight_blocks: &[u8],
    down_weight_blocks: &[u8],
    ffn_dim: usize,
) -> Option<Vec<f32>> {
    let hidden = input.len();
    if hidden == 0
        || !hidden.is_multiple_of(32)
        || ffn_dim == 0
        || !ffn_dim.is_multiple_of(32)
        || ffn_norm.len() != hidden
    {
        return None;
    }
    let bpr_hidden = hidden / 32;
    let bpr_ffn = ffn_dim / 32;
    if gate_weight_blocks.len() != ffn_dim * bpr_hidden * 36
        || up_weight_blocks.len() != ffn_dim * bpr_hidden * 36
        || down_weight_blocks.len() != hidden * bpr_ffn * 36
    {
        return None;
    }
    let k = metal_linear_kernel()?;
    let nb = |n: usize| {
        k.device
            .new_buffer((n * 4) as u64, MTLResourceOptions::StorageModeShared)
    };
    let in_buf = nb(hidden);
    let out_buf = nb(hidden);
    write_buffer_f32(&in_buf, input);
    let gate_w = ResidentLinearWeight {
        format: ResidentWeightFormat::Q8_0,
        buffer: upload_weight_buffer(k, gate_weight_blocks),
        q8_wire: false,
    };
    let up_w = ResidentLinearWeight {
        format: ResidentWeightFormat::Q8_0,
        buffer: upload_weight_buffer(k, up_weight_blocks),
        q8_wire: false,
    };
    let down_w = ResidentLinearWeight {
        format: ResidentWeightFormat::Q8_0,
        buffer: upload_weight_buffer(k, down_weight_blocks),
        q8_wire: false,
    };
    let mut keep = Vec::new();
    let cb = k.queue.new_command_buffer();
    let e = cb.new_compute_command_encoder();
    encode_ffn_block(
        e, k, &mut keep, &in_buf, &out_buf, ffn_norm, eps, None, false, &gate_w, &up_w, &down_w,
        ffn_dim,
    );
    e.end_encoding();
    cb.commit();
    cb.wait_until_completed();
    let mut out = vec![0.0f32; hidden];
    read_buffer_f32(&out_buf, &mut out);
    Some(out)
}

/// GPU-resident attention block in a single command buffer (no CPU readback): rms_norm
/// -> quantize -> q/k/v matmul -> RoPE(q,k) -> write current k/v into the KV cache
/// buffers at `position` (blit) -> decode attention over the cache -> quantize -> o
/// matmul -> residual add with the input. `cache_k`/`cache_v` are laid out as
/// `[n_kv * position_count * head_dim]`; positions 0..position-1 are caller-filled, this
/// writes position `position_count-1`. cos/sin tables come from the CPU's RoPE math.
/// Returns the `[hidden]` output, or None if Metal is unavailable. Bit-identical to
/// running the standalone kernels.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
pub fn try_attention_block_resident(
    input: &[f32],
    attn_norm: &[f32],
    eps: f32,
    q_weight_blocks: &[u8],
    k_weight_blocks: &[u8],
    v_weight_blocks: &[u8],
    o_weight_blocks: &[u8],
    cos_t: &[f32],
    sin_t: &[f32],
    cache_k: &[f32],
    cache_v: &[f32],
    n_heads: usize,
    n_kv_heads: usize,
    head_dim: usize,
    position_count: usize,
    scale: f32,
    split_half_pairing: bool,
) -> Option<Vec<f32>> {
    let hidden = input.len();
    let q_dim = n_heads * head_dim;
    let kv_dim = n_kv_heads * head_dim;
    let half_rope = cos_t.len();
    if hidden == 0
        || !hidden.is_multiple_of(32)
        || !q_dim.is_multiple_of(32)
        || head_dim == 0
        || !head_dim.is_multiple_of(2)
        || n_heads == 0
        || n_kv_heads == 0
        || !n_heads.is_multiple_of(n_kv_heads)
        || position_count == 0
        || attn_norm.len() != hidden
        || sin_t.len() != half_rope
        || half_rope * 2 > head_dim
        || cache_k.len() != kv_dim * position_count
        || cache_v.len() != cache_k.len()
    {
        return None;
    }
    let bpr_hidden = hidden / 32;
    let bpr_q = q_dim / 32;
    if q_weight_blocks.len() != q_dim * bpr_hidden * 36
        || k_weight_blocks.len() != kv_dim * bpr_hidden * 36
        || v_weight_blocks.len() != kv_dim * bpr_hidden * 36
        || o_weight_blocks.len() != hidden * bpr_q * 36
    {
        return None;
    }
    let k = metal_linear_kernel()?;
    let nb = |n: usize| {
        k.device
            .new_buffer((n * 4) as u64, MTLResourceOptions::StorageModeShared)
    };
    let in_buf = nb(hidden);
    let out_buf = nb(hidden);
    write_buffer_f32(&in_buf, input);
    let q_w = ResidentLinearWeight {
        format: ResidentWeightFormat::Q8_0,
        buffer: upload_weight_buffer(k, q_weight_blocks),
        q8_wire: false,
    };
    let k_w = ResidentLinearWeight {
        format: ResidentWeightFormat::Q8_0,
        buffer: upload_weight_buffer(k, k_weight_blocks),
        q8_wire: false,
    };
    let v_w = ResidentLinearWeight {
        format: ResidentWeightFormat::Q8_0,
        buffer: upload_weight_buffer(k, v_weight_blocks),
        q8_wire: false,
    };
    let o_w = ResidentLinearWeight {
        format: ResidentWeightFormat::Q8_0,
        buffer: upload_weight_buffer(k, o_weight_blocks),
        q8_wire: false,
    };
    let cache_k_buf = upload_cache_buffer(k, cache_k);
    let cache_v_buf = upload_cache_buffer(k, cache_v);
    let mut keep = Vec::new();
    let cb = k.queue.new_command_buffer();
    let e = cb.new_compute_command_encoder();
    encode_attention_block(
        e,
        k,
        &mut keep,
        &in_buf,
        &out_buf,
        attn_norm,
        eps,
        None,
        None,
        None,
        &q_w,
        &k_w,
        &v_w,
        &o_w,
        cos_t,
        sin_t,
        &cache_k_buf,
        &cache_v_buf,
        None,
        kv16_enabled(),
        kvq8_enabled(),
        position_count,
        position_count - 1,
        n_heads,
        n_kv_heads,
        head_dim,
        position_count,
        0,
        scale,
        split_half_pairing,
    );
    e.end_encoding();
    cb.commit();
    cb.wait_until_completed();
    let mut out = vec![0.0f32; hidden];
    read_buffer_f32(&out_buf, &mut out);
    Some(out)
}

/// GPU-resident decode layer for one token in a SINGLE command buffer: runs the attention
/// block then the FFN block with no CPU readback between them (the attention output stays
/// in a GPU buffer and feeds the FFN block directly), so there is one commit/wait per layer
/// instead of two. Bit-identical to `try_attention_block_resident` followed by
/// `try_ffn_block_resident`. Returns the `[hidden]` layer output, or None if Metal is
/// unavailable or the dimensions are invalid.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
pub fn try_decode_layer_resident(
    input: &[f32],
    attn_norm: &[f32],
    ffn_norm: &[f32],
    eps: f32,
    q_weight_blocks: &[u8],
    k_weight_blocks: &[u8],
    v_weight_blocks: &[u8],
    o_weight_blocks: &[u8],
    gate_weight_blocks: &[u8],
    up_weight_blocks: &[u8],
    down_weight_blocks: &[u8],
    cos_t: &[f32],
    sin_t: &[f32],
    cache_k: &[f32],
    cache_v: &[f32],
    n_heads: usize,
    n_kv_heads: usize,
    head_dim: usize,
    position_count: usize,
    ffn_dim: usize,
    scale: f32,
    split_half_pairing: bool,
) -> Option<Vec<f32>> {
    let hidden = input.len();
    let q_dim = n_heads * head_dim;
    let kv_dim = n_kv_heads * head_dim;
    let half_rope = cos_t.len();
    // Attention-block constraints.
    if hidden == 0
        || !hidden.is_multiple_of(32)
        || !q_dim.is_multiple_of(32)
        || head_dim == 0
        || !head_dim.is_multiple_of(2)
        || n_heads == 0
        || n_kv_heads == 0
        || !n_heads.is_multiple_of(n_kv_heads)
        || position_count == 0
        || attn_norm.len() != hidden
        || sin_t.len() != half_rope
        || half_rope * 2 > head_dim
        || cache_k.len() != kv_dim * position_count
        || cache_v.len() != cache_k.len()
    {
        return None;
    }
    // FFN-block constraints.
    if ffn_dim == 0 || !ffn_dim.is_multiple_of(32) || ffn_norm.len() != hidden {
        return None;
    }
    let bpr_hidden = hidden / 32;
    let bpr_q = q_dim / 32;
    let bpr_ffn = ffn_dim / 32;
    if q_weight_blocks.len() != q_dim * bpr_hidden * 36
        || k_weight_blocks.len() != kv_dim * bpr_hidden * 36
        || v_weight_blocks.len() != kv_dim * bpr_hidden * 36
        || o_weight_blocks.len() != hidden * bpr_q * 36
        || gate_weight_blocks.len() != ffn_dim * bpr_hidden * 36
        || up_weight_blocks.len() != ffn_dim * bpr_hidden * 36
        || down_weight_blocks.len() != hidden * bpr_ffn * 36
    {
        return None;
    }
    let k = metal_linear_kernel()?;
    let nb = |n: usize| {
        k.device
            .new_buffer((n * 4) as u64, MTLResourceOptions::StorageModeShared)
    };
    let in_buf = nb(hidden);
    let attn_buf = nb(hidden);
    let out_buf = nb(hidden);
    write_buffer_f32(&in_buf, input);
    let wrap_q8 = |blocks: &[u8]| ResidentLinearWeight {
        format: ResidentWeightFormat::Q8_0,
        buffer: upload_weight_buffer(k, blocks),
        q8_wire: false,
    };
    let q_w = wrap_q8(q_weight_blocks);
    let k_w = wrap_q8(k_weight_blocks);
    let v_w = wrap_q8(v_weight_blocks);
    let o_w = wrap_q8(o_weight_blocks);
    let gate_w = wrap_q8(gate_weight_blocks);
    let up_w = wrap_q8(up_weight_blocks);
    let down_w = wrap_q8(down_weight_blocks);
    let cache_k_buf = upload_cache_buffer(k, cache_k);
    let cache_v_buf = upload_cache_buffer(k, cache_v);
    let mut keep = Vec::new();
    let cb = k.queue.new_command_buffer();
    let e = cb.new_compute_command_encoder();
    encode_attention_block(
        e,
        k,
        &mut keep,
        &in_buf,
        &attn_buf,
        attn_norm,
        eps,
        None,
        None,
        None,
        &q_w,
        &k_w,
        &v_w,
        &o_w,
        cos_t,
        sin_t,
        &cache_k_buf,
        &cache_v_buf,
        None,
        kv16_enabled(),
        kvq8_enabled(),
        position_count,
        position_count - 1,
        n_heads,
        n_kv_heads,
        head_dim,
        position_count,
        0,
        scale,
        split_half_pairing,
    );
    encode_ffn_block(
        e, k, &mut keep, &attn_buf, &out_buf, ffn_norm, eps, None, false, &gate_w, &up_w, &down_w,
        ffn_dim,
    );
    e.end_encoding();
    cb.commit();
    cb.wait_until_completed();
    let mut out = vec![0.0f32; hidden];
    read_buffer_f32(&out_buf, &mut out);
    Some(out)
}

/// Borrowed per-layer inputs for `try_decode_forward_resident`: the layer's two RMSNorm
/// weights, its seven Q8_0 weight-block buffers (q/k/v/o gate/up/down), and its K/V caches
/// (each `[n_kv_heads * position_count * head_dim]`, positions `0..position_count-1`
/// caller-filled; the current token is written at the last position).
pub struct ResidentDecodeLayer<'a> {
    pub attn_norm: &'a [f32],
    pub ffn_norm: &'a [f32],
    pub q_weight_blocks: &'a [u8],
    pub k_weight_blocks: &'a [u8],
    pub v_weight_blocks: &'a [u8],
    pub o_weight_blocks: &'a [u8],
    pub gate_weight_blocks: &'a [u8],
    pub up_weight_blocks: &'a [u8],
    pub down_weight_blocks: &'a [u8],
    pub cache_k: &'a [f32],
    pub cache_v: &'a [f32],
}

/// GPU-resident per-token decode over ALL transformer layers in a SINGLE command buffer: for
/// each layer the attention block then the FFN block are encoded back-to-back with the hidden
/// state staying in GPU buffers, so the whole token costs exactly ONE commit/wait (vs one per
/// layer for `try_decode_layer_resident`, or one per op for the standalone kernels). RoPE
/// tables and the per-token attention `scale` are shared across layers. `embedding` is the
/// input hidden state `[hidden]`; the returned `[hidden]` is the post-final-layer hidden state
/// (the final norm + output projection are applied by the caller). Bit-identical to feeding
/// each layer's output into the next via `try_decode_layer_resident`. Returns None if Metal is
/// unavailable, `layers` is empty, or any layer's dimensions are invalid.
#[cfg(target_os = "macos")]
#[allow(clippy::too_many_arguments)]
pub fn try_decode_forward_resident(
    embedding: &[f32],
    layers: &[ResidentDecodeLayer],
    cos_t: &[f32],
    sin_t: &[f32],
    eps: f32,
    n_heads: usize,
    n_kv_heads: usize,
    head_dim: usize,
    position_count: usize,
    ffn_dim: usize,
    scale: f32,
    split_half_pairing: bool,
) -> Option<Vec<f32>> {
    let hidden = embedding.len();
    let q_dim = n_heads * head_dim;
    let kv_dim = n_kv_heads * head_dim;
    let half_rope = cos_t.len();
    if hidden == 0
        || !hidden.is_multiple_of(32)
        || !q_dim.is_multiple_of(32)
        || head_dim == 0
        || !head_dim.is_multiple_of(2)
        || n_heads == 0
        || n_kv_heads == 0
        || !n_heads.is_multiple_of(n_kv_heads)
        || position_count == 0
        || sin_t.len() != half_rope
        || half_rope * 2 > head_dim
        || ffn_dim == 0
        || !ffn_dim.is_multiple_of(32)
        || layers.is_empty()
    {
        return None;
    }
    let bpr_hidden = hidden / 32;
    let bpr_q = q_dim / 32;
    let bpr_ffn = ffn_dim / 32;
    for l in layers {
        if l.attn_norm.len() != hidden
            || l.ffn_norm.len() != hidden
            || l.cache_k.len() != kv_dim * position_count
            || l.cache_v.len() != l.cache_k.len()
            || l.q_weight_blocks.len() != q_dim * bpr_hidden * 36
            || l.k_weight_blocks.len() != kv_dim * bpr_hidden * 36
            || l.v_weight_blocks.len() != kv_dim * bpr_hidden * 36
            || l.o_weight_blocks.len() != hidden * bpr_q * 36
            || l.gate_weight_blocks.len() != ffn_dim * bpr_hidden * 36
            || l.up_weight_blocks.len() != ffn_dim * bpr_hidden * 36
            || l.down_weight_blocks.len() != hidden * bpr_ffn * 36
        {
            return None;
        }
    }
    let k = metal_linear_kernel()?;
    let nb = |n: usize| {
        k.device
            .new_buffer((n * 4) as u64, MTLResourceOptions::StorageModeShared)
    };
    // `buf_a`/`buf_b` ping-pong as each layer's in/out hidden; `mid` carries the attention
    // output into the FFN block within a layer. All three are reused across layers: compute
    // encoders execute in submission order with coherency between them, so the sequential
    // reuse is hazard-free (no encoder reads a buffer a later encoder in the same layer step
    // is still writing).
    let buf_a = nb(hidden);
    let buf_b = nb(hidden);
    let mid = nb(hidden);
    write_buffer_f32(&buf_a, embedding);
    // Resolve every layer's Q8_0 weights to cache-resident GPU buffers up front. They are
    // keyed by (pointer, len) in `MetalLinearCache`, so the first decode of a model uploads
    // them and every subsequent token reuses the same on-GPU buffers -- the upload-once win.
    let resident: Vec<[ResidentLinearWeight; 7]> = {
        let mut cache = metal_linear_cache().lock().ok()?;
        layers
            .iter()
            .map(|l| {
                let q8 = |buffer| ResidentLinearWeight {
                    format: ResidentWeightFormat::Q8_0,
                    buffer,
                    q8_wire: false,
                };
                [
                    q8(cache.q8_block_weight_buffer(&k.device, l.q_weight_blocks)),
                    q8(cache.q8_block_weight_buffer(&k.device, l.k_weight_blocks)),
                    q8(cache.q8_block_weight_buffer(&k.device, l.v_weight_blocks)),
                    q8(cache.q8_block_weight_buffer(&k.device, l.o_weight_blocks)),
                    q8(cache.q8_block_weight_buffer(&k.device, l.gate_weight_blocks)),
                    q8(cache.q8_block_weight_buffer(&k.device, l.up_weight_blocks)),
                    q8(cache.q8_block_weight_buffer(&k.device, l.down_weight_blocks)),
                ]
            })
            .collect()
    };
    let mut keep = Vec::new();
    let cb = k.queue.new_command_buffer();
    let e = cb.new_compute_command_encoder();
    let mut from_a = true;
    for (i, layer) in layers.iter().enumerate() {
        let (in_buf, out_buf) = if from_a {
            (&buf_a, &buf_b)
        } else {
            (&buf_b, &buf_a)
        };
        let w = &resident[i];
        let cache_k_buf = upload_cache_buffer(k, layer.cache_k);
        let cache_v_buf = upload_cache_buffer(k, layer.cache_v);
        encode_attention_block(
            e,
            k,
            &mut keep,
            in_buf,
            &mid,
            layer.attn_norm,
            eps,
            None,
            None,
            None,
            &w[0],
            &w[1],
            &w[2],
            &w[3],
            cos_t,
            sin_t,
            &cache_k_buf,
            &cache_v_buf,
            None,
            kv16_enabled(),
            kvq8_enabled(),
            position_count,
            position_count - 1,
            n_heads,
            n_kv_heads,
            head_dim,
            position_count,
            0,
            scale,
            split_half_pairing,
        );
        encode_ffn_block(
            e,
            k,
            &mut keep,
            &mid,
            out_buf,
            layer.ffn_norm,
            eps,
            None,
            false,
            &w[4],
            &w[5],
            &w[6],
            ffn_dim,
        );
        // Keep the transient per-layer cache buffers alive until the command buffer completes.
        keep.push(cache_k_buf);
        keep.push(cache_v_buf);
        from_a = !from_a;
    }
    e.end_encoding();
    cb.commit();
    cb.wait_until_completed();
    // After N flips, the last layer's output sits in `buf_a` iff N is even (`from_a` true).
    let final_buf = if from_a { &buf_a } else { &buf_b };
    let mut out = vec![0.0f32; hidden];
    read_buffer_f32(final_buf, &mut out);
    Some(out)
}

/// Per-layer weights/norms for `ResidentDecodeState::forward_token`. Unlike
/// `ResidentDecodeLayer`, the K/V cache is NOT here -- it lives in the session and persists
/// across tokens. Holds the seven Q8_0 weight-block byte buffers and the two RMSNorm f32
/// weights.
pub struct ResidentLayerWeights<'a> {
    pub attn_norm: &'a [f32],
    pub ffn_norm: &'a [f32],
    /// Per-head QK-norm weights (`[head_dim]`, F32), applied to Q/K after the
    /// projection and before RoPE (Qwen3/gemma3). `None` for plain Llama-family
    /// rows.
    pub q_norm: Option<&'a [f32]>,
    pub k_norm: Option<&'a [f32]>,
    /// gemma3 sandwich norms (`[hidden]`, F32): RMSNorm applied to the
    /// attention block's output BEFORE its residual add (`post_attention_norm`)
    /// and to the FFN block's output BEFORE its residual add (`post_ffw_norm`).
    /// Reference semantics: src/runnable/model.rs:851-853, :875-877. `None` for
    /// the Llama 2-norm structure. The batched prefill and speculative-verify
    /// paths do not apply them and fail closed when they are present.
    pub post_attn_norm: Option<&'a [f32]>,
    pub post_ffw_norm: Option<&'a [f32]>,
    /// gemma3 FFN activation is GeGLU — `gelu_tanh(gate) * up` — instead of
    /// the Llama-family SiLU (reference src/runnable/model.rs:865-873). The
    /// batched prefill and speculative-verify paths encode SiLU only and fail
    /// closed when this is set.
    pub ffn_geglu: bool,
    pub q_weight_blocks: ResidentWeightBytes<'a>,
    pub k_weight_blocks: ResidentWeightBytes<'a>,
    pub v_weight_blocks: ResidentWeightBytes<'a>,
    pub o_weight_blocks: ResidentWeightBytes<'a>,
    pub gate_weight_blocks: ResidentWeightBytes<'a>,
    pub up_weight_blocks: ResidentWeightBytes<'a>,
    pub down_weight_blocks: ResidentWeightBytes<'a>,
}

/// Where a resident weight's bytes live on the CPU side.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ResidentWeightFormat {
    DenseF32,
    DenseF16,
    Q8_0,
    Q4K,
    Q6K,
    Q1_0,
    Q2_0G64,
    Q2_0G128,
}

impl ResidentWeightFormat {
    #[cfg(target_os = "macos")]
    fn values_per_block(self) -> usize {
        match self {
            Self::DenseF32 | Self::DenseF16 => 1,
            Self::Q8_0 => 32,
            Self::Q4K | Self::Q6K => 256,
            Self::Q1_0 | Self::Q2_0G128 => 128,
            Self::Q2_0G64 => 64,
        }
    }

    fn wire_bytes_per_block(self) -> usize {
        match self {
            Self::DenseF32 => 4,
            Self::DenseF16 => 2,
            Self::Q8_0 => 34,
            Self::Q4K => 144,
            Self::Q6K => 210,
            Self::Q1_0 => 18,
            Self::Q2_0G64 => 18,
            Self::Q2_0G128 => 34,
        }
    }

    /// Whether the **hybrid** Prism wire path ([`try_prism_wire_matvec_f32`] /
    /// [`try_prism_wire_matmul_f32`]) will run this format on the GPU.
    ///
    /// This is a third admission gate, independent of
    /// `runnable::model::resident_metal_format` — which decides page-backing and the
    /// fully *resident* graph. The two sets are deliberately not equal: `Q8_0` is
    /// admitted there and declined here, so a page-backed `Q8_0` projection arriving via
    /// `par_matvec`/`par_matmul` falls through to the CPU kernel rather than taking a
    /// second GPU path that carries none of the resident lane's parity evidence.
    ///
    /// Admitting a type to `resident_metal_format` therefore does **not** enable it here;
    /// that is a separate lane change with its own evidence needs. The match is kept
    /// exhaustive on purpose: a new `ResidentWeightFormat` variant must fail to compile
    /// here rather than inherit a silent `false` from a `_` arm.
    #[cfg(target_os = "macos")]
    fn hybrid_prism_wire_supported(self) -> bool {
        match self {
            // DenseF16 is also the tied 128k-row BitNet output head. The shared
            // dense kernel consumes its canonical row-major GGUF bytes directly,
            // so the hybrid bridge can keep that head page-backed and resident.
            Self::DenseF16 | Self::Q1_0 | Self::Q2_0G64 | Self::Q2_0G128 => true,
            Self::DenseF32 | Self::Q8_0 | Self::Q4K | Self::Q6K => false,
        }
    }
}

#[derive(Clone, Copy)]
pub enum ResidentWeightBytes<'a> {
    /// 36-byte f32-scale CPU blocks; uploaded (and wire-converted when wire mode is
    /// on) through the buffer cache.
    Blocks36(&'a [u8]),
    /// Page-aligned 34-byte wire blocks (fast-load); wrapped in place by an offset-0
    /// NoCopy buffer — the GPU reads this allocation directly, no upload copy.
    WirePages {
        format: ResidentWeightFormat,
        pages: &'a std::sync::Arc<crate::wire_mmap::WirePages>,
    },
    /// Ordinary retained K-quant wire bytes. These are uploaded once into the
    /// resident cache; the Metal no-copy loader uses `WirePages` instead.
    KQuantBytes {
        format: ResidentWeightFormat,
        bytes: &'a [u8],
    },
}

impl ResidentWeightBytes<'_> {
    pub fn format(&self) -> ResidentWeightFormat {
        match self {
            Self::Blocks36(_) => ResidentWeightFormat::Q8_0,
            Self::WirePages { format, .. } | Self::KQuantBytes { format, .. } => *format,
        }
    }

    /// Number of quant blocks/super-blocks described by this byte view.
    pub fn block_count(&self) -> usize {
        match self {
            ResidentWeightBytes::Blocks36(bytes) => bytes.len() / 36,
            ResidentWeightBytes::WirePages { format, pages } => {
                pages.byte_len() / format.wire_bytes_per_block()
            }
            ResidentWeightBytes::KQuantBytes { format, bytes } => {
                bytes.len() / format.wire_bytes_per_block()
            }
        }
    }

    #[cfg(target_os = "macos")]
    fn matches_shape(&self, input_width: usize, rows: usize) -> bool {
        let format = self.format();
        input_width.is_multiple_of(format.values_per_block())
            && self.block_count() == rows * (input_width / format.values_per_block())
    }
}

#[cfg(target_os = "macos")]
struct ResidentLinearWeight {
    format: ResidentWeightFormat,
    buffer: Buffer,
    /// Q8_0 has two resident layouts: decoded 36-byte blocks and raw 34-byte
    /// GGUF wire blocks. Carry the physical layout with the buffer instead of
    /// consulting process-global fast-path flags at dispatch time.
    q8_wire: bool,
}

#[cfg(target_os = "macos")]
fn resolve_resident_weight(
    cache: &mut MetalLinearCache,
    device: &Device,
    weight: &ResidentWeightBytes<'_>,
    q8_wire: bool,
) -> Option<ResidentLinearWeight> {
    let format = weight.format();
    let physical_q8_wire = format == ResidentWeightFormat::Q8_0 && q8_wire;
    let buffer = match weight {
        ResidentWeightBytes::Blocks36(blocks) => {
            if q8_wire {
                cache.q8_wire_weight_buffer(device, blocks)
            } else {
                cache.q8_block_weight_buffer(device, blocks)
            }
        }
        ResidentWeightBytes::WirePages { format, pages } => {
            if *format == ResidentWeightFormat::Q8_0 && !q8_wire {
                return None;
            }
            cache.q8_wire_nocopy_buffer(device, pages)
        }
        ResidentWeightBytes::KQuantBytes { bytes, .. } => {
            cache.raw_wire_weight_buffer(device, bytes)
        }
    };
    Some(ResidentLinearWeight {
        format,
        buffer,
        q8_wire: physical_q8_wire,
    })
}

