    /// Encode-ahead queues the next layer before the host has explicitly
    /// drained the previous layer. Prove that shared and MoE argument blocks
    /// remain layer-local under that schedule, and that immediate tail-buffer
    /// promotion still exposes the second queued result after the FIFO fence.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_ghost_two_layer_encode_ahead_keeps_arguments_immutable() {
        if !detect_metal_device().available {
            return;
        }
        use crate::inference::{gemma4::gelu_tanh, quantize_q8_0_blocks};

        const HIDDEN: usize = 128;
        const FFN: usize = 128;
        const EXPERTS: usize = 128;
        let first = ghost_common_fixture(211);
        let second = ghost_common_fixture(223);
        let second_post_ffw = second.layer.post_ffw_norm.clone();
        let second_post_norm_1 = second.post_norm_1.clone();
        let second_gate_wire = second.gate_wire.clone();
        let second_up_wire = second.up_wire.clone();
        let second_down_wire = second.down_wire.clone();
        let attention: Vec<f32> = (0..HIDDEN)
            .map(|i| (((i * 37 + 9) % 181) as f32 - 90.0) * 0.0039)
            .collect();

        let normalized =
            crate::gemma4_runtime::rms_norm(&attention, Some(&second.ffn_norm), 1.0e-6);
        let normalized_q8 = quantize_q8_0_blocks(&normalized);
        let gate = ghost_common_cpu_q4_matvec(&second_gate_wire, FFN, &normalized_q8);
        let up = ghost_common_cpu_q4_matvec(&second_up_wire, FFN, &normalized_q8);
        let activated: Vec<f32> = gate
            .iter()
            .zip(&up)
            .map(|(&gate, &up)| gelu_tanh(gate) * up)
            .collect();
        let activated_q8 = quantize_q8_0_blocks(&activated);
        let down = ghost_common_cpu_q4_matvec(&second_down_wire, HIDDEN, &activated_q8);
        let expected_shared =
            crate::gemma4_runtime::rms_norm(&down, Some(&second_post_norm_1), 1.0e-6);

        let first_post_1 = first.post_norm_1;
        let first_layer = first.layer;
        let second_layer = second.layer;
        let mut common = Gemma4GhostCommonMetal::new_synthetic(
            vec![first_layer, second_layer],
            vec![first_post_1, second.post_norm_1],
            2,
            2,
        )
        .expect("two-layer synthetic common core");
        let first_post_norm_2 = vec![0.83f32; HIDDEN];
        let second_post_norm_2: Vec<f32> = (0..HIDDEN)
            .map(|i| 0.71 + (i % 13) as f32 * 0.011)
            .collect();
        let config = |post_norm_2: Vec<f32>, layer_output_scale: f32| Gemma4GhostMoeLayerConfig {
            router: vec![0.0; EXPERTS * HIDDEN],
            gate_input_scale: vec![1.0; HIDDEN],
            pre_norm_2: vec![1.0; HIDDEN],
            post_norm_2,
            down_exps_scale: vec![1.0; EXPERTS],
            layer_output_scale,
        };
        assert!(common.configure_moe(vec![
            config(first_post_norm_2, 0.5),
            config(second_post_norm_2.clone(), 0.75),
        ]));

        // A pointer check catches any future refactor that accidentally folds
        // these immutable blocks back into shared hot scratch.
        assert_ne!(
            common.norms[0].shared_rms_scalar.contents(),
            common.norms[1].shared_rms_scalar.contents()
        );
        let moe_layers = common.moe_layers.as_ref().expect("configured MoE");
        assert_ne!(
            moe_layers[0].rms_scalar.contents(),
            moe_layers[1].rms_scalar.contents()
        );
        assert_ne!(
            moe_layers[0].layer_scale_scalar.contents(),
            moe_layers[1].layer_scale_scalar.contents()
        );

        assert!(common.write_attention_output_for_test(&attention, 0));
        let first_shared = common.enqueue_shared_branch(0).expect("first shared");
        // Production reaches this state through the queued next-layer
        // attention command; the test keeps the common input unchanged so only
        // argument-buffer isolation is under test.
        common.latest_attention_layer = Some(1);
        let second_shared = common.enqueue_shared_branch(1).expect("second shared");
        assert!(second_shared.wait().is_some());
        assert!(first_shared.wait().is_some());
        let actual_shared = common.read_shared_output();
        for (index, (&got, &want)) in actual_shared.iter().zip(&expected_shared).enumerate() {
            let tolerance = 3.0e-2 * want.abs().max(1.0);
            assert!(
                (got - want).abs() <= tolerance,
                "encode-ahead shared value {index}: metal={got} cpu={want} tolerance={tolerance}"
            );
        }

        let routed: Vec<f32> = (0..HIDDEN)
            .map(|i| (((i * 29 + 17) % 173) as f32 - 86.0) * 0.0041)
            .collect();
        write_buffer_f32(&common.routed_output, &routed);
        let kernel = metal_linear_kernel().expect("Metal kernel");
        let first_tail = kernel.queue.new_command_buffer();
        let first_encoder = first_tail.new_compute_command_encoder();
        assert_eq!(common.encode_moe_tail(first_encoder, kernel, 0), Some(5));
        first_encoder.end_encoding();
        first_tail.commit();
        common.promote_tail_output();

        let second_tail = kernel.queue.new_command_buffer();
        let second_encoder = second_tail.new_compute_command_encoder();
        assert_eq!(common.encode_moe_tail(second_encoder, kernel, 1), Some(5));
        second_encoder.end_encoding();
        second_tail.commit();
        common.promote_tail_output();

        // Waiting on the later FIFO command first mirrors the runtime's next
        // attention/router fence; the earlier command must already be terminal.
        second_tail.wait_until_completed();
        assert_eq!(
            second_tail.status(),
            metal::MTLCommandBufferStatus::Completed
        );
        first_tail.wait_until_completed();
        assert_eq!(
            first_tail.status(),
            metal::MTLCommandBufferStatus::Completed
        );

        let routed_normed =
            crate::gemma4_runtime::rms_norm(&routed, Some(&second_post_norm_2), 1.0e-6);
        let combined: Vec<f32> = actual_shared
            .iter()
            .zip(&routed_normed)
            .map(|(shared, routed)| shared + routed)
            .collect();
        let combined_normed =
            crate::gemma4_runtime::rms_norm(&combined, Some(&second_post_ffw), 1.0e-6);
        let expected_tail: Vec<f32> = attention
            .iter()
            .zip(&combined_normed)
            .map(|(residual, ffn)| (residual + ffn) * 0.75)
            .collect();
        let actual_tail = common.read_hidden();
        for (index, (&got, &want)) in actual_tail.iter().zip(&expected_tail).enumerate() {
            assert!(
                (got - want).abs() <= 4.0e-3f32.max(want.abs() * 4.0e-3),
                "encode-ahead tail value {index}: metal={got} cpu={want}"
            );
        }
    }

    // A full gemma4 layer (attention sub-block then FFN sub-block, chained in one GPU
    // command buffer via Gemma4ResidentLayer) must match the same two-stage chain on
    // CPU: h_mid = h_in + attention(h_in); h_out = h_mid + ffn(h_mid).
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_layer_matches_cpu() {
        if !detect_metal_device().available {
            return;
        }
        use crate::inference::quantize_q8_0_blocks;
        let hidden = 2560usize;
        let n_heads = 8usize;
        let n_kv_heads = 2usize;
        let head_dim = 256usize;
        let ffn_dim = 10240usize;
        let group = n_heads / n_kv_heads;
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv_heads * head_dim;
        let half = head_dim / 2;
        let max_positions = 8usize;
        let write_position = 3usize;
        let filled = 4usize;
        let window_start = 0usize;
        let eps = 1.0e-6f32;
        let scale = 1.0 / (head_dim as f32).sqrt();

        let make_weight = |rows: usize, in_dim: usize, seed: usize| -> (Vec<u8>, Vec<Vec<f32>>) {
            let mut wire = Vec::new();
            let mut deq = Vec::new();
            for r in 0..rows {
                let row: Vec<f32> = (0..in_dim)
                    .map(|i| ((((r * in_dim + i + seed) % 29) as f32) - 14.0) * 0.03)
                    .collect();
                let mut drow = vec![0.0f32; in_dim];
                for (b, blk) in quantize_q8_0_blocks(&row).iter().enumerate() {
                    wire.extend_from_slice(&f32_to_f16_bits(blk.scale).to_le_bytes());
                    for (j, &q) in blk.quants.iter().enumerate() {
                        wire.push(q as u8);
                        drow[b * 32 + j] = blk.scale * q as f32;
                    }
                }
                deq.push(drow);
            }
            (wire, deq)
        };
        let (q_wire, q_deq) = make_weight(q_dim, hidden, 1);
        let (k_wire, k_deq) = make_weight(kv_dim, hidden, 5);
        let (v_wire, v_deq) = make_weight(kv_dim, hidden, 9);
        let (o_wire, o_deq) = make_weight(hidden, q_dim, 13);
        let (gate_wire, gate_deq) = make_weight(ffn_dim, hidden, 17);
        let (up_wire, up_deq) = make_weight(ffn_dim, hidden, 21);
        let (down_wire, down_deq) = make_weight(hidden, ffn_dim, 25);
        let h_in: Vec<f32> = (0..hidden)
            .map(|i| ((i as f32 % 13.0) - 6.0) * 0.1)
            .collect();
        let attn_norm: Vec<f32> = (0..hidden).map(|i| 0.8 + (i as f32 % 5.0) * 0.05).collect();
        let post_attn: Vec<f32> = (0..hidden).map(|i| 0.9 + (i as f32 % 3.0) * 0.03).collect();
        let ffn_norm: Vec<f32> = (0..hidden)
            .map(|i| 0.85 + (i as f32 % 4.0) * 0.04)
            .collect();
        let post_ffw: Vec<f32> = (0..hidden)
            .map(|i| 0.95 + (i as f32 % 6.0) * 0.02)
            .collect();
        let q_norm: Vec<f32> = (0..head_dim)
            .map(|i| 0.7 + (i as f32 % 11.0) * 0.02)
            .collect();
        let k_norm: Vec<f32> = (0..head_dim)
            .map(|i| 0.6 + (i as f32 % 7.0) * 0.03)
            .collect();
        let cos_t: Vec<f32> = (0..half).map(|i| (0.3 + i as f32 * 0.01).cos()).collect();
        let sin_t: Vec<f32> = (0..half).map(|i| (0.3 + i as f32 * 0.01).sin()).collect();
        let cache_len = n_kv_heads * max_positions * head_dim;
        let cache_k_init: Vec<f32> = (0..cache_len)
            .map(|i| ((i % 17) as f32 - 8.0) * 0.05)
            .collect();
        let cache_v_init: Vec<f32> = (0..cache_len)
            .map(|i| ((i % 23) as f32 - 11.0) * 0.04)
            .collect();

        // ---- CPU reference: attention(h_in) -> h_mid, then ffn(h_mid) -> h_out ----
        let rms = |x: &[f32], w: Option<&[f32]>| -> Vec<f32> {
            let mss = x.iter().map(|v| v * v).sum::<f32>() / x.len() as f32;
            let inv = (mss + eps).powf(-0.5);
            (0..x.len())
                .map(|i| x[i] * inv * w.map_or(1.0, |w| w[i]))
                .collect()
        };
        let matmul = |deq: &[Vec<f32>], x: &[f32]| -> Vec<f32> {
            deq.iter()
                .map(|row| row.iter().zip(x).map(|(a, b)| a * b).sum())
                .collect()
        };
        let per_head = |x: &[f32], heads: usize, w: Option<&[f32]>| -> Vec<f32> {
            let mut out = vec![0.0f32; x.len()];
            for h in 0..heads {
                let n = rms(&x[h * head_dim..(h + 1) * head_dim], w);
                out[h * head_dim..(h + 1) * head_dim].copy_from_slice(&n);
            }
            out
        };
        let rope = |x: &mut [f32], heads: usize| {
            for h in 0..heads {
                let base = h * head_dim;
                for i in 0..half {
                    let (x0, x1) = (x[base + i], x[base + half + i]);
                    x[base + i] = x0 * cos_t[i] - x1 * sin_t[i];
                    x[base + half + i] = x0 * sin_t[i] + x1 * cos_t[i];
                }
            }
        };
        // attention
        let normf = rms(&h_in, Some(&attn_norm));
        let mut q = per_head(&matmul(&q_deq, &normf), n_heads, Some(&q_norm));
        let mut kk = per_head(&matmul(&k_deq, &normf), n_kv_heads, Some(&k_norm));
        let vv = per_head(&matmul(&v_deq, &normf), n_kv_heads, None);
        rope(&mut q, n_heads);
        rope(&mut kk, n_kv_heads);
        let kv_at = |init: &[f32], cur: &[f32], kvh: usize, p: usize| -> Vec<f32> {
            if p == write_position {
                cur[kvh * head_dim..(kvh + 1) * head_dim].to_vec()
            } else {
                let base = kvh * max_positions * head_dim + p * head_dim;
                init[base..base + head_dim].to_vec()
            }
        };
        let mut ctx = vec![0.0f32; q_dim];
        for h in 0..n_heads {
            let kvh = h / group;
            let qh = &q[h * head_dim..(h + 1) * head_dim];
            let mut scores = Vec::new();
            for p in window_start..filled {
                let kp = kv_at(&cache_k_init, &kk, kvh, p);
                scores.push(scale * qh.iter().zip(&kp).map(|(a, b)| a * b).sum::<f32>());
            }
            let m = scores.iter().cloned().fold(f32::NEG_INFINITY, f32::max);
            let mut den = 0.0f32;
            for s in &mut scores {
                *s = (*s - m).exp();
                den += *s;
            }
            for (idx, p) in (window_start..filled).enumerate() {
                let vp = kv_at(&cache_v_init, &vv, kvh, p);
                let w = scores[idx] / den;
                for d in 0..head_dim {
                    ctx[h * head_dim + d] += w * vp[d];
                }
            }
        }
        let attn_out = rms(&matmul(&o_deq, &ctx), Some(&post_attn));
        let h_mid: Vec<f32> = h_in.iter().zip(&attn_out).map(|(a, b)| a + b).collect();
        // ffn
        let fnormf = rms(&h_mid, Some(&ffn_norm));
        let gate = matmul(&gate_deq, &fnormf);
        let up = matmul(&up_deq, &fnormf);
        let act: Vec<f32> = gate
            .iter()
            .zip(&up)
            .map(|(g, u)| crate::inference::gemma4::gelu_tanh(*g) * u)
            .collect();
        let dn = rms(&matmul(&down_deq, &act), Some(&post_ffw));
        let want: Vec<f32> = h_mid.iter().zip(&dn).map(|(a, b)| a + b).collect();

        let layer = Gemma4ResidentLayer::from_wire(
            GemmaWireFmt::Q8_0,
            attn_norm.clone(),
            q_norm.clone(),
            k_norm.clone(),
            post_attn.clone(),
            ffn_norm.clone(),
            post_ffw.clone(),
            &q_wire,
            &k_wire,
            Some(&v_wire),
            &o_wire,
            &gate_wire,
            &up_wire,
            &down_wire,
            n_heads,
            n_kv_heads,
            head_dim,
            ffn_dim,
            eps,
        )
        .expect("layer weights");
        let got = try_gemma4_layer(
            &layer,
            &h_in,
            &cos_t,
            &sin_t,
            &cache_k_init,
            &cache_v_init,
            max_positions,
            write_position,
            filled,
            window_start,
            scale,
            true, // owning layer
        )
        .expect("gemma4 layer");
        for (a, b) in got.iter().zip(&want) {
            assert!((a - b).abs() < 3.0e-2, "{a} != {b}");
        }
    }

    // Two gemma4 layers chained in ONE command buffer with a persistent shared cache:
    // layer 0 owns its K/V and scatters this token; layer 1 (cross-shared) reads
    // layer 0's cache (incl. the just-scattered token) with no K/V projection. Must
    // match the same two-layer chain on CPU. Validates the multi-layer driver +
    // cross-layer KV sharing end-to-end.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_two_layers_shared_kv_matches_cpu() {
        if !detect_metal_device().available {
            return;
        }
        use crate::inference::quantize_q8_0_blocks;
        let hidden = 128usize;
        let n_heads = 2usize;
        let n_kv_heads = 1usize;
        let head_dim = 256usize;
        let ffn_dim = 256usize;
        let group = n_heads / n_kv_heads;
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv_heads * head_dim;
        let half = head_dim / 2;
        let max_positions = 8usize;
        let write_position = 3usize;
        let filled = 4usize;
        let eps = 1.0e-6f32;
        let scale = 1.0 / (head_dim as f32).sqrt();

        let make_weight = |rows: usize, in_dim: usize, seed: usize| -> (Vec<u8>, Vec<Vec<f32>>) {
            let mut wire = Vec::new();
            let mut deq = Vec::new();
            for r in 0..rows {
                let row: Vec<f32> = (0..in_dim)
                    .map(|i| ((((r * in_dim + i + seed) % 29) as f32) - 14.0) * 0.03)
                    .collect();
                let mut drow = vec![0.0f32; in_dim];
                for (b, blk) in quantize_q8_0_blocks(&row).iter().enumerate() {
                    wire.extend_from_slice(&f32_to_f16_bits(blk.scale).to_le_bytes());
                    for (j, &q) in blk.quants.iter().enumerate() {
                        wire.push(q as u8);
                        drow[b * 32 + j] = blk.scale * q as f32;
                    }
                }
                deq.push(drow);
            }
            (wire, deq)
        };
        // Distinct weights per layer (seed offset 100 for layer 1).
        let mk_layer_w = |off: usize| {
            (
                make_weight(q_dim, hidden, off + 1),
                make_weight(kv_dim, hidden, off + 5),
                make_weight(kv_dim, hidden, off + 9),
                make_weight(hidden, q_dim, off + 13),
                make_weight(ffn_dim, hidden, off + 17),
                make_weight(ffn_dim, hidden, off + 21),
                make_weight(hidden, ffn_dim, off + 25),
            )
        };
        let w0 = mk_layer_w(0);
        let w1 = mk_layer_w(100);
        let mk_norms = |off: usize| {
            (
                (0..hidden)
                    .map(|i| 0.8 + ((i + off) as f32 % 5.0) * 0.05)
                    .collect::<Vec<f32>>(),
                (0..hidden)
                    .map(|i| 0.9 + ((i + off) as f32 % 3.0) * 0.03)
                    .collect::<Vec<f32>>(),
                (0..hidden)
                    .map(|i| 0.85 + ((i + off) as f32 % 4.0) * 0.04)
                    .collect::<Vec<f32>>(),
                (0..hidden)
                    .map(|i| 0.95 + ((i + off) as f32 % 6.0) * 0.02)
                    .collect::<Vec<f32>>(),
                (0..head_dim)
                    .map(|i| 0.7 + ((i + off) as f32 % 11.0) * 0.02)
                    .collect::<Vec<f32>>(),
                (0..head_dim)
                    .map(|i| 0.6 + ((i + off) as f32 % 7.0) * 0.03)
                    .collect::<Vec<f32>>(),
            )
        };
        let (an0, pa0, fn0, pf0, qn0, kn0) = mk_norms(0);
        let (an1, pa1, fn1, pf1, qn1, kn1) = mk_norms(3);
        let cos_t: Vec<f32> = (0..half).map(|i| (0.3 + i as f32 * 0.01).cos()).collect();
        let sin_t: Vec<f32> = (0..half).map(|i| (0.3 + i as f32 * 0.01).sin()).collect();
        let h_in: Vec<f32> = (0..hidden)
            .map(|i| ((i as f32 % 13.0) - 6.0) * 0.1)
            .collect();
        let cache_len = n_kv_heads * max_positions * head_dim;
        let cache_k0: Vec<f32> = (0..cache_len)
            .map(|i| ((i % 17) as f32 - 8.0) * 0.05)
            .collect();
        let cache_v0: Vec<f32> = (0..cache_len)
            .map(|i| ((i % 23) as f32 - 11.0) * 0.04)
            .collect();

        // ---- CPU reference ----
        let rms = |x: &[f32], w: Option<&[f32]>| -> Vec<f32> {
            let mss = x.iter().map(|v| v * v).sum::<f32>() / x.len() as f32;
            let inv = (mss + eps).powf(-0.5);
            (0..x.len())
                .map(|i| x[i] * inv * w.map_or(1.0, |w| w[i]))
                .collect()
        };
        let matmul = |deq: &[Vec<f32>], x: &[f32]| -> Vec<f32> {
            deq.iter()
                .map(|row| row.iter().zip(x).map(|(a, b)| a * b).sum())
                .collect()
        };
        let per_head = |x: &[f32], heads: usize, w: Option<&[f32]>| -> Vec<f32> {
            let mut out = vec![0.0f32; x.len()];
            for h in 0..heads {
                let n = rms(&x[h * head_dim..(h + 1) * head_dim], w);
                out[h * head_dim..(h + 1) * head_dim].copy_from_slice(&n);
            }
            out
        };
        let rope = |x: &mut [f32], heads: usize| {
            for h in 0..heads {
                let base = h * head_dim;
                for i in 0..half {
                    let (x0, x1) = (x[base + i], x[base + half + i]);
                    x[base + i] = x0 * cos_t[i] - x1 * sin_t[i];
                    x[base + half + i] = x0 * sin_t[i] + x1 * cos_t[i];
                }
            }
        };
        // attention over a flat cache; returns ctx [q_dim].
        let attend = |q: &[f32], ck: &[f32], cv: &[f32]| -> Vec<f32> {
            let mut ctx = vec![0.0f32; q_dim];
            for h in 0..n_heads {
                let kvh = h / group;
                let qh = &q[h * head_dim..(h + 1) * head_dim];
                let mut sc = Vec::new();
                for p in 0..filled {
                    let base = kvh * max_positions * head_dim + p * head_dim;
                    sc.push(
                        scale
                            * qh.iter()
                                .zip(&ck[base..base + head_dim])
                                .map(|(a, b)| a * b)
                                .sum::<f32>(),
                    );
                }
                let m = sc.iter().cloned().fold(f32::NEG_INFINITY, f32::max);
                let mut den = 0.0f32;
                for s in &mut sc {
                    *s = (*s - m).exp();
                    den += *s;
                }
                for (idx, p) in (0..filled).enumerate() {
                    let base = kvh * max_positions * head_dim + p * head_dim;
                    let wgt = sc[idx] / den;
                    for d in 0..head_dim {
                        ctx[h * head_dim + d] += wgt * cv[base + d];
                    }
                }
            }
            ctx
        };
        let ffn = |h: &[f32],
                   gate: &[Vec<f32>],
                   up: &[Vec<f32>],
                   down: &[Vec<f32>],
                   fnw: &[f32],
                   pfw: &[f32]|
         -> Vec<f32> {
            let nf = rms(h, Some(fnw));
            let g = matmul(gate, &nf);
            let u = matmul(up, &nf);
            let act: Vec<f32> = g
                .iter()
                .zip(&u)
                .map(|(a, b)| crate::inference::gemma4::gelu_tanh(*a) * b)
                .collect();
            rms(&matmul(down, &act), Some(pfw))
        };

        // layer 0 (owning): compute k/v, inject into a copy of cache0, attention, ffn.
        let nf0 = rms(&h_in, Some(&an0));
        let mut q0 = per_head(&matmul(&w0.0 .1, &nf0), n_heads, Some(&qn0));
        let mut k0 = per_head(&matmul(&w0.1 .1, &nf0), n_kv_heads, Some(&kn0));
        let v0 = per_head(&matmul(&w0.2 .1, &nf0), n_kv_heads, None);
        rope(&mut q0, n_heads);
        rope(&mut k0, n_kv_heads);
        let mut eff_k = cache_k0.clone();
        let mut eff_v = cache_v0.clone();
        for kvh in 0..n_kv_heads {
            let base = kvh * max_positions * head_dim + write_position * head_dim;
            eff_k[base..base + head_dim].copy_from_slice(&k0[kvh * head_dim..(kvh + 1) * head_dim]);
            eff_v[base..base + head_dim].copy_from_slice(&v0[kvh * head_dim..(kvh + 1) * head_dim]);
        }
        let ctx0 = attend(&q0, &eff_k, &eff_v);
        let attn0 = rms(&matmul(&w0.3 .1, &ctx0), Some(&pa0));
        let h_mid0: Vec<f32> = h_in.iter().zip(&attn0).map(|(a, b)| a + b).collect();
        let dn0 = ffn(&h_mid0, &w0.4 .1, &w0.5 .1, &w0.6 .1, &fn0, &pf0);
        let h_out0: Vec<f32> = h_mid0.iter().zip(&dn0).map(|(a, b)| a + b).collect();

        // layer 1 (shared, reads eff_k/eff_v from layer 0): q only.
        let nf1 = rms(&h_out0, Some(&an1));
        let mut q1 = per_head(&matmul(&w1.0 .1, &nf1), n_heads, Some(&qn1));
        rope(&mut q1, n_heads);
        let ctx1 = attend(&q1, &eff_k, &eff_v);
        let attn1 = rms(&matmul(&w1.3 .1, &ctx1), Some(&pa1));
        let h_mid1: Vec<f32> = h_out0.iter().zip(&attn1).map(|(a, b)| a + b).collect();
        let dn1 = ffn(&h_mid1, &w1.4 .1, &w1.5 .1, &w1.6 .1, &fn1, &pf1);
        let want: Vec<f32> = h_mid1.iter().zip(&dn1).map(|(a, b)| a + b).collect();

        // ---- GPU: two layers, one command buffer, persistent shared cache ----
        let layer0 = Gemma4ResidentLayer::from_wire(
            GemmaWireFmt::Q8_0,
            an0,
            qn0,
            kn0,
            pa0,
            fn0,
            pf0,
            &w0.0 .0,
            &w0.1 .0,
            Some(&w0.2 .0),
            &w0.3 .0,
            &w0.4 .0,
            &w0.5 .0,
            &w0.6 .0,
            n_heads,
            n_kv_heads,
            head_dim,
            ffn_dim,
            eps,
        )
        .expect("layer0");
        let layer1 = Gemma4ResidentLayer::from_wire(
            GemmaWireFmt::Q8_0,
            an1,
            qn1,
            kn1,
            pa1,
            fn1,
            pf1,
            &w1.0 .0,
            &w1.1 .0,
            Some(&w1.2 .0),
            &w1.3 .0,
            &w1.4 .0,
            &w1.5 .0,
            &w1.6 .0,
            n_heads,
            n_kv_heads,
            head_dim,
            ffn_dim,
            eps,
        )
        .expect("layer1");
        let kk = metal_linear_kernel().expect("metal");
        let mk = |bytes: usize| {
            kk.device
                .new_buffer(bytes as u64, MTLResourceOptions::StorageModeShared)
        };
        let buf_a = mk(hidden * 4);
        let buf_b = mk(hidden * 4);
        let mid = mk(hidden * 4);
        let ck = mk(cache_len * 4);
        let cv = mk(cache_len * 4);
        write_buffer_f32(&buf_a, &h_in);
        write_buffer_f32(&ck, &cache_k0);
        write_buffer_f32(&cv, &cache_v0);
        let mut keep = Vec::new();
        let cb = kk.queue.new_command_buffer();
        let e = cb.new_compute_command_encoder();
        // layer 0 owns: buf_a -> buf_b, scatters into ck/cv.
        encode_gemma4_layer(
            e,
            kk,
            &mut keep,
            &layer0,
            &buf_a,
            &mid,
            &buf_b,
            &cos_t,
            &sin_t,
            &ck,
            &cv,
            max_positions,
            write_position,
            filled,
            0,
            scale,
            true,
        );
        // layer 1 shared: buf_b -> buf_a, reads ck/cv (now holding layer 0's token).
        encode_gemma4_layer(
            e,
            kk,
            &mut keep,
            &layer1,
            &buf_b,
            &mid,
            &buf_a,
            &cos_t,
            &sin_t,
            &ck,
            &cv,
            max_positions,
            write_position,
            filled,
            0,
            scale,
            false,
        );
        e.end_encoding();
        cb.commit();
        cb.wait_until_completed();
        let mut got = vec![0.0f32; hidden];
        read_buffer_f32(&buf_a, &mut got);
        for (a, b) in got.iter().zip(&want) {
            assert!((a - b).abs() < 4.0e-2, "{a} != {b}");
        }
    }

    // Gemma's PLE per-layer injection on GPU (ple_inp_gate GEMV -> gelu*pli ->
    // ple_proj GEMV -> rms_norm(post_norm) -> residual -> output_scale) must match the
    // CPU reference (gemma4_runtime's per-layer PLE step).
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_ple_matches_cpu() {
        if !detect_metal_device().available {
            return;
        }
        let hidden = 128usize;
        let ple_dim = 64usize;
        let eps = 1.0e-6f32;
        let output_scale = 0.061f32;
        let h_in: Vec<f32> = (0..hidden)
            .map(|i| ((i as f32 % 13.0) - 6.0) * 0.1)
            .collect();
        let pli: Vec<f32> = (0..ple_dim)
            .map(|i| ((i as f32 % 9.0) - 4.0) * 0.2)
            .collect();
        // Output-major: inp_gate[o*hidden + i] (o in 0..ple_dim), proj[o*ple_dim + i].
        let inp_gate: Vec<f32> = (0..ple_dim * hidden)
            .map(|n| (((n % 29) as f32) - 14.0) * 0.02)
            .collect();
        let proj_w: Vec<f32> = (0..hidden * ple_dim)
            .map(|n| (((n % 23) as f32) - 11.0) * 0.03)
            .collect();
        let post_norm: Vec<f32> = (0..hidden).map(|i| 0.9 + (i as f32 % 5.0) * 0.04).collect();

        // CPU reference.
        let mut gated = vec![0.0f32; ple_dim];
        for (o, g) in gated.iter_mut().enumerate() {
            let dot: f32 = (0..hidden)
                .map(|i| inp_gate[o * hidden + i] * h_in[i])
                .sum();
            *g = crate::inference::gemma4::gelu_tanh(dot) * pli[o];
        }
        let mut proj = vec![0.0f32; hidden];
        for (o, pr) in proj.iter_mut().enumerate() {
            *pr = (0..ple_dim)
                .map(|i| proj_w[o * ple_dim + i] * gated[i])
                .sum();
        }
        let mss = proj.iter().map(|v| v * v).sum::<f32>() / hidden as f32;
        let inv = (mss + eps).powf(-0.5);
        let want: Vec<f32> = (0..hidden)
            .map(|i| (h_in[i] + proj[i] * inv * post_norm[i]) * output_scale)
            .collect();

        let got = try_gemma4_ple(
            &h_in,
            &pli,
            &inp_gate,
            &proj_w,
            &post_norm,
            output_scale,
            eps,
            ple_dim,
        )
        .expect("gemma4 ple");
        for (a, b) in got.iter().zip(&want) {
            assert!((a - b).abs() < 1.0e-3, "{a} != {b}");
        }
    }

    // GPU pli (the folded encode_gemma4_pli) must match the CPU pli prep
    // (Gemma4Runtime::step / Gemma4GpuRuntime::forward).
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_pli_matches_cpu() {
        if !detect_metal_device().available {
            return;
        }
        let hidden = 128usize;
        let ple_dim = 64usize;
        let n_layers = 3usize;
        let ple_total = n_layers * ple_dim;
        let eps = 1.0e-6f32;
        let h0: Vec<f32> = (0..hidden)
            .map(|i| ((i as f32 % 13.0) - 6.0) * 0.1)
            .collect();
        let proj: Vec<f32> = (0..ple_total * hidden)
            .map(|n| (((n % 29) as f32) - 14.0) * 0.01)
            .collect();
        let proj_norm: Vec<f32> = (0..ple_dim)
            .map(|i| 0.8 + (i as f32 % 5.0) * 0.05)
            .collect();
        let ti: Vec<f32> = (0..ple_total)
            .map(|i| ((i % 17) as f32 - 8.0) * 0.07)
            .collect();

        // CPU reference (step() math).
        let proj_scale = (hidden as f32).powf(-0.5);
        let embed_scale = (ple_dim as f32).sqrt();
        let frac = std::f32::consts::FRAC_1_SQRT_2;
        let mut want = vec![0.0f32; ple_total];
        let ctx: Vec<f32> = (0..ple_total)
            .map(|o| {
                (0..hidden)
                    .map(|i| proj[o * hidden + i] * h0[i])
                    .sum::<f32>()
            })
            .collect();
        for l in 0..n_layers {
            let ctx_l: Vec<f32> = (0..ple_dim)
                .map(|d| ctx[l * ple_dim + d] * proj_scale)
                .collect();
            let mss = ctx_l.iter().map(|v| v * v).sum::<f32>() / ple_dim as f32;
            let inv = (mss + eps).powf(-0.5);
            for d in 0..ple_dim {
                want[l * ple_dim + d] =
                    (ctx_l[d] * inv * proj_norm[d] + ti[l * ple_dim + d] * embed_scale) * frac;
            }
        }
        let got = try_gemma4_pli(&h0, &proj, &proj_norm, &ti, hidden, ple_dim, n_layers, eps)
            .expect("gemma4 pli");
        for (a, b) in got.iter().zip(&want) {
            assert!((a - b).abs() < 1.0e-3, "{a} != {b}");
        }
    }

    // Gemma's logits head on GPU (rms_norm(output_norm) -> tied token_embd GEMV ->
    // soft_cap) must match the CPU reference, and the argmax (greedy next token) must
    // agree.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_head_matches_cpu() {
        if !detect_metal_device().available {
            return;
        }
        use crate::inference::quantize_q8_0_blocks;
        let hidden = 128usize;
        let vocab = 160usize;
        let eps = 1.0e-6f32;
        let softcap = 30.0f32;
        let h_in: Vec<f32> = (0..hidden)
            .map(|i| ((i as f32 % 13.0) - 6.0) * 0.12)
            .collect();
        let output_norm: Vec<f32> = (0..hidden)
            .map(|i| 0.85 + (i as f32 % 5.0) * 0.05)
            .collect();
        // Vocab-major Q8 embedding table: row v is token v's embedding.
        let mut wire = Vec::new();
        let mut deq = Vec::new();
        for v in 0..vocab {
            let row: Vec<f32> = (0..hidden)
                .map(|i| ((((v * hidden + i) % 31) as f32) - 15.0) * 0.05)
                .collect();
            let mut drow = vec![0.0f32; hidden];
            for (b, blk) in quantize_q8_0_blocks(&row).iter().enumerate() {
                wire.extend_from_slice(&f32_to_f16_bits(blk.scale).to_le_bytes());
                for (j, &q) in blk.quants.iter().enumerate() {
                    wire.push(q as u8);
                    drow[b * 32 + j] = blk.scale * q as f32;
                }
            }
            deq.push(drow);
        }
        // CPU reference: rms_norm -> matvec -> soft_cap.
        let mss = h_in.iter().map(|v| v * v).sum::<f32>() / hidden as f32;
        let inv = (mss + eps).powf(-0.5);
        let normf: Vec<f32> = (0..hidden)
            .map(|i| h_in[i] * inv * output_norm[i])
            .collect();
        let want: Vec<f32> = deq
            .iter()
            .map(|row| {
                let logit: f32 = row.iter().zip(&normf).map(|(a, b)| a * b).sum();
                softcap * (logit / softcap).tanh()
            })
            .collect();

        let got =
            try_gemma4_head(&h_in, &output_norm, &wire, vocab, softcap, eps).expect("gemma4 head");
        for (a, b) in got.iter().zip(&want) {
            assert!((a - b).abs() < 5.0e-3, "{a} != {b}");
        }
        // Greedy argmax must agree.
        let amax = |v: &[f32]| {
            v.iter()
                .enumerate()
                .max_by(|a, b| a.1.partial_cmp(b.1).unwrap())
                .map(|(i, _)| i)
                .unwrap()
        };
        assert_eq!(amax(&got), amax(&want));
    }

    // The full GPU forward (try_gemma4_forward: N layers + per-layer PLE + head, one
    // command buffer) must match the SAME pipeline assembled from the individually
    // CPU-validated try_* pieces in sequence. Two owning layers + PLE + head.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_forward_matches_composed_pieces() {
        if !detect_metal_device().available {
            return;
        }
        use crate::inference::quantize_q8_0_blocks;
        let hidden = 128usize;
        let n_heads = 2usize;
        let n_kv_heads = 1usize;
        let head_dim = 256usize;
        let ffn_dim = 256usize;
        let ple_dim = 64usize;
        let vocab = 160usize;
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv_heads * head_dim;
        let half = head_dim / 2;
        let max_positions = 8usize;
        let write_position = 3usize;
        let filled = 4usize;
        let eps = 1.0e-6f32;
        let softcap = 30.0f32;
        let scale = 1.0 / (head_dim as f32).sqrt();

        let mw = |rows: usize, in_dim: usize, seed: usize| -> Vec<u8> {
            let mut wire = Vec::new();
            for r in 0..rows {
                let row: Vec<f32> = (0..in_dim)
                    .map(|i| ((((r * in_dim + i + seed) % 29) as f32) - 14.0) * 0.03)
                    .collect();
                for blk in quantize_q8_0_blocks(&row).iter() {
                    wire.extend_from_slice(&f32_to_f16_bits(blk.scale).to_le_bytes());
                    for &q in blk.quants.iter() {
                        wire.push(q as u8);
                    }
                }
            }
            wire
        };
        let mk_norms = |off: usize| {
            (
                (0..hidden)
                    .map(|i| 0.8 + ((i + off) as f32 % 5.0) * 0.05)
                    .collect::<Vec<f32>>(),
                (0..hidden)
                    .map(|i| 0.9 + ((i + off) as f32 % 3.0) * 0.03)
                    .collect::<Vec<f32>>(),
                (0..hidden)
                    .map(|i| 0.85 + ((i + off) as f32 % 4.0) * 0.04)
                    .collect::<Vec<f32>>(),
                (0..hidden)
                    .map(|i| 0.95 + ((i + off) as f32 % 6.0) * 0.02)
                    .collect::<Vec<f32>>(),
                (0..head_dim)
                    .map(|i| 0.7 + ((i + off) as f32 % 11.0) * 0.02)
                    .collect::<Vec<f32>>(),
                (0..head_dim)
                    .map(|i| 0.6 + ((i + off) as f32 % 7.0) * 0.03)
                    .collect::<Vec<f32>>(),
            )
        };
        let build_layer = |off: usize| {
            let (an, pa, fnw, pf, qn, kn) = mk_norms(off);
            Gemma4ResidentLayer::from_wire(
                GemmaWireFmt::Q8_0,
                an,
                qn,
                kn,
                pa,
                fnw,
                pf,
                &mw(q_dim, hidden, off + 1),
                &mw(kv_dim, hidden, off + 5),
                Some(&mw(kv_dim, hidden, off + 9)),
                &mw(hidden, q_dim, off + 13),
                &mw(ffn_dim, hidden, off + 17),
                &mw(ffn_dim, hidden, off + 21),
                &mw(hidden, ffn_dim, off + 25),
                n_heads,
                n_kv_heads,
                head_dim,
                ffn_dim,
                eps,
            )
            .expect("layer")
        };
        let mk_ple = |off: usize| Gemma4ResidentPle {
            inp_gate: (0..ple_dim * hidden)
                .map(|n| (((n + off) % 29) as f32 - 14.0) * 0.02)
                .collect(),
            proj: (0..hidden * ple_dim)
                .map(|n| (((n + off) % 23) as f32 - 11.0) * 0.03)
                .collect(),
            post_norm: (0..hidden)
                .map(|i| 0.9 + ((i + off) as f32 % 5.0) * 0.04)
                .collect(),
            output_scale: 0.061,
        };
        let mk_input = |off: usize| Gemma4TokenLayerInput {
            cos_t: (0..half)
                .map(|i| (0.3 + (i + off) as f32 * 0.01).cos())
                .collect(),
            sin_t: (0..half)
                .map(|i| (0.3 + (i + off) as f32 * 0.01).sin())
                .collect(),
            pli: (0..ple_dim)
                .map(|i| ((i + off) as f32 % 9.0 - 4.0) * 0.2)
                .collect(),
            window_start: 0,
        };
        let cache_len = n_kv_heads * max_positions * head_dim;
        let mk_cache = |off: usize| -> Vec<f32> {
            (0..cache_len)
                .map(|i| (((i + off) % 17) as f32 - 8.0) * 0.05)
                .collect()
        };

        let h0: Vec<f32> = (0..hidden)
            .map(|i| ((i as f32 % 13.0) - 6.0) * 0.1)
            .collect();
        let output_norm: Vec<f32> = (0..hidden)
            .map(|i| 0.88 + (i as f32 % 5.0) * 0.03)
            .collect();
        let embd_wire = mw(vocab, hidden, 99);

        let l0 = build_layer(0);
        let l1 = build_layer(50);
        let ple0 = mk_ple(2);
        let ple1 = mk_ple(7);
        let in0 = mk_input(0);
        let in1 = mk_input(4);
        let ck0 = mk_cache(0);
        let cv0 = mk_cache(3);
        let ck1 = mk_cache(6);
        let cv1 = mk_cache(11);

        // ---- Oracle: chain the individually CPU-validated try_* pieces. ----
        let h1 = try_gemma4_layer(
            &l0,
            &h0,
            &in0.cos_t,
            &in0.sin_t,
            &ck0,
            &cv0,
            max_positions,
            write_position,
            filled,
            0,
            scale,
            true,
        )
        .expect("l0");
        let h1p = try_gemma4_ple(
            &h1,
            &in0.pli,
            &ple0.inp_gate,
            &ple0.proj,
            &ple0.post_norm,
            ple0.output_scale,
            eps,
            ple_dim,
        )
        .expect("ple0");
        let h2 = try_gemma4_layer(
            &l1,
            &h1p,
            &in1.cos_t,
            &in1.sin_t,
            &ck1,
            &cv1,
            max_positions,
            write_position,
            filled,
            0,
            scale,
            true,
        )
        .expect("l1");
        let h2p = try_gemma4_ple(
            &h2,
            &in1.pli,
            &ple1.inp_gate,
            &ple1.proj,
            &ple1.post_norm,
            ple1.output_scale,
            eps,
            ple_dim,
        )
        .expect("ple1");
        let want =
            try_gemma4_head(&h2p, &output_norm, &embd_wire, vocab, softcap, eps).expect("head");

        // ---- Integrated: one command buffer for everything. ----
        let got = try_gemma4_forward(
            &[l0, l1],
            &[Some(ple0), Some(ple1)],
            &[true, true],
            &[0, 1],
            &[in0, in1],
            &[Some(ck0), Some(ck1)],
            &[Some(cv0), Some(cv1)],
            &h0,
            &output_norm,
            &embd_wire,
            vocab,
            softcap,
            eps,
            max_positions,
            write_position,
            filled,
            scale,
        )
        .expect("forward");

        for (a, b) in got.iter().zip(&want) {
            assert!((a - b).abs() < 5.0e-3, "{a} != {b}");
        }
        let amax = |v: &[f32]| {
            v.iter()
                .enumerate()
                .max_by(|a, b| a.1.partial_cmp(b.1).unwrap())
                .map(|(i, _)| i)
                .unwrap()
        };
        assert_eq!(amax(&got), amax(&want));
    }

    // from_wire_pages (nocopy, the production 16GB-fit path) must produce a layer
    // identical to from_wire (copy) on the same wire bytes: the GPU reads the same
    // bytes either way. Writes the 7 weights to a temp file and maps each as WirePages.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_layer_from_wire_pages_matches_copy() {
        use crate::inference::quantize_q8_0_blocks;
        use crate::wire_mmap::WirePages;
        use std::fs::File;
        use std::io::Write;
        if !detect_metal_device().available {
            return;
        }
        let hidden = 64usize;
        let n_heads = 2usize;
        let n_kv_heads = 1usize;
        let head_dim = 64usize;
        let ffn_dim = 64usize;
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv_heads * head_dim;
        let eps = 1.0e-6f32;
        let scale = 1.0 / (head_dim as f32).sqrt();
        let mw = |rows: usize, in_dim: usize, seed: usize| -> Vec<u8> {
            let mut wire = Vec::new();
            for r in 0..rows {
                let row: Vec<f32> = (0..in_dim)
                    .map(|i| ((((r * in_dim + i + seed) % 29) as f32) - 14.0) * 0.03)
                    .collect();
                for blk in quantize_q8_0_blocks(&row).iter() {
                    wire.extend_from_slice(&f32_to_f16_bits(blk.scale).to_le_bytes());
                    for &q in blk.quants.iter() {
                        wire.push(q as u8);
                    }
                }
            }
            wire
        };
        let weights = [
            mw(q_dim, hidden, 1),
            mw(kv_dim, hidden, 5),
            mw(kv_dim, hidden, 9),
            mw(hidden, q_dim, 13),
            mw(ffn_dim, hidden, 17),
            mw(ffn_dim, hidden, 21),
            mw(hidden, ffn_dim, 25),
        ];
        // Concatenate into a temp file; record each tensor's (offset, len).
        let mut blob = Vec::new();
        let mut spans = Vec::new();
        for w in &weights {
            spans.push((blob.len() as u64, w.len()));
            blob.extend_from_slice(w);
        }
        let path = std::env::temp_dir().join(format!("gemma4_wp_test_{}.bin", std::process::id()));
        File::create(&path).unwrap().write_all(&blob).unwrap();
        let file = File::open(&path).unwrap();
        let pages: Vec<_> = spans
            .iter()
            .map(|&(off, len)| WirePages::read_from_file(&file, off, len).unwrap())
            .collect();

        let norms = || {
            (
                (0..hidden)
                    .map(|i| 0.8 + (i as f32 % 5.0) * 0.05)
                    .collect::<Vec<f32>>(),
                (0..hidden)
                    .map(|i| 0.9 + (i as f32 % 3.0) * 0.03)
                    .collect::<Vec<f32>>(),
                (0..hidden)
                    .map(|i| 0.85 + (i as f32 % 4.0) * 0.04)
                    .collect::<Vec<f32>>(),
                (0..hidden)
                    .map(|i| 0.95 + (i as f32 % 6.0) * 0.02)
                    .collect::<Vec<f32>>(),
                (0..head_dim)
                    .map(|i| 0.7 + (i as f32 % 11.0) * 0.02)
                    .collect::<Vec<f32>>(),
                (0..head_dim)
                    .map(|i| 0.6 + (i as f32 % 7.0) * 0.03)
                    .collect::<Vec<f32>>(),
            )
        };
        let (an, pa, fnw, pf, qn, kn) = norms();
        let copy = Gemma4ResidentLayer::from_wire(
            GemmaWireFmt::Q8_0,
            an.clone(),
            qn.clone(),
            kn.clone(),
            pa.clone(),
            fnw.clone(),
            pf.clone(),
            &weights[0],
            &weights[1],
            Some(&weights[2]),
            &weights[3],
            &weights[4],
            &weights[5],
            &weights[6],
            n_heads,
            n_kv_heads,
            head_dim,
            ffn_dim,
            eps,
        )
        .expect("copy");
        let nocopy = Gemma4ResidentLayer::from_wire_pages(
            GemmaWireFmt::Q8_0,
            an,
            qn,
            kn,
            pa,
            fnw,
            pf,
            &pages[0],
            &pages[1],
            Some(&pages[2]),
            &pages[3],
            &pages[4],
            &pages[5],
            &pages[6],
            n_heads,
            n_kv_heads,
            head_dim,
            ffn_dim,
            eps,
        )
        .expect("nocopy");

        let h_in: Vec<f32> = (0..hidden)
            .map(|i| ((i as f32 % 13.0) - 6.0) * 0.1)
            .collect();
        let half = head_dim / 2;
        let cos_t: Vec<f32> = (0..half).map(|i| (0.3 + i as f32 * 0.01).cos()).collect();
        let sin_t: Vec<f32> = (0..half).map(|i| (0.3 + i as f32 * 0.01).sin()).collect();
        let cache_len = n_kv_heads * 8 * head_dim;
        let ck: Vec<f32> = (0..cache_len)
            .map(|i| ((i % 17) as f32 - 8.0) * 0.05)
            .collect();
        let cv: Vec<f32> = (0..cache_len)
            .map(|i| ((i % 23) as f32 - 11.0) * 0.04)
            .collect();
        let run = |layer: &Gemma4ResidentLayer| {
            try_gemma4_layer(
                layer, &h_in, &cos_t, &sin_t, &ck, &cv, 8, 3, 4, 0, scale, true,
            )
            .expect("layer")
        };
        let a = run(&copy);
        let b = run(&nocopy);
        let _ = std::fs::remove_file(&path);
        for (x, y) in a.iter().zip(&b) {
            assert!((x - y).abs() < 1.0e-4, "{x} != {y}");
        }
    }

    // The stateful Gemma4ResidentModel::forward_token (resident weights + token_embd +
    // persistent caches) must match the stateless try_gemma4_forward for one token at
    // position 0 — same layers/PLE/head, so the only difference is statefulness.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_resident_model_forward_token_matches_stateless() {
        if !detect_metal_device().available {
            return;
        }
        use crate::inference::quantize_q8_0_blocks;
        let hidden = 128usize;
        let n_heads = 2usize;
        let n_kv_heads = 1usize;
        let head_dim = 256usize;
        let ffn_dim = 256usize;
        let ple_dim = 64usize;
        let vocab = 160usize;
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv_heads * head_dim;
        let half = head_dim / 2;
        let max_positions = 8usize;
        let eps = 1.0e-6f32;
        let softcap = 30.0f32;
        let scale = 1.0 / (head_dim as f32).sqrt();

        let mw = |rows: usize, in_dim: usize, seed: usize| -> Vec<u8> {
            let mut wire = Vec::new();
            for r in 0..rows {
                let row: Vec<f32> = (0..in_dim)
                    .map(|i| ((((r * in_dim + i + seed) % 29) as f32) - 14.0) * 0.03)
                    .collect();
                for blk in quantize_q8_0_blocks(&row).iter() {
                    wire.extend_from_slice(&f32_to_f16_bits(blk.scale).to_le_bytes());
                    for &q in blk.quants.iter() {
                        wire.push(q as u8);
                    }
                }
            }
            wire
        };
        let mk_norms = |off: usize| {
            (
                (0..hidden)
                    .map(|i| 0.8 + ((i + off) as f32 % 5.0) * 0.05)
                    .collect::<Vec<f32>>(),
                (0..hidden)
                    .map(|i| 0.9 + ((i + off) as f32 % 3.0) * 0.03)
                    .collect::<Vec<f32>>(),
                (0..hidden)
                    .map(|i| 0.85 + ((i + off) as f32 % 4.0) * 0.04)
                    .collect::<Vec<f32>>(),
                (0..hidden)
                    .map(|i| 0.95 + ((i + off) as f32 % 6.0) * 0.02)
                    .collect::<Vec<f32>>(),
                (0..head_dim)
                    .map(|i| 0.7 + ((i + off) as f32 % 11.0) * 0.02)
                    .collect::<Vec<f32>>(),
                (0..head_dim)
                    .map(|i| 0.6 + ((i + off) as f32 % 7.0) * 0.03)
                    .collect::<Vec<f32>>(),
            )
        };
        let build_layer = |off: usize| {
            let (an, pa, fnw, pf, qn, kn) = mk_norms(off);
            Gemma4ResidentLayer::from_wire(
                GemmaWireFmt::Q8_0,
                an,
                qn,
                kn,
                pa,
                fnw,
                pf,
                &mw(q_dim, hidden, off + 1),
                &mw(kv_dim, hidden, off + 5),
                Some(&mw(kv_dim, hidden, off + 9)),
                &mw(hidden, q_dim, off + 13),
                &mw(ffn_dim, hidden, off + 17),
                &mw(ffn_dim, hidden, off + 21),
                &mw(hidden, ffn_dim, off + 25),
                n_heads,
                n_kv_heads,
                head_dim,
                ffn_dim,
                eps,
            )
            .expect("layer")
        };
        let mk_ple = |off: usize| Gemma4ResidentPle {
            inp_gate: (0..ple_dim * hidden)
                .map(|n| (((n + off) % 29) as f32 - 14.0) * 0.02)
                .collect(),
            proj: (0..hidden * ple_dim)
                .map(|n| (((n + off) % 23) as f32 - 11.0) * 0.03)
                .collect(),
            post_norm: (0..hidden)
                .map(|i| 0.9 + ((i + off) as f32 % 5.0) * 0.04)
                .collect(),
            output_scale: 0.061,
        };
        let mk_input = |off: usize| Gemma4TokenLayerInput {
            cos_t: (0..half)
                .map(|i| (0.3 + (i + off) as f32 * 0.01).cos())
                .collect(),
            sin_t: (0..half)
                .map(|i| (0.3 + (i + off) as f32 * 0.01).sin())
                .collect(),
            pli: (0..ple_dim)
                .map(|i| ((i + off) as f32 % 9.0 - 4.0) * 0.2)
                .collect(),
            window_start: 0,
        };
        let h0: Vec<f32> = (0..hidden)
            .map(|i| ((i as f32 % 13.0) - 6.0) * 0.1)
            .collect();
        let output_norm: Vec<f32> = (0..hidden)
            .map(|i| 0.88 + (i as f32 % 5.0) * 0.03)
            .collect();
        let embd_wire = mw(vocab, hidden, 99);
        let cache_len = n_kv_heads * max_positions * head_dim;
        let zeros = vec![0.0f32; cache_len];

        // Stateless oracle (validated): position 0, filled 1, fresh cache.
        // PLE is exercised separately (metal_gemma4_ple/_pli); here both paths run
        // PLE-free so forward_token (GPU pli) and try_gemma4_forward stay comparable.
        let _ = mk_ple(0);
        let want = try_gemma4_forward(
            &[build_layer(0), build_layer(50)],
            &[None, None],
            &[true, true],
            &[0, 1],
            &[mk_input(0), mk_input(4)],
            &[Some(zeros.clone()), Some(zeros.clone())],
            &[Some(zeros.clone()), Some(zeros.clone())],
            &h0,
            &output_norm,
            &embd_wire,
            vocab,
            softcap,
            eps,
            max_positions,
            0,
            1,
            scale,
        )
        .expect("stateless");

        // Stateful model (fresh layers from the same bytes), token at position 0.
        let model = Gemma4ResidentModel::new(
            vec![build_layer(0), build_layer(50)],
            vec![None, None],
            vec![1.0, 1.0],
            vec![true, true],
            vec![0, 1],
            &embd_wire,
            output_norm.clone(),
            hidden,
            vocab,
            softcap,
            eps,
            max_positions,
            scale,
        )
        .expect("model");
        let got = model
            .forward_token(&h0, &[mk_input(0), mk_input(4)], &[], 0)
            .expect("forward_token");

        for (a, b) in got.iter().zip(&want) {
            assert!((a - b).abs() < 5.0e-3, "{a} != {b}");
        }
        let amax = |v: &[f32]| {
            v.iter()
                .enumerate()
                .max_by(|a, b| a.1.partial_cmp(b.1).unwrap())
                .map(|(i, _)| i)
                .unwrap()
        };
        assert_eq!(amax(&got), amax(&want));
    }

    // QAT integration gate (visible): a Gemma4ResidentModel built with Q4_0 projection
    // weights must decode a token on the GPU matching the CPU f32×dequant reference of
    // the SAME model. Exercises the resident path end-to-end with GemmaWireFmt::Q4_0
    // routed through encode_gemma4_layer (attention + FFN Q4_0 GEMV) plus the Q8 head.
    // One owning V-ful layer, no PLE, position 0 (fresh cache). The supported dense
    // rows are untouched (they pass Q8_0); this proves the Q4_0 layer routing is real.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_resident_q4_forward_matches_cpu() {
        if !detect_metal_device().available {
            return;
        }
        use crate::inference::{gemma4::gelu_tanh, q4_0_wire_block_dequant, quantize_q8_0_blocks};
        let hidden = 128usize;
        let n_heads = 2usize;
        let n_kv_heads = 1usize;
        let head_dim = 256usize;
        let ffn_dim = 256usize;
        let vocab = 160usize;
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv_heads * head_dim;
        let half = head_dim / 2;
        let max_positions = 8usize;
        let eps = 1.0e-6f32;
        let softcap = 30.0f32;
        let scale = 1.0 / (head_dim as f32).sqrt();

        // Q4_0 projection weight -> (wire bytes, dequantized rows). The CPU reference
        // dots the SAME values the GPU's f32×dequant Q4_0 GEMV reads.
        let mw4 = |rows: usize, in_dim: usize, seed: usize| -> (Vec<u8>, Vec<Vec<f32>>) {
            let mut wire = Vec::new();
            let mut deq = Vec::new();
            for r in 0..rows {
                let mut drow = vec![0.0f32; in_dim];
                for b in 0..(in_dim / 32) {
                    let sc = (((r + b + seed) % 7) as f32 + 1.0) * 0.015;
                    let mut blk = [0u8; 18];
                    blk[0..2].copy_from_slice(&f32_to_f16_bits(sc).to_le_bytes());
                    for (j, slot) in blk[2..].iter_mut().enumerate() {
                        *slot = ((r * 13 + b * 7 + j * 5 + seed) % 256) as u8;
                    }
                    let d = q4_0_wire_block_dequant(&blk);
                    for (i, &val) in d.iter().enumerate() {
                        drow[b * 32 + i] = val;
                    }
                    wire.extend_from_slice(&blk);
                }
                deq.push(drow);
            }
            (wire, deq)
        };
        let (q_wire, q_deq) = mw4(q_dim, hidden, 1);
        let (k_wire, k_deq) = mw4(kv_dim, hidden, 5);
        let (v_wire, v_deq) = mw4(kv_dim, hidden, 9);
        let (o_wire, o_deq) = mw4(hidden, q_dim, 13);
        let (gate_wire, gate_deq) = mw4(ffn_dim, hidden, 17);
        let (up_wire, up_deq) = mw4(ffn_dim, hidden, 21);
        let (down_wire, down_deq) = mw4(hidden, ffn_dim, 25);

        let attn_norm: Vec<f32> = (0..hidden).map(|i| 0.8 + (i as f32 % 5.0) * 0.05).collect();
        let post_attn_norm: Vec<f32> = (0..hidden).map(|i| 0.9 + (i as f32 % 3.0) * 0.03).collect();
        let ffn_norm: Vec<f32> = (0..hidden)
            .map(|i| 0.85 + (i as f32 % 4.0) * 0.04)
            .collect();
        let post_ffw_norm: Vec<f32> = (0..hidden)
            .map(|i| 0.95 + (i as f32 % 6.0) * 0.02)
            .collect();
        let q_norm: Vec<f32> = (0..head_dim)
            .map(|i| 0.7 + (i as f32 % 11.0) * 0.02)
            .collect();
        let k_norm: Vec<f32> = (0..head_dim)
            .map(|i| 0.6 + (i as f32 % 7.0) * 0.03)
            .collect();
        let output_norm: Vec<f32> = (0..hidden)
            .map(|i| 0.88 + (i as f32 % 5.0) * 0.03)
            .collect();
        let h0: Vec<f32> = (0..hidden)
            .map(|i| ((i as f32 % 13.0) - 6.0) * 0.1)
            .collect();
        let cos_t: Vec<f32> = (0..half).map(|i| (0.3 + i as f32 * 0.01).cos()).collect();
        let sin_t: Vec<f32> = (0..half).map(|i| (0.3 + i as f32 * 0.01).sin()).collect();

        // Q8 vocab-major embedding table (the head is unchanged Q8) -> wire + dequant.
        let mut embd_wire = Vec::new();
        let mut embd_deq = Vec::new();
        for v in 0..vocab {
            let row: Vec<f32> = (0..hidden)
                .map(|i| ((((v * hidden + i) % 31) as f32) - 15.0) * 0.05)
                .collect();
            let mut drow = vec![0.0f32; hidden];
            for (b, blk) in quantize_q8_0_blocks(&row).iter().enumerate() {
                embd_wire.extend_from_slice(&f32_to_f16_bits(blk.scale).to_le_bytes());
                for (j, &qq) in blk.quants.iter().enumerate() {
                    embd_wire.push(qq as u8);
                    drow[b * 32 + j] = blk.scale * qq as f32;
                }
            }
            embd_deq.push(drow);
        }

        // ---- CPU reference over the dequantized weights ----
        let rms = |x: &[f32], w: Option<&[f32]>| -> Vec<f32> {
            let mss = x.iter().map(|v| v * v).sum::<f32>() / x.len() as f32;
            let inv = (mss + eps).powf(-0.5);
            (0..x.len())
                .map(|i| x[i] * inv * w.map_or(1.0, |w| w[i]))
                .collect()
        };
        let matmul = |deq: &[Vec<f32>], x: &[f32]| -> Vec<f32> {
            deq.iter()
                .map(|row| row.iter().zip(x).map(|(a, b)| a * b).sum())
                .collect()
        };
        let per_head = |x: &[f32], heads: usize, w: Option<&[f32]>| -> Vec<f32> {
            let mut out = vec![0.0f32; x.len()];
            for h in 0..heads {
                let n = rms(&x[h * head_dim..(h + 1) * head_dim], w);
                out[h * head_dim..(h + 1) * head_dim].copy_from_slice(&n);
            }
            out
        };
        let rope = |x: &mut [f32], heads: usize| {
            for h in 0..heads {
                let base = h * head_dim;
                for i in 0..half {
                    let (x0, x1) = (x[base + i], x[base + half + i]);
                    x[base + i] = x0 * cos_t[i] - x1 * sin_t[i];
                    x[base + half + i] = x0 * sin_t[i] + x1 * cos_t[i];
                }
            }
        };
        // Attention at position 0 (fresh cache): only the current token's K/V, so the
        // single-element softmax weight is 1 and ctx is just V.
        let normf = rms(&h0, Some(&attn_norm));
        let mut q = per_head(&matmul(&q_deq, &normf), n_heads, Some(&q_norm));
        let _kk = per_head(&matmul(&k_deq, &normf), n_kv_heads, Some(&k_norm));
        let vv = per_head(&matmul(&v_deq, &normf), n_kv_heads, None);
        rope(&mut q, n_heads);
        let group = n_heads / n_kv_heads;
        let mut ctx = vec![0.0f32; q_dim];
        for h in 0..n_heads {
            let kvh = h / group;
            for d in 0..head_dim {
                ctx[h * head_dim + d] = vv[kvh * head_dim + d];
            }
        }
        let attn_out = matmul(&o_deq, &ctx);
        let mid: Vec<f32> = h0
            .iter()
            .zip(rms(&attn_out, Some(&post_attn_norm)))
            .map(|(a, b)| a + b)
            .collect();
        // FFN.
        let normf2 = rms(&mid, Some(&ffn_norm));
        let gate = matmul(&gate_deq, &normf2);
        let up = matmul(&up_deq, &normf2);
        let act: Vec<f32> = gate
            .iter()
            .zip(&up)
            .map(|(g, u)| gelu_tanh(*g) * u)
            .collect();
        let down = matmul(&down_deq, &act);
        let h_final: Vec<f32> = mid
            .iter()
            .zip(rms(&down, Some(&post_ffw_norm)))
            .map(|(a, b)| a + b)
            .collect();
        // Head: rms -> logits -> soft_cap.
        let normh = rms(&h_final, Some(&output_norm));
        let want: Vec<f32> = embd_deq
            .iter()
            .map(|row| {
                let logit: f32 = row.iter().zip(&normh).map(|(a, b)| a * b).sum();
                softcap * (logit / softcap).tanh()
            })
            .collect();

        // ---- GPU resident model (Q4_0 layer) ----
        let layer = Gemma4ResidentLayer::from_wire(
            GemmaWireFmt::Q4_0,
            attn_norm,
            q_norm,
            k_norm,
            post_attn_norm,
            ffn_norm,
            post_ffw_norm,
            &q_wire,
            &k_wire,
            Some(&v_wire),
            &o_wire,
            &gate_wire,
            &up_wire,
            &down_wire,
            n_heads,
            n_kv_heads,
            head_dim,
            ffn_dim,
            eps,
        )
        .expect("q4 layer");
        let model = Gemma4ResidentModel::new(
            vec![layer],
            vec![None],
            vec![1.0],
            vec![true],
            vec![0],
            &embd_wire,
            output_norm,
            hidden,
            vocab,
            softcap,
            eps,
            max_positions,
            scale,
        )
        .expect("q4 model");
        let input = Gemma4TokenLayerInput {
            cos_t,
            sin_t,
            pli: Vec::new(),
            window_start: 0,
        };
        let got = model
            .forward_token(&h0, &[input], &[], 0)
            .expect("forward_token q4");
        for (a, b) in got.iter().zip(&want) {
            assert!((a - b).abs() < 2.0e-2, "{a} != {b}");
        }
        let amax = |v: &[f32]| {
            v.iter()
                .enumerate()
                .max_by(|a, b| a.1.partial_cmp(b.1).unwrap())
                .map(|(i, _)| i)
                .unwrap()
        };
        assert_eq!(amax(&got), amax(&want), "greedy argmax must agree");
    }

    // GABBRO M3-followup: the SAME full resident forward (attention + FFN + head) with
    // NVFP4 layer projections must match the CPU dequant oracle — proving the NVFP4
    // GEMV runs correctly IN CONTEXT (not just the standalone gate), and that the
    // format-aware blocks_per_row (block_elements()=64) threads through encode_gemma4_ffn
    // /encode_gemma4_attention. Built directly (no Gemma4GpuRuntime::load), so it needs
    // no model file and does not touch the load-path admission gate.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_resident_nvfp4_forward_matches_cpu() {
        if !detect_metal_device().available {
            return;
        }
        use crate::inference::{gemma4::gelu_tanh, nvfp4_wire_block_dequant, quantize_q8_0_blocks};
        let hidden = 128usize;
        let n_heads = 2usize;
        let n_kv_heads = 1usize;
        let head_dim = 256usize;
        let ffn_dim = 256usize;
        let vocab = 160usize;
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv_heads * head_dim;
        let half = head_dim / 2;
        let max_positions = 8usize;
        let eps = 1.0e-6f32;
        let softcap = 30.0f32;
        let scale = 1.0 / (head_dim as f32).sqrt();

        // NVFP4 projection weight -> (36-byte superblocks, dequantized rows). The CPU
        // reference dots the SAME values the GPU's f32×decode NVFP4 GEMV reads.
        let mw_nvfp4 = |rows: usize, in_dim: usize, seed: usize| -> (Vec<u8>, Vec<Vec<f32>>) {
            let mut wire = Vec::new();
            let mut deq = Vec::new();
            for r in 0..rows {
                let mut drow = vec![0.0f32; in_dim];
                for b in 0..(in_dim / 64) {
                    let mut blk = [0u8; 36];
                    // 4 UE4M3 sub-block scales in [8,72): non-zero, never 0x7F/0xFF sentinels.
                    for (s, slot) in blk[0..4].iter_mut().enumerate() {
                        *slot = (((r * 5 + b * 3 + s + seed) % 64) + 8) as u8;
                    }
                    // 32 packed E2M1 nibble bytes.
                    for (j, slot) in blk[4..].iter_mut().enumerate() {
                        *slot = ((r * 13 + b * 7 + j * 5 + seed) % 256) as u8;
                    }
                    let d = nvfp4_wire_block_dequant(&blk);
                    for (i, &val) in d.iter().enumerate() {
                        drow[b * 64 + i] = val;
                    }
                    wire.extend_from_slice(&blk);
                }
                deq.push(drow);
            }
            (wire, deq)
        };
        let (q_wire, q_deq) = mw_nvfp4(q_dim, hidden, 1);
        let (k_wire, k_deq) = mw_nvfp4(kv_dim, hidden, 5);
        let (v_wire, v_deq) = mw_nvfp4(kv_dim, hidden, 9);
        let (o_wire, o_deq) = mw_nvfp4(hidden, q_dim, 13);
        let (gate_wire, gate_deq) = mw_nvfp4(ffn_dim, hidden, 17);
        let (up_wire, up_deq) = mw_nvfp4(ffn_dim, hidden, 21);
        let (down_wire, down_deq) = mw_nvfp4(hidden, ffn_dim, 25);

        let attn_norm: Vec<f32> = (0..hidden).map(|i| 0.8 + (i as f32 % 5.0) * 0.05).collect();
        let post_attn_norm: Vec<f32> = (0..hidden).map(|i| 0.9 + (i as f32 % 3.0) * 0.03).collect();
        let ffn_norm: Vec<f32> = (0..hidden)
            .map(|i| 0.85 + (i as f32 % 4.0) * 0.04)
            .collect();
        let post_ffw_norm: Vec<f32> = (0..hidden)
            .map(|i| 0.95 + (i as f32 % 6.0) * 0.02)
            .collect();
        let q_norm: Vec<f32> = (0..head_dim)
            .map(|i| 0.7 + (i as f32 % 11.0) * 0.02)
            .collect();
        let k_norm: Vec<f32> = (0..head_dim)
            .map(|i| 0.6 + (i as f32 % 7.0) * 0.03)
            .collect();
        let output_norm: Vec<f32> = (0..hidden)
            .map(|i| 0.88 + (i as f32 % 5.0) * 0.03)
            .collect();
        let h0: Vec<f32> = (0..hidden)
            .map(|i| ((i as f32 % 13.0) - 6.0) * 0.1)
            .collect();
        let cos_t: Vec<f32> = (0..half).map(|i| (0.3 + i as f32 * 0.01).cos()).collect();
        let sin_t: Vec<f32> = (0..half).map(|i| (0.3 + i as f32 * 0.01).sin()).collect();

        // Q8 vocab-major embedding table (the head is unchanged Q8) -> wire + dequant.
        let mut embd_wire = Vec::new();
        let mut embd_deq = Vec::new();
        for v in 0..vocab {
            let row: Vec<f32> = (0..hidden)
                .map(|i| ((((v * hidden + i) % 31) as f32) - 15.0) * 0.05)
                .collect();
            let mut drow = vec![0.0f32; hidden];
            for (b, blk) in quantize_q8_0_blocks(&row).iter().enumerate() {
                embd_wire.extend_from_slice(&f32_to_f16_bits(blk.scale).to_le_bytes());
                for (j, &qq) in blk.quants.iter().enumerate() {
                    embd_wire.push(qq as u8);
                    drow[b * 32 + j] = blk.scale * qq as f32;
                }
            }
            embd_deq.push(drow);
        }

        // ---- CPU reference over the dequantized weights ----
        let rms = |x: &[f32], w: Option<&[f32]>| -> Vec<f32> {
            let mss = x.iter().map(|v| v * v).sum::<f32>() / x.len() as f32;
            let inv = (mss + eps).powf(-0.5);
            (0..x.len())
                .map(|i| x[i] * inv * w.map_or(1.0, |w| w[i]))
                .collect()
        };
        let matmul = |deq: &[Vec<f32>], x: &[f32]| -> Vec<f32> {
            deq.iter()
                .map(|row| row.iter().zip(x).map(|(a, b)| a * b).sum())
                .collect()
        };
        let per_head = |x: &[f32], heads: usize, w: Option<&[f32]>| -> Vec<f32> {
            let mut out = vec![0.0f32; x.len()];
            for h in 0..heads {
                let n = rms(&x[h * head_dim..(h + 1) * head_dim], w);
                out[h * head_dim..(h + 1) * head_dim].copy_from_slice(&n);
            }
            out
        };
        let rope = |x: &mut [f32], heads: usize| {
            for h in 0..heads {
                let base = h * head_dim;
                for i in 0..half {
                    let (x0, x1) = (x[base + i], x[base + half + i]);
                    x[base + i] = x0 * cos_t[i] - x1 * sin_t[i];
                    x[base + half + i] = x0 * sin_t[i] + x1 * cos_t[i];
                }
            }
        };
        let normf = rms(&h0, Some(&attn_norm));
        let mut q = per_head(&matmul(&q_deq, &normf), n_heads, Some(&q_norm));
        let _kk = per_head(&matmul(&k_deq, &normf), n_kv_heads, Some(&k_norm));
        let vv = per_head(&matmul(&v_deq, &normf), n_kv_heads, None);
        rope(&mut q, n_heads);
        let group = n_heads / n_kv_heads;
        let mut ctx = vec![0.0f32; q_dim];
        for h in 0..n_heads {
            let kvh = h / group;
            for d in 0..head_dim {
                ctx[h * head_dim + d] = vv[kvh * head_dim + d];
            }
        }
        let attn_out = matmul(&o_deq, &ctx);
        let mid: Vec<f32> = h0
            .iter()
            .zip(rms(&attn_out, Some(&post_attn_norm)))
            .map(|(a, b)| a + b)
            .collect();
        let normf2 = rms(&mid, Some(&ffn_norm));
        let gate = matmul(&gate_deq, &normf2);
        let up = matmul(&up_deq, &normf2);
        let act: Vec<f32> = gate
            .iter()
            .zip(&up)
            .map(|(g, u)| gelu_tanh(*g) * u)
            .collect();
        let down = matmul(&down_deq, &act);
        let h_final: Vec<f32> = mid
            .iter()
            .zip(rms(&down, Some(&post_ffw_norm)))
            .map(|(a, b)| a + b)
            .collect();
        let normh = rms(&h_final, Some(&output_norm));
        let want: Vec<f32> = embd_deq
            .iter()
            .map(|row| {
                let logit: f32 = row.iter().zip(&normh).map(|(a, b)| a * b).sum();
                softcap * (logit / softcap).tanh()
            })
            .collect();

        // ---- GPU resident model (NVFP4 layer projections, Q8 head) ----
        let layer = Gemma4ResidentLayer::from_wire(
            GemmaWireFmt::Nvfp4,
            attn_norm,
            q_norm,
            k_norm,
            post_attn_norm,
            ffn_norm,
            post_ffw_norm,
            &q_wire,
            &k_wire,
            Some(&v_wire),
            &o_wire,
            &gate_wire,
            &up_wire,
            &down_wire,
            n_heads,
            n_kv_heads,
            head_dim,
            ffn_dim,
            eps,
        )
        .expect("nvfp4 layer");
        let model = Gemma4ResidentModel::new(
            vec![layer],
            vec![None],
            vec![1.0],
            vec![true],
            vec![0],
            &embd_wire,
            output_norm,
            hidden,
            vocab,
            softcap,
            eps,
            max_positions,
            scale,
        )
        .expect("nvfp4 model");
        let input = Gemma4TokenLayerInput {
            cos_t,
            sin_t,
            pli: Vec::new(),
            window_start: 0,
        };
        let got = model
            .forward_token(&h0, &[input], &[], 0)
            .expect("forward_token nvfp4");
        for (a, b) in got.iter().zip(&want) {
            assert!((a - b).abs() < 2.0e-2, "{a} != {b}");
        }
        let amax = |v: &[f32]| {
            v.iter()
                .enumerate()
                .max_by(|a, b| a.1.partial_cmp(b.1).unwrap())
                .map(|(i, _)| i)
                .unwrap()
        };
        assert_eq!(amax(&got), amax(&want), "greedy argmax must agree");
    }

    // The QAT hybrid split point: forward_token_hidden (GPU layers, no head) followed by
    // the CPU head (rms_norm -> token_embd matvec -> soft_cap) must reproduce exactly
    // what forward_token computes with the head encoded on the GPU. Proves the runtime's
    // "GPU layers + CPU Q6_K head" lane is byte-faithful to the all-GPU path; here the
    // head is Q8 so the same dequantized table drives both sides.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gemma4_forward_token_hidden_plus_cpu_head_matches_forward_token() {
        if !detect_metal_device().available {
            return;
        }
        use crate::inference::quantize_q8_0_blocks;
        let hidden = 128usize;
        let n_heads = 2usize;
        let n_kv_heads = 1usize;
        let head_dim = 256usize;
        let ffn_dim = 256usize;
        let vocab = 160usize;
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv_heads * head_dim;
        let half = head_dim / 2;
        let max_positions = 8usize;
        let eps = 1.0e-6f32;
        let softcap = 30.0f32;
        let scale = 1.0 / (head_dim as f32).sqrt();

        let mw = |rows: usize, in_dim: usize, seed: usize| -> Vec<u8> {
            let mut wire = Vec::new();
            for r in 0..rows {
                let row: Vec<f32> = (0..in_dim)
                    .map(|i| ((((r * in_dim + i + seed) % 29) as f32) - 14.0) * 0.03)
                    .collect();
                for blk in quantize_q8_0_blocks(&row).iter() {
                    wire.extend_from_slice(&f32_to_f16_bits(blk.scale).to_le_bytes());
                    for &q in blk.quants.iter() {
                        wire.push(q as u8);
                    }
                }
            }
            wire
        };
        let an: Vec<f32> = (0..hidden).map(|i| 0.8 + (i as f32 % 5.0) * 0.05).collect();
        let pa: Vec<f32> = (0..hidden).map(|i| 0.9 + (i as f32 % 3.0) * 0.03).collect();
        let fnw: Vec<f32> = (0..hidden)
            .map(|i| 0.85 + (i as f32 % 4.0) * 0.04)
            .collect();
        let pf: Vec<f32> = (0..hidden)
            .map(|i| 0.95 + (i as f32 % 6.0) * 0.02)
            .collect();
        let qn: Vec<f32> = (0..head_dim)
            .map(|i| 0.7 + (i as f32 % 11.0) * 0.02)
            .collect();
        let kn: Vec<f32> = (0..head_dim)
            .map(|i| 0.6 + (i as f32 % 7.0) * 0.03)
            .collect();
        let output_norm: Vec<f32> = (0..hidden)
            .map(|i| 0.88 + (i as f32 % 5.0) * 0.03)
            .collect();
        let h0: Vec<f32> = (0..hidden)
            .map(|i| ((i as f32 % 13.0) - 6.0) * 0.1)
            .collect();

        // Q8 vocab-major head table -> wire + dequant (drives the CPU head reference).
        let mut embd_wire = Vec::new();
        let mut embd_deq = Vec::new();
        for v in 0..vocab {
            let row: Vec<f32> = (0..hidden)
                .map(|i| ((((v * hidden + i) % 31) as f32) - 15.0) * 0.05)
                .collect();
            let mut drow = vec![0.0f32; hidden];
            for (b, blk) in quantize_q8_0_blocks(&row).iter().enumerate() {
                embd_wire.extend_from_slice(&f32_to_f16_bits(blk.scale).to_le_bytes());
                for (j, &qq) in blk.quants.iter().enumerate() {
                    embd_wire.push(qq as u8);
                    drow[b * 32 + j] = blk.scale * qq as f32;
                }
            }
            embd_deq.push(drow);
        }

        let build = || {
            let layer = Gemma4ResidentLayer::from_wire(
                GemmaWireFmt::Q8_0,
                an.clone(),
                qn.clone(),
                kn.clone(),
                pa.clone(),
                fnw.clone(),
                pf.clone(),
                &mw(q_dim, hidden, 1),
                &mw(kv_dim, hidden, 5),
                Some(&mw(kv_dim, hidden, 9)),
                &mw(hidden, q_dim, 13),
                &mw(ffn_dim, hidden, 17),
                &mw(ffn_dim, hidden, 21),
                &mw(hidden, ffn_dim, 25),
                n_heads,
                n_kv_heads,
                head_dim,
                ffn_dim,
                eps,
            )
            .expect("layer");
            Gemma4ResidentModel::new(
                vec![layer],
                vec![None],
                vec![1.0],
                vec![true],
                vec![0],
                &embd_wire,
                output_norm.clone(),
                hidden,
                vocab,
                softcap,
                eps,
                max_positions,
                scale,
            )
            .expect("model")
        };
        let input = || Gemma4TokenLayerInput {
            cos_t: (0..half).map(|i| (0.3 + i as f32 * 0.01).cos()).collect(),
            sin_t: (0..half).map(|i| (0.3 + i as f32 * 0.01).sin()).collect(),
            pli: Vec::new(),
            window_start: 0,
        };

        let gpu_head = build();
        let logits_gpu = gpu_head
            .forward_token(&h0, &[input()], &[], 0)
            .expect("forward_token");
        let cpu_head = build();
        let hidden_only = cpu_head
            .forward_token_hidden(&h0, &[input()], &[], 0)
            .expect("forward_token_hidden");

        // CPU head over the returned hidden state.
        let mss = hidden_only.iter().map(|v| v * v).sum::<f32>() / hidden as f32;
        let inv = (mss + eps).powf(-0.5);
        let last: Vec<f32> = (0..hidden)
            .map(|i| hidden_only[i] * inv * output_norm[i])
            .collect();
        let logits_cpu: Vec<f32> = embd_deq
            .iter()
            .map(|row| {
                let logit: f32 = row.iter().zip(&last).map(|(a, b)| a * b).sum();
                softcap * (logit / softcap).tanh()
            })
            .collect();

        for (a, b) in logits_gpu.iter().zip(&logits_cpu) {
            assert!((a - b).abs() < 5.0e-3, "{a} != {b}");
        }
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn metal_attention_block_resident_matches_standalone() {
        if !detect_metal_device().available {
            return;
        }
        let n_heads = 2usize;
        let n_kv = 2usize;
        let head_dim = 32usize;
        let hidden = 64usize;
        let position_count = 3usize;
        let pos = position_count - 1;
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv * head_dim;
        let half = head_dim / 2;
        let eps = 1.0e-5f32;
        let scale = 1.0 / (head_dim as f32).sqrt();
        let bpr_hidden = hidden / 32;
        let bpr_q = q_dim / 32;
        let input: Vec<f32> = (0..hidden)
            .map(|i| ((i as f32 % 11.0) - 5.0) * 0.2)
            .collect();
        let attn_norm: Vec<f32> = (0..hidden).map(|i| 0.5 + (i as f32 % 3.0) * 0.1).collect();
        let cos_t: Vec<f32> = (0..half).map(|p| (0.2 + p as f32 * 0.1).cos()).collect();
        let sin_t: Vec<f32> = (0..half).map(|p| (0.2 + p as f32 * 0.1).sin()).collect();
        let mkw = |rows: usize, bpr: usize, seed: usize| {
            let mut w: Vec<u8> = Vec::new();
            for r in 0..rows {
                for b in 0..bpr {
                    let s = 0.05 + ((r * bpr + b + seed) as f32 % 7.0) * 0.01;
                    w.extend_from_slice(&s.to_le_bytes());
                    for l in 0..32 {
                        w.push((((r * 5 + b * 3 + l + seed) as i32 % 17) - 8) as i8 as u8);
                    }
                }
            }
            w
        };
        let q_w = mkw(q_dim, bpr_hidden, 1);
        let k_w = mkw(kv_dim, bpr_hidden, 2);
        let v_w = mkw(kv_dim, bpr_hidden, 3);
        let o_w = mkw(hidden, bpr_q, 4);
        let cache_k: Vec<f32> = (0..kv_dim * position_count)
            .map(|i| ((i as f32 % 13.0) - 6.0) * 0.1)
            .collect();
        let cache_v: Vec<f32> = (0..kv_dim * position_count)
            .map(|i| ((i as f32 % 7.0) - 3.0) * 0.15)
            .collect();

        // Reference: standalone (CPU-verified) kernels in sequence.
        let norm = try_rms_norm_f32(&input, &attn_norm, eps).unwrap();
        let (sn, qn) = try_quantize_q8_0_f32(&norm).unwrap();
        let mut query = vec![0.0f32; q_dim];
        assert!(try_q8_0_block_linear_row(
            &sn, &qn, &q_w, q_dim, bpr_hidden, &mut query
        ));
        let mut key = vec![0.0f32; kv_dim];
        assert!(try_q8_0_block_linear_row(
            &sn, &qn, &k_w, kv_dim, bpr_hidden, &mut key
        ));
        let mut val = vec![0.0f32; kv_dim];
        assert!(try_q8_0_block_linear_row(
            &sn, &qn, &v_w, kv_dim, bpr_hidden, &mut val
        ));
        let query_r =
            try_rope_rotate_f32(&query, &cos_t, &sin_t, n_heads, head_dim, half, false).unwrap();
        let key_r = try_rope_rotate_f32(&key, &cos_t, &sin_t, n_kv, head_dim, half, false).unwrap();
        let mut ref_k = cache_k.clone();
        let mut ref_v = cache_v.clone();
        for h in 0..n_kv {
            let dst = (h * position_count + pos) * head_dim;
            ref_k[dst..dst + head_dim].copy_from_slice(&key_r[h * head_dim..(h + 1) * head_dim]);
            ref_v[dst..dst + head_dim].copy_from_slice(&val[h * head_dim..(h + 1) * head_dim]);
        }
        let ctx = try_attention_decode_f32(
            &query_r,
            &ref_k,
            &ref_v,
            n_heads,
            n_kv,
            head_dim,
            position_count,
            scale,
        )
        .unwrap();
        let (sc, qc) = try_quantize_q8_0_f32(&ctx).unwrap();
        let mut o = vec![0.0f32; hidden];
        assert!(try_q8_0_block_linear_row(
            &sc, &qc, &o_w, hidden, bpr_q, &mut o
        ));
        let expected = try_residual_add_f32(&input, &o).unwrap();

        let got = try_attention_block_resident(
            &input,
            &attn_norm,
            eps,
            &q_w,
            &k_w,
            &v_w,
            &o_w,
            &cos_t,
            &sin_t,
            &cache_k,
            &cache_v,
            n_heads,
            n_kv,
            head_dim,
            position_count,
            scale,
            false,
        )
        .unwrap();
        for (a, b) in got.iter().zip(&expected) {
            assert!((a - b).abs() < 1.0e-3, "{a} != {b}");
        }
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn metal_ffn_block_resident_matches_standalone() {
        if !detect_metal_device().available {
            return;
        }
        let hidden = 64usize;
        let ffn = 128usize;
        let eps = 1.0e-5f32;
        let bpr_hidden = hidden / 32;
        let bpr_ffn = ffn / 32;
        let input: Vec<f32> = (0..hidden)
            .map(|i| ((i as f32 % 11.0) - 5.0) * 0.2)
            .collect();
        let ffn_norm: Vec<f32> = (0..hidden).map(|i| 0.5 + (i as f32 % 3.0) * 0.1).collect();
        let mkw = |rows: usize, bpr: usize, seed: usize| {
            let mut w: Vec<u8> = Vec::new();
            for r in 0..rows {
                for b in 0..bpr {
                    let scale = 0.05 + ((r * bpr + b + seed) as f32 % 7.0) * 0.01;
                    w.extend_from_slice(&scale.to_le_bytes());
                    for l in 0..32 {
                        w.push((((r * 5 + b * 3 + l + seed) as i32 % 17) - 8) as i8 as u8);
                    }
                }
            }
            w
        };
        let gate_w = mkw(ffn, bpr_hidden, 1);
        let up_w = mkw(ffn, bpr_hidden, 2);
        let down_w = mkw(hidden, bpr_ffn, 3);

        // Reference: the standalone (CPU-verified) kernels run in sequence.
        let norm = try_rms_norm_f32(&input, &ffn_norm, eps).unwrap();
        let (s1, q1) = try_quantize_q8_0_f32(&norm).unwrap();
        let mut gate = vec![0.0f32; ffn];
        assert!(try_q8_0_block_linear_row(
            &s1, &q1, &gate_w, ffn, bpr_hidden, &mut gate
        ));
        let mut up = vec![0.0f32; ffn];
        assert!(try_q8_0_block_linear_row(
            &s1, &q1, &up_w, ffn, bpr_hidden, &mut up
        ));
        let act = try_silu_mul_f32(&gate, &up).unwrap();
        let (s2, q2) = try_quantize_q8_0_f32(&act).unwrap();
        let mut down = vec![0.0f32; hidden];
        assert!(try_q8_0_block_linear_row(
            &s2, &q2, &down_w, hidden, bpr_ffn, &mut down
        ));
        let expected = try_residual_add_f32(&input, &down).unwrap();

        let got =
            try_ffn_block_resident(&input, &ffn_norm, eps, &gate_w, &up_w, &down_w, ffn).unwrap();
        for (a, b) in got.iter().zip(&expected) {
            assert!((a - b).abs() < 1.0e-3, "{a} != {b}");
        }
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn metal_decode_layer_resident_matches_blocks() {
        if !detect_metal_device().available {
            return;
        }
        // The fused decode layer (attention block + FFN block in ONE command buffer, with the
        // attention output staying GPU-resident and feeding the FFN block) must equal running
        // the two standalone resident blocks separately. Same kernels + same inputs, so this
        // should be bit-identical; it guards the cross-block buffer handoff and lifetimes.
        let n_heads = 2usize;
        let n_kv = 2usize;
        let head_dim = 32usize;
        let hidden = 64usize;
        let ffn = 128usize;
        let position_count = 3usize;
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv * head_dim;
        let half = head_dim / 2;
        let eps = 1.0e-5f32;
        let scale = 1.0 / (head_dim as f32).sqrt();
        let bpr_hidden = hidden / 32;
        let bpr_q = q_dim / 32;
        let bpr_ffn = ffn / 32;
        let input: Vec<f32> = (0..hidden)
            .map(|i| ((i as f32 % 11.0) - 5.0) * 0.2)
            .collect();
        let attn_norm: Vec<f32> = (0..hidden).map(|i| 0.5 + (i as f32 % 3.0) * 0.1).collect();
        let ffn_norm: Vec<f32> = (0..hidden).map(|i| 0.4 + (i as f32 % 5.0) * 0.07).collect();
        let cos_t: Vec<f32> = (0..half).map(|p| (0.2 + p as f32 * 0.1).cos()).collect();
        let sin_t: Vec<f32> = (0..half).map(|p| (0.2 + p as f32 * 0.1).sin()).collect();
        let mkw = |rows: usize, bpr: usize, seed: usize| {
            let mut w: Vec<u8> = Vec::new();
            for r in 0..rows {
                for b in 0..bpr {
                    let s = 0.05 + ((r * bpr + b + seed) as f32 % 7.0) * 0.01;
                    w.extend_from_slice(&s.to_le_bytes());
                    for l in 0..32 {
                        w.push((((r * 5 + b * 3 + l + seed) as i32 % 17) - 8) as i8 as u8);
                    }
                }
            }
            w
        };
        let q_w = mkw(q_dim, bpr_hidden, 1);
        let k_w = mkw(kv_dim, bpr_hidden, 2);
        let v_w = mkw(kv_dim, bpr_hidden, 3);
        let o_w = mkw(hidden, bpr_q, 4);
        let gate_w = mkw(ffn, bpr_hidden, 5);
        let up_w = mkw(ffn, bpr_hidden, 6);
        let down_w = mkw(hidden, bpr_ffn, 7);
        let cache_k: Vec<f32> = (0..kv_dim * position_count)
            .map(|i| ((i as f32 % 13.0) - 6.0) * 0.1)
            .collect();
        let cache_v: Vec<f32> = (0..kv_dim * position_count)
            .map(|i| ((i as f32 % 7.0) - 3.0) * 0.15)
            .collect();

        // Reference: the two standalone resident blocks run separately, attention -> FFN.
        let attn_out = try_attention_block_resident(
            &input,
            &attn_norm,
            eps,
            &q_w,
            &k_w,
            &v_w,
            &o_w,
            &cos_t,
            &sin_t,
            &cache_k,
            &cache_v,
            n_heads,
            n_kv,
            head_dim,
            position_count,
            scale,
            false,
        )
        .unwrap();
        let expected =
            try_ffn_block_resident(&attn_out, &ffn_norm, eps, &gate_w, &up_w, &down_w, ffn)
                .unwrap();

        let got = try_decode_layer_resident(
            &input,
            &attn_norm,
            &ffn_norm,
            eps,
            &q_w,
            &k_w,
            &v_w,
            &o_w,
            &gate_w,
            &up_w,
            &down_w,
            &cos_t,
            &sin_t,
            &cache_k,
            &cache_v,
            n_heads,
            n_kv,
            head_dim,
            position_count,
            ffn,
            scale,
            false,
        )
        .unwrap();
        assert_eq!(got.len(), hidden);
        for (a, b) in got.iter().zip(&expected) {
            assert!((a - b).abs() < 1.0e-4, "{a} != {b}");
        }
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn metal_decode_forward_resident_matches_per_layer() {
        if !detect_metal_device().available {
            return;
        }
        // Running all layers in ONE command buffer must equal feeding each layer's output
        // into the next via the single-layer fused path. Same kernels + inputs, so it should
        // be bit-identical; this guards the cross-LAYER ping-pong buffering and the
        // single-commit lifetime over many encoders.
        let n_heads = 2usize;
        let n_kv = 2usize;
        let head_dim = 32usize;
        let hidden = 64usize;
        let ffn = 128usize;
        let position_count = 3usize;
        let n_layers = 3usize;
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv * head_dim;
        let half = head_dim / 2;
        let eps = 1.0e-5f32;
        let scale = 1.0 / (head_dim as f32).sqrt();
        let bpr_hidden = hidden / 32;
        let bpr_q = q_dim / 32;
        let bpr_ffn = ffn / 32;
        let embedding: Vec<f32> = (0..hidden)
            .map(|i| ((i as f32 % 11.0) - 5.0) * 0.2)
            .collect();
        let cos_t: Vec<f32> = (0..half).map(|p| (0.2 + p as f32 * 0.1).cos()).collect();
        let sin_t: Vec<f32> = (0..half).map(|p| (0.2 + p as f32 * 0.1).sin()).collect();
        let mkw = |rows: usize, bpr: usize, seed: usize| {
            let mut w: Vec<u8> = Vec::new();
            for r in 0..rows {
                for b in 0..bpr {
                    let s = 0.05 + ((r * bpr + b + seed) as f32 % 7.0) * 0.01;
                    w.extend_from_slice(&s.to_le_bytes());
                    for l in 0..32 {
                        w.push((((r * 5 + b * 3 + l + seed) as i32 % 17) - 8) as i8 as u8);
                    }
                }
            }
            w
        };

        struct LayerData {
            attn_norm: Vec<f32>,
            ffn_norm: Vec<f32>,
            q: Vec<u8>,
            k: Vec<u8>,
            v: Vec<u8>,
            o: Vec<u8>,
            gate: Vec<u8>,
            up: Vec<u8>,
            down: Vec<u8>,
            cache_k: Vec<f32>,
            cache_v: Vec<f32>,
        }
        // Seeds vary by layer so each layer has distinct weights/norms/cache.
        let data: Vec<LayerData> = (0..n_layers)
            .map(|li| {
                let s = li * 100;
                LayerData {
                    attn_norm: (0..hidden)
                        .map(|i| 0.5 + ((i + li) as f32 % 3.0) * 0.1)
                        .collect(),
                    ffn_norm: (0..hidden)
                        .map(|i| 0.4 + ((i + li) as f32 % 5.0) * 0.07)
                        .collect(),
                    q: mkw(q_dim, bpr_hidden, s + 1),
                    k: mkw(kv_dim, bpr_hidden, s + 2),
                    v: mkw(kv_dim, bpr_hidden, s + 3),
                    o: mkw(hidden, bpr_q, s + 4),
                    gate: mkw(ffn, bpr_hidden, s + 5),
                    up: mkw(ffn, bpr_hidden, s + 6),
                    down: mkw(hidden, bpr_ffn, s + 7),
                    cache_k: (0..kv_dim * position_count)
                        .map(|i| (((i + li) as f32 % 13.0) - 6.0) * 0.1)
                        .collect(),
                    cache_v: (0..kv_dim * position_count)
                        .map(|i| (((i + li) as f32 % 7.0) - 3.0) * 0.15)
                        .collect(),
                }
            })
            .collect();

        // Reference: loop the single-layer fused path, feeding each output into the next.
        let mut hidden_state = embedding.clone();
        for d in &data {
            hidden_state = try_decode_layer_resident(
                &hidden_state,
                &d.attn_norm,
                &d.ffn_norm,
                eps,
                &d.q,
                &d.k,
                &d.v,
                &d.o,
                &d.gate,
                &d.up,
                &d.down,
                &cos_t,
                &sin_t,
                &d.cache_k,
                &d.cache_v,
                n_heads,
                n_kv,
                head_dim,
                position_count,
                ffn,
                scale,
                false,
            )
            .unwrap();
        }
        let expected = hidden_state;

        let layers: Vec<ResidentDecodeLayer> = data
            .iter()
            .map(|d| ResidentDecodeLayer {
                attn_norm: &d.attn_norm,
                ffn_norm: &d.ffn_norm,
                q_weight_blocks: &d.q,
                k_weight_blocks: &d.k,
                v_weight_blocks: &d.v,
                o_weight_blocks: &d.o,
                gate_weight_blocks: &d.gate,
                up_weight_blocks: &d.up,
                down_weight_blocks: &d.down,
                cache_k: &d.cache_k,
                cache_v: &d.cache_v,
            })
            .collect();
        let got = try_decode_forward_resident(
            &embedding,
            &layers,
            &cos_t,
            &sin_t,
            eps,
            n_heads,
            n_kv,
            head_dim,
            position_count,
            ffn,
            scale,
            false,
        )
        .unwrap();
        assert_eq!(got.len(), hidden);
        for (a, b) in got.iter().zip(&expected) {
            assert!((a - b).abs() < 1.0e-4, "{a} != {b}");
        }

        // Upload-once: after that decode every layer's Q8 weights are resident in the
        // process-global cache (keyed by pointer+len), so subsequent tokens reuse the same
        // on-GPU buffers rather than re-uploading. Checked on this test's own pointers, so
        // it is race-free under parallel test execution.
        {
            let cache = metal_linear_cache().lock().unwrap();
            let resident = |b: &[u8]| {
                cache
                    .q8_block_weight_buffers
                    .contains_key(&(b.as_ptr() as usize, b.len()))
            };
            for d in &data {
                assert!(resident(&d.q) && resident(&d.k) && resident(&d.v) && resident(&d.o));
                assert!(resident(&d.gate) && resident(&d.up) && resident(&d.down));
            }
        }
        // A second decode reusing the same weight slices (now cache hits) must be identical.
        let got2 = try_decode_forward_resident(
            &embedding,
            &layers,
            &cos_t,
            &sin_t,
            eps,
            n_heads,
            n_kv,
            head_dim,
            position_count,
            ffn,
            scale,
            false,
        )
        .unwrap();
        assert_eq!(got, got2);
    }

    /// The three-dispatch decode attention must reproduce the single-kernel one
    /// BIT-FOR-BIT, not approximately. `assert_eq!` on the raw f32s is the whole point:
    /// the split only changes how threads are laid out, so any difference at all means
    /// an accumulation order moved and the pinned gemma3 parity receipts would shift.
    ///
    /// Geometries cover the production gemma3-1b row (4 query heads / 1 KV head /
    /// head_dim 256 — the shape that cannot reach the v2 or split-K kernels), a
    /// windowed read range (non-zero `kv_base_offset` with `position_count` shorter than
    /// the cache), the 1:1 non-GQA case, and a position count that is not a multiple of
    /// the 32-lane stride (so the softmax kernel's ragged tail is exercised).
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_attention_decode_split3_is_bit_identical_to_v1() {
        if !detect_metal_device().available {
            return;
        }
        // (n_heads, n_kv_heads, head_dim, cache_positions, window_start, position_count)
        let cases: [(usize, usize, usize, usize, usize, usize); 6] = [
            (4, 1, 256, 1, 0, 1),
            (4, 1, 256, 37, 0, 37),
            (4, 1, 256, 600, 88, 512),
            (4, 1, 256, 512, 0, 512),
            (2, 2, 64, 100, 0, 100),
            (8, 2, 128, 130, 7, 123),
        ];
        for (n_heads, n_kv, head_dim, cache_positions, window_start, position_count) in cases {
            let q_dim = n_heads * head_dim;
            let query: Vec<f32> = (0..q_dim)
                .map(|i| (((i * 37) % 211) as f32 - 105.0) * 0.017)
                .collect();
            let cache_len = n_kv * cache_positions * head_dim;
            let keys: Vec<f32> = (0..cache_len)
                .map(|i| (((i * 53) % 197) as f32 - 98.0) * 0.011)
                .collect();
            let values: Vec<f32> = (0..cache_len)
                .map(|i| (((i * 71) % 179) as f32 - 89.0) * 0.013)
                .collect();
            let scale = 1.0 / (head_dim as f32).sqrt();
            // Contiguous [kv_head][position][head_dim]: the window shifts the read range
            // by `window_start` positions, exactly as the resident encode does.
            let position_stride = head_dim;
            let kv_head_stride = cache_positions * head_dim;
            let kv_base_offset = window_start * head_dim;
            let single = try_attention_decode_strided_f32(
                &query,
                &keys,
                &values,
                n_heads,
                n_kv,
                head_dim,
                position_count,
                scale,
                position_stride,
                kv_head_stride,
                kv_base_offset,
            )
            .expect("single-kernel attention");
            let split = try_attention_decode_strided_split3_f32(
                &query,
                &keys,
                &values,
                n_heads,
                n_kv,
                head_dim,
                position_count,
                scale,
                position_stride,
                kv_head_stride,
                kv_base_offset,
            )
            .expect("split-3 attention");
            assert_eq!(
                single.len(),
                q_dim,
                "geometry {n_heads}x{n_kv}x{head_dim} pc={position_count}"
            );
            let mismatches = single
                .iter()
                .zip(&split)
                .enumerate()
                .filter(|(_, (a, b))| a.to_bits() != b.to_bits())
                .collect::<Vec<_>>();
            let worst = mismatches
                .iter()
                .map(|(_, (a, b))| (*a - *b).abs())
                .fold(0.0f32, f32::max);
            assert!(
                mismatches.is_empty(),
                "split-3 decode attention diverged from the single-kernel encode at \
                 n_heads={n_heads} n_kv={n_kv} head_dim={head_dim} \
                 position_count={position_count} window_start={window_start}: \
                 {} / {} elements differ, max abs diff {worst:e}, first at index {} \
                 ({} vs {})",
                mismatches.len(),
                single.len(),
                mismatches[0].0,
                mismatches[0].1 .0,
                mismatches[0].1 .1,
            );
        }
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn metal_attention_decode_strided_matches_contiguous() {
        if !detect_metal_device().available {
            return;
        }
        // Reading a per-layer slice of an interleaved [position][layer][kv_head][head_dim]
        // cache via explicit strides must match the contiguous [kv_head][position][head_dim]
        // result for the same logical K/V. Surrounding layers are filled with noise, so a
        // wrong stride or base offset would read the wrong layer and corrupt the output.
        let n_heads = 4usize;
        let n_kv = 2usize;
        let head_dim = 8usize;
        let position_count = 5usize;
        let layer_count = 3usize;
        let target_layer = 1usize;
        let scale = 1.0 / (head_dim as f32).sqrt();
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv * head_dim;

        let query: Vec<f32> = (0..q_dim).map(|i| ((i as f32 % 7.0) - 3.0) * 0.2).collect();
        let logical = |kvh: usize, p: usize, d: usize, base: f32| {
            (((kvh * 131 + p * 17 + d) as f32 % 19.0) - 9.0) * 0.1 + base
        };

        // Contiguous [kv_head][position][head_dim] reference.
        let mut contig_k = vec![0.0f32; kv_dim * position_count];
        let mut contig_v = vec![0.0f32; kv_dim * position_count];
        for kvh in 0..n_kv {
            for p in 0..position_count {
                for d in 0..head_dim {
                    let idx = (kvh * position_count + p) * head_dim + d;
                    contig_k[idx] = logical(kvh, p, d, 0.0);
                    contig_v[idx] = logical(kvh, p, d, 0.5);
                }
            }
        }

        // Interleaved [position][layer][kv_head][head_dim]; only `target_layer` holds the
        // logical values, the other layers hold noise.
        let mut inter_k = vec![0.0f32; position_count * layer_count * kv_dim];
        let mut inter_v = vec![0.0f32; position_count * layer_count * kv_dim];
        for p in 0..position_count {
            for l in 0..layer_count {
                for kvh in 0..n_kv {
                    for d in 0..head_dim {
                        let idx = ((p * layer_count + l) * n_kv + kvh) * head_dim + d;
                        if l == target_layer {
                            inter_k[idx] = logical(kvh, p, d, 0.0);
                            inter_v[idx] = logical(kvh, p, d, 0.5);
                        } else {
                            inter_k[idx] = 7.0 + idx as f32;
                            inter_v[idx] = -3.0 - idx as f32;
                        }
                    }
                }
            }
        }

        let expected = try_attention_decode_f32(
            &query,
            &contig_k,
            &contig_v,
            n_heads,
            n_kv,
            head_dim,
            position_count,
            scale,
        )
        .unwrap();
        let got = try_attention_decode_strided_f32(
            &query,
            &inter_k,
            &inter_v,
            n_heads,
            n_kv,
            head_dim,
            position_count,
            scale,
            layer_count * n_kv * head_dim,  // position_stride
            head_dim,                       // kv_head_stride
            target_layer * n_kv * head_dim, // kv_base_offset
        )
        .unwrap();
        assert_eq!(got.len(), q_dim);
        for (a, b) in got.iter().zip(&expected) {
            assert!((a - b).abs() < 1.0e-5, "{a} != {b}");
        }
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn metal_resident_decode_state_matches_full_upload() {
        if !detect_metal_device().available {
            return;
        }
        // The persistent on-GPU KV session (append one slot per token, never re-upload) must,
        // at each token, equal the full-upload try_decode_forward_resident fed the same
        // accumulated history. Same kernels + inputs => identical; this guards the persistent
        // cache append/stride bookkeeping across many tokens.
        let n_layers = 2usize;
        let n_heads = 2usize;
        let n_kv = 2usize;
        let head_dim = 32usize;
        let hidden = 64usize;
        let ffn = 128usize;
        let max_positions = 8usize;
        let tokens = 4usize;
        let eps = 1.0e-5f32;
        let scale = 1.0 / (head_dim as f32).sqrt();
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv * head_dim;
        let half = head_dim / 2;
        let bpr_hidden = hidden / 32;
        let bpr_q = q_dim / 32;
        let bpr_ffn = ffn / 32;
        let mkw = |rows: usize, bpr: usize, seed: usize| {
            let mut w: Vec<u8> = Vec::new();
            for r in 0..rows {
                for b in 0..bpr {
                    let s = 0.05 + ((r * bpr + b + seed) as f32 % 7.0) * 0.01;
                    w.extend_from_slice(&s.to_le_bytes());
                    for l in 0..32 {
                        w.push((((r * 5 + b * 3 + l + seed) as i32 % 17) - 8) as i8 as u8);
                    }
                }
            }
            w
        };
        struct LW {
            attn_norm: Vec<f32>,
            ffn_norm: Vec<f32>,
            q: Vec<u8>,
            k: Vec<u8>,
            v: Vec<u8>,
            o: Vec<u8>,
            gate: Vec<u8>,
            up: Vec<u8>,
            down: Vec<u8>,
        }
        let data: Vec<LW> = (0..n_layers)
            .map(|li| {
                let s = li * 100;
                LW {
                    attn_norm: (0..hidden)
                        .map(|i| 0.5 + ((i + li) as f32 % 3.0) * 0.1)
                        .collect(),
                    ffn_norm: (0..hidden)
                        .map(|i| 0.4 + ((i + li) as f32 % 5.0) * 0.07)
                        .collect(),
                    q: mkw(q_dim, bpr_hidden, s + 1),
                    k: mkw(kv_dim, bpr_hidden, s + 2),
                    v: mkw(kv_dim, bpr_hidden, s + 3),
                    o: mkw(hidden, bpr_q, s + 4),
                    gate: mkw(ffn, bpr_hidden, s + 5),
                    up: mkw(ffn, bpr_hidden, s + 6),
                    down: mkw(hidden, bpr_ffn, s + 7),
                }
            })
            .collect();
        let weights: Vec<ResidentLayerWeights> = data
            .iter()
            .map(|d| ResidentLayerWeights {
                attn_norm: &d.attn_norm,
                ffn_norm: &d.ffn_norm,
                q_weight_blocks: ResidentWeightBytes::Blocks36(&d.q),
                k_weight_blocks: ResidentWeightBytes::Blocks36(&d.k),
                v_weight_blocks: ResidentWeightBytes::Blocks36(&d.v),
                o_weight_blocks: ResidentWeightBytes::Blocks36(&d.o),
                gate_weight_blocks: ResidentWeightBytes::Blocks36(&d.gate),
                up_weight_blocks: ResidentWeightBytes::Blocks36(&d.up),
                down_weight_blocks: ResidentWeightBytes::Blocks36(&d.down),
                q_norm: None,
                k_norm: None,
                post_attn_norm: None,
                post_ffw_norm: None,
                ffn_geglu: false,
            })
            .collect();

        let mut session = ResidentDecodeState::new(
            n_layers,
            n_heads,
            n_kv,
            head_dim,
            hidden,
            ffn,
            // Tiny initial capacity with a larger cap so the multi-token loop exercises the
            // on-demand growth (GPU->GPU blit of materialized slots) as well as appends.
            2,
            max_positions,
            eps,
            false,
            None,
        )
        .unwrap();

        for t in 0..tokens {
            let emb: Vec<f32> = (0..hidden)
                .map(|i| (((i + t) as f32 % 11.0) - 5.0) * 0.2)
                .collect();
            let cos_t: Vec<f32> = (0..half)
                .map(|p| (0.2 + (p + t) as f32 * 0.1).cos())
                .collect();
            let sin_t: Vec<f32> = (0..half)
                .map(|p| (0.2 + (p + t) as f32 * 0.1).sin())
                .collect();
            let position_count = t + 1;

            // Reference history = the session's accumulated slots 0..t-1, re-laid into a
            // [kv_head][position_count][head_dim] buffer with slot t left for the kernel.
            let ref_caches: Vec<(Vec<f32>, Vec<f32>)> = (0..n_layers)
                .map(|layer| {
                    let hist_k = session.cache_k_contiguous(layer, t);
                    let hist_v = session.cache_v_contiguous(layer, t);
                    let mut ck = vec![0.0f32; kv_dim * position_count];
                    let mut cv = vec![0.0f32; kv_dim * position_count];
                    for h in 0..n_kv {
                        for p in 0..t {
                            let src = (h * t + p) * head_dim;
                            let dst = (h * position_count + p) * head_dim;
                            ck[dst..dst + head_dim].copy_from_slice(&hist_k[src..src + head_dim]);
                            cv[dst..dst + head_dim].copy_from_slice(&hist_v[src..src + head_dim]);
                        }
                    }
                    (ck, cv)
                })
                .collect();
            let ref_layers: Vec<ResidentDecodeLayer> = data
                .iter()
                .zip(&ref_caches)
                .map(|(d, (ck, cv))| ResidentDecodeLayer {
                    attn_norm: &d.attn_norm,
                    ffn_norm: &d.ffn_norm,
                    q_weight_blocks: &d.q,
                    k_weight_blocks: &d.k,
                    v_weight_blocks: &d.v,
                    o_weight_blocks: &d.o,
                    gate_weight_blocks: &d.gate,
                    up_weight_blocks: &d.up,
                    down_weight_blocks: &d.down,
                    cache_k: ck,
                    cache_v: cv,
                })
                .collect();
            let expected = try_decode_forward_resident(
                &emb,
                &ref_layers,
                &cos_t,
                &sin_t,
                eps,
                n_heads,
                n_kv,
                head_dim,
                position_count,
                ffn,
                scale,
                false,
            )
            .unwrap();

            let got = match session
                .forward_token(
                    &emb, &weights, &cos_t, &sin_t, None, t, scale, None, None, 0, None, None,
                )
                .unwrap()
            {
                ResidentTokenOut::Data(v) => v,
                ResidentTokenOut::Sampled(_) => panic!("unexpected sampled output"),
            };
            assert_eq!(got.len(), hidden);
            for (a, b) in got.iter().zip(&expected) {
                assert!((a - b).abs() < 1.0e-4, "token {t}: {a} != {b}");
            }
        }
    }

    // -----------------------------------------------------------------------
    // gemma3→Metal Phase 2 self-parity scaffolding: a pure-CPU emulation of the
    // resident decode op chain on its NON-f32y path (rms_norm → Q8_0 activation
    // quantize → integer-dot GEMV → …). The activation quantization uses the
    // same per-block formula as the GPU quantize kernels
    // (`crate::inference::quantize_q8_0_blocks`), so the remaining CPU/GPU
    // delta is f32 reduction order only. Weights are the 36-byte CPU Q8_0
    // blocks the sibling tests build with `mkw`-style generators. Tests using
    // this reference SKIP when the f32y GEMV OnceLock latched on earlier in the
    // process (the reference mirrors the quantize path).
    #[cfg(target_os = "macos")]
    fn cpu_ref_q8_matvec(x: &[f32], w36: &[u8], rows: usize) -> Vec<f32> {
        use crate::inference::quantize_q8_0_blocks;
        let bpr = x.len() / 32;
        assert_eq!(w36.len(), rows * bpr * 36, "weight byte length");
        let xq = quantize_q8_0_blocks(x);
        (0..rows)
            .map(|r| {
                let mut acc = 0.0f32;
                for (b, xb) in xq.iter().enumerate() {
                    let base = (r * bpr + b) * 36;
                    let ws = f32::from_le_bytes(w36[base..base + 4].try_into().unwrap());
                    let mut int = 0i32;
                    for (l, &qv) in xb.quants.iter().enumerate() {
                        int += w36[base + 4 + l] as i8 as i32 * qv as i32;
                    }
                    acc += ws * xb.scale * int as f32;
                }
                acc
            })
            .collect()
    }

    /// RMSNorm — same formula as the GPU kernel and the runnable reference.
    #[cfg(target_os = "macos")]
    fn cpu_ref_rms_norm(x: &[f32], w: &[f32], eps: f32) -> Vec<f32> {
        let ss: f32 = x.iter().map(|v| v * v).sum();
        let inv = 1.0 / (ss / x.len() as f32 + eps).sqrt();
        x.iter().zip(w).map(|(v, wv)| v * inv * wv).collect()
    }

    /// Per-head RMSNorm over contiguous `head_dim` slices (QK-norm), in place.
    #[cfg(target_os = "macos")]
    fn cpu_ref_rms_norm_per_head(
        vec: &mut [f32],
        n_heads: usize,
        head_dim: usize,
        w: &[f32],
        eps: f32,
    ) {
        for h in 0..n_heads {
            let s = &mut vec[h * head_dim..(h + 1) * head_dim];
            let ss: f32 = s.iter().map(|v| v * v).sum();
            let inv = 1.0 / (ss / head_dim as f32 + eps).sqrt();
            for (x, wv) in s.iter_mut().zip(w) {
                *x = *x * inv * *wv;
            }
        }
    }

    /// Split-half (NEOX) RoPE in place — pair `(i, i + half)` per head.
    #[cfg(target_os = "macos")]
    fn cpu_ref_rope_split_half(
        vec: &mut [f32],
        n_heads: usize,
        head_dim: usize,
        cos_t: &[f32],
        sin_t: &[f32],
    ) {
        let half = cos_t.len();
        for h in 0..n_heads {
            let base = h * head_dim;
            for i in 0..half {
                let (a, b) = (base + i, base + i + half);
                let (x0, x1) = (vec[a], vec[b]);
                vec[a] = x0 * cos_t[i] - x1 * sin_t[i];
                vec[b] = x0 * sin_t[i] + x1 * cos_t[i];
            }
        }
    }

    /// Softmax attention for ONE query row over a `[kv_head][total][head_dim]`
    /// cache, restricted to the contiguous position range `[lo, lo + count)`.
    #[cfg(target_os = "macos")]
    #[allow(clippy::too_many_arguments)]
    fn cpu_ref_attention(
        query: &[f32],
        keys: &[f32],
        values: &[f32],
        n_heads: usize,
        n_kv_heads: usize,
        head_dim: usize,
        total: usize,
        lo: usize,
        count: usize,
        scale: f32,
    ) -> Vec<f32> {
        let group = n_heads / n_kv_heads;
        let kv_head_stride = total * head_dim;
        let mut out = vec![0.0f32; n_heads * head_dim];
        for h in 0..n_heads {
            let kvh = h / group;
            let q = &query[h * head_dim..(h + 1) * head_dim];
            let mut scores = vec![0.0f32; count];
            let mut m = f32::NEG_INFINITY;
            for (i, s) in scores.iter_mut().enumerate() {
                let p = lo + i;
                let krow = &keys[kvh * kv_head_stride + p * head_dim..][..head_dim];
                *s = scale * q.iter().zip(krow).map(|(a, b)| a * b).sum::<f32>();
                m = m.max(*s);
            }
            let mut den = 0.0f32;
            for s in &mut scores {
                *s = (*s - m).exp();
                den += *s;
            }
            let o = &mut out[h * head_dim..(h + 1) * head_dim];
            for (i, &sc) in scores.iter().enumerate() {
                let p = lo + i;
                let vrow = &values[kvh * kv_head_stride + p * head_dim..][..head_dim];
                let w = sc / den;
                for d in 0..head_dim {
                    o[d] += w * vrow[d];
                }
            }
        }
        out
    }

    /// 36-byte Q8_0 CPU-block weight generator shared by the Phase 2 tests
    /// (same value pattern as the sibling `mkw` closures).
    #[cfg(target_os = "macos")]
    fn mk_w36(rows: usize, bpr: usize, seed: usize) -> Vec<u8> {
        let mut w: Vec<u8> = Vec::with_capacity(rows * bpr * 36);
        for r in 0..rows {
            for b in 0..bpr {
                let s = 0.05 + ((r * bpr + b + seed) as f32 % 7.0) * 0.01;
                w.extend_from_slice(&s.to_le_bytes());
                for l in 0..32 {
                    w.push((((r * 5 + b * 3 + l + seed) as i32 % 17) - 8) as i8 as u8);
                }
            }
        }
        w
    }

    // gemma3→Metal Phase 2a: the generic resident decode applies per-head
    // QK-norm at the gemma3-1B geometry (hidden 1152, 4 Q heads / 1 KV head,
    // head_dim 256, split-half RoPE pairing) — the qwen3 wiring (d56f7da2)
    // admits the gemma3 shape unchanged. Pure-CPU independent reference over 3
    // tokens (so the KV cache carries real history), plus a non-vacuity guard:
    // dropping the QK-norm weights must change the output materially.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_resident_gemma3_qk_norm_decode_selfparity() {
        if !detect_metal_device().available {
            return;
        }
        if f32y_gemv_enabled() {
            eprintln!(
                "SKIP metal_resident_gemma3_qk_norm_decode_selfparity: CAMELID_METAL_F32Y \
                 latched on earlier in this process; the CPU reference mirrors the quantize path"
            );
            return;
        }
        let n_layers = 2usize;
        let n_heads = 4usize;
        let n_kv = 1usize;
        let head_dim = 256usize;
        let hidden = 1152usize;
        let ffn = 288usize;
        let tokens = 3usize;
        let eps = 1.0e-6f32;
        let scale = 1.0 / (head_dim as f32).sqrt();
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv * head_dim;
        let half = head_dim / 2;
        let bpr_hidden = hidden / 32;
        let bpr_q = q_dim / 32;
        let bpr_ffn = ffn / 32;

        struct LW {
            attn_norm: Vec<f32>,
            ffn_norm: Vec<f32>,
            q_norm: Vec<f32>,
            k_norm: Vec<f32>,
            q: Vec<u8>,
            k: Vec<u8>,
            v: Vec<u8>,
            o: Vec<u8>,
            gate: Vec<u8>,
            up: Vec<u8>,
            down: Vec<u8>,
        }
        let data: Vec<LW> = (0..n_layers)
            .map(|li| {
                let s = li * 100;
                LW {
                    attn_norm: (0..hidden)
                        .map(|i| 0.5 + ((i + li) as f32 % 3.0) * 0.1)
                        .collect(),
                    ffn_norm: (0..hidden)
                        .map(|i| 0.4 + ((i + li) as f32 % 5.0) * 0.07)
                        .collect(),
                    q_norm: (0..head_dim)
                        .map(|i| 0.7 + ((i + li) as f32 % 11.0) * 0.02)
                        .collect(),
                    k_norm: (0..head_dim)
                        .map(|i| 0.6 + ((i + li) as f32 % 7.0) * 0.03)
                        .collect(),
                    q: mk_w36(q_dim, bpr_hidden, s + 1),
                    k: mk_w36(kv_dim, bpr_hidden, s + 2),
                    v: mk_w36(kv_dim, bpr_hidden, s + 3),
                    o: mk_w36(hidden, bpr_q, s + 4),
                    gate: mk_w36(ffn, bpr_hidden, s + 5),
                    up: mk_w36(ffn, bpr_hidden, s + 6),
                    down: mk_w36(hidden, bpr_ffn, s + 7),
                }
            })
            .collect();
        let mk_views = |with_qk_norm: bool| -> Vec<ResidentLayerWeights<'_>> {
            data.iter()
                .map(|d| ResidentLayerWeights {
                    attn_norm: &d.attn_norm,
                    ffn_norm: &d.ffn_norm,
                    q_norm: with_qk_norm.then_some(d.q_norm.as_slice()),
                    k_norm: with_qk_norm.then_some(d.k_norm.as_slice()),
                    post_attn_norm: None,
                    post_ffw_norm: None,
                    ffn_geglu: false,
                    q_weight_blocks: ResidentWeightBytes::Blocks36(&d.q),
                    k_weight_blocks: ResidentWeightBytes::Blocks36(&d.k),
                    v_weight_blocks: ResidentWeightBytes::Blocks36(&d.v),
                    o_weight_blocks: ResidentWeightBytes::Blocks36(&d.o),
                    gate_weight_blocks: ResidentWeightBytes::Blocks36(&d.gate),
                    up_weight_blocks: ResidentWeightBytes::Blocks36(&d.up),
                    down_weight_blocks: ResidentWeightBytes::Blocks36(&d.down),
                })
                .collect()
        };
        let weights = mk_views(true);
        let weights_no_norm = mk_views(false);

        let mut session = ResidentDecodeState::new(
            n_layers, n_heads, n_kv, head_dim, hidden, ffn, tokens, tokens, eps,
            true, // gemma3 forces split-half (NEOX) pairing host-side
            None,
        )
        .unwrap();
        let mut session_no_norm = ResidentDecodeState::new(
            n_layers, n_heads, n_kv, head_dim, hidden, ffn, tokens, tokens, eps, true, None,
        )
        .unwrap();

        // Reference caches: per layer, [kv_head=1][pos][head_dim] grown per token.
        let mut ref_k: Vec<Vec<f32>> = vec![Vec::new(); n_layers];
        let mut ref_v: Vec<Vec<f32>> = vec![Vec::new(); n_layers];

        for t in 0..tokens {
            let emb: Vec<f32> = (0..hidden)
                .map(|i| (((i + t) as f32 % 11.0) - 5.0) * 0.2)
                .collect();
            let cos_t: Vec<f32> = (0..half)
                .map(|p| (0.2 + (p + t) as f32 * 0.1).cos())
                .collect();
            let sin_t: Vec<f32> = (0..half)
                .map(|p| (0.2 + (p + t) as f32 * 0.1).sin())
                .collect();

            // CPU reference token step.
            let mut x = emb.clone();
            for (li, d) in data.iter().enumerate() {
                let xn = cpu_ref_rms_norm(&x, &d.attn_norm, eps);
                let mut q = cpu_ref_q8_matvec(&xn, &d.q, q_dim);
                let mut kx = cpu_ref_q8_matvec(&xn, &d.k, kv_dim);
                let v = cpu_ref_q8_matvec(&xn, &d.v, kv_dim);
                cpu_ref_rms_norm_per_head(&mut q, n_heads, head_dim, &d.q_norm, eps);
                cpu_ref_rms_norm_per_head(&mut kx, n_kv, head_dim, &d.k_norm, eps);
                cpu_ref_rope_split_half(&mut q, n_heads, head_dim, &cos_t, &sin_t);
                cpu_ref_rope_split_half(&mut kx, n_kv, head_dim, &cos_t, &sin_t);
                ref_k[li].extend_from_slice(&kx);
                ref_v[li].extend_from_slice(&v);
                let ctx = cpu_ref_attention(
                    &q,
                    &ref_k[li],
                    &ref_v[li],
                    n_heads,
                    n_kv,
                    head_dim,
                    t + 1,
                    0,
                    t + 1,
                    scale,
                );
                let o = cpu_ref_q8_matvec(&ctx, &d.o, hidden);
                for (h, ov) in x.iter_mut().zip(&o) {
                    *h += *ov;
                }
                let xn2 = cpu_ref_rms_norm(&x, &d.ffn_norm, eps);
                let g = cpu_ref_q8_matvec(&xn2, &d.gate, ffn);
                let u = cpu_ref_q8_matvec(&xn2, &d.up, ffn);
                let act: Vec<f32> = g
                    .iter()
                    .zip(&u)
                    .map(|(gv, uv)| (gv / (1.0 + (-gv).exp())) * uv)
                    .collect();
                let dn = cpu_ref_q8_matvec(&act, &d.down, hidden);
                for (h, dv) in x.iter_mut().zip(&dn) {
                    *h += *dv;
                }
            }

            let got = match session
                .forward_token(
                    &emb, &weights, &cos_t, &sin_t, None, t, scale, None, None, 0, None, None,
                )
                .unwrap()
            {
                ResidentTokenOut::Data(v) => v,
                ResidentTokenOut::Sampled(_) => panic!("unexpected sampled output"),
            };
            assert_eq!(got.len(), hidden);
            let mut max_diff = 0.0f32;
            for (a, b) in got.iter().zip(&x) {
                max_diff = max_diff.max((a - b).abs());
                assert!((a - b).abs() < 3.0e-3, "token {t}: {a} != {b}");
            }
            eprintln!("[2a-selfparity] token {t}: max |gpu-cpu| = {max_diff:.2e}");

            // Non-vacuity: the same decode WITHOUT QK-norm must differ materially,
            // proving the norm actually engaged on the GPU path.
            let got_no_norm = match session_no_norm
                .forward_token(
                    &emb,
                    &weights_no_norm,
                    &cos_t,
                    &sin_t,
                    None,
                    t,
                    scale,
                    None,
                    None,
                    0,
                    None,
                    None,
                )
                .unwrap()
            {
                ResidentTokenOut::Data(v) => v,
                ResidentTokenOut::Sampled(_) => panic!("unexpected sampled output"),
            };
            let delta = got
                .iter()
                .zip(&got_no_norm)
                .map(|(a, b)| (a - b).abs())
                .fold(0.0f32, f32::max);
            // At t=0 the softmax runs over a single position, so QK-norm cannot
            // affect the output (scores are irrelevant); from t>=1 it must.
            if t >= 1 {
                assert!(
                    delta > 0.05,
                    "token {t}: QK-norm had no material effect (max delta {delta}); the \
                     wiring is not engaging"
                );
            }
        }
    }

    // gemma3→Metal Phase 2b: the resident decode applies the gemma3 sandwich
    // norms — RMSNorm on the attention output BEFORE its residual add
    // (post_attention_norm) and on the FFN output BEFORE its residual add
    // (post_ffw_norm), reference src/runnable/model.rs:851-853/:875-877 — at
    // the gemma3-1B geometry, alongside the QK-norm. Pure-CPU independent
    // reference over 3 tokens, plus a non-vacuity guard (dropping the sandwich
    // norms must change the output at every token, including t=0: the
    // post-attention norm rescales the value path itself).
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_resident_gemma3_sandwich_norms_decode_selfparity() {
        if !detect_metal_device().available {
            return;
        }
        if f32y_gemv_enabled() {
            eprintln!(
                "SKIP metal_resident_gemma3_sandwich_norms_decode_selfparity: \
                 CAMELID_METAL_F32Y latched on earlier in this process; the CPU reference \
                 mirrors the quantize path"
            );
            return;
        }
        let n_layers = 2usize;
        let n_heads = 4usize;
        let n_kv = 1usize;
        let head_dim = 256usize;
        let hidden = 1152usize;
        let ffn = 288usize;
        let tokens = 3usize;
        let eps = 1.0e-6f32;
        let scale = 1.0 / (head_dim as f32).sqrt();
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv * head_dim;
        let half = head_dim / 2;
        let bpr_hidden = hidden / 32;
        let bpr_q = q_dim / 32;
        let bpr_ffn = ffn / 32;

        struct LW {
            attn_norm: Vec<f32>,
            ffn_norm: Vec<f32>,
            q_norm: Vec<f32>,
            k_norm: Vec<f32>,
            post_attn_norm: Vec<f32>,
            post_ffw_norm: Vec<f32>,
            q: Vec<u8>,
            k: Vec<u8>,
            v: Vec<u8>,
            o: Vec<u8>,
            gate: Vec<u8>,
            up: Vec<u8>,
            down: Vec<u8>,
        }
        let data: Vec<LW> = (0..n_layers)
            .map(|li| {
                let s = li * 100;
                LW {
                    attn_norm: (0..hidden)
                        .map(|i| 0.5 + ((i + li) as f32 % 3.0) * 0.1)
                        .collect(),
                    ffn_norm: (0..hidden)
                        .map(|i| 0.4 + ((i + li) as f32 % 5.0) * 0.07)
                        .collect(),
                    q_norm: (0..head_dim)
                        .map(|i| 0.7 + ((i + li) as f32 % 11.0) * 0.02)
                        .collect(),
                    k_norm: (0..head_dim)
                        .map(|i| 0.6 + ((i + li) as f32 % 7.0) * 0.03)
                        .collect(),
                    post_attn_norm: (0..hidden)
                        .map(|i| 0.9 + ((i + li) as f32 % 3.0) * 0.03)
                        .collect(),
                    post_ffw_norm: (0..hidden)
                        .map(|i| 0.95 + ((i + li) as f32 % 6.0) * 0.02)
                        .collect(),
                    q: mk_w36(q_dim, bpr_hidden, s + 1),
                    k: mk_w36(kv_dim, bpr_hidden, s + 2),
                    v: mk_w36(kv_dim, bpr_hidden, s + 3),
                    o: mk_w36(hidden, bpr_q, s + 4),
                    gate: mk_w36(ffn, bpr_hidden, s + 5),
                    up: mk_w36(ffn, bpr_hidden, s + 6),
                    down: mk_w36(hidden, bpr_ffn, s + 7),
                }
            })
            .collect();
        let mk_views = |with_post_norms: bool| -> Vec<ResidentLayerWeights<'_>> {
            data.iter()
                .map(|d| ResidentLayerWeights {
                    attn_norm: &d.attn_norm,
                    ffn_norm: &d.ffn_norm,
                    q_norm: Some(&d.q_norm),
                    k_norm: Some(&d.k_norm),
                    post_attn_norm: with_post_norms.then_some(d.post_attn_norm.as_slice()),
                    post_ffw_norm: with_post_norms.then_some(d.post_ffw_norm.as_slice()),
                    ffn_geglu: false,
                    q_weight_blocks: ResidentWeightBytes::Blocks36(&d.q),
                    k_weight_blocks: ResidentWeightBytes::Blocks36(&d.k),
                    v_weight_blocks: ResidentWeightBytes::Blocks36(&d.v),
                    o_weight_blocks: ResidentWeightBytes::Blocks36(&d.o),
                    gate_weight_blocks: ResidentWeightBytes::Blocks36(&d.gate),
                    up_weight_blocks: ResidentWeightBytes::Blocks36(&d.up),
                    down_weight_blocks: ResidentWeightBytes::Blocks36(&d.down),
                })
                .collect()
        };
        let weights = mk_views(true);
        let weights_no_post = mk_views(false);

        let mut session = ResidentDecodeState::new(
            n_layers, n_heads, n_kv, head_dim, hidden, ffn, tokens, tokens, eps, true, None,
        )
        .unwrap();
        let mut session_no_post = ResidentDecodeState::new(
            n_layers, n_heads, n_kv, head_dim, hidden, ffn, tokens, tokens, eps, true, None,
        )
        .unwrap();

        let mut ref_k: Vec<Vec<f32>> = vec![Vec::new(); n_layers];
        let mut ref_v: Vec<Vec<f32>> = vec![Vec::new(); n_layers];

        for t in 0..tokens {
            let emb: Vec<f32> = (0..hidden)
                .map(|i| (((i + t) as f32 % 11.0) - 5.0) * 0.2)
                .collect();
            let cos_t: Vec<f32> = (0..half)
                .map(|p| (0.2 + (p + t) as f32 * 0.1).cos())
                .collect();
            let sin_t: Vec<f32> = (0..half)
                .map(|p| (0.2 + (p + t) as f32 * 0.1).sin())
                .collect();

            // CPU reference token step with the sandwich norms.
            let mut x = emb.clone();
            for (li, d) in data.iter().enumerate() {
                let xn = cpu_ref_rms_norm(&x, &d.attn_norm, eps);
                let mut q = cpu_ref_q8_matvec(&xn, &d.q, q_dim);
                let mut kx = cpu_ref_q8_matvec(&xn, &d.k, kv_dim);
                let v = cpu_ref_q8_matvec(&xn, &d.v, kv_dim);
                cpu_ref_rms_norm_per_head(&mut q, n_heads, head_dim, &d.q_norm, eps);
                cpu_ref_rms_norm_per_head(&mut kx, n_kv, head_dim, &d.k_norm, eps);
                cpu_ref_rope_split_half(&mut q, n_heads, head_dim, &cos_t, &sin_t);
                cpu_ref_rope_split_half(&mut kx, n_kv, head_dim, &cos_t, &sin_t);
                ref_k[li].extend_from_slice(&kx);
                ref_v[li].extend_from_slice(&v);
                let ctx = cpu_ref_attention(
                    &q,
                    &ref_k[li],
                    &ref_v[li],
                    n_heads,
                    n_kv,
                    head_dim,
                    t + 1,
                    0,
                    t + 1,
                    scale,
                );
                let o = cpu_ref_q8_matvec(&ctx, &d.o, hidden);
                let on = cpu_ref_rms_norm(&o, &d.post_attn_norm, eps);
                for (h, ov) in x.iter_mut().zip(&on) {
                    *h += *ov;
                }
                let xn2 = cpu_ref_rms_norm(&x, &d.ffn_norm, eps);
                let g = cpu_ref_q8_matvec(&xn2, &d.gate, ffn);
                let u = cpu_ref_q8_matvec(&xn2, &d.up, ffn);
                let act: Vec<f32> = g
                    .iter()
                    .zip(&u)
                    .map(|(gv, uv)| (gv / (1.0 + (-gv).exp())) * uv)
                    .collect();
                let dn = cpu_ref_q8_matvec(&act, &d.down, hidden);
                let dnn = cpu_ref_rms_norm(&dn, &d.post_ffw_norm, eps);
                for (h, dv) in x.iter_mut().zip(&dnn) {
                    *h += *dv;
                }
            }

            let got = match session
                .forward_token(
                    &emb, &weights, &cos_t, &sin_t, None, t, scale, None, None, 0, None, None,
                )
                .unwrap()
            {
                ResidentTokenOut::Data(v) => v,
                ResidentTokenOut::Sampled(_) => panic!("unexpected sampled output"),
            };
            assert_eq!(got.len(), hidden);
            let mut max_diff = 0.0f32;
            for (a, b) in got.iter().zip(&x) {
                max_diff = max_diff.max((a - b).abs());
                assert!((a - b).abs() < 3.0e-3, "token {t}: {a} != {b}");
            }
            eprintln!("[2b-selfparity] token {t}: max |gpu-cpu| = {max_diff:.2e}");

            // Non-vacuity: dropping BOTH sandwich norms must change the output
            // materially at every token (the post-attention norm rescales the
            // value path itself, so this holds at t=0 too).
            let got_no_post = match session_no_post
                .forward_token(
                    &emb,
                    &weights_no_post,
                    &cos_t,
                    &sin_t,
                    None,
                    t,
                    scale,
                    None,
                    None,
                    0,
                    None,
                    None,
                )
                .unwrap()
            {
                ResidentTokenOut::Data(v) => v,
                ResidentTokenOut::Sampled(_) => panic!("unexpected sampled output"),
            };
            let delta = got
                .iter()
                .zip(&got_no_post)
                .map(|(a, b)| (a - b).abs())
                .fold(0.0f32, f32::max);
            assert!(
                delta > 0.05,
                "token {t}: sandwich norms had no material effect (max delta {delta}); the \
                 wiring is not engaging"
            );
        }
    }

    // gemma3→Metal Phase 2b: the batched prefill and speculative-verify paths
    // do not APPLY the sandwich norms, so they must fail closed when a layer
    // carries them (the decode path is the only sanctioned lane).
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_resident_post_norm_layers_fail_closed_on_prefill() {
        if !detect_metal_device().available {
            return;
        }
        let hidden = 64usize;
        let head_dim = 32usize;
        let ffn = 64usize;
        let bpr_hidden = hidden / 32;
        let q_dim = 2 * head_dim;
        let attn_norm: Vec<f32> = vec![1.0; hidden];
        let ffn_norm: Vec<f32> = vec![1.0; hidden];
        let post: Vec<f32> = vec![1.0; hidden];
        let q = mk_w36(q_dim, bpr_hidden, 1);
        let kv = mk_w36(head_dim, bpr_hidden, 2);
        let v = mk_w36(head_dim, bpr_hidden, 3);
        let o = mk_w36(hidden, q_dim / 32, 4);
        let gate = mk_w36(ffn, bpr_hidden, 5);
        let up = mk_w36(ffn, bpr_hidden, 6);
        let down = mk_w36(hidden, ffn / 32, 7);
        let layer = ResidentLayerWeights {
            attn_norm: &attn_norm,
            ffn_norm: &ffn_norm,
            q_norm: None,
            k_norm: None,
            post_attn_norm: Some(&post),
            post_ffw_norm: Some(&post),
            ffn_geglu: false,
            q_weight_blocks: ResidentWeightBytes::Blocks36(&q),
            k_weight_blocks: ResidentWeightBytes::Blocks36(&kv),
            v_weight_blocks: ResidentWeightBytes::Blocks36(&v),
            o_weight_blocks: ResidentWeightBytes::Blocks36(&o),
            gate_weight_blocks: ResidentWeightBytes::Blocks36(&gate),
            up_weight_blocks: ResidentWeightBytes::Blocks36(&up),
            down_weight_blocks: ResidentWeightBytes::Blocks36(&down),
        };
        let mut session =
            ResidentDecodeState::new(1, 2, 1, head_dim, hidden, ffn, 8, 8, 1.0e-6, true, None)
                .unwrap();
        let embeddings = vec![0.1f32; 2 * hidden];
        let cos_all = vec![0.5f32; 2 * (head_dim / 2)];
        let sin_all = vec![0.5f32; 2 * (head_dim / 2)];
        // The layer carries sandwich norms -> batched prefill must decline
        // regardless of every other precondition.
        assert!(
            session
                .prefill_tokens(
                    &embeddings,
                    2,
                    std::slice::from_ref(&layer),
                    &cos_all,
                    &sin_all,
                    1.0
                )
                .is_none(),
            "batched prefill must fail closed for sandwich-norm layers"
        );
        // A GeGLU layer set (no sandwich norms) must decline too: the prefill
        // FFN encodes SiLU only.
        let geglu_layer = ResidentLayerWeights {
            post_attn_norm: None,
            post_ffw_norm: None,
            ffn_geglu: true,
            ..layer
        };
        assert!(
            session
                .prefill_tokens(
                    &embeddings,
                    2,
                    std::slice::from_ref(&geglu_layer),
                    &cos_all,
                    &sin_all,
                    1.0
                )
                .is_none(),
            "batched prefill must fail closed for GeGLU layers"
        );
    }

    // gemma3→Metal Phase 2c: the resident FFN encodes GeGLU — gelu_tanh(gate)
    // * up via the existing gelu_mul_f32 kernel (reference
    // src/runnable/model.rs:865-873) — at the gemma3-1B geometry, on top of
    // the QK-norm and sandwich norms. Pure-CPU independent reference over 3
    // tokens, plus a non-vacuity guard (a SiLU decode of the same weights must
    // differ materially at every token).
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_resident_gemma3_geglu_decode_selfparity() {
        if !detect_metal_device().available {
            return;
        }
        if f32y_gemv_enabled() {
            eprintln!(
                "SKIP metal_resident_gemma3_geglu_decode_selfparity: CAMELID_METAL_F32Y \
                 latched on earlier in this process; the CPU reference mirrors the quantize path"
            );
            return;
        }
        let n_layers = 2usize;
        let n_heads = 4usize;
        let n_kv = 1usize;
        let head_dim = 256usize;
        let hidden = 1152usize;
        let ffn = 288usize;
        let tokens = 3usize;
        let eps = 1.0e-6f32;
        let scale = 1.0 / (head_dim as f32).sqrt();
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv * head_dim;
        let half = head_dim / 2;
        let bpr_hidden = hidden / 32;
        let bpr_q = q_dim / 32;
        let bpr_ffn = ffn / 32;

        struct LW {
            attn_norm: Vec<f32>,
            ffn_norm: Vec<f32>,
            q_norm: Vec<f32>,
            k_norm: Vec<f32>,
            post_attn_norm: Vec<f32>,
            post_ffw_norm: Vec<f32>,
            q: Vec<u8>,
            k: Vec<u8>,
            v: Vec<u8>,
            o: Vec<u8>,
            gate: Vec<u8>,
            up: Vec<u8>,
            down: Vec<u8>,
        }
        let data: Vec<LW> = (0..n_layers)
            .map(|li| {
                let s = li * 100;
                LW {
                    attn_norm: (0..hidden)
                        .map(|i| 0.5 + ((i + li) as f32 % 3.0) * 0.1)
                        .collect(),
                    ffn_norm: (0..hidden)
                        .map(|i| 0.4 + ((i + li) as f32 % 5.0) * 0.07)
                        .collect(),
                    q_norm: (0..head_dim)
                        .map(|i| 0.7 + ((i + li) as f32 % 11.0) * 0.02)
                        .collect(),
                    k_norm: (0..head_dim)
                        .map(|i| 0.6 + ((i + li) as f32 % 7.0) * 0.03)
                        .collect(),
                    post_attn_norm: (0..hidden)
                        .map(|i| 0.9 + ((i + li) as f32 % 3.0) * 0.03)
                        .collect(),
                    post_ffw_norm: (0..hidden)
                        .map(|i| 0.95 + ((i + li) as f32 % 6.0) * 0.02)
                        .collect(),
                    q: mk_w36(q_dim, bpr_hidden, s + 1),
                    k: mk_w36(kv_dim, bpr_hidden, s + 2),
                    v: mk_w36(kv_dim, bpr_hidden, s + 3),
                    o: mk_w36(hidden, bpr_q, s + 4),
                    gate: mk_w36(ffn, bpr_hidden, s + 5),
                    up: mk_w36(ffn, bpr_hidden, s + 6),
                    down: mk_w36(hidden, bpr_ffn, s + 7),
                }
            })
            .collect();
        let mk_views = |geglu: bool| -> Vec<ResidentLayerWeights<'_>> {
            data.iter()
                .map(|d| ResidentLayerWeights {
                    attn_norm: &d.attn_norm,
                    ffn_norm: &d.ffn_norm,
                    q_norm: Some(&d.q_norm),
                    k_norm: Some(&d.k_norm),
                    post_attn_norm: Some(&d.post_attn_norm),
                    post_ffw_norm: Some(&d.post_ffw_norm),
                    ffn_geglu: geglu,
                    q_weight_blocks: ResidentWeightBytes::Blocks36(&d.q),
                    k_weight_blocks: ResidentWeightBytes::Blocks36(&d.k),
                    v_weight_blocks: ResidentWeightBytes::Blocks36(&d.v),
                    o_weight_blocks: ResidentWeightBytes::Blocks36(&d.o),
                    gate_weight_blocks: ResidentWeightBytes::Blocks36(&d.gate),
                    up_weight_blocks: ResidentWeightBytes::Blocks36(&d.up),
                    down_weight_blocks: ResidentWeightBytes::Blocks36(&d.down),
                })
                .collect()
        };
        let weights = mk_views(true);
        let weights_silu = mk_views(false);

        let mut session = ResidentDecodeState::new(
            n_layers, n_heads, n_kv, head_dim, hidden, ffn, tokens, tokens, eps, true, None,
        )
        .unwrap();
        let mut session_silu = ResidentDecodeState::new(
            n_layers, n_heads, n_kv, head_dim, hidden, ffn, tokens, tokens, eps, true, None,
        )
        .unwrap();

        // gelu_pytorch_tanh — same constants as the kernel and the runnable
        // reference (`gelu_tanh`, src/runnable/model.rs:2053-2056).
        fn gelu_tanh(x: f32) -> f32 {
            const C: f32 = 0.797_884_6;
            0.5 * x * (1.0 + (C * (x + 0.044_715 * x * x * x)).tanh())
        }

        let mut ref_k: Vec<Vec<f32>> = vec![Vec::new(); n_layers];
        let mut ref_v: Vec<Vec<f32>> = vec![Vec::new(); n_layers];

        for t in 0..tokens {
            let emb: Vec<f32> = (0..hidden)
                .map(|i| (((i + t) as f32 % 11.0) - 5.0) * 0.2)
                .collect();
            let cos_t: Vec<f32> = (0..half)
                .map(|p| (0.2 + (p + t) as f32 * 0.1).cos())
                .collect();
            let sin_t: Vec<f32> = (0..half)
                .map(|p| (0.2 + (p + t) as f32 * 0.1).sin())
                .collect();

            // CPU reference token step: full gemma3 block structure with GeGLU.
            let mut x = emb.clone();
            for (li, d) in data.iter().enumerate() {
                let xn = cpu_ref_rms_norm(&x, &d.attn_norm, eps);
                let mut q = cpu_ref_q8_matvec(&xn, &d.q, q_dim);
                let mut kx = cpu_ref_q8_matvec(&xn, &d.k, kv_dim);
                let v = cpu_ref_q8_matvec(&xn, &d.v, kv_dim);
                cpu_ref_rms_norm_per_head(&mut q, n_heads, head_dim, &d.q_norm, eps);
                cpu_ref_rms_norm_per_head(&mut kx, n_kv, head_dim, &d.k_norm, eps);
                cpu_ref_rope_split_half(&mut q, n_heads, head_dim, &cos_t, &sin_t);
                cpu_ref_rope_split_half(&mut kx, n_kv, head_dim, &cos_t, &sin_t);
                ref_k[li].extend_from_slice(&kx);
                ref_v[li].extend_from_slice(&v);
                let ctx = cpu_ref_attention(
                    &q,
                    &ref_k[li],
                    &ref_v[li],
                    n_heads,
                    n_kv,
                    head_dim,
                    t + 1,
                    0,
                    t + 1,
                    scale,
                );
                let o = cpu_ref_q8_matvec(&ctx, &d.o, hidden);
                let on = cpu_ref_rms_norm(&o, &d.post_attn_norm, eps);
                for (h, ov) in x.iter_mut().zip(&on) {
                    *h += *ov;
                }
                let xn2 = cpu_ref_rms_norm(&x, &d.ffn_norm, eps);
                let g = cpu_ref_q8_matvec(&xn2, &d.gate, ffn);
                let u = cpu_ref_q8_matvec(&xn2, &d.up, ffn);
                let act: Vec<f32> = g
                    .iter()
                    .zip(&u)
                    .map(|(gv, uv)| gelu_tanh(*gv) * uv)
                    .collect();
                let dn = cpu_ref_q8_matvec(&act, &d.down, hidden);
                let dnn = cpu_ref_rms_norm(&dn, &d.post_ffw_norm, eps);
                for (h, dv) in x.iter_mut().zip(&dnn) {
                    *h += *dv;
                }
            }

            let got = match session
                .forward_token(
                    &emb, &weights, &cos_t, &sin_t, None, t, scale, None, None, 0, None, None,
                )
                .unwrap()
            {
                ResidentTokenOut::Data(v) => v,
                ResidentTokenOut::Sampled(_) => panic!("unexpected sampled output"),
            };
            assert_eq!(got.len(), hidden);
            // Tolerance note: unlike 2a/2b (elementwise exp/rsqrt agree to ~1e-6
            // between MSL and libm), tanh differs by a few ULPs between the two,
            // and on the quantize path a single activation crossing a Q8_0
            // rounding boundary shifts one quant by 1 — contributing up to
            // ws*act_scale ≈ 1e-2 to a down-projection dot. The non-vacuity
            // guard below (GeGLU vs SiLU) is the structural check; this bound
            // still catches a wrong activation outright (delta would be O(1e-1)).
            let mut max_diff = 0.0f32;
            for (a, b) in got.iter().zip(&x) {
                max_diff = max_diff.max((a - b).abs());
                assert!((a - b).abs() < 1.5e-2, "token {t}: {a} != {b}");
            }
            eprintln!("[2c-selfparity] token {t}: max |gpu-cpu| = {max_diff:.2e}");

            // Non-vacuity: the SiLU decode of the same weights must differ.
            let got_silu = match session_silu
                .forward_token(
                    &emb,
                    &weights_silu,
                    &cos_t,
                    &sin_t,
                    None,
                    t,
                    scale,
                    None,
                    None,
                    0,
                    None,
                    None,
                )
                .unwrap()
            {
                ResidentTokenOut::Data(v) => v,
                ResidentTokenOut::Sampled(_) => panic!("unexpected sampled output"),
            };
            let delta = got
                .iter()
                .zip(&got_silu)
                .map(|(a, b)| (a - b).abs())
                .fold(0.0f32, f32::max);
            assert!(
                delta > 0.02,
                "token {t}: GeGLU had no material effect vs SiLU (max delta {delta}); the \
                 wiring is not engaging"
            );
        }
    }

    // gemma3→Metal Phase 2d: per-layer dual-theta RoPE. A session built with a
    // ResidentLayerSchedule ropes each layer with its own theta's cos/sin
    // tables (primary = global, ALT = local), per Gemma3Metadata's
    // local:global cadence. Pure-CPU reference over 3 tokens at the 1B
    // geometry with the full gemma3 block structure; plus:
    // - a bit-identity guard: an all-primary schedule (no layer selects ALT)
    //   decodes to_bits-identically to a schedule-less session — the threading
    //   is provably a no-op when disengaged;
    // - fail-closed guards: missing ALT tables decline the forward, a
    //   mis-sized schedule declines construction, and a schedule-carrying
    //   session declines batched prefill;
    // - a non-vacuity guard from t>=1 (at t=0 the softmax runs over one
    //   position, so RoPE cannot affect the output).
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_resident_gemma3_dual_theta_rope_decode_selfparity() {
        if !detect_metal_device().available {
            return;
        }
        if f32y_gemv_enabled() {
            eprintln!(
                "SKIP metal_resident_gemma3_dual_theta_rope_decode_selfparity: \
                 CAMELID_METAL_F32Y latched on earlier in this process; the CPU reference \
                 mirrors the quantize path"
            );
            return;
        }
        let n_layers = 2usize;
        let n_heads = 4usize;
        let n_kv = 1usize;
        let head_dim = 256usize;
        let hidden = 1152usize;
        let ffn = 288usize;
        let tokens = 3usize;
        let eps = 1.0e-6f32;
        let scale = 1.0 / (head_dim as f32).sqrt();
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv * head_dim;
        let half = head_dim / 2;
        let bpr_hidden = hidden / 32;
        let bpr_q = q_dim / 32;
        let bpr_ffn = ffn / 32;

        struct LW {
            attn_norm: Vec<f32>,
            ffn_norm: Vec<f32>,
            q_norm: Vec<f32>,
            k_norm: Vec<f32>,
            post_attn_norm: Vec<f32>,
            post_ffw_norm: Vec<f32>,
            q: Vec<u8>,
            k: Vec<u8>,
            v: Vec<u8>,
            o: Vec<u8>,
            gate: Vec<u8>,
            up: Vec<u8>,
            down: Vec<u8>,
        }
        let data: Vec<LW> = (0..n_layers)
            .map(|li| {
                let s = li * 100;
                LW {
                    attn_norm: (0..hidden)
                        .map(|i| 0.5 + ((i + li) as f32 % 3.0) * 0.1)
                        .collect(),
                    ffn_norm: (0..hidden)
                        .map(|i| 0.4 + ((i + li) as f32 % 5.0) * 0.07)
                        .collect(),
                    q_norm: (0..head_dim)
                        .map(|i| 0.7 + ((i + li) as f32 % 11.0) * 0.02)
                        .collect(),
                    k_norm: (0..head_dim)
                        .map(|i| 0.6 + ((i + li) as f32 % 7.0) * 0.03)
                        .collect(),
                    post_attn_norm: (0..hidden)
                        .map(|i| 0.9 + ((i + li) as f32 % 3.0) * 0.03)
                        .collect(),
                    post_ffw_norm: (0..hidden)
                        .map(|i| 0.95 + ((i + li) as f32 % 6.0) * 0.02)
                        .collect(),
                    q: mk_w36(q_dim, bpr_hidden, s + 1),
                    k: mk_w36(kv_dim, bpr_hidden, s + 2),
                    v: mk_w36(kv_dim, bpr_hidden, s + 3),
                    o: mk_w36(hidden, bpr_q, s + 4),
                    gate: mk_w36(ffn, bpr_hidden, s + 5),
                    up: mk_w36(ffn, bpr_hidden, s + 6),
                    down: mk_w36(hidden, bpr_ffn, s + 7),
                }
            })
            .collect();
        let weights: Vec<ResidentLayerWeights> = data
            .iter()
            .map(|d| ResidentLayerWeights {
                attn_norm: &d.attn_norm,
                ffn_norm: &d.ffn_norm,
                q_norm: Some(&d.q_norm),
                k_norm: Some(&d.k_norm),
                post_attn_norm: Some(&d.post_attn_norm),
                post_ffw_norm: Some(&d.post_ffw_norm),
                ffn_geglu: true,
                q_weight_blocks: ResidentWeightBytes::Blocks36(&d.q),
                k_weight_blocks: ResidentWeightBytes::Blocks36(&d.k),
                v_weight_blocks: ResidentWeightBytes::Blocks36(&d.v),
                o_weight_blocks: ResidentWeightBytes::Blocks36(&d.o),
                gate_weight_blocks: ResidentWeightBytes::Blocks36(&d.gate),
                up_weight_blocks: ResidentWeightBytes::Blocks36(&d.up),
                down_weight_blocks: ResidentWeightBytes::Blocks36(&d.down),
            })
            .collect();

        // gemma3-1B cadence over 2 layers: layer 0 sliding (ALT/local theta),
        // layer 1 global (primary theta). Real thetas via the oracle-form
        // builder — the same code the production wiring uses.
        let schedule = ResidentLayerSchedule {
            use_alt_rope: vec![true, false],
            window: vec![None, None],
        };
        // Mis-sized schedule fails construction.
        assert!(
            ResidentDecodeState::new(
                n_layers,
                n_heads,
                n_kv,
                head_dim,
                hidden,
                ffn,
                tokens,
                tokens,
                eps,
                true,
                Some(ResidentLayerSchedule {
                    use_alt_rope: vec![true],
                    window: vec![None],
                }),
            )
            .is_none(),
            "schedule/layer-count mismatch must decline construction"
        );
        let mut session = ResidentDecodeState::new(
            n_layers,
            n_heads,
            n_kv,
            head_dim,
            hidden,
            ffn,
            tokens,
            tokens,
            eps,
            true,
            Some(schedule.clone()),
        )
        .unwrap();
        // Bit-identity pair: all-primary schedule vs no schedule.
        let mut session_trivial = ResidentDecodeState::new(
            n_layers,
            n_heads,
            n_kv,
            head_dim,
            hidden,
            ffn,
            tokens,
            tokens,
            eps,
            true,
            Some(ResidentLayerSchedule {
                use_alt_rope: vec![false, false],
                window: vec![None, None],
            }),
        )
        .unwrap();
        let mut session_none = ResidentDecodeState::new(
            n_layers, n_heads, n_kv, head_dim, hidden, ffn, tokens, tokens, eps, true, None,
        )
        .unwrap();

        // Schedule-carrying sessions decline batched prefill (single table set).
        {
            let mut prefill_session = ResidentDecodeState::new(
                n_layers,
                n_heads,
                n_kv,
                head_dim,
                hidden,
                ffn,
                tokens,
                tokens,
                eps,
                true,
                Some(schedule.clone()),
            )
            .unwrap();
            let embeddings = vec![0.1f32; 2 * hidden];
            let cs = vec![0.5f32; 2 * half];
            assert!(
                prefill_session
                    .prefill_tokens(&embeddings, 2, &weights, &cs, &cs, scale)
                    .is_none(),
                "batched prefill must fail closed for schedule-carrying sessions"
            );
        }

        fn gelu_tanh(x: f32) -> f32 {
            const C: f32 = 0.797_884_6;
            0.5 * x * (1.0 + (C * (x + 0.044_715 * x * x * x)).tanh())
        }

        let mut ref_k: Vec<Vec<f32>> = vec![Vec::new(); n_layers];
        let mut ref_v: Vec<Vec<f32>> = vec![Vec::new(); n_layers];

        for t in 0..tokens {
            let emb: Vec<f32> = (0..hidden)
                .map(|i| (((i + t) as f32 % 11.0) - 5.0) * 0.2)
                .collect();
            // Real gemma3 thetas: primary = global 1e6, ALT = local 1e4.
            let (cos_g, sin_g) = crate::inference::gemma3_rope_tables(t, head_dim, 1.0e6);
            let (cos_l, sin_l) = crate::inference::gemma3_rope_tables(t, head_dim, 1.0e4);

            // Missing ALT tables fail closed (the schedule selects ALT on layer 0).
            assert!(
                session
                    .forward_token(
                        &emb, &weights, &cos_g, &sin_g, None, t, scale, None, None, 0, None, None,
                    )
                    .is_none(),
                "token {t}: forward_token must decline when the schedule needs ALT tables \
                 and none were passed"
            );

            // CPU reference: layer 0 ropes with the LOCAL tables, layer 1 with
            // the GLOBAL tables.
            let mut x = emb.clone();
            for (li, d) in data.iter().enumerate() {
                let (lc, ls) = if schedule.use_alt_rope[li] {
                    (&cos_l, &sin_l)
                } else {
                    (&cos_g, &sin_g)
                };
                let xn = cpu_ref_rms_norm(&x, &d.attn_norm, eps);
                let mut q = cpu_ref_q8_matvec(&xn, &d.q, q_dim);
                let mut kx = cpu_ref_q8_matvec(&xn, &d.k, kv_dim);
                let v = cpu_ref_q8_matvec(&xn, &d.v, kv_dim);
                cpu_ref_rms_norm_per_head(&mut q, n_heads, head_dim, &d.q_norm, eps);
                cpu_ref_rms_norm_per_head(&mut kx, n_kv, head_dim, &d.k_norm, eps);
                cpu_ref_rope_split_half(&mut q, n_heads, head_dim, lc, ls);
                cpu_ref_rope_split_half(&mut kx, n_kv, head_dim, lc, ls);
                ref_k[li].extend_from_slice(&kx);
                ref_v[li].extend_from_slice(&v);
                let ctx = cpu_ref_attention(
                    &q,
                    &ref_k[li],
                    &ref_v[li],
                    n_heads,
                    n_kv,
                    head_dim,
                    t + 1,
                    0,
                    t + 1,
                    scale,
                );
                let o = cpu_ref_q8_matvec(&ctx, &d.o, hidden);
                let on = cpu_ref_rms_norm(&o, &d.post_attn_norm, eps);
                for (h, ov) in x.iter_mut().zip(&on) {
                    *h += *ov;
                }
                let xn2 = cpu_ref_rms_norm(&x, &d.ffn_norm, eps);
                let g = cpu_ref_q8_matvec(&xn2, &d.gate, ffn);
                let u = cpu_ref_q8_matvec(&xn2, &d.up, ffn);
                let act: Vec<f32> = g
                    .iter()
                    .zip(&u)
                    .map(|(gv, uv)| gelu_tanh(*gv) * uv)
                    .collect();
                let dn = cpu_ref_q8_matvec(&act, &d.down, hidden);
                let dnn = cpu_ref_rms_norm(&dn, &d.post_ffw_norm, eps);
                for (h, dv) in x.iter_mut().zip(&dnn) {
                    *h += *dv;
                }
            }

            let got = match session
                .forward_token(
                    &emb,
                    &weights,
                    &cos_g,
                    &sin_g,
                    Some((&cos_l, &sin_l)),
                    t,
                    scale,
                    None,
                    None,
                    0,
                    None,
                    None,
                )
                .unwrap()
            {
                ResidentTokenOut::Data(v) => v,
                ResidentTokenOut::Sampled(_) => panic!("unexpected sampled output"),
            };
            assert_eq!(got.len(), hidden);
            let mut max_diff = 0.0f32;
            for (a, b) in got.iter().zip(&x) {
                max_diff = max_diff.max((a - b).abs());
                assert!((a - b).abs() < 1.5e-2, "token {t}: {a} != {b}");
            }
            eprintln!("[2d-selfparity] token {t}: max |gpu-cpu| = {max_diff:.2e}");

            // Bit-identity: all-primary schedule (ALT provided but never
            // selected) == schedule-less session, exactly.
            let got_trivial = match session_trivial
                .forward_token(
                    &emb,
                    &weights,
                    &cos_g,
                    &sin_g,
                    Some((&cos_l, &sin_l)),
                    t,
                    scale,
                    None,
                    None,
                    0,
                    None,
                    None,
                )
                .unwrap()
            {
                ResidentTokenOut::Data(v) => v,
                ResidentTokenOut::Sampled(_) => panic!("unexpected sampled output"),
            };
            let got_none = match session_none
                .forward_token(
                    &emb, &weights, &cos_g, &sin_g, None, t, scale, None, None, 0, None, None,
                )
                .unwrap()
            {
                ResidentTokenOut::Data(v) => v,
                ResidentTokenOut::Sampled(_) => panic!("unexpected sampled output"),
            };
            for (i, (a, b)) in got_trivial.iter().zip(&got_none).enumerate() {
                assert_eq!(
                    a.to_bits(),
                    b.to_bits(),
                    "token {t} element {i}: all-primary schedule must be bit-identical to \
                     no schedule ({a} vs {b})"
                );
            }

            // Non-vacuity from t>=1: the dual-theta decode must differ from the
            // single-theta (schedule-less) decode once scores matter.
            if t >= 1 {
                let delta = got
                    .iter()
                    .zip(&got_none)
                    .map(|(a, b)| (a - b).abs())
                    .fold(0.0f32, f32::max);
                assert!(
                    delta > 0.02,
                    "token {t}: dual-theta RoPE had no material effect (max delta {delta}); \
                     the schedule is not engaging"
                );
            }
        }
    }

    // gemma3→Metal Phase 2e: the sliding-window decode mask. A schedule layer
    // with `window: Some(w)` attends only `[pos + 1 - w ..= pos]` — the window
    // INCLUDES the current position (`crate::window_ref::window_bounds`
    // convention) — via the gemma4 math (window_start = filled - w,
    // position_count = filled - window_start, kv_base_offset = window_start *
    // head_dim) on the UNCHANGED v1 decode-attention kernel.
    //
    // Assertion layers, strongest first:
    // 1. BIT-EXACT window oracle (single sliding layer, every depth): the
    //    windowed decode at position t must equal, to the bit, a fresh session
    //    seeded with EXACTLY the window's cache rows and decoded full-causal
    //    (same rope tables — `position` only picks the write slot). Any error
    //    in window_start, position_count, or the kv_base_offset shift changes
    //    the attention range and the bits. This is GPU-vs-GPU: no
    //    CPU-emulation noise at all.
    // 2. Off-by-one lock, both directions (two-layer mixed schedule): through
    //    t = w-1 (filled <= window) the windowed decode is BIT-identical to a
    //    windowless twin — a window-excludes-current bug would diverge at
    //    t = w-1 — and from t = w it must differ materially — a one-too-wide
    //    bug would still match there.
    // 3. CPU-reference smoke over 10 tokens with flip-tolerant bounds. The
    //    Q8_0 quantize path turns ~ULP CPU/GPU differences (reduction order in
    //    the fused rms_norm_quantize) into occasional rounding-boundary flips
    //    whose effect broadcasts through a whole projection (observed as
    //    isolated tokens at rms ~1e-2..7e-2 even on a WINDOWLESS decode, e.g.
    //    tokens 6/7/9 of this fixture while token 8 agrees to 1e-6 — data-
    //    dependent, not positional). A structural window bug instead diverges
    //    at EVERY clipped token with rms ~2e-1+, so the smoke bound is
    //    per-token loose (max < 2e-1, rms < 1e-1) — above all observed flip
    //    noise, below any wrong-range signal from t=5 on.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_resident_gemma3_sliding_window_decode_selfparity() {
        if !detect_metal_device().available {
            return;
        }
        if f32y_gemv_enabled() {
            eprintln!(
                "SKIP metal_resident_gemma3_sliding_window_decode_selfparity: \
                 CAMELID_METAL_F32Y latched on earlier in this process; the CPU reference \
                 mirrors the quantize path"
            );
            return;
        }
        let n_layers = 2usize;
        let n_heads = 4usize;
        let n_kv = 1usize;
        let head_dim = 256usize;
        let hidden = 1152usize;
        let ffn = 288usize;
        let tokens = 10usize;
        let window = 4usize;
        let eps = 1.0e-6f32;
        let scale = 1.0 / (head_dim as f32).sqrt();
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv * head_dim;
        let bpr_hidden = hidden / 32;
        let bpr_q = q_dim / 32;
        let bpr_ffn = ffn / 32;

        struct LW {
            attn_norm: Vec<f32>,
            ffn_norm: Vec<f32>,
            q_norm: Vec<f32>,
            k_norm: Vec<f32>,
            post_attn_norm: Vec<f32>,
            post_ffw_norm: Vec<f32>,
            q: Vec<u8>,
            k: Vec<u8>,
            v: Vec<u8>,
            o: Vec<u8>,
            gate: Vec<u8>,
            up: Vec<u8>,
            down: Vec<u8>,
        }
        let data: Vec<LW> = (0..n_layers)
            .map(|li| {
                let s = li * 100;
                LW {
                    attn_norm: (0..hidden)
                        .map(|i| 0.5 + ((i + li) as f32 % 3.0) * 0.1)
                        .collect(),
                    ffn_norm: (0..hidden)
                        .map(|i| 0.4 + ((i + li) as f32 % 5.0) * 0.07)
                        .collect(),
                    q_norm: (0..head_dim)
                        .map(|i| 0.7 + ((i + li) as f32 % 11.0) * 0.02)
                        .collect(),
                    k_norm: (0..head_dim)
                        .map(|i| 0.6 + ((i + li) as f32 % 7.0) * 0.03)
                        .collect(),
                    post_attn_norm: (0..hidden)
                        .map(|i| 0.9 + ((i + li) as f32 % 3.0) * 0.03)
                        .collect(),
                    post_ffw_norm: (0..hidden)
                        .map(|i| 0.95 + ((i + li) as f32 % 6.0) * 0.02)
                        .collect(),
                    q: mk_w36(q_dim, bpr_hidden, s + 1),
                    k: mk_w36(kv_dim, bpr_hidden, s + 2),
                    v: mk_w36(kv_dim, bpr_hidden, s + 3),
                    o: mk_w36(hidden, bpr_q, s + 4),
                    gate: mk_w36(ffn, bpr_hidden, s + 5),
                    up: mk_w36(ffn, bpr_hidden, s + 6),
                    down: mk_w36(hidden, bpr_ffn, s + 7),
                }
            })
            .collect();
        // SiLU FFN here, deliberately: windowing is orthogonal to the
        // activation (GeGLU is locked by 2c and the real-row full-forward
        // gate), and SiLU keeps the CPU smoke reference's quantize-flip rate
        // down (the MSL/libm tanh gap adds flips of its own — see 2c).
        fn mk_views(set: &[LW]) -> Vec<ResidentLayerWeights<'_>> {
            set.iter()
                .map(|d| ResidentLayerWeights {
                    attn_norm: &d.attn_norm,
                    ffn_norm: &d.ffn_norm,
                    q_norm: Some(&d.q_norm),
                    k_norm: Some(&d.k_norm),
                    post_attn_norm: Some(&d.post_attn_norm),
                    post_ffw_norm: Some(&d.post_ffw_norm),
                    ffn_geglu: false,
                    q_weight_blocks: ResidentWeightBytes::Blocks36(&d.q),
                    k_weight_blocks: ResidentWeightBytes::Blocks36(&d.k),
                    v_weight_blocks: ResidentWeightBytes::Blocks36(&d.v),
                    o_weight_blocks: ResidentWeightBytes::Blocks36(&d.o),
                    gate_weight_blocks: ResidentWeightBytes::Blocks36(&d.gate),
                    up_weight_blocks: ResidentWeightBytes::Blocks36(&d.up),
                    down_weight_blocks: ResidentWeightBytes::Blocks36(&d.down),
                })
                .collect()
        }
        let weights = mk_views(&data);
        let weights_single = mk_views(&data[..1]);

        // ------------------------------------------------------------------
        // 1. Bit-exact window oracle: single sliding layer, every depth.
        // ------------------------------------------------------------------
        {
            let mut a = ResidentDecodeState::new(
                1,
                n_heads,
                n_kv,
                head_dim,
                hidden,
                ffn,
                tokens,
                tokens,
                eps,
                true,
                Some(ResidentLayerSchedule {
                    use_alt_rope: vec![true],
                    window: vec![Some(window)],
                }),
            )
            .unwrap();
            for t in 0..tokens {
                let emb: Vec<f32> = (0..hidden)
                    .map(|i| ((((i * 7 + t * 13) % 23) as f32) - 11.0) * 0.13)
                    .collect();
                let (cos_l, sin_l) = crate::inference::gemma3_rope_tables(t, head_dim, 1.0e4);
                let filled = t + 1;
                let ws = filled.saturating_sub(window);
                let count = filled - ws;
                // Seed the oracle with EXACTLY the window's history rows,
                // copied bit-for-bit out of A's GPU cache (positions [ws, t)),
                // BEFORE A appends the current token.
                let hist_k = a.cache_k_contiguous(0, t);
                let hist_v = a.cache_v_contiguous(0, t);
                let seed = count - 1; // history rows inside the window
                let mut b = ResidentDecodeState::new(
                    1, n_heads, n_kv, head_dim, hidden, ffn, tokens, tokens, eps, true,
                    None, // full causal: the oracle's range IS the seed
                )
                .unwrap();
                if seed > 0 {
                    let ck = &hist_k[ws * head_dim..(ws + seed) * head_dim];
                    let cv = &hist_v[ws * head_dim..(ws + seed) * head_dim];
                    assert!(b.seed_layer(0, ck, cv, seed), "oracle seed");
                }
                b.set_filled(seed);
                let run = |s: &mut ResidentDecodeState, pos: usize| -> Vec<f32> {
                    match s
                        .forward_token(
                            &emb,
                            &weights_single,
                            &cos_l,
                            &sin_l,
                            Some((&cos_l, &sin_l)),
                            pos,
                            scale,
                            None,
                            None,
                            0,
                            None,
                            None,
                        )
                        .unwrap()
                    {
                        ResidentTokenOut::Data(v) => v,
                        ResidentTokenOut::Sampled(_) => panic!("unexpected sampled output"),
                    }
                };
                let got_a = run(&mut a, t);
                let got_b = run(&mut b, seed);
                for (i, (av, bv)) in got_a.iter().zip(&got_b).enumerate() {
                    assert_eq!(
                        av.to_bits(),
                        bv.to_bits(),
                        "depth {t} element {i}: windowed decode must be BIT-identical to the \
                         seeded-window full-causal oracle ({av} vs {bv}) — window range wrong"
                    );
                }
            }
            eprintln!(
                "[2e-oracle] windowed decode bit-identical to the seeded-window oracle at \
                 depths 0..{tokens} (window {window})"
            );
        }

        // ------------------------------------------------------------------
        // 2+3. Two-layer mixed schedule: off-by-one bit-probe, mandatory
        // divergence, CPU smoke with flip-count gate. Layer 0 slides (local
        // theta, window 4); layer 1 is global (primary theta, full causal).
        // ------------------------------------------------------------------
        let schedule = ResidentLayerSchedule {
            use_alt_rope: vec![true, false],
            window: vec![Some(window), None],
        };
        let mut session = ResidentDecodeState::new(
            n_layers,
            n_heads,
            n_kv,
            head_dim,
            hidden,
            ffn,
            tokens,
            tokens,
            eps,
            true,
            Some(schedule.clone()),
        )
        .unwrap();
        let mut session_full = ResidentDecodeState::new(
            n_layers,
            n_heads,
            n_kv,
            head_dim,
            hidden,
            ffn,
            tokens,
            tokens,
            eps,
            true,
            Some(ResidentLayerSchedule {
                use_alt_rope: vec![true, false],
                window: vec![None, None],
            }),
        )
        .unwrap();
        // Window-vector length is validated too.
        assert!(
            ResidentDecodeState::new(
                n_layers,
                n_heads,
                n_kv,
                head_dim,
                hidden,
                ffn,
                tokens,
                tokens,
                eps,
                true,
                Some(ResidentLayerSchedule {
                    use_alt_rope: vec![true, false],
                    window: vec![Some(window)],
                }),
            )
            .is_none(),
            "window/layer-count mismatch must decline construction"
        );

        let mut ref_k: Vec<Vec<f32>> = vec![Vec::new(); n_layers];
        let mut ref_v: Vec<Vec<f32>> = vec![Vec::new(); n_layers];
        // The windowless twin needs its OWN reference history: layer 1's K/V
        // derive from layer 0's output, which differs between the windowed and
        // full runs once the mask clips.
        let mut ref_k_full: Vec<Vec<f32>> = vec![Vec::new(); n_layers];
        let mut ref_v_full: Vec<Vec<f32>> = vec![Vec::new(); n_layers];
        let mut noisy_tokens = 0usize;

        for t in 0..tokens {
            // Decorrelated across tokens (multiplicative index mix), so the
            // windowed softmax does not sit on near-collinear K rows.
            let emb: Vec<f32> = (0..hidden)
                .map(|i| ((((i * 7 + t * 13) % 23) as f32) - 11.0) * 0.13)
                .collect();
            let (cos_g, sin_g) = crate::inference::gemma3_rope_tables(t, head_dim, 1.0e6);
            let (cos_l, sin_l) = crate::inference::gemma3_rope_tables(t, head_dim, 1.0e4);

            // CPU reference: layer 0 restricts its softmax to the trailing
            // window (lo = filled - window, count = filled - lo); layer 1 is
            // full causal.
            let filled = t + 1;
            let step = |windowed: bool,
                        ref_k: &mut Vec<Vec<f32>>,
                        ref_v: &mut Vec<Vec<f32>>|
             -> Vec<f32> {
                let mut x = emb.clone();
                for (li, d) in data.iter().enumerate() {
                    let (lc, ls) = if schedule.use_alt_rope[li] {
                        (&cos_l, &sin_l)
                    } else {
                        (&cos_g, &sin_g)
                    };
                    let lo = if windowed {
                        schedule.window[li].map_or(0, |w| filled.saturating_sub(w))
                    } else {
                        0
                    };
                    let count = filled - lo;
                    let xn = cpu_ref_rms_norm(&x, &d.attn_norm, eps);
                    let mut q = cpu_ref_q8_matvec(&xn, &d.q, q_dim);
                    let mut kx = cpu_ref_q8_matvec(&xn, &d.k, kv_dim);
                    let v = cpu_ref_q8_matvec(&xn, &d.v, kv_dim);
                    cpu_ref_rms_norm_per_head(&mut q, n_heads, head_dim, &d.q_norm, eps);
                    cpu_ref_rms_norm_per_head(&mut kx, n_kv, head_dim, &d.k_norm, eps);
                    cpu_ref_rope_split_half(&mut q, n_heads, head_dim, lc, ls);
                    cpu_ref_rope_split_half(&mut kx, n_kv, head_dim, lc, ls);
                    ref_k[li].extend_from_slice(&kx);
                    ref_v[li].extend_from_slice(&v);
                    let ctx = cpu_ref_attention(
                        &q, &ref_k[li], &ref_v[li], n_heads, n_kv, head_dim, filled, lo, count,
                        scale,
                    );
                    let o = cpu_ref_q8_matvec(&ctx, &d.o, hidden);
                    let on = cpu_ref_rms_norm(&o, &d.post_attn_norm, eps);
                    for (h, ov) in x.iter_mut().zip(&on) {
                        *h += *ov;
                    }
                    let xn2 = cpu_ref_rms_norm(&x, &d.ffn_norm, eps);
                    let g = cpu_ref_q8_matvec(&xn2, &d.gate, ffn);
                    let u = cpu_ref_q8_matvec(&xn2, &d.up, ffn);
                    let act: Vec<f32> = g
                        .iter()
                        .zip(&u)
                        .map(|(gv, uv)| (gv / (1.0 + (-gv).exp())) * uv)
                        .collect();
                    let dn = cpu_ref_q8_matvec(&act, &d.down, hidden);
                    let dnn = cpu_ref_rms_norm(&dn, &d.post_ffw_norm, eps);
                    for (h, dv) in x.iter_mut().zip(&dnn) {
                        *h += *dv;
                    }
                }
                x
            };
            let x = step(true, &mut ref_k, &mut ref_v);
            let x_full = step(false, &mut ref_k_full, &mut ref_v_full);

            let run = |s: &mut ResidentDecodeState| -> Vec<f32> {
                match s
                    .forward_token(
                        &emb,
                        &weights,
                        &cos_g,
                        &sin_g,
                        Some((&cos_l, &sin_l)),
                        t,
                        scale,
                        None,
                        None,
                        0,
                        None,
                        None,
                    )
                    .unwrap()
                {
                    ResidentTokenOut::Data(v) => v,
                    ResidentTokenOut::Sampled(_) => panic!("unexpected sampled output"),
                }
            };
            let got = run(&mut session);
            let got_full = run(&mut session_full);

            assert_eq!(got.len(), hidden);
            let metrics = |got: &[f32], want: &[f32]| {
                let mut max_diff = 0.0f32;
                let mut sum_sq = 0.0f64;
                for (a, b) in got.iter().zip(want) {
                    let d = (a - b).abs();
                    max_diff = max_diff.max(d);
                    sum_sq += (d as f64) * (d as f64);
                }
                (max_diff, (sum_sq / got.len() as f64).sqrt())
            };
            let (max_diff, rms) = metrics(&got, &x);
            let (max_full, rms_full) = metrics(&got_full, &x_full);
            eprintln!(
                "[2e-selfparity] token {t}: windowed max = {max_diff:.2e} rms = {rms:.2e} | \
                 windowless max = {max_full:.2e} rms = {rms_full:.2e}"
            );
            assert!(
                max_diff < 2.0e-1 && rms < 1.0e-1,
                "token {t} (windowed): max |gpu-cpu| = {max_diff:.2e}, rms = {rms:.2e}"
            );
            assert!(
                max_full < 2.0e-1 && rms_full < 1.0e-1,
                "token {t} (windowless): max |gpu-cpu| = {max_full:.2e}, rms = {rms_full:.2e}"
            );
            if rms >= 5.0e-3 {
                noisy_tokens += 1;
            }

            let delta = got
                .iter()
                .zip(&got_full)
                .map(|(a, b)| (a - b).abs())
                .fold(0.0f32, f32::max);
            if filled <= window {
                // The window still covers every position: the mask must be a
                // bit-exact no-op. A window-excludes-current off-by-one would
                // first diverge here at t = window - 1.
                for (i, (a, b)) in got.iter().zip(&got_full).enumerate() {
                    assert_eq!(
                        a.to_bits(),
                        b.to_bits(),
                        "token {t} element {i}: windowed decode must be bit-identical to \
                         windowless while filled <= window ({a} vs {b})"
                    );
                }
            } else {
                // The mask now drops at least one position: outputs must
                // differ. A one-too-wide off-by-one would still match at t=4.
                assert!(
                    delta > 1.0e-3,
                    "token {t}: sliding window had no effect (max delta {delta}); the mask \
                     is not engaging"
                );
            }
        }
        // Informational: how many tokens carried quantize-flip noise. Once a
        // flip lands, layer 1's cache rows carry it forward, so consecutive
        // noisy tokens are one event, not many — an assert on the count would
        // be brittle across devices (flip positions are fixture- and
        // device-dependent). The structural load is carried by the bit-exact
        // oracle above and the per-token rms bound (a mis-indexed window
        // produces rms ~2e-1+ at clipped depths, over the 1e-1 bound).
        eprintln!("[2e-selfparity] {noisy_tokens}/10 tokens above rms 5e-3 (quantize flips)");
    }

    // gemma3 long-prompt TTFT campaign, Phase 1: the KV-EQUIVALENCE INVARIANT and
    // its power against the window-mutation class, proven on a synthetic fixture so
    // it runs in the default suite with no GGUF and no model load.
    //
    // The claim under test is the one Tier A/B will be gated on: two sessions that
    // ran the same tokens must hold the same KV. `kv_snapshot` + `kv_equivalence`
    // is the direct check; this test establishes (a) the positive control — two
    // independent sessions with the SAME schedule are bit-identical, so the gate is
    // not vacuously red — and (b) that six deliberate schedule mutations each make
    // it red, so the gate is not vacuously green.
    //
    // Two properties of the invariant that the assertions below pin down, because
    // they decide where a defect becomes visible:
    //
    //  * Layer 0's K/V is computed from the token embedding and never from
    //    attention, so a mask defect is INVISIBLE in layer 0's cache and first
    //    appears in layer 1's. An n-layer model's LAST layer's attention appears in
    //    no cache at all — which is why the snapshot carries `final_hidden`, and why
    //    the mutants are also asserted to move it.
    //  * A window mutation is a no-op while `filled <= window`. The fixture runs
    //    past the window on purpose; the real-row pack has to do the same, which is
    //    exactly why prompts below 512 tokens have no power over the window bound.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_kv_snapshot_equivalence_catches_window_and_rope_mutations() {
        use crate::kv_equivalence::compare;
        if !detect_metal_device().available {
            return;
        }
        let n_layers = 3usize;
        let n_heads = 4usize;
        let n_kv = 1usize;
        let head_dim = 256usize;
        let hidden = 1152usize;
        let ffn = 288usize;
        let tokens = 9usize;
        let window = 4usize;
        let eps = 1.0e-6f32;
        let scale = 1.0 / (head_dim as f32).sqrt();
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv * head_dim;
        let bpr_hidden = hidden / 32;
        let bpr_q = q_dim / 32;
        let bpr_ffn = ffn / 32;

        struct LW {
            attn_norm: Vec<f32>,
            ffn_norm: Vec<f32>,
            q_norm: Vec<f32>,
            k_norm: Vec<f32>,
            post_attn_norm: Vec<f32>,
            post_ffw_norm: Vec<f32>,
            q: Vec<u8>,
            k: Vec<u8>,
            v: Vec<u8>,
            o: Vec<u8>,
            gate: Vec<u8>,
            up: Vec<u8>,
            down: Vec<u8>,
        }
        let data: Vec<LW> = (0..n_layers)
            .map(|li| {
                let s = li * 100;
                LW {
                    attn_norm: (0..hidden)
                        .map(|i| 0.5 + ((i + li) as f32 % 3.0) * 0.1)
                        .collect(),
                    ffn_norm: (0..hidden)
                        .map(|i| 0.4 + ((i + li) as f32 % 5.0) * 0.07)
                        .collect(),
                    q_norm: (0..head_dim)
                        .map(|i| 0.7 + ((i + li) as f32 % 11.0) * 0.02)
                        .collect(),
                    k_norm: (0..head_dim)
                        .map(|i| 0.6 + ((i + li) as f32 % 7.0) * 0.03)
                        .collect(),
                    post_attn_norm: (0..hidden)
                        .map(|i| 0.9 + ((i + li) as f32 % 3.0) * 0.03)
                        .collect(),
                    post_ffw_norm: (0..hidden)
                        .map(|i| 0.95 + ((i + li) as f32 % 6.0) * 0.02)
                        .collect(),
                    q: mk_w36(q_dim, bpr_hidden, s + 1),
                    k: mk_w36(kv_dim, bpr_hidden, s + 2),
                    v: mk_w36(kv_dim, bpr_hidden, s + 3),
                    o: mk_w36(hidden, bpr_q, s + 4),
                    gate: mk_w36(ffn, bpr_hidden, s + 5),
                    up: mk_w36(ffn, bpr_hidden, s + 6),
                    down: mk_w36(hidden, bpr_ffn, s + 7),
                }
            })
            .collect();
        let weights: Vec<ResidentLayerWeights<'_>> = data
            .iter()
            .map(|d| ResidentLayerWeights {
                attn_norm: &d.attn_norm,
                ffn_norm: &d.ffn_norm,
                q_norm: Some(&d.q_norm),
                k_norm: Some(&d.k_norm),
                post_attn_norm: Some(&d.post_attn_norm),
                post_ffw_norm: Some(&d.post_ffw_norm),
                ffn_geglu: false,
                q_weight_blocks: ResidentWeightBytes::Blocks36(&d.q),
                k_weight_blocks: ResidentWeightBytes::Blocks36(&d.k),
                v_weight_blocks: ResidentWeightBytes::Blocks36(&d.v),
                o_weight_blocks: ResidentWeightBytes::Blocks36(&d.o),
                gate_weight_blocks: ResidentWeightBytes::Blocks36(&d.gate),
                up_weight_blocks: ResidentWeightBytes::Blocks36(&d.up),
                down_weight_blocks: ResidentWeightBytes::Blocks36(&d.down),
            })
            .collect();

        // Production-shaped schedule: layers 0 and 1 slide (ALT/local theta),
        // layer 2 is global (primary theta) — the 1B row's cadence in miniature.
        let base_alt = vec![true, true, false];
        let base_window = vec![Some(window), Some(window), None];

        // Run `tokens` forwards under one schedule and return (KV snapshot with the
        // final hidden attached). Every run sees byte-identical inputs, so the ONLY
        // difference between two runs is the schedule.
        let run = |alt: &[bool], win: &[Option<usize>]| -> crate::kv_equivalence::KvSnapshot {
            let mut session = ResidentDecodeState::new(
                n_layers,
                n_heads,
                n_kv,
                head_dim,
                hidden,
                ffn,
                tokens,
                tokens,
                eps,
                true,
                Some(ResidentLayerSchedule {
                    use_alt_rope: alt.to_vec(),
                    window: win.to_vec(),
                }),
            )
            .expect("resident session");
            let mut last = Vec::new();
            for t in 0..tokens {
                let emb: Vec<f32> = (0..hidden)
                    .map(|i| ((((i * 7 + t * 13) % 23) as f32) - 11.0) * 0.13)
                    .collect();
                let (cos_g, sin_g) = crate::inference::gemma3_rope_tables(t, head_dim, 1.0e6);
                let (cos_l, sin_l) = crate::inference::gemma3_rope_tables(t, head_dim, 1.0e4);
                last = match session
                    .forward_token(
                        &emb,
                        &weights,
                        &cos_g,
                        &sin_g,
                        Some((&cos_l, &sin_l)),
                        t,
                        scale,
                        None,
                        None,
                        0,
                        None,
                        None,
                    )
                    .expect("resident forward")
                {
                    ResidentTokenOut::Data(v) => v,
                    ResidentTokenOut::Sampled(_) => panic!("unexpected sampled output"),
                };
            }
            session.kv_snapshot(tokens).with_final_hidden(last)
        };

        // (a) POSITIVE CONTROL — two independent sessions, same schedule, same
        //     inputs: bit-identical KV and a matching digest. Without this the
        //     mutant assertions below prove nothing.
        let baseline = run(&base_alt, &base_window);
        let baseline2 = run(&base_alt, &base_window);
        let v = compare(&baseline, &baseline2).expect("compare");
        v.assert_bit_identical("positive control (same schedule, same inputs)");
        assert_eq!(
            baseline.digest(),
            baseline2.digest(),
            "same-schedule digests must match"
        );
        assert!(v.meets_bound(0.0, 10.0).is_ok());
        eprintln!(
            "[kv-equiv] positive control: {} | digest {}",
            v.summary(),
            &baseline.digest()[..16]
        );

        // (b) MUTANTS — each must make the invariant red. The names mirror the
        //     campaign's mutation harness so a failure here names the same defect.
        // `mask_only` marks the mutations that change ONLY the attention mask. Those
        // cannot reach layer 0's cache; the RoPE mutant can and does (K is rotated
        // before it is written), so it is excluded from that assertion rather than
        // the assertion being weakened for everyone.
        struct Mutant {
            name: &'static str,
            alt: Vec<bool>,
            window: Vec<Option<usize>>,
            mask_only: bool,
        }
        let mutants = vec![
            Mutant {
                name: "window_minus_one (window_start off by +1 once saturated)",
                alt: base_alt.clone(),
                window: vec![Some(window - 1), Some(window - 1), None],
                mask_only: true,
            },
            Mutant {
                name: "window_plus_one (one position too wide)",
                alt: base_alt.clone(),
                window: vec![Some(window + 1), Some(window + 1), None],
                mask_only: true,
            },
            Mutant {
                name: "no_lower_bound (full causal — the lower bound dropped)",
                alt: base_alt.clone(),
                window: vec![None, None, None],
                mask_only: true,
            },
            Mutant {
                name: "window_on_all_layers (the global layer slides too)",
                alt: base_alt.clone(),
                window: vec![Some(window), Some(window), Some(window)],
                mask_only: true,
            },
            Mutant {
                name: "window_on_the_wrong_layers (schedule inverted)",
                alt: base_alt.clone(),
                window: vec![None, None, Some(window)],
                mask_only: true,
            },
            Mutant {
                name: "rope_tables_swapped (ALT/primary inverted)",
                alt: vec![false, false, true],
                window: base_window.clone(),
                mask_only: false,
            },
        ];
        for Mutant {
            name,
            alt,
            window: win,
            mask_only,
        } in &mutants
        {
            let mutant = run(alt, win);
            let v = compare(&baseline, &mutant).expect("compare");
            assert!(
                !v.bit_identical,
                "MUTANT SURVIVED the KV-equivalence invariant: {name}. A mutation the \
                 invariant cannot see is a hole in the Tier A/B gate."
            );
            assert!(
                v.meets_bound(1.0e-6, 10.0).is_err(),
                "MUTANT SURVIVED the Tier B bound+outlier check: {name} ({})",
                v.summary()
            );
            assert_ne!(baseline.digest(), mutant.digest(), "digest blind to {name}");
            eprintln!(
                "[kv-equiv] CAUGHT {name}: {} first_diff={}",
                v.summary(),
                v.first_difference
                    .map(|s| s.to_string())
                    .unwrap_or_else(|| "<none>".into())
            );
            // Where the defect first shows is a documented property of the
            // invariant, not an accident: a MASK mutation cannot reach layer 0's
            // cache, because K/V there come from the token embedding and never from
            // attention. A ROPE mutation can and does — it rotates K before the
            // cache write — which is why only mask mutants carry this assertion.
            if *mask_only {
                if let Some(site) = v.first_difference {
                    assert!(
                        site.layer > 0
                            || site.tensor == crate::kv_equivalence::KvTensor::FinalHidden,
                        "{name}: layer 0's cache must be mask-independent, got {site}"
                    );
                }
                assert_eq!(
                    v.per_layer_max_abs[0], 0.0,
                    "{name}: layer 0's KV must be untouched by a mask-only mutation"
                );
            } else {
                assert!(
                    v.per_layer_max_abs[0] > 0.0,
                    "{name}: a RoPE mutation rotates K before the cache write, so layer 0 \
                     MUST move — if it does not, the ALT/primary selection is not wired"
                );
            }
        }

        // (c) The blind spot, asserted so it stays documented: below the window a
        //     window mutation is a genuine no-op — the invariant is GREEN and must
        //     be. This is why the prompt pack needs prompts past 512 tokens.
        let short = 3usize; // < window (4)
        let run_short = |win: &[Option<usize>]| -> crate::kv_equivalence::KvSnapshot {
            let mut session = ResidentDecodeState::new(
                n_layers,
                n_heads,
                n_kv,
                head_dim,
                hidden,
                ffn,
                short,
                short,
                eps,
                true,
                Some(ResidentLayerSchedule {
                    use_alt_rope: base_alt.clone(),
                    window: win.to_vec(),
                }),
            )
            .expect("resident session");
            let mut last = Vec::new();
            for t in 0..short {
                let emb: Vec<f32> = (0..hidden)
                    .map(|i| ((((i * 7 + t * 13) % 23) as f32) - 11.0) * 0.13)
                    .collect();
                let (cos_g, sin_g) = crate::inference::gemma3_rope_tables(t, head_dim, 1.0e6);
                let (cos_l, sin_l) = crate::inference::gemma3_rope_tables(t, head_dim, 1.0e4);
                last = match session
                    .forward_token(
                        &emb,
                        &weights,
                        &cos_g,
                        &sin_g,
                        Some((&cos_l, &sin_l)),
                        t,
                        scale,
                        None,
                        None,
                        0,
                        None,
                        None,
                    )
                    .expect("resident forward")
                {
                    ResidentTokenOut::Data(v) => v,
                    ResidentTokenOut::Sampled(_) => panic!("unexpected sampled output"),
                };
            }
            session.kv_snapshot(short).with_final_hidden(last)
        };
        let short_base = run_short(&base_window);
        for win in [
            vec![Some(window + 1), Some(window + 1), None],
            vec![Some(window + 5), Some(window + 5), None],
            vec![None, None, None],
        ] {
            let v = compare(&short_base, &run_short(&win)).expect("compare");
            v.assert_bit_identical(
                "below the window, a WIDER window (or none at all) must be a bit-exact no-op",
            );
        }
        eprintln!(
            "[kv-equiv] blind spot confirmed: with filled <= window, widening the window is a \
             bit-exact no-op — prompts must exceed the window to have power over its bound"
        );
    }

    // gemma3→Metal Phase 2 FINAL GATE: full-forward parity on the REAL row.
    // The resident lane (all Phase 2 encodes: QK-norm, sandwich norms, GeGLU,
    // dual-theta RoPE with forced split-half pairing, sliding-window schedule,
    // sqrt(d_model) embed scale, token-by-token prefill through the decode
    // path) must produce a TOKEN-IDENTICAL greedy continuation to the runnable
    // lane — the CPU oracle that is itself bit-pinned to HF transformers
    // (qa/runnable/gemma3-parity.json) — at depths 1/5/50, everything under
    // 512 tokens (the window is active but unclipped, matching the oracle's
    // no-mask semantics). The resident machinery is driven DIRECTLY (the
    // production arch disqualifier stays up until Phase 3).
    //
    // The comparison runs the resident lane in its PRODUCTION GEMV
    // configuration (f32y + wire + NSG8, the CLI fast stack): activations stay
    // f32 end-to-end, so the only resident-vs-oracle delta is reduction order.
    // The default-latched quantize path is NOT the production lane and its Q8
    // activation noise (~0.5 logit over 26 layers) flips near-ties; like
    // metal_spec_verify_bit_identical, this test SKIPS unless those gates are
    // armed — but it arms them from the SHELL, never with an in-test
    // `set_var` (see the comment on the gate check below). The targeted run
    // below is the enforced proof lane.
    //
    // Run: CAMELID_METAL_F32Y=1 CAMELID_METAL_WIRE=1 CAMELID_METAL_WIRE_NSG8=1 \
    //      CAMELID_GEMMA3_GGUF=/path/gemma-3-1b-it-Q8_0.gguf \
    //      cargo test --release --lib gemma3_real_row_resident_forward -- --nocapture
    // (~10 min: the oracle re-runs its stateless f32 forward per step.)
    #[cfg(target_os = "macos")]
    #[test]
    fn gemma3_real_row_resident_forward_matches_runnable_oracle() {
        if !detect_metal_device().available {
            return;
        }
        let Some(path) = std::env::var_os("CAMELID_GEMMA3_GGUF") else {
            eprintln!(
                "SKIP gemma3_real_row_resident_forward_matches_runnable_oracle: \
                 set CAMELID_GEMMA3_GGUF to the gemma-3-1b-it-Q8_0 GGUF"
            );
            return;
        };
        // The production GEMV gates must be armed BY THE CALLER, not here. They are
        // process-wide OnceLocks read by every other Metal test in this binary, so
        // setting them from inside a test latches whichever siblings have not read
        // them yet onto the wire path — where the standalone block helpers' 36-byte
        // uploads are read as 34-byte wire blocks and come back NaN. Measured: with
        // an in-test `set_var` here, `cargo test --lib metal::tests` fails
        // metal_attention_block_resident_matches_standalone,
        // metal_ffn_block_resident_matches_standalone,
        // metal_decode_layer_resident_matches_blocks,
        // metal_decode_forward_resident_matches_per_layer and
        // metal_resident_decode_state_matches_full_upload; without it the suite is
        // green and this test simply SKIPs unless it was invoked targeted.
        if !(f32y_gemv_enabled() && wire_weights_enabled() && wire_nsg8_enabled()) {
            eprintln!(
                "SKIP gemma3_real_row_resident_forward_matches_runnable_oracle: the \
                 production GEMV gates (f32y/wire/NSG8) are not armed. Run targeted: \
                 CAMELID_METAL_F32Y=1 CAMELID_METAL_WIRE=1 CAMELID_METAL_WIRE_NSG8=1 \
                 CAMELID_GEMMA3_GGUF=... cargo test --release --lib \
                 gemma3_real_row_resident_forward -- --nocapture"
            );
            return;
        }
        let path = path.to_string_lossy().to_string();
        use crate::gguf::{read_metadata, GgufTensorType};
        use crate::model::LlamaModelConfig;
        use std::io::{Read, Seek, SeekFrom};

        let gguf = read_metadata(&path).expect("gguf metadata");
        let cfg = LlamaModelConfig::from_gguf(&gguf).expect("config");
        let g3 = cfg.gemma3.clone().expect("gemma3 metadata");
        let n_layers = cfg.block_count as usize;
        let n_heads = cfg.attention_head_count as usize;
        let n_kv = cfg.attention_head_count_kv as usize;
        let hidden = cfg.embedding_length as usize;
        let head_dim = cfg
            .attention_key_length
            .map(|v| v as usize)
            .unwrap_or(hidden / n_heads);
        let rope_dim = cfg
            .rope_dimension_count
            .map(|v| v as usize)
            .unwrap_or(head_dim);
        let eps = cfg.rms_norm_epsilon;
        let scale = 1.0 / (head_dim as f32).sqrt();

        // ---- raw tensor loading: Q8_0 wire (34B) -> 36B CPU blocks, F32 -> Vec.
        let f = std::cell::RefCell::new(std::fs::File::open(&path).expect("open gguf"));
        let desc = |name: &str| {
            gguf.tensors
                .iter()
                .find(|t| t.name == name)
                .unwrap_or_else(|| panic!("tensor {name} missing"))
        };
        let read_bytes = |name: &str| -> Vec<u8> {
            let d = desc(name);
            let mut bytes = vec![0u8; d.n_bytes as usize];
            let mut f = f.borrow_mut();
            f.seek(SeekFrom::Start(d.absolute_offset)).expect("seek");
            f.read_exact(&mut bytes).expect("read");
            bytes
        };
        fn f16_bits_to_f32(h: u16) -> f32 {
            let h = h as u32;
            let sign = (h & 0x8000) << 16;
            let exp = (h >> 10) & 0x1f;
            let man = h & 0x3ff;
            f32::from_bits(if exp == 0 && man == 0 {
                sign
            } else if exp == 0 {
                let mut e = 127 - 15 + 1;
                let mut m = man;
                while m & 0x400 == 0 {
                    m <<= 1;
                    e -= 1;
                }
                sign | ((e as u32) << 23) | ((m & 0x3ff) << 13)
            } else {
                sign | ((exp + 127 - 15) << 23) | (man << 13)
            })
        }
        let to_blocks36 = |wire: &[u8]| -> Vec<u8> {
            assert_eq!(wire.len() % 34, 0);
            let mut out = Vec::with_capacity(wire.len() / 34 * 36);
            for b in wire.chunks_exact(34) {
                let s = f16_bits_to_f32(u16::from_le_bytes([b[0], b[1]]));
                out.extend_from_slice(&s.to_le_bytes());
                out.extend_from_slice(&b[2..34]);
            }
            out
        };
        let to_f32 = |bytes: &[u8]| -> Vec<f32> {
            bytes
                .chunks_exact(4)
                .map(|c| f32::from_le_bytes(c.try_into().unwrap()))
                .collect()
        };
        let load_q8 = |name: &str| -> Vec<u8> {
            assert_eq!(desc(name).tensor_type, GgufTensorType::Q8_0, "{name}");
            let bytes = read_bytes(name);
            to_blocks36(&bytes)
        };
        let load_f32 = |name: &str| -> Vec<f32> {
            assert_eq!(desc(name).tensor_type, GgufTensorType::F32, "{name}");
            to_f32(&read_bytes(name))
        };

        struct LW {
            attn_norm: Vec<f32>,
            ffn_norm: Vec<f32>,
            q_norm: Vec<f32>,
            k_norm: Vec<f32>,
            post_attn_norm: Vec<f32>,
            post_ffw_norm: Vec<f32>,
            q: Vec<u8>,
            k: Vec<u8>,
            v: Vec<u8>,
            o: Vec<u8>,
            gate: Vec<u8>,
            up: Vec<u8>,
            down: Vec<u8>,
        }
        eprintln!("[real-row] loading {n_layers} layers from {path}");
        let data: Vec<LW> = (0..n_layers)
            .map(|li| {
                let p = |t: &str| format!("blk.{li}.{t}.weight");
                LW {
                    attn_norm: load_f32(&p("attn_norm")),
                    ffn_norm: load_f32(&p("ffn_norm")),
                    q_norm: load_f32(&p("attn_q_norm")),
                    k_norm: load_f32(&p("attn_k_norm")),
                    post_attn_norm: load_f32(&p("post_attention_norm")),
                    post_ffw_norm: load_f32(&p("post_ffw_norm")),
                    q: load_q8(&p("attn_q")),
                    k: load_q8(&p("attn_k")),
                    v: load_q8(&p("attn_v")),
                    o: load_q8(&p("attn_output")),
                    gate: load_q8(&p("ffn_gate")),
                    up: load_q8(&p("ffn_up")),
                    down: load_q8(&p("ffn_down")),
                }
            })
            .collect();
        let output_norm = load_f32("output_norm.weight");
        // Tied LM head: the row has no output.weight; the logits projection IS
        // the token embedding (runnable lane does the same).
        assert!(
            !gguf.tensors.iter().any(|t| t.name == "output.weight"),
            "expected a tied LM head on the 1B row"
        );
        let token_embd = load_q8("token_embd.weight");
        let bpr_hidden = hidden / 32;
        let vocab = token_embd.len() / 36 / bpr_hidden;

        let weights: Vec<ResidentLayerWeights> = data
            .iter()
            .map(|d| ResidentLayerWeights {
                attn_norm: &d.attn_norm,
                ffn_norm: &d.ffn_norm,
                q_norm: Some(&d.q_norm),
                k_norm: Some(&d.k_norm),
                post_attn_norm: Some(&d.post_attn_norm),
                post_ffw_norm: Some(&d.post_ffw_norm),
                ffn_geglu: g3.ffn_geglu,
                q_weight_blocks: ResidentWeightBytes::Blocks36(&d.q),
                k_weight_blocks: ResidentWeightBytes::Blocks36(&d.k),
                v_weight_blocks: ResidentWeightBytes::Blocks36(&d.v),
                o_weight_blocks: ResidentWeightBytes::Blocks36(&d.o),
                gate_weight_blocks: ResidentWeightBytes::Blocks36(&d.gate),
                up_weight_blocks: ResidentWeightBytes::Blocks36(&d.up),
                down_weight_blocks: ResidentWeightBytes::Blocks36(&d.down),
            })
            .collect();

        // Schedule straight from the parsed metadata — the same source the
        // production wiring uses.
        let schedule = ResidentLayerSchedule {
            use_alt_rope: (0..n_layers).map(|l| g3.is_sliding_layer(l)).collect(),
            window: (0..n_layers)
                .map(|l| g3.layer_window(l).map(|w| w as usize))
                .collect(),
        };
        let prompt: Vec<u32> = vec![2, 2364, 1077, 4056, 9062, 578, 6146, 236881];
        let gen_tokens = 50usize;
        let total = prompt.len() + gen_tokens;
        assert!(total < 512, "comparison must stay inside the window");
        let mut session = ResidentDecodeState::new(
            n_layers,
            n_heads,
            n_kv,
            head_dim,
            hidden,
            cfg.feed_forward_length as usize,
            total + 1,
            512,
            eps,
            g3.rope_neox_pairing, // forced split-half, from the metadata
            Some(schedule),
        )
        .expect("resident session");

        // Scaled embedding row, dequantized exactly like the oracle's
        // (f16-widened scale times i8 quant), times sqrt(d_model).
        let embed = |tok: u32| -> Vec<f32> {
            let base = tok as usize * bpr_hidden * 36;
            let mut row = Vec::with_capacity(hidden);
            for b in 0..bpr_hidden {
                let blk = &token_embd[base + b * 36..base + (b + 1) * 36];
                let s = f32::from_le_bytes(blk[..4].try_into().unwrap());
                for &q in &blk[4..36] {
                    row.push(q as i8 as f32 * s * g3.embed_scale);
                }
            }
            row
        };
        let mut forward = |tok: u32, pos: usize, want_logits: bool| -> Option<Vec<f32>> {
            let (cos_g, sin_g) =
                crate::inference::gemma3_rope_tables(pos, rope_dim, g3.rope_freq_base_global);
            let (cos_l, sin_l) =
                crate::inference::gemma3_rope_tables(pos, rope_dim, g3.rope_freq_base_local);
            let stage = want_logits.then_some(LogitsStage {
                final_norm: &output_norm,
                output_weight_blocks: ResidentWeightBytes::Blocks36(&token_embd),
                vocab_size: vocab,
            });
            match session
                .forward_token(
                    &embed(tok),
                    &weights,
                    &cos_g,
                    &sin_g,
                    Some((&cos_l, &sin_l)),
                    pos,
                    scale,
                    stage,
                    None,
                    0,
                    None,
                    None,
                )
                .expect("resident forward")
            {
                ResidentTokenOut::Data(v) => Some(v),
                ResidentTokenOut::Sampled(_) => panic!("unexpected sampled output"),
            }
        };

        // The oracle: the runnable lane, bit-pinned to HF transformers.
        eprintln!("[real-row] loading the runnable oracle");
        let oracle = crate::runnable::RunnableModel::load(&path).expect("runnable oracle");

        fn argmax(v: &[f32]) -> u32 {
            let mut best = 0usize;
            let mut best_v = f32::NEG_INFINITY;
            for (i, &x) in v.iter().enumerate() {
                if x > best_v {
                    best_v = x;
                    best = i;
                }
            }
            best as u32
        }

        // Token-by-token prefill through the decode path (gemma4 precedent):
        // the prompt runs the same per-token resident graph, no batched
        // prefill (head_dim 256 exceeds every prefill kernel cap by design).
        // The LAST prompt token is left for the first co-decode step, which
        // runs it with the logits stage attached.
        for (i, &tok) in prompt.iter().enumerate().take(prompt.len() - 1) {
            forward(tok, i, false);
        }

        // Greedy co-decode: at every step the resident argmax must equal the
        // oracle argmax; report the max abs logit diff at depths 1/5/50.
        let mut seq = prompt.clone();
        let mut max_abs_diff_overall = 0.0f32;
        for step in 0..gen_tokens {
            let oracle_logits = oracle.forward_logits(&seq).expect("oracle forward");
            let resident_logits =
                forward(*seq.last().unwrap(), seq.len() - 1, true).expect("resident logits");
            assert_eq!(resident_logits.len(), oracle_logits.len());
            let o_tok = argmax(&oracle_logits);
            let r_tok = argmax(&resident_logits);
            let mut max_diff = 0.0f32;
            for (a, b) in resident_logits.iter().zip(&oracle_logits) {
                max_diff = max_diff.max((a - b).abs());
            }
            max_abs_diff_overall = max_abs_diff_overall.max(max_diff);
            let depth = step + 1;
            if depth == 1 || depth == 5 || depth == 50 {
                eprintln!(
                    "[real-row] depth {depth}: argmax resident={r_tok} oracle={o_tok}, \
                     max |logit diff| = {max_diff:.3e}"
                );
            }
            if r_tok != o_tok {
                // Diagnose before failing: report the near-tie gap.
                let gap = oracle_logits[o_tok as usize] - oracle_logits[r_tok as usize];
                panic!(
                    "depth {depth}: argmax diverged (resident {r_tok} vs oracle {o_tok}, \
                     oracle logit gap {gap:.6}, max |logit diff| {max_diff:.3e})"
                );
            }
            seq.push(o_tok);
        }
        // Bookkeeping: every position except the final generated token (which
        // never needs its KV appended) went through the resident decode once.
        assert_eq!(session.filled(), prompt.len() + gen_tokens - 1);
        eprintln!(
            "[real-row] PASS: 50/50 greedy tokens identical to the runnable oracle; \
             overall max |logit diff| = {max_abs_diff_overall:.3e}"
        );
    }

    // gemma3 long-prompt TTFT campaign, Phase 2 — the window expression is written
    // ONCE (`schedule_window_bounds`) and shared by the token-by-token decode encode
    // and the batched windowed prefill. This pins it against the campaign's own
    // reference (`crate::window_ref::window_bounds`) so the two cannot drift, and
    // records the ONE input on which they deliberately disagree.
    #[cfg(target_os = "macos")]
    #[test]
    fn schedule_window_bounds_matches_window_ref() {
        for position in 0..2600usize {
            for window in [1usize, 2, 63, 64, 65, 511, 512, 513, 1024, 4096] {
                let filled = position + 1;
                assert_eq!(
                    schedule_window_bounds(Some(window), filled),
                    crate::window_ref::window_bounds(position, Some(window)),
                    "window {window} at position {position}"
                );
            }
            assert_eq!(
                schedule_window_bounds(None, position + 1),
                crate::window_ref::window_bounds(position, None),
                "full-causal layer at position {position}"
            );
        }
        // The one deliberate disagreement, recorded rather than discovered: the
        // degenerate `Some(0)`. `window_bounds` treats it as "disabled" (full
        // causal); the SHIPPED encode expression reads it literally as an empty
        // read range. Bit-identity with the shipped lane is the Tier A gate, so
        // the shipped expression is the one both callers run. No real schedule
        // produces 0 — `Gemma3Metadata::layer_window` yields `None` or a positive
        // window — so this is a documentation assert, not a behaviour claim.
        assert_eq!(schedule_window_bounds(Some(0), 7), (7, 0));
        assert_eq!(crate::window_ref::window_bounds(6, Some(0)), (0, 7));
    }

    // gemma3 long-prompt TTFT campaign, Phase 2 — GATE G1 on a SYNTHETIC fixture.
    //
    // The claim: `prefill_tokens_windowed` over `n` rows leaves the KV cache and
    // every row's final hidden BIT-IDENTICAL to `n` sequential `forward_token`
    // prefill decodes. Not "within a tolerance" — batching over the token dimension
    // re-associates no floating-point reduction (each output element's reduction
    // stays serial), so a differing bit is a bug, and the campaign's stopping rule
    // says fix it rather than lower the bar.
    //
    // The fixture carries all four features `prefill_tokens` fails closed on, so
    // this is not a degenerate pass: head_dim 256, a per-layer dual-theta schedule
    // with a mixed sliding/global cadence, both sandwich norms, GeGLU, and per-head
    // QK-norm. The final hidden is compared as well as the caches, because the LAST
    // layer's attention reaches no KV cache at all (§16e found a mutant that moves
    // zero cache bits).
    //
    // The length sweep straddles the chunk boundary (rows per command buffer = 4),
    // the window boundary (window = 6, so runs at 5/6/7 sit either side of
    // saturation), and single-row / exact-multiple / one-past cases.
    //
    // Run targeted, gates armed from the SHELL (they are process-latched OnceLocks):
    // CAMELID_METAL_F32Y=1 CAMELID_METAL_WIRE=1 CAMELID_METAL_WIRE_NSG8=1 \
    //   cargo test --release --lib metal_batched_windowed_prefill -- --nocapture
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_batched_windowed_prefill_is_bit_identical_to_token_by_token() {
        use crate::kv_equivalence::compare;
        if !detect_metal_device().available {
            return;
        }
        if !(f32y_gemv_enabled() && wire_weights_enabled() && wire_nsg8_enabled()) {
            eprintln!(
                "SKIP metal_batched_windowed_prefill_is_bit_identical_to_token_by_token: the \
                 production GEMV gates (f32y/wire/NSG8) are not armed; arm them from the shell \
                 (never from inside a test — they are process-wide OnceLocks)"
            );
            return;
        }
        let n_layers = 4usize;
        let n_heads = 4usize;
        let n_kv = 1usize;
        let head_dim = 256usize;
        let hidden = 1152usize;
        let ffn = 288usize;
        let window = 6usize;
        let eps = 1.0e-6f32;
        let scale = 1.0 / (head_dim as f32).sqrt();
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv * head_dim;
        let bpr_hidden = hidden / 32;
        let bpr_q = q_dim / 32;
        let bpr_ffn = ffn / 32;
        const CHUNK: usize = 4;

        struct LW {
            attn_norm: Vec<f32>,
            ffn_norm: Vec<f32>,
            q_norm: Vec<f32>,
            k_norm: Vec<f32>,
            post_attn_norm: Vec<f32>,
            post_ffw_norm: Vec<f32>,
            q: Vec<u8>,
            k: Vec<u8>,
            v: Vec<u8>,
            o: Vec<u8>,
            gate: Vec<u8>,
            up: Vec<u8>,
            down: Vec<u8>,
        }
        let data: Vec<LW> = (0..n_layers)
            .map(|li| {
                let s = li * 100;
                LW {
                    attn_norm: (0..hidden)
                        .map(|i| 0.5 + ((i + li) as f32 % 3.0) * 0.1)
                        .collect(),
                    ffn_norm: (0..hidden)
                        .map(|i| 0.4 + ((i + li) as f32 % 5.0) * 0.07)
                        .collect(),
                    q_norm: (0..head_dim)
                        .map(|i| 0.7 + ((i + li) as f32 % 11.0) * 0.02)
                        .collect(),
                    k_norm: (0..head_dim)
                        .map(|i| 0.6 + ((i + li) as f32 % 7.0) * 0.03)
                        .collect(),
                    post_attn_norm: (0..hidden)
                        .map(|i| 0.9 + ((i + li) as f32 % 3.0) * 0.03)
                        .collect(),
                    post_ffw_norm: (0..hidden)
                        .map(|i| 0.95 + ((i + li) as f32 % 6.0) * 0.02)
                        .collect(),
                    q: mk_w36(q_dim, bpr_hidden, s + 1),
                    k: mk_w36(kv_dim, bpr_hidden, s + 2),
                    v: mk_w36(kv_dim, bpr_hidden, s + 3),
                    o: mk_w36(hidden, bpr_q, s + 4),
                    gate: mk_w36(ffn, bpr_hidden, s + 5),
                    up: mk_w36(ffn, bpr_hidden, s + 6),
                    down: mk_w36(hidden, bpr_ffn, s + 7),
                }
            })
            .collect();
        // Two arch shapes through the SAME batched entry point:
        //   * "gemma3": sandwich norms + GeGLU + QK-norm + a dual-theta windowed
        //     schedule — everything `prefill_tokens` fails closed on;
        //   * "llama": no sandwich norms, SiLU, no QK-norm, no schedule — the
        //     regression that proves the added machinery is inert for every other
        //     arch (each `Option` is `None`, so the extra dispatches are not encoded
        //     at all and the residual sources are the un-normed buffers).
        let mk_views = |gemma3: bool| -> Vec<ResidentLayerWeights<'_>> {
            data.iter()
                .map(|d| ResidentLayerWeights {
                    attn_norm: &d.attn_norm,
                    ffn_norm: &d.ffn_norm,
                    q_norm: gemma3.then_some(d.q_norm.as_slice()),
                    k_norm: gemma3.then_some(d.k_norm.as_slice()),
                    post_attn_norm: gemma3.then_some(d.post_attn_norm.as_slice()),
                    post_ffw_norm: gemma3.then_some(d.post_ffw_norm.as_slice()),
                    ffn_geglu: gemma3,
                    q_weight_blocks: ResidentWeightBytes::Blocks36(&d.q),
                    k_weight_blocks: ResidentWeightBytes::Blocks36(&d.k),
                    v_weight_blocks: ResidentWeightBytes::Blocks36(&d.v),
                    o_weight_blocks: ResidentWeightBytes::Blocks36(&d.o),
                    gate_weight_blocks: ResidentWeightBytes::Blocks36(&d.gate),
                    up_weight_blocks: ResidentWeightBytes::Blocks36(&d.up),
                    down_weight_blocks: ResidentWeightBytes::Blocks36(&d.down),
                })
                .collect()
        };
        let emb_row = |t: usize| -> Vec<f32> {
            (0..hidden)
                .map(|i| ((((i * 7 + t * 13) % 23) as f32) - 11.0) * 0.13)
                .collect()
        };

        // Lengths: 1 (single row), 3 (partial chunk), 4/8 (exact chunk multiples),
        // 5/9 (one past a chunk edge), 6/7 (the window edge: filled == window and
        // the first clipped position), 13 (three chunks + a ragged tail), 17.
        for &n in &[1usize, 3, 4, 5, 6, 7, 8, 9, 13, 17] {
            for &gemma3 in &[true, false] {
                let weights = mk_views(gemma3);
                let schedule = gemma3.then(|| ResidentLayerSchedule {
                    // The 1B row's cadence in miniature: three sliding layers on the
                    // local theta, one global on the primary.
                    use_alt_rope: vec![true, true, true, false],
                    window: vec![Some(window), Some(window), Some(window), None],
                });
                let mk_session = || {
                    ResidentDecodeState::new(
                        n_layers,
                        n_heads,
                        n_kv,
                        head_dim,
                        hidden,
                        ffn,
                        n,
                        n,
                        eps,
                        true,
                        schedule.clone(),
                    )
                    .expect("resident session")
                };

                // --- the shipped lane: n sequential forward_token prefill decodes ---
                let mut token_session = mk_session();
                let mut token_hidden: Vec<f32> = Vec::with_capacity(n * hidden);
                for t in 0..n {
                    let (cos_g, sin_g) = crate::inference::gemma3_rope_tables(t, head_dim, 1.0e6);
                    let (cos_l, sin_l) = crate::inference::gemma3_rope_tables(t, head_dim, 1.0e4);
                    match token_session
                        .forward_token(
                            &emb_row(t),
                            &weights,
                            &cos_g,
                            &sin_g,
                            Some((&cos_l, &sin_l)),
                            t,
                            scale,
                            None,
                            None,
                            0,
                            None,
                            None,
                        )
                        .expect("resident forward")
                    {
                        ResidentTokenOut::Data(v) => token_hidden.extend_from_slice(&v),
                        ResidentTokenOut::Sampled(_) => panic!("unexpected sampled output"),
                    }
                }
                assert_eq!(token_session.filled(), n);

                // --- Tier A: one command buffer per chunk of CHUNK rows ---
                let mut embeddings: Vec<f32> = Vec::with_capacity(n * hidden);
                let mut cos_all: Vec<f32> = Vec::new();
                let mut sin_all: Vec<f32> = Vec::new();
                let mut alt_cos: Vec<f32> = Vec::new();
                let mut alt_sin: Vec<f32> = Vec::new();
                for t in 0..n {
                    embeddings.extend_from_slice(&emb_row(t));
                    let (c, s) = crate::inference::gemma3_rope_tables(t, head_dim, 1.0e6);
                    cos_all.extend_from_slice(&c);
                    sin_all.extend_from_slice(&s);
                    let (c, s) = crate::inference::gemma3_rope_tables(t, head_dim, 1.0e4);
                    alt_cos.extend_from_slice(&c);
                    alt_sin.extend_from_slice(&s);
                }
                let mut batch_session = mk_session();
                let batch_hidden = batch_session
                    .prefill_tokens_windowed_hidden(
                        &embeddings,
                        n,
                        &weights,
                        &cos_all,
                        &sin_all,
                        Some((&alt_cos, &alt_sin)),
                        scale,
                        CHUNK,
                        // G1 is a BIT-identity gate; pin the scalar GEMM explicitly so a
                        // shell with CAMELID_GEMMA3_PREFILL_MM armed cannot silently turn
                        // this assertion into a different claim.
                        PrefillGemm::ForceScalar,
                        // ... and pin the per-row attention too: Phase 4's batched
                        // attention is not bit-identical either.
                        PrefillAttn::ForceRow,
                    )
                    .expect("batched windowed prefill must be admitted for this fixture");
                // G11: `filled` must land on n exactly, or the caller's rebuild
                // predicate re-seeds from a hollow CPU KV cache.
                assert_eq!(
                    batch_session.filled(),
                    n,
                    "n={n} gemma3={gemma3}: batched prefill must leave filled == n"
                );

                let arch = if gemma3 { "gemma3" } else { "llama" };
                let eq = compare(
                    &token_session
                        .kv_snapshot(n)
                        .with_final_hidden(token_hidden.clone()),
                    &batch_session.kv_snapshot(n).with_final_hidden(batch_hidden),
                )
                .expect("same geometry");
                eq.assert_bit_identical(&format!(
                    "G1 (synthetic, {arch}): batched windowed prefill of {n} rows vs {n} \
                     token-by-token forwards, chunk {CHUNK}"
                ));
                assert_eq!(
                    eq.compared_elements(),
                    n_layers * 2 * n_kv * head_dim * n + n * hidden,
                    "n={n} {arch}: the comparison denominator must cover every cached K/V \
                     element AND every row's final hidden"
                );

                // Phase 3, FAIL-CLOSED SHAPE ADMISSION. This fixture's ffn_dim is 288 —
                // not a multiple of the tiled kernel's 128-row gate — so asking for the
                // MM GEMM must silently fall back to the scalar one and stay BIT-identical.
                // A shape gate that admitted 288 would corrupt the tail rows of every FFN
                // tile, which is precisely why the gate is asserted rather than assumed.
                assert!(
                    !ffn.is_multiple_of(2 * PREFILL_MM_ROW_TILE),
                    "this leg only means something while the fixture's ffn_dim is \
                     inadmissible for the tiled GEMM"
                );
                let mut mm_session = mk_session();
                let mm_hidden = mm_session
                    .prefill_tokens_windowed_hidden(
                        &embeddings,
                        n,
                        &weights,
                        &cos_all,
                        &sin_all,
                        Some((&alt_cos, &alt_sin)),
                        scale,
                        CHUNK,
                        PrefillGemm::ForceMm,
                        PrefillAttn::ForceRow,
                    )
                    .expect("an inadmissible shape must FALL BACK, never decline the prefill");
                compare(
                    &token_session
                        .kv_snapshot(n)
                        .with_final_hidden(token_hidden.clone()),
                    &mm_session.kv_snapshot(n).with_final_hidden(mm_hidden),
                )
                .expect("same geometry")
                .assert_bit_identical(&format!(
                    "Phase 3 admission (synthetic, {arch}): ffn_dim {ffn} is not a \
                     128-multiple, so ForceMm must fall back to the scalar GEMM"
                ));
            }
        }
        eprintln!(
            "[G1-synthetic] PASS: batched windowed prefill BIT-IDENTICAL to token-by-token \
             at n = 1/3/4/5/6/7/8/9/13/17 (chunk {CHUNK}, window {window}), for both the \
             gemma3 shape (dual-theta + sandwich norms + GeGLU + QK-norm) and the plain \
             llama shape"
        );
    }

    /// One decoder layer of the real gemma3-1B row, loaded from the GGUF into the
    /// 36-byte block layout the resident kernels take.
    #[cfg(target_os = "macos")]
    struct RealRowLayer {
        attn_norm: Vec<f32>,
        ffn_norm: Vec<f32>,
        q_norm: Vec<f32>,
        k_norm: Vec<f32>,
        post_attn_norm: Vec<f32>,
        post_ffw_norm: Vec<f32>,
        q: Vec<u8>,
        k: Vec<u8>,
        v: Vec<u8>,
        o: Vec<u8>,
        gate: Vec<u8>,
        up: Vec<u8>,
        down: Vec<u8>,
    }

    /// The real row, loaded once. Shared by the window mutation harness; the Phase 2
    /// final gate above keeps its own inline loader (it is a frozen receipt and is
    /// deliberately not refactored under a campaign that is changing prefill).
    #[cfg(target_os = "macos")]
    struct RealRow {
        g3: crate::model::Gemma3Metadata,
        layers: Vec<RealRowLayer>,
        output_norm: Vec<f32>,
        token_embd: Vec<u8>,
        vocab: usize,
        n_layers: usize,
        n_heads: usize,
        n_kv: usize,
        hidden: usize,
        head_dim: usize,
        rope_dim: usize,
        ffn: usize,
        eps: f32,
        scale: f32,
        split_half_pairing: bool,
    }

    #[cfg(target_os = "macos")]
    fn load_gemma3_real_row(path: &str) -> RealRow {
        use crate::gguf::{read_metadata, GgufTensorType};
        use crate::model::LlamaModelConfig;
        use std::io::{Read, Seek, SeekFrom};

        let gguf = read_metadata(path).expect("gguf metadata");
        let cfg = LlamaModelConfig::from_gguf(&gguf).expect("config");
        let g3 = cfg.gemma3.clone().expect("gemma3 metadata");
        let n_layers = cfg.block_count as usize;
        let n_heads = cfg.attention_head_count as usize;
        let n_kv = cfg.attention_head_count_kv as usize;
        let hidden = cfg.embedding_length as usize;
        let head_dim = cfg
            .attention_key_length
            .map(|v| v as usize)
            .unwrap_or(hidden / n_heads);
        let rope_dim = cfg
            .rope_dimension_count
            .map(|v| v as usize)
            .unwrap_or(head_dim);

        let f = std::cell::RefCell::new(std::fs::File::open(path).expect("open gguf"));
        let desc = |name: &str| {
            gguf.tensors
                .iter()
                .find(|t| t.name == name)
                .unwrap_or_else(|| panic!("tensor {name} missing"))
        };
        let read_bytes = |name: &str| -> Vec<u8> {
            let d = desc(name);
            let mut bytes = vec![0u8; d.n_bytes as usize];
            let mut f = f.borrow_mut();
            f.seek(SeekFrom::Start(d.absolute_offset)).expect("seek");
            f.read_exact(&mut bytes).expect("read");
            bytes
        };
        fn f16_bits_to_f32(h: u16) -> f32 {
            let h = h as u32;
            let sign = (h & 0x8000) << 16;
            let exp = (h >> 10) & 0x1f;
            let man = h & 0x3ff;
            f32::from_bits(if exp == 0 && man == 0 {
                sign
            } else if exp == 0 {
                let mut e = 127 - 15 + 1;
                let mut m = man;
                while m & 0x400 == 0 {
                    m <<= 1;
                    e -= 1;
                }
                sign | ((e as u32) << 23) | ((m & 0x3ff) << 13)
            } else {
                sign | ((exp + 127 - 15) << 23) | (man << 13)
            })
        }
        let load_q8 = |name: &str| -> Vec<u8> {
            assert_eq!(desc(name).tensor_type, GgufTensorType::Q8_0, "{name}");
            let wire = read_bytes(name);
            assert_eq!(wire.len() % 34, 0);
            let mut out = Vec::with_capacity(wire.len() / 34 * 36);
            for b in wire.chunks_exact(34) {
                let s = f16_bits_to_f32(u16::from_le_bytes([b[0], b[1]]));
                out.extend_from_slice(&s.to_le_bytes());
                out.extend_from_slice(&b[2..34]);
            }
            out
        };
        let load_f32 = |name: &str| -> Vec<f32> {
            assert_eq!(desc(name).tensor_type, GgufTensorType::F32, "{name}");
            read_bytes(name)
                .chunks_exact(4)
                .map(|c| f32::from_le_bytes(c.try_into().unwrap()))
                .collect()
        };
        let layers: Vec<RealRowLayer> = (0..n_layers)
            .map(|li| {
                let p = |t: &str| format!("blk.{li}.{t}.weight");
                RealRowLayer {
                    attn_norm: load_f32(&p("attn_norm")),
                    ffn_norm: load_f32(&p("ffn_norm")),
                    q_norm: load_f32(&p("attn_q_norm")),
                    k_norm: load_f32(&p("attn_k_norm")),
                    post_attn_norm: load_f32(&p("post_attention_norm")),
                    post_ffw_norm: load_f32(&p("post_ffw_norm")),
                    q: load_q8(&p("attn_q")),
                    k: load_q8(&p("attn_k")),
                    v: load_q8(&p("attn_v")),
                    o: load_q8(&p("attn_output")),
                    gate: load_q8(&p("ffn_gate")),
                    up: load_q8(&p("ffn_up")),
                    down: load_q8(&p("ffn_down")),
                }
            })
            .collect();
        let output_norm = load_f32("output_norm.weight");
        assert!(
            !gguf.tensors.iter().any(|t| t.name == "output.weight"),
            "expected a tied LM head on the 1B row"
        );
        let token_embd = load_q8("token_embd.weight");
        let vocab = token_embd.len() / 36 / (hidden / 32);
        RealRow {
            split_half_pairing: g3.rope_neox_pairing,
            g3,
            layers,
            output_norm,
            token_embd,
            vocab,
            n_layers,
            n_heads,
            n_kv,
            hidden,
            head_dim,
            rope_dim,
            ffn: cfg.feed_forward_length as usize,
            eps: cfg.rms_norm_epsilon,
            scale: 1.0 / (head_dim as f32).sqrt(),
        }
    }

    #[cfg(target_os = "macos")]
    impl RealRow {
        fn weights(&self) -> Vec<ResidentLayerWeights<'_>> {
            self.layers
                .iter()
                .map(|d| ResidentLayerWeights {
                    attn_norm: &d.attn_norm,
                    ffn_norm: &d.ffn_norm,
                    q_norm: Some(&d.q_norm),
                    k_norm: Some(&d.k_norm),
                    post_attn_norm: Some(&d.post_attn_norm),
                    post_ffw_norm: Some(&d.post_ffw_norm),
                    ffn_geglu: self.g3.ffn_geglu,
                    q_weight_blocks: ResidentWeightBytes::Blocks36(&d.q),
                    k_weight_blocks: ResidentWeightBytes::Blocks36(&d.k),
                    v_weight_blocks: ResidentWeightBytes::Blocks36(&d.v),
                    o_weight_blocks: ResidentWeightBytes::Blocks36(&d.o),
                    gate_weight_blocks: ResidentWeightBytes::Blocks36(&d.gate),
                    up_weight_blocks: ResidentWeightBytes::Blocks36(&d.up),
                    down_weight_blocks: ResidentWeightBytes::Blocks36(&d.down),
                })
                .collect()
        }

        /// The PRODUCTION schedule, straight from the parsed metadata — the same
        /// source the serve wiring reads. Every mutant below is a perturbation of
        /// exactly this object.
        fn schedule(&self) -> ResidentLayerSchedule {
            ResidentLayerSchedule {
                use_alt_rope: (0..self.n_layers)
                    .map(|l| self.g3.is_sliding_layer(l))
                    .collect(),
                window: (0..self.n_layers)
                    .map(|l| self.g3.layer_window(l).map(|w| w as usize))
                    .collect(),
            }
        }

        fn embed(&self, tok: u32) -> Vec<f32> {
            let bpr = self.hidden / 32;
            let base = tok as usize * bpr * 36;
            let mut row = Vec::with_capacity(self.hidden);
            for b in 0..bpr {
                let blk = &self.token_embd[base + b * 36..base + (b + 1) * 36];
                let s = f32::from_le_bytes(blk[..4].try_into().unwrap());
                for &q in &blk[4..36] {
                    row.push(q as i8 as f32 * s * self.g3.embed_scale);
                }
            }
            row
        }
    }

    // gemma3 long-prompt TTFT campaign, Phase 2 — the CHUNK-WIDTH probe.
    //
    // The chunk width is the one free parameter Tier A has, and the naive reading
    // ("wider amortizes the weights further, so wider is better") is wrong on this
    // kernel. The batched-column GEMV is a GEMV, not a tiled GEMM: every threadgroup
    // walks the WHOLE activation panel, so activation traffic per token is
    // `sum_projections(out_rows / 2 * in_dim * 4)` — about 53 MB per layer per token
    // on this row, and INDEPENDENT of the chunk width. What the chunk width does
    // control is whether that panel is small enough to be served from cache: at 256
    // rows the FFN activation panel is `256 * 6912 * 4` = 7.1 MB and the `down`
    // projection re-reads it 576 times per layer; at 64 rows it is 1.8 MB.
    //
    // Weight traffic runs the other way — 0.74 GB per layer-sweep, so 11.6 MB/token
    // at 64 rows and 46 MB/token at 16 — which is why the answer is a measurement and
    // not an argument. This probe is that measurement, and the default it picks is
    // recorded in the phase record rather than being folded into the code silently.
    //
    // Timing-only: correctness is `gemma3_real_row_batched_prefill_kv_bit_identical`.
    // Skipped unless CAMELID_GEMMA3_CHUNK_PROBE is set, because a wall-clock probe in
    // the default suite would be noise on a shared host.
    //
    // CAMELID_METAL_F32Y=1 CAMELID_METAL_WIRE=1 CAMELID_METAL_WIRE_NSG8=1 \
    // CAMELID_GEMMA3_GGUF=<gguf> CAMELID_GEMMA3_CHUNK_PROBE=1 \
    //   cargo test --release --lib gemma3_real_row_batched_prefill_chunk -- --nocapture
    #[cfg(target_os = "macos")]
    #[test]
    fn gemma3_real_row_batched_prefill_chunk_width_probe() {
        if !detect_metal_device().available
            || std::env::var_os("CAMELID_GEMMA3_CHUNK_PROBE").is_none()
        {
            return;
        }
        let Some(path) = std::env::var_os("CAMELID_GEMMA3_GGUF") else {
            eprintln!("SKIP chunk-width probe: set CAMELID_GEMMA3_GGUF");
            return;
        };
        if !(f32y_gemv_enabled() && wire_weights_enabled() && wire_nsg8_enabled()) {
            eprintln!("SKIP chunk-width probe: the production GEMV gates are not armed");
            return;
        }
        let row = load_gemma3_real_row(&path.to_string_lossy());
        let weights = row.weights();
        let schedule = row.schedule();
        let n = 1200usize;
        let token_at = |i: usize| -> u32 { (2 + (i * 7919) % (row.vocab - 3)) as u32 };
        let mut embeddings: Vec<f32> = Vec::with_capacity(n * row.hidden);
        let mut cos_all: Vec<f32> = Vec::new();
        let mut sin_all: Vec<f32> = Vec::new();
        let mut alt_cos: Vec<f32> = Vec::new();
        let mut alt_sin: Vec<f32> = Vec::new();
        for t in 0..n {
            embeddings.extend_from_slice(&row.embed(token_at(t)));
            let (c, s) =
                crate::inference::gemma3_rope_tables(t, row.rope_dim, row.g3.rope_freq_base_global);
            cos_all.extend_from_slice(&c);
            sin_all.extend_from_slice(&s);
            let (c, s) =
                crate::inference::gemma3_rope_tables(t, row.rope_dim, row.g3.rope_freq_base_local);
            alt_cos.extend_from_slice(&c);
            alt_sin.extend_from_slice(&s);
        }
        let mk_session = || {
            ResidentDecodeState::new(
                row.n_layers,
                row.n_heads,
                row.n_kv,
                row.head_dim,
                row.hidden,
                row.ffn,
                n,
                n,
                row.eps,
                row.split_half_pairing,
                Some(schedule.clone()),
            )
            .expect("resident session")
        };
        // Warm the weight cache and the pipelines with one small batched run, so the
        // first measured chunk width does not carry the upload.
        {
            let mut warm = mk_session();
            warm.prefill_tokens_windowed(
                &embeddings[..8 * row.hidden],
                8,
                &weights,
                &cos_all[..8 * (row.rope_dim / 2)],
                &sin_all[..8 * (row.rope_dim / 2)],
                Some((
                    &alt_cos[..8 * (row.rope_dim / 2)],
                    &alt_sin[..8 * (row.rope_dim / 2)],
                )),
                row.scale,
                8,
            )
            .expect("warm-up");
        }
        for &chunk in &[16usize, 32, 64, 128, 256, 512] {
            let mut session = mk_session();
            let started = std::time::Instant::now();
            session
                .prefill_tokens_windowed(
                    &embeddings,
                    n,
                    &weights,
                    &cos_all,
                    &sin_all,
                    Some((&alt_cos, &alt_sin)),
                    row.scale,
                    chunk,
                )
                .expect("batched windowed prefill");
            let s = started.elapsed().as_secs_f64();
            eprintln!(
                "[chunk-probe] rows={chunk:4}  n={n}  {s:7.3}s  {:6.3} ms/token  load {:.2}",
                s * 1000.0 / n as f64,
                loadavg_1m()
            );
        }
        // Token-by-token baseline in the same process, same weights, same warm cache.
        let mut token_session = mk_session();
        let half = row.rope_dim / 2;
        let started = std::time::Instant::now();
        for t in 0..n {
            token_session
                .forward_token(
                    &embeddings[t * row.hidden..(t + 1) * row.hidden],
                    &weights,
                    &cos_all[t * half..(t + 1) * half],
                    &sin_all[t * half..(t + 1) * half],
                    Some((
                        &alt_cos[t * half..(t + 1) * half],
                        &alt_sin[t * half..(t + 1) * half],
                    )),
                    t,
                    row.scale,
                    None,
                    None,
                    0,
                    // Encode-ahead armed, as the production prefill loop has it — the
                    // baseline must be the lane as it actually runs, not a handicapped one.
                    (t + 1 < n).then(|| {
                        (
                            &cos_all[(t + 1) * half..(t + 2) * half],
                            &sin_all[(t + 1) * half..(t + 2) * half],
                        )
                    }),
                    (t + 1 < n).then(|| {
                        (
                            &alt_cos[(t + 1) * half..(t + 2) * half],
                            &alt_sin[(t + 1) * half..(t + 2) * half],
                        )
                    }),
                )
                .expect("resident forward");
        }
        let s = started.elapsed().as_secs_f64();
        eprintln!(
            "[chunk-probe] token-by-token  n={n}  {s:7.3}s  {:6.3} ms/token  load {:.2}",
            s * 1000.0 / n as f64,
            loadavg_1m()
        );
    }

    /// 1-minute load average, so every timing line carries the host condition it was
    /// taken under (the campaign's Phase 0 rule: a 6–15 % host spread must not be
    /// mistaken for a lever).
    #[cfg(target_os = "macos")]
    fn loadavg_1m() -> f64 {
        let mut avg = [0.0f64; 3];
        // SAFETY: `getloadavg` fills at most `nelem` doubles into the caller's array.
        let n = unsafe { libc::getloadavg(avg.as_mut_ptr(), 3) };
        if n > 0 {
            avg[0]
        } else {
            f64::NAN
        }
    }

    // gemma3 long-prompt TTFT campaign, Phase 2 — GATE G1 ON THE REAL ROW.
    //
    // The synthetic twin above proves the batched encode on a 4-layer fixture; this
    // proves it on the shipped weights, the shipped 22-sliding/4-global schedule and
    // the shipped head_dim 256, at prompt lengths that straddle the 512-position
    // window and the 256-row chunk boundary. Bit-identity is the gate: batching over
    // the token dimension moves no floating-point reduction, so there is no tolerance
    // to negotiate.
    //
    // Both sides are fed the SAME embedding array, so an embedding-lookup difference
    // cannot mask or manufacture a result — the claim is about the encode.
    //
    // Cost note (machine constraint): one process, one model load, no server. The
    // token-by-token side is the expensive half (n sequential command buffers), which
    // is why the sweep tops out at 1 024 rather than 2 400.
    //
    // Run targeted, gates armed from the SHELL:
    // CAMELID_METAL_F32Y=1 CAMELID_METAL_WIRE=1 CAMELID_METAL_WIRE_NSG8=1 \
    // CAMELID_GEMMA3_GGUF=/path/gemma-3-1b-it-Q8_0.gguf \
    //   cargo test --release --lib gemma3_real_row_batched_prefill -- --nocapture
    #[cfg(target_os = "macos")]
    #[test]
    fn gemma3_real_row_batched_prefill_kv_bit_identical() {
        use crate::kv_equivalence::compare;
        if !detect_metal_device().available {
            return;
        }
        let Some(path) = std::env::var_os("CAMELID_GEMMA3_GGUF") else {
            eprintln!(
                "SKIP gemma3_real_row_batched_prefill_kv_bit_identical: set CAMELID_GEMMA3_GGUF \
                 to the gemma-3-1b-it-Q8_0 GGUF"
            );
            return;
        };
        if !(f32y_gemv_enabled() && wire_weights_enabled() && wire_nsg8_enabled()) {
            eprintln!(
                "SKIP gemma3_real_row_batched_prefill_kv_bit_identical: the production GEMV \
                 gates (f32y/wire/NSG8) are not armed; arm them from the shell."
            );
            return;
        }
        let row = load_gemma3_real_row(&path.to_string_lossy());
        let weights = row.weights();
        let schedule = row.schedule();
        assert_eq!(
            schedule.window.iter().filter(|w| w.is_some()).count(),
            22,
            "expected the 1B row's 22 sliding / 4 global cadence"
        );
        assert_eq!(row.head_dim, 256, "expected the 1B row's head_dim");

        // A deterministic pseudo-prompt over real vocab ids: content does not matter
        // for a bit-identity gate, coverage of the window and chunk edges does.
        let token_at = |i: usize| -> u32 { (2 + (i * 7919) % (row.vocab - 3)) as u32 };
        // 5   — inside one chunk, window not yet saturated;
        // 256 — exactly one chunk;
        // 257 — one row past a chunk edge (a two-chunk run with a 1-row tail);
        // 513 — two chunks past the 512 window AND one past 512;
        // 1024 — four chunks, deep window clipping on all 22 sliding layers.
        for &n in &[5usize, 256, 257, 513, 1024] {
            let prompt: Vec<u32> = (0..n).map(token_at).collect();
            let mut embeddings: Vec<f32> = Vec::with_capacity(n * row.hidden);
            let mut cos_all: Vec<f32> = Vec::new();
            let mut sin_all: Vec<f32> = Vec::new();
            let mut alt_cos: Vec<f32> = Vec::new();
            let mut alt_sin: Vec<f32> = Vec::new();
            for (t, &tok) in prompt.iter().enumerate() {
                embeddings.extend_from_slice(&row.embed(tok));
                let (c, s) = crate::inference::gemma3_rope_tables(
                    t,
                    row.rope_dim,
                    row.g3.rope_freq_base_global,
                );
                cos_all.extend_from_slice(&c);
                sin_all.extend_from_slice(&s);
                let (c, s) = crate::inference::gemma3_rope_tables(
                    t,
                    row.rope_dim,
                    row.g3.rope_freq_base_local,
                );
                alt_cos.extend_from_slice(&c);
                alt_sin.extend_from_slice(&s);
            }
            let mk_session = || {
                ResidentDecodeState::new(
                    row.n_layers,
                    row.n_heads,
                    row.n_kv,
                    row.head_dim,
                    row.hidden,
                    row.ffn,
                    n,
                    n,
                    row.eps,
                    row.split_half_pairing,
                    Some(schedule.clone()),
                )
                .expect("resident session")
            };

            let started = std::time::Instant::now();
            let mut token_session = mk_session();
            let mut token_hidden: Vec<f32> = Vec::with_capacity(n * row.hidden);
            for t in 0..n {
                let half = row.rope_dim / 2;
                match token_session
                    .forward_token(
                        &embeddings[t * row.hidden..(t + 1) * row.hidden],
                        &weights,
                        &cos_all[t * half..(t + 1) * half],
                        &sin_all[t * half..(t + 1) * half],
                        Some((
                            &alt_cos[t * half..(t + 1) * half],
                            &alt_sin[t * half..(t + 1) * half],
                        )),
                        t,
                        row.scale,
                        None,
                        None,
                        0,
                        None,
                        None,
                    )
                    .expect("resident forward")
                {
                    ResidentTokenOut::Data(v) => token_hidden.extend_from_slice(&v),
                    ResidentTokenOut::Sampled(_) => panic!("unexpected sampled output"),
                }
            }
            assert_eq!(token_session.filled(), n);
            let token_s = started.elapsed().as_secs_f64();

            let started = std::time::Instant::now();
            let mut batch_session = mk_session();
            let batch_hidden = batch_session
                .prefill_tokens_windowed_hidden(
                    &embeddings,
                    n,
                    &weights,
                    &cos_all,
                    &sin_all,
                    Some((&alt_cos, &alt_sin)),
                    row.scale,
                    256,
                    PrefillGemm::ForceScalar,
                    PrefillAttn::ForceRow,
                )
                .expect("batched windowed prefill must be admitted for the real row");
            assert_eq!(
                batch_session.filled(),
                n,
                "n={n}: batched prefill must leave filled == n (G11)"
            );
            let batch_s = started.elapsed().as_secs_f64();

            let eq = compare(
                &token_session
                    .kv_snapshot(n)
                    .with_final_hidden(token_hidden.clone()),
                &batch_session.kv_snapshot(n).with_final_hidden(batch_hidden),
            )
            .expect("same geometry");
            eprintln!(
                "[G1-real-row] n={n}: token-by-token {token_s:.2}s, batched {batch_s:.2}s \
                 ({:.2}x), compared {} elements, bit_identical={}",
                token_s / batch_s.max(1.0e-9),
                eq.compared_elements(),
                eq.bit_identical
            );
            eq.assert_bit_identical(&format!(
                "G1 (real row): batched windowed prefill of {n} rows vs {n} token-by-token \
                 forwards, chunk 256"
            ));
        }
        eprintln!(
            "[G1-real-row] PASS: bit-identical KV AND final hidden at n = 5/256/257/513/1024"
        );
    }

    /// The Phase 3 cache envelope. §18a pinned `5.0e-2` ABSOLUTE before measuring and
    /// **that pin FAILED**; §18b amends it to a RELATIVE bound and says why. The failure
    /// is on the record with its numbers rather than edited out.
    ///
    /// What §18a got wrong was the scale, not the reasoning. It argued correctly that
    /// half round-to-nearest (2^-11 = 4.883e-4 relative, per operand element) puts the
    /// f32-reduction-noise floor out of reach — then picked an absolute number as if this
    /// row's K/V were O(1). Measured, they are not: `kv_scale` reaches 1.396e2 at n=256,
    /// so `5.0e-2` is 3.6e-4 RELATIVE — below the half round-off floor the same paragraph
    /// had just derived. It was unreachable by arithmetic, which is exactly the failure
    /// mode §18a set out to avoid.
    ///
    /// `2.0e-3` is pinned relative to the caches' own max magnitude. Both ends are still
    /// real: half staging on two operands is ~9.8e-4 per GEMM output before cancellation,
    /// so the bound is ~2x the single-GEMM floor; and the weakest window-mutation signature
    /// on record (max |ΔKV| 4.29e-1, `w-len-513`/`window_plus_one`, §16g) is 3.1e-3
    /// relative at this row's kv_scale — so the scalar half STILL excludes every recorded
    /// mutant, by 1.5x. That margin is thin, which is why the outlier half is the half
    /// the gate leans on (§16g) and why §18b says so out loud.
    #[cfg(target_os = "macos")]
    const PHASE3_KV_REL_BOUND: f32 = 2.0e-3;

    /// The half of the envelope with the power (§16g). Mutants whose per-position median
    /// is non-zero show ratios of 41x - 1525x; `w-len-513`'s median is exactly 0.0, where
    /// any finite factor fires. 8.0 keeps a 5.1x margin below the weakest recorded ratio
    /// while still allowing a real 8x per-position spread for a uniform numerics change.
    #[cfg(target_os = "macos")]
    const PHASE3_KV_OUTLIER_FACTOR: f32 = 8.0;

    /// The final hidden's bound, AMENDED in §18b after §18a's single scalar failed on
    /// this clause — disclosed there with the number that forced it, not quietly moved.
    ///
    /// It is RELATIVE, and the justification is arithmetic rather than measured: half
    /// round-to-nearest is 2^-11 = 4.883e-4 relative per element, both GEMM operands
    /// stage in half (~9.8e-4 per output before any cancellation), and the residual
    /// stream sums 52 such GEMM-fed blocks (26 layers x attention + FFN). Independent
    /// errors add in quadrature: sqrt(52) x 9.8e-4 = 7.1e-3. 1.0e-2 is that ceiling
    /// rounded up. The caches carry the pinned ABSOLUTE bound because they are the
    /// observable the campaign's mutation signatures are recorded against.
    #[cfg(target_os = "macos")]
    const PHASE3_HIDDEN_REL_BOUND: f32 = 1.0e-2;

    // gemma3 long-prompt TTFT campaign, Phase 3 — GATE G6 on the REAL row.
    //
    // The claim Phase 3 can make and Phase 2's could not: the tiled simdgroup-matmul
    // prefill leaves the KV cache and every row's final hidden WITHIN A PUBLISHED
    // ENVELOPE of `n` sequential `forward_token` prefill decodes — not bit-identical,
    // because the dequantized Q8_0 weight and the activation panel stage in half and the
    // MMA accumulates in tile order.
    //
    // Both halves of `meets_bound` are load-bearing and they catch different things:
    //   * the scalar bound catches a kernel that is uniformly wrong;
    //   * the per-position outlier test catches a mask/stride defect that touches few
    //     positions hard — which is the shape EVERY window mutant has (§16g), including
    //     the one whose per-position median is exactly 0.0.
    // The final hidden is bounded separately, because the LAST layer's attention reaches
    // no KV cache and a defect confined to it moves zero cache bits (§16e).
    //
    // The lengths are the Phase 2 G1 sweep verbatim, so the two gates are directly
    // comparable: 5 (inside one chunk, window unsaturated), 256 (exactly one chunk),
    // 257 (a 1-row ragged tail — the kernel's guarded store path), 513 (past the window
    // AND past 512), 1024 (four chunks, deep clipping on all 22 sliding layers).
    //
    // Run targeted, gates armed from the SHELL (process-latched OnceLocks):
    // CAMELID_METAL_F32Y=1 CAMELID_METAL_WIRE=1 CAMELID_METAL_WIRE_NSG8=1 \
    // CAMELID_GEMMA3_GGUF=/path/gemma-3-1b-it-Q8_0.gguf \
    //   cargo test --release --lib gemma3_real_row_prefill_mm_kv -- --nocapture
    #[cfg(target_os = "macos")]
    #[test]
    fn gemma3_real_row_prefill_mm_kv_meets_published_envelope() {
        use crate::kv_equivalence::compare;
        if !detect_metal_device().available {
            return;
        }
        let Some(path) = std::env::var_os("CAMELID_GEMMA3_GGUF") else {
            eprintln!(
                "SKIP gemma3_real_row_prefill_mm_kv_meets_published_envelope: set \
                 CAMELID_GEMMA3_GGUF to the gemma-3-1b-it-Q8_0 GGUF"
            );
            return;
        };
        if !(f32y_gemv_enabled() && wire_weights_enabled() && wire_nsg8_enabled()) {
            eprintln!(
                "SKIP gemma3_real_row_prefill_mm_kv_meets_published_envelope: the production \
                 GEMV gates (f32y/wire/NSG8) are not armed; arm them from the shell."
            );
            return;
        }
        let row = load_gemma3_real_row(&path.to_string_lossy());
        let weights = row.weights();
        let schedule = row.schedule();
        assert_eq!(row.head_dim, 256, "expected the 1B row's head_dim");

        let token_at = |i: usize| -> u32 { (2 + (i * 7919) % (row.vocab - 3)) as u32 };
        let mut worst_kv = 0.0f32;
        let mut worst_hidden = 0.0f32;
        let mut failures: Vec<String> = Vec::new();
        // 2400 is the campaign's headline prompt length and is carried here on purpose:
        // the per-position outlier ratio GROWS with depth (deeper positions accumulate
        // more round-off while the median barely moves), so the length that matters most
        // is also the one where the outlier half has least margin.
        for &n in &[5usize, 256, 257, 513, 1024, 2400] {
            let mut embeddings: Vec<f32> = Vec::with_capacity(n * row.hidden);
            let mut cos_all: Vec<f32> = Vec::new();
            let mut sin_all: Vec<f32> = Vec::new();
            let mut alt_cos: Vec<f32> = Vec::new();
            let mut alt_sin: Vec<f32> = Vec::new();
            for t in 0..n {
                embeddings.extend_from_slice(&row.embed(token_at(t)));
                let (c, s) = crate::inference::gemma3_rope_tables(
                    t,
                    row.rope_dim,
                    row.g3.rope_freq_base_global,
                );
                cos_all.extend_from_slice(&c);
                sin_all.extend_from_slice(&s);
                let (c, s) = crate::inference::gemma3_rope_tables(
                    t,
                    row.rope_dim,
                    row.g3.rope_freq_base_local,
                );
                alt_cos.extend_from_slice(&c);
                alt_sin.extend_from_slice(&s);
            }
            let mk_session = || {
                ResidentDecodeState::new(
                    row.n_layers,
                    row.n_heads,
                    row.n_kv,
                    row.head_dim,
                    row.hidden,
                    row.ffn,
                    n,
                    n,
                    row.eps,
                    row.split_half_pairing,
                    Some(schedule.clone()),
                )
                .expect("resident session")
            };

            // The reference is the SHIPPED token-by-token lane, not the Phase 2 batched
            // one: Phase 2 is bit-identical to it, so this measures the whole distance
            // Phase 3 travels rather than a distance from an intermediate.
            let mut token_session = mk_session();
            let mut token_hidden: Vec<f32> = Vec::with_capacity(n * row.hidden);
            let half = row.rope_dim / 2;
            for t in 0..n {
                match token_session
                    .forward_token(
                        &embeddings[t * row.hidden..(t + 1) * row.hidden],
                        &weights,
                        &cos_all[t * half..(t + 1) * half],
                        &sin_all[t * half..(t + 1) * half],
                        Some((
                            &alt_cos[t * half..(t + 1) * half],
                            &alt_sin[t * half..(t + 1) * half],
                        )),
                        t,
                        row.scale,
                        None,
                        None,
                        0,
                        None,
                        None,
                    )
                    .expect("resident forward")
                {
                    ResidentTokenOut::Data(v) => token_hidden.extend_from_slice(&v),
                    ResidentTokenOut::Sampled(_) => panic!("unexpected sampled output"),
                }
            }
            assert_eq!(token_session.filled(), n);

            let mut mm_session = mk_session();
            let mm_hidden = mm_session
                .prefill_tokens_windowed_hidden(
                    &embeddings,
                    n,
                    &weights,
                    &cos_all,
                    &sin_all,
                    Some((&alt_cos, &alt_sin)),
                    row.scale,
                    256,
                    PrefillGemm::ForceMm,
                    PrefillAttn::ForceRow,
                )
                .expect("the tiled-MM prefill must be admitted for the real row");
            assert_eq!(
                mm_session.filled(),
                n,
                "n={n}: batched prefill must leave filled == n (G11)"
            );

            // The reference magnitudes, reported alongside every delta. §18a's original
            // single-scalar pin covered the caches AND the final hidden with one number,
            // and that was an error of KIND, not of value: the two tensors live three
            // orders of magnitude apart on this row (K is post-QK-norm, V is a projection
            // of a normed vector; the final hidden is the whole 26-layer residual stream).
            // §18b amends it; the numbers that forced the amendment are printed here.
            let token_snapshot = token_session.kv_snapshot(n);
            let amax = |xs: &[f32]| xs.iter().fold(0.0f32, |m, x| m.max(x.abs()));
            let kv_scale = token_snapshot
                .k
                .iter()
                .chain(&token_snapshot.v)
                .fold(0.0f32, |m, b| m.max(amax(b)));
            let hidden_scale = amax(&token_hidden);

            let eq = compare(
                &token_snapshot
                    .clone()
                    .with_final_hidden(token_hidden.clone()),
                &mm_session.kv_snapshot(n).with_final_hidden(mm_hidden),
            )
            .expect("same geometry");
            let median = eq.median_position_max_abs();
            eprintln!(
                "[G6-mm] n={n}: {} outlier_ratio={:.1}x kv_scale={kv_scale:.3e} \
                 kv_rel={:.3e} hidden_scale={hidden_scale:.3e} hidden_rel={:.3e}",
                eq.summary(),
                if median > 0.0 {
                    eq.max_abs_diff / median
                } else {
                    f32::INFINITY
                },
                eq.max_abs_diff / kv_scale.max(f32::MIN_POSITIVE),
                eq.hidden_max_abs_diff / hidden_scale.max(f32::MIN_POSITIVE),
            );
            // A pass here must not be a pass by vacuity: the MM path is NOT expected to
            // be bit-identical, and if it ever were, the fixture would have silently
            // fallen back to the scalar GEMM and this gate would be testing nothing.
            assert!(
                !eq.bit_identical,
                "n={n}: the tiled-MM prefill came out bit-identical — it must have fallen \
                 back to the scalar GEMM, so this gate proved nothing"
            );
            // THE PINNED GATE, on the caches. Run on a cache-only comparison so the
            // scalar bound means one thing on one scale, and scaled by the caches' own
            // magnitude — §18b. Failures are COLLECTED, not raised: a bound is amended
            // from the whole curve, never from the first length that trips it.
            let eq_caches =
                compare(&token_snapshot, &mm_session.kv_snapshot(n)).expect("same geometry");
            let cache_bound = PHASE3_KV_REL_BOUND * kv_scale;
            if let Err(why) = eq_caches.meets_bound(cache_bound, PHASE3_KV_OUTLIER_FACTOR) {
                failures.push(format!(
                    "n={n}: cache envelope (bound {PHASE3_KV_REL_BOUND:.3e} x kv_scale \
                     {kv_scale:.4e} = {cache_bound:.4e}, outlier factor \
                     {PHASE3_KV_OUTLIER_FACTOR}) — {why}"
                ));
            }
            // The final hidden, on its own scale (§18b). It is checked separately and is
            // NOT optional: the LAST layer's attention reaches no KV cache, so a defect
            // confined to it moves zero cache elements (§16e).
            if eq.hidden_max_abs_diff > PHASE3_HIDDEN_REL_BOUND * hidden_scale {
                failures.push(format!(
                    "n={n}: max |final_hidden diff| {:.6e} exceeds {PHASE3_HIDDEN_REL_BOUND:.3e} \
                     x the reference hidden's own magnitude {hidden_scale:.6e} (= {:.6e})",
                    eq.hidden_max_abs_diff,
                    PHASE3_HIDDEN_REL_BOUND * hidden_scale
                ));
            }
            worst_kv = worst_kv.max(eq.max_abs_diff / kv_scale);
            worst_hidden = worst_hidden.max(eq.hidden_max_abs_diff / hidden_scale);
        }
        assert!(
            failures.is_empty(),
            "G6 (real row): the tiled-MM prefill misses the envelope published in \
             GEMMA3_METAL_CONDUCTOR.md §18a/§18b at {} of 5 lengths:\n  {}",
            failures.len(),
            failures.join("\n  ")
        );
        eprintln!(
            "[G6-mm] PASS at n = 5/256/257/513/1024/2400: worst cache RELATIVE diff \
             {worst_kv:.6e} (bound {PHASE3_KV_REL_BOUND:.3e}), worst hidden RELATIVE diff \
             {worst_hidden:.6e} (bound {PHASE3_HIDDEN_REL_BOUND:.3e}), outlier factor \
             {PHASE3_KV_OUTLIER_FACTOR}"
        );
    }

    // gemma3 long-prompt TTFT campaign, Phase 4 — GATE G6 for Tier B.
    //
    // Same envelope, unmoved: the §18b bounds (`PHASE3_KV_REL_BOUND` 2.0e-3 x the
    // caches' own magnitude, `PHASE3_HIDDEN_REL_BOUND` 1.0e-2 relative,
    // `PHASE3_KV_OUTLIER_FACTOR` 8.0) were pinned and committed BEFORE Phase 3 measured
    // anything, and Phase 4 does not widen them. That is deliberate and it is the whole
    // gate: the scalar half already sits only 1.5x below the weakest recorded window
    // mutation (4.29e-1 absolute = 3.1e-3 relative, §18b), so there is no room to widen
    // it and still be separating numerics from mask defects. If batched attention does
    // not fit inside the bound Phase 3 published, that is a Phase 4 failure reported as
    // one — not a bound moved to fit.
    //
    // The reference is the SHIPPED token-by-token lane, so the number this prints is
    // directly comparable to §18d's table and to the mutation signatures at the same
    // lengths, rather than to an intermediate.
    //
    // CAMELID_METAL_F32Y=1 CAMELID_METAL_WIRE=1 CAMELID_METAL_WIRE_NSG8=1 \
    // CAMELID_GEMMA3_GGUF=<gguf> \
    //   cargo test --release --lib gemma3_real_row_prefill_attn_mm_kv -- --nocapture
    #[cfg(target_os = "macos")]
    #[test]
    fn gemma3_real_row_prefill_attn_mm_kv_meets_published_envelope() {
        use crate::kv_equivalence::compare;
        if !detect_metal_device().available {
            return;
        }
        let Some(path) = std::env::var_os("CAMELID_GEMMA3_GGUF") else {
            eprintln!(
                "SKIP gemma3_real_row_prefill_attn_mm_kv_meets_published_envelope: set \
                 CAMELID_GEMMA3_GGUF to the gemma-3-1b-it-Q8_0 GGUF"
            );
            return;
        };
        if !(f32y_gemv_enabled() && wire_weights_enabled() && wire_nsg8_enabled()) {
            eprintln!(
                "SKIP gemma3_real_row_prefill_attn_mm_kv_meets_published_envelope: the \
                 production GEMV gates (f32y/wire/NSG8) are not armed; arm them from the shell."
            );
            return;
        }
        let row = load_gemma3_real_row(&path.to_string_lossy());
        let weights = row.weights();
        let schedule = row.schedule();
        assert_eq!(row.head_dim, 256, "expected the 1B row's head_dim");

        let token_at = |i: usize| -> u32 { (2 + (i * 7919) % (row.vocab - 3)) as u32 };
        let mut worst_kv = 0.0f32;
        let mut worst_hidden = 0.0f32;
        let mut failures: Vec<String> = Vec::new();
        for &n in &[5usize, 256, 257, 513, 1024, 2400] {
            let mut embeddings: Vec<f32> = Vec::with_capacity(n * row.hidden);
            let mut cos_all: Vec<f32> = Vec::new();
            let mut sin_all: Vec<f32> = Vec::new();
            let mut alt_cos: Vec<f32> = Vec::new();
            let mut alt_sin: Vec<f32> = Vec::new();
            for t in 0..n {
                embeddings.extend_from_slice(&row.embed(token_at(t)));
                let (c, s) = crate::inference::gemma3_rope_tables(
                    t,
                    row.rope_dim,
                    row.g3.rope_freq_base_global,
                );
                cos_all.extend_from_slice(&c);
                sin_all.extend_from_slice(&s);
                let (c, s) = crate::inference::gemma3_rope_tables(
                    t,
                    row.rope_dim,
                    row.g3.rope_freq_base_local,
                );
                alt_cos.extend_from_slice(&c);
                alt_sin.extend_from_slice(&s);
            }
            let mk_session = || {
                ResidentDecodeState::new(
                    row.n_layers,
                    row.n_heads,
                    row.n_kv,
                    row.head_dim,
                    row.hidden,
                    row.ffn,
                    n,
                    n,
                    row.eps,
                    row.split_half_pairing,
                    Some(schedule.clone()),
                )
                .expect("resident session")
            };

            let mut token_session = mk_session();
            let mut token_hidden: Vec<f32> = Vec::with_capacity(n * row.hidden);
            let half = row.rope_dim / 2;
            for t in 0..n {
                match token_session
                    .forward_token(
                        &embeddings[t * row.hidden..(t + 1) * row.hidden],
                        &weights,
                        &cos_all[t * half..(t + 1) * half],
                        &sin_all[t * half..(t + 1) * half],
                        Some((
                            &alt_cos[t * half..(t + 1) * half],
                            &alt_sin[t * half..(t + 1) * half],
                        )),
                        t,
                        row.scale,
                        None,
                        None,
                        0,
                        None,
                        None,
                    )
                    .expect("resident forward")
                {
                    ResidentTokenOut::Data(v) => token_hidden.extend_from_slice(&v),
                    ResidentTokenOut::Sampled(_) => panic!("unexpected sampled output"),
                }
            }
            assert_eq!(token_session.filled(), n);

            let prefill = |attn: PrefillAttn| {
                let mut s = mk_session();
                let hidden = s
                    .prefill_tokens_windowed_hidden(
                        &embeddings,
                        n,
                        &weights,
                        &cos_all,
                        &sin_all,
                        Some((&alt_cos, &alt_sin)),
                        row.scale,
                        256,
                        PrefillGemm::ForceMm,
                        attn,
                    )
                    .expect("the batched prefill must be admitted for the real row");
                assert_eq!(
                    s.filled(),
                    n,
                    "n={n}: batched prefill must leave filled == n (G11)"
                );
                (s.kv_snapshot(n), hidden)
            };
            // Phase 3's path (per-row attention) and Phase 4's, over the same prompt.
            let (row_snapshot, _) = prefill(PrefillAttn::ForceRow);
            let (mm_snapshot, mm_hidden) = prefill(PrefillAttn::ForceMm);
            // NOT a pass by vacuity, and this is the assertion that catches a silent
            // admission failure: if `use_attn_mm` had declined, Phase 4 would have run
            // Phase 3's encode and these two would be bit-identical.
            assert!(
                !compare(&row_snapshot, &mm_snapshot)
                    .expect("same geometry")
                    .bit_identical,
                "n={n}: batched attention came out bit-identical to the per-row path — \
                 admission must have declined, so this gate proved nothing"
            );

            let token_snapshot = token_session.kv_snapshot(n);
            let amax = |xs: &[f32]| xs.iter().fold(0.0f32, |m, x| m.max(x.abs()));
            let kv_scale = token_snapshot
                .k
                .iter()
                .chain(&token_snapshot.v)
                .fold(0.0f32, |m, b| m.max(amax(b)));
            let hidden_scale = amax(&token_hidden);
            let eq = compare(
                &token_snapshot
                    .clone()
                    .with_final_hidden(token_hidden.clone()),
                &mm_snapshot.clone().with_final_hidden(mm_hidden),
            )
            .expect("same geometry");
            let median = eq.median_position_max_abs();
            eprintln!(
                "[G6-attn] n={n}: {} outlier_ratio={:.1}x kv_scale={kv_scale:.3e} \
                 kv_rel={:.3e} hidden_scale={hidden_scale:.3e} hidden_rel={:.3e}",
                eq.summary(),
                if median > 0.0 {
                    eq.max_abs_diff / median
                } else {
                    f32::INFINITY
                },
                eq.max_abs_diff / kv_scale.max(f32::MIN_POSITIVE),
                eq.hidden_max_abs_diff / hidden_scale.max(f32::MIN_POSITIVE),
            );
            let eq_caches = compare(&token_snapshot, &mm_snapshot).expect("same geometry");
            let cache_bound = PHASE3_KV_REL_BOUND * kv_scale;
            if let Err(why) = eq_caches.meets_bound(cache_bound, PHASE3_KV_OUTLIER_FACTOR) {
                failures.push(format!(
                    "n={n}: cache envelope (bound {PHASE3_KV_REL_BOUND:.3e} x kv_scale \
                     {kv_scale:.4e} = {cache_bound:.4e}, outlier factor \
                     {PHASE3_KV_OUTLIER_FACTOR}) — {why}"
                ));
            }
            if eq.hidden_max_abs_diff > PHASE3_HIDDEN_REL_BOUND * hidden_scale {
                failures.push(format!(
                    "n={n}: max |final_hidden diff| {:.6e} exceeds {PHASE3_HIDDEN_REL_BOUND:.3e} \
                     x the reference hidden's own magnitude {hidden_scale:.6e} (= {:.6e})",
                    eq.hidden_max_abs_diff,
                    PHASE3_HIDDEN_REL_BOUND * hidden_scale
                ));
            }
            worst_kv = worst_kv.max(eq.max_abs_diff / kv_scale);
            worst_hidden = worst_hidden.max(eq.hidden_max_abs_diff / hidden_scale);
        }
        assert!(
            failures.is_empty(),
            "G6 (real row, Tier B): batched windowed attention misses the envelope \
             published in GEMMA3_METAL_CONDUCTOR.md §18b at {} of 6 lengths:\n  {}",
            failures.len(),
            failures.join("\n  ")
        );
        eprintln!(
            "[G6-attn] PASS at n = 5/256/257/513/1024/2400: worst cache RELATIVE diff \
             {worst_kv:.6e} (bound {PHASE3_KV_REL_BOUND:.3e}), worst hidden RELATIVE diff \
             {worst_hidden:.6e} (bound {PHASE3_HIDDEN_REL_BOUND:.3e}), outlier factor \
             {PHASE3_KV_OUTLIER_FACTOR}"
        );
    }

    // gemma3 long-prompt TTFT campaign, Phase 3 — the KERNEL-LEVEL measurement.
    //
    // Three prefill paths over the SAME prompt in ONE process, with the same warm weight
    // cache and the same pipelines: token-by-token (today's shipped lane, encode-ahead
    // armed), Phase 2's batched GEMV, and Phase 3's tiled MM. The env flag is a latched
    // OnceLock, which is exactly why `PrefillGemm` exists — a shell can only pick one.
    //
    // Reported per path: ms/token, and achieved GEMM throughput against this host's
    // measured ~3.4 TFLOPS Q8_0 wall (§15). The FLOP count is the model's, not the
    // kernel's: 2 x 26 836 992 MACs x 26 layers = 1.3955 GFLOP per token, which is what
    // an ideal GEMM would do. Attention, norms, RoPE and scatter are NOT in that number,
    // so the reported TFLOPS is a lower bound on GEMM efficiency and an honest
    // whole-path figure at the same time.
    //
    // CAMELID_METAL_F32Y=1 CAMELID_METAL_WIRE=1 CAMELID_METAL_WIRE_NSG8=1 \
    // CAMELID_GEMMA3_GGUF=/path/gemma-3-1b-it-Q8_0.gguf \
    //   cargo test --release --lib gemma3_real_row_prefill_gemm_probe -- --nocapture
    #[cfg(target_os = "macos")]
    #[test]
    fn gemma3_real_row_prefill_gemm_probe() {
        if !detect_metal_device().available {
            return;
        }
        let Some(path) = std::env::var_os("CAMELID_GEMMA3_GGUF") else {
            eprintln!(
                "SKIP gemma3_real_row_prefill_gemm_probe: set CAMELID_GEMMA3_GGUF to the \
                 gemma-3-1b-it-Q8_0 GGUF"
            );
            return;
        };
        if !(f32y_gemv_enabled() && wire_weights_enabled() && wire_nsg8_enabled()) {
            eprintln!(
                "SKIP gemma3_real_row_prefill_gemm_probe: the production GEMV gates \
                 (f32y/wire/NSG8) are not armed; arm them from the shell."
            );
            return;
        }
        let row = load_gemma3_real_row(&path.to_string_lossy());
        let weights = row.weights();
        let schedule = row.schedule();
        let n = 1200usize;
        let q_dim = row.n_heads * row.head_dim;
        let kv_dim = row.n_kv * row.head_dim;
        let macs_per_layer = row.hidden * q_dim
            + 2 * row.hidden * kv_dim
            + q_dim * row.hidden
            + 3 * row.hidden * row.ffn;
        let gflop_per_token = 2.0 * (macs_per_layer * row.n_layers) as f64 / 1.0e9;

        let token_at = |i: usize| -> u32 { (2 + (i * 7919) % (row.vocab - 3)) as u32 };
        let mut embeddings: Vec<f32> = Vec::with_capacity(n * row.hidden);
        let mut cos_all: Vec<f32> = Vec::new();
        let mut sin_all: Vec<f32> = Vec::new();
        let mut alt_cos: Vec<f32> = Vec::new();
        let mut alt_sin: Vec<f32> = Vec::new();
        for t in 0..n {
            embeddings.extend_from_slice(&row.embed(token_at(t)));
            let (c, s) =
                crate::inference::gemma3_rope_tables(t, row.rope_dim, row.g3.rope_freq_base_global);
            cos_all.extend_from_slice(&c);
            sin_all.extend_from_slice(&s);
            let (c, s) =
                crate::inference::gemma3_rope_tables(t, row.rope_dim, row.g3.rope_freq_base_local);
            alt_cos.extend_from_slice(&c);
            alt_sin.extend_from_slice(&s);
        }
        let mk_session = || {
            ResidentDecodeState::new(
                row.n_layers,
                row.n_heads,
                row.n_kv,
                row.head_dim,
                row.hidden,
                row.ffn,
                n,
                n,
                row.eps,
                row.split_half_pairing,
                Some(schedule.clone()),
            )
            .expect("resident session")
        };
        let half = row.rope_dim / 2;
        // Warm the weight cache and both GEMM pipelines, so no measured run carries the
        // upload or a PSO compile.
        for gemm in [PrefillGemm::ForceScalar, PrefillGemm::ForceMm] {
            let mut warm = mk_session();
            warm.prefill_tokens_windowed_gemm(
                &embeddings[..8 * row.hidden],
                8,
                &weights,
                &cos_all[..8 * half],
                &sin_all[..8 * half],
                Some((&alt_cos[..8 * half], &alt_sin[..8 * half])),
                row.scale,
                8,
                gemm,
                PrefillAttn::ForceRow,
            )
            .expect("warm-up");
        }

        let report = |label: &str, secs: f64| {
            let ms_per_token = secs * 1000.0 / n as f64;
            eprintln!(
                "[gemm-probe] {label:<24} {secs:7.3}s  {ms_per_token:7.3} ms/token  \
                 {:.3} TFLOPS  load {:.2}",
                gflop_per_token / 1.0e3 / (ms_per_token / 1000.0),
                loadavg_1m()
            );
        };

        for (label, gemm) in [
            ("batched gemv (Phase 2)", PrefillGemm::ForceScalar),
            ("batched mm (Phase 3)", PrefillGemm::ForceMm),
        ] {
            let mut session = mk_session();
            let started = std::time::Instant::now();
            session
                .prefill_tokens_windowed_gemm(
                    &embeddings,
                    n,
                    &weights,
                    &cos_all,
                    &sin_all,
                    Some((&alt_cos, &alt_sin)),
                    row.scale,
                    256,
                    gemm,
                    PrefillAttn::ForceRow,
                )
                .expect("batched windowed prefill");
            report(label, started.elapsed().as_secs_f64());
        }

        let mut token_session = mk_session();
        let started = std::time::Instant::now();
        for t in 0..n {
            token_session
                .forward_token(
                    &embeddings[t * row.hidden..(t + 1) * row.hidden],
                    &weights,
                    &cos_all[t * half..(t + 1) * half],
                    &sin_all[t * half..(t + 1) * half],
                    Some((
                        &alt_cos[t * half..(t + 1) * half],
                        &alt_sin[t * half..(t + 1) * half],
                    )),
                    t,
                    row.scale,
                    None,
                    None,
                    0,
                    None,
                    None,
                )
                .expect("resident forward");
        }
        report("token-by-token (today)", started.elapsed().as_secs_f64());
    }

    // gemma3 long-prompt TTFT campaign, Phase 4 — the KERNEL-LEVEL measurement, and the
    // campaign's stopping rule 5.
    //
    // Both attention paths over the SAME prompt in ONE process with the SAME warm weight
    // cache and the SAME GEMM (Phase 3's tiled MM pinned on both sides), so what is being
    // timed is attention and only attention. Stopping rule 5 requires the batched kernel
    // to beat Tier A's per-row attention by >= 3x on wall clock; this is the number that
    // decides it, and it is reported whether it clears the bar or not.
    //
    // Also printed, from the same tile arithmetic the kernel runs: how many 64x64 score
    // tiles the dispatch grid covers, how many the causal cull drops, and how many the
    // WINDOW cull drops. The window cull is the whole reason a windowed layer's per-query
    // cost is O(1) in prompt length rather than O(n), so it is counted rather than
    // asserted.
    //
    // CAMELID_METAL_F32Y=1 CAMELID_METAL_WIRE=1 CAMELID_METAL_WIRE_NSG8=1 \
    // CAMELID_GEMMA3_GGUF=<gguf> \
    //   cargo test --release --lib gemma3_real_row_prefill_attn_probe -- --nocapture
    #[cfg(target_os = "macos")]
    #[test]
    fn gemma3_real_row_prefill_attn_probe() {
        if !detect_metal_device().available {
            return;
        }
        let Some(path) = std::env::var_os("CAMELID_GEMMA3_GGUF") else {
            eprintln!(
                "SKIP gemma3_real_row_prefill_attn_probe: set CAMELID_GEMMA3_GGUF to the \
                 gemma-3-1b-it-Q8_0 GGUF"
            );
            return;
        };
        if !(f32y_gemv_enabled() && wire_weights_enabled() && wire_nsg8_enabled()) {
            eprintln!(
                "SKIP gemma3_real_row_prefill_attn_probe: the production GEMV gates \
                 (f32y/wire/NSG8) are not armed; arm them from the shell."
            );
            return;
        }
        let row = load_gemma3_real_row(&path.to_string_lossy());
        let weights = row.weights();
        let schedule = row.schedule();
        const CHUNK: usize = 256;
        let half = row.rope_dim / 2;

        // The dispatch grid's tile census, computed with the kernel's OWN predicates:
        // upper cull `r0 > t0 + q_offset + NR1 - 1`, window cull
        // `r0 + NR0 + window <= t0 + q_offset + 1`, both at NR0 = NR1 = ATTN_MM_TILE.
        let tile_census = |n: usize| -> (usize, usize, usize, usize) {
            let (mut total, mut causal, mut win, mut kept) = (0usize, 0, 0, 0);
            let mut base = 0usize;
            while base < n {
                let k = CHUNK.min(n - base);
                let n_pad = (base + k).next_multiple_of(ATTN_MM_TILE);
                for w in schedule.window.iter() {
                    let w = w.unwrap_or(0);
                    for ty in 0..k.div_ceil(ATTN_MM_TILE) {
                        let t0 = ty * ATTN_MM_TILE;
                        for tx in 0..n_pad / ATTN_MM_TILE {
                            let r0 = tx * ATTN_MM_TILE;
                            total += 1;
                            if r0 > t0 + base + ATTN_MM_TILE - 1 {
                                causal += 1;
                            } else if w != 0 && r0 + ATTN_MM_TILE + w <= t0 + base + 1 {
                                win += 1;
                            } else {
                                kept += 1;
                            }
                        }
                    }
                }
                base += k;
            }
            (total, causal, win, kept)
        };

        for &n in &[1200usize, 2400] {
            let token_at = |i: usize| -> u32 { (2 + (i * 7919) % (row.vocab - 3)) as u32 };
            let mut embeddings: Vec<f32> = Vec::with_capacity(n * row.hidden);
            let mut cos_all: Vec<f32> = Vec::new();
            let mut sin_all: Vec<f32> = Vec::new();
            let mut alt_cos: Vec<f32> = Vec::new();
            let mut alt_sin: Vec<f32> = Vec::new();
            for t in 0..n {
                embeddings.extend_from_slice(&row.embed(token_at(t)));
                let (c, s) = crate::inference::gemma3_rope_tables(
                    t,
                    row.rope_dim,
                    row.g3.rope_freq_base_global,
                );
                cos_all.extend_from_slice(&c);
                sin_all.extend_from_slice(&s);
                let (c, s) = crate::inference::gemma3_rope_tables(
                    t,
                    row.rope_dim,
                    row.g3.rope_freq_base_local,
                );
                alt_cos.extend_from_slice(&c);
                alt_sin.extend_from_slice(&s);
            }
            // The MODEL's attention work at this length: sum over layers and positions of
            // min(p+1, window) attended keys, x 2 matmuls x head_dim x n_heads x 2 flops.
            // Tiling makes the kernel do somewhat more than this, so a rate computed
            // against it is a LOWER bound on the kernel's efficiency.
            let attended: u64 = schedule
                .window
                .iter()
                .map(|w| {
                    (0..n)
                        .map(|p| match w {
                            Some(win) => (p + 1).min(*win) as u64,
                            None => (p + 1) as u64,
                        })
                        .sum::<u64>()
                })
                .sum();
            let gflop = 4.0 * attended as f64 * (row.head_dim * row.n_heads) as f64 / 1.0e9;
            let mk_session = || {
                ResidentDecodeState::new(
                    row.n_layers,
                    row.n_heads,
                    row.n_kv,
                    row.head_dim,
                    row.hidden,
                    row.ffn,
                    n,
                    n,
                    row.eps,
                    row.split_half_pairing,
                    Some(schedule.clone()),
                )
                .expect("resident session")
            };
            for attn in [PrefillAttn::ForceRow, PrefillAttn::ForceMm] {
                let mut warm = mk_session();
                warm.prefill_tokens_windowed_gemm(
                    &embeddings[..64 * row.hidden],
                    64,
                    &weights,
                    &cos_all[..64 * half],
                    &sin_all[..64 * half],
                    Some((&alt_cos[..64 * half], &alt_sin[..64 * half])),
                    row.scale,
                    64,
                    PrefillGemm::ForceMm,
                    attn,
                )
                .expect("warm-up");
            }
            let mut secs = [0.0f64; 2];
            for (i, attn) in [PrefillAttn::ForceRow, PrefillAttn::ForceMm]
                .into_iter()
                .enumerate()
            {
                let mut session = mk_session();
                let started = std::time::Instant::now();
                session
                    .prefill_tokens_windowed_gemm(
                        &embeddings,
                        n,
                        &weights,
                        &cos_all,
                        &sin_all,
                        Some((&alt_cos, &alt_sin)),
                        row.scale,
                        CHUNK,
                        PrefillGemm::ForceMm,
                        attn,
                    )
                    .expect("batched windowed prefill");
                secs[i] = started.elapsed().as_secs_f64();
            }
            let (total, causal, win, kept) = tile_census(n);
            eprintln!(
                "[attn-probe] n={n} per-row {:7.3}s ({:6.3} ms/token) | batched {:7.3}s \
                 ({:6.3} ms/token) | {:5.2}x | attention {:.2} GFLOP, batched-path \
                 {:.3} TFLOPS lower bound | load {:.2}",
                secs[0],
                secs[0] * 1000.0 / n as f64,
                secs[1],
                secs[1] * 1000.0 / n as f64,
                secs[0] / secs[1],
                gflop,
                gflop / 1.0e3 / secs[1],
                loadavg_1m()
            );
            eprintln!(
                "[attn-probe] n={n} score tiles: {total} in the grid, {causal} dropped by \
                 the causal cull, {win} dropped by the WINDOW cull ({:.1} % of the grid, \
                 {:.1} % of what causal alone would have kept), {kept} computed",
                100.0 * win as f64 / total as f64,
                100.0 * win as f64 / (win + kept) as f64,
            );
        }
    }

    // gemma3 long-prompt TTFT campaign, Phase 1 — THE MUTATION HARNESS (gate G7).
    //
    // The campaign's recon found that the existing windowed evidence has near-zero
    // power against window-edge errors, and that nothing downstream is trustworthy
    // until that is fixed. This is the fix's proof: the new pack
    // (qa/prompt-packs/gemma3-window-edge-pack-v1.json) is run on the REAL row
    // under the production schedule and under seven deliberate defects, and every
    // defect must be CAUGHT. A pack that passes under a broken mask is worthless.
    //
    // Two observables are scored per (item, mutant), because they have different
    // power and the campaign needs to know which:
    //   * TOKEN IDENTITY — the greedy continuation's ids. This is what the external
    //     oracle gate (G9) can see, and it is argmax-only: a perturbation smaller
    //     than the local top-2 gap is invisible to it.
    //   * KV EQUIVALENCE — src/kv_equivalence, over every layer's K/V at every
    //     prompt position plus the final hidden. No softmax sits between the defect
    //     and the observable, so this sees perturbations token identity cannot.
    //
    // The mutations are applied through ResidentLayerSchedule, NOT by editing the
    // window arithmetic, and that is deliberate: `window_start =
    // filled.saturating_sub(w)` means a schedule of w-1 IS "window_start off by +1
    // wherever the window is saturated", and w+1 IS the off-by-one the other way.
    // Expressing the defects as data makes the harness committable and repeatable
    // instead of a scratch build that has to be reverted.
    //
    // Run targeted, gates armed from the SHELL (they are process-latched — see the
    // Phase 2 gate test above):
    // CAMELID_METAL_F32Y=1 CAMELID_METAL_WIRE=1 CAMELID_METAL_WIRE_NSG8=1 \
    // CAMELID_GEMMA3_GGUF=/path/gemma-3-1b-it-Q8_0.gguf \
    // [CAMELID_GEMMA3_MUTATION_OUT=/path/receipt.json] \
    //   cargo test --release --lib gemma3_real_row_window_mutation -- --nocapture
    // (~25 min: 8 schedules x the pack's mutation subset, token-by-token.)
    #[cfg(target_os = "macos")]
    #[test]
    fn gemma3_real_row_window_mutation_harness() {
        use crate::kv_equivalence::compare;
        if !detect_metal_device().available {
            return;
        }
        let Some(path) = std::env::var_os("CAMELID_GEMMA3_GGUF") else {
            eprintln!(
                "SKIP gemma3_real_row_window_mutation_harness: set CAMELID_GEMMA3_GGUF to the \
                 gemma-3-1b-it-Q8_0 GGUF"
            );
            return;
        };
        if !(f32y_gemv_enabled() && wire_weights_enabled() && wire_nsg8_enabled()) {
            eprintln!(
                "SKIP gemma3_real_row_window_mutation_harness: the production GEMV gates \
                 (f32y/wire/NSG8) are not armed; arm them from the shell."
            );
            return;
        }
        let pack_path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("qa/prompt-packs/gemma3-window-edge-pack-v1.json");
        let pack: serde_json::Value =
            serde_json::from_str(&std::fs::read_to_string(&pack_path).expect("read pack"))
                .expect("parse pack");
        let subset: Vec<String> = pack["mutation_subset"]
            .as_array()
            .expect("mutation_subset")
            .iter()
            .map(|v| v.as_str().expect("id").to_string())
            .collect();
        let all_items = pack["items"].as_array().expect("items");
        let items: Vec<(String, Vec<u32>)> = subset
            .iter()
            .map(|id| {
                let item = all_items
                    .iter()
                    .find(|i| i["id"].as_str() == Some(id.as_str()))
                    .unwrap_or_else(|| panic!("pack item {id} missing"));
                let ids: Vec<u32> = item["prompt_token_ids"]
                    .as_array()
                    .unwrap_or_else(|| panic!("{id}: prompt_token_ids missing"))
                    .iter()
                    .map(|v| v.as_u64().expect("token id") as u32)
                    .collect();
                (id.clone(), ids)
            })
            .collect();

        let row = load_gemma3_real_row(&path.to_string_lossy());
        let weights = row.weights();
        let base_schedule = row.schedule();
        let n_layers = row.n_layers;
        assert_eq!(
            base_schedule.window.iter().filter(|w| w.is_some()).count(),
            22,
            "expected the 1B row's 22 sliding / 4 global cadence"
        );
        const GEN: usize = 12;

        // --- the mutants, as schedule perturbations of the production object ---
        let mut schedules: Vec<(&str, &str, ResidentLayerSchedule)> = Vec::new();
        schedules.push((
            "baseline",
            "the production schedule, straight from the GGUF metadata",
            base_schedule.clone(),
        ));
        schedules.push((
            "window_minus_one",
            "w-1 on every sliding layer == window_start off by +1 wherever the window is \
             saturated; drops the OLDEST in-window position",
            ResidentLayerSchedule {
                use_alt_rope: base_schedule.use_alt_rope.clone(),
                window: base_schedule
                    .window
                    .iter()
                    .map(|w| w.map(|v| v - 1))
                    .collect(),
            },
        ));
        schedules.push((
            "window_plus_one",
            "w+1 == window_start off by -1; admits the FIRST out-of-window position",
            ResidentLayerSchedule {
                use_alt_rope: base_schedule.use_alt_rope.clone(),
                window: base_schedule
                    .window
                    .iter()
                    .map(|w| w.map(|v| v + 1))
                    .collect(),
            },
        ));
        schedules.push((
            "no_lower_bound",
            "the lower bound dropped entirely: full causal on all 26 layers — what every \
             batched causal mask in the tree does today, and what the CPU runnable lane does",
            ResidentLayerSchedule {
                use_alt_rope: base_schedule.use_alt_rope.clone(),
                window: vec![None; n_layers],
            },
        ));
        schedules.push((
            "window_on_all_layers",
            "the 4 global layers slide too",
            ResidentLayerSchedule {
                use_alt_rope: base_schedule.use_alt_rope.clone(),
                window: vec![Some(row.g3.sliding_window as usize); n_layers],
            },
        ));
        schedules.push((
            "window_on_wrong_layers",
            "the schedule inverted: the 4 globals slide and the 22 sliders go full causal",
            ResidentLayerSchedule {
                use_alt_rope: base_schedule.use_alt_rope.clone(),
                window: base_schedule
                    .window
                    .iter()
                    .map(|w| {
                        if w.is_some() {
                            None
                        } else {
                            Some(row.g3.sliding_window as usize)
                        }
                    })
                    .collect(),
            },
        ));
        schedules.push((
            "layer_pattern_shift_by_one",
            "the whole local/global cadence rotated one layer (globals at 6/12/18/24 instead of \
             5/11/17/23) — the shape a per-layer schedule indexing error takes in a batched loop",
            ResidentLayerSchedule {
                use_alt_rope: (0..n_layers)
                    .map(|l| base_schedule.use_alt_rope[(l + n_layers - 1) % n_layers])
                    .collect(),
                window: (0..n_layers)
                    .map(|l| base_schedule.window[(l + n_layers - 1) % n_layers])
                    .collect(),
            },
        ));
        schedules.push((
            "rope_tables_swapped",
            "ALT/primary RoPE table selection inverted; the window is untouched",
            ResidentLayerSchedule {
                use_alt_rope: base_schedule.use_alt_rope.iter().map(|b| !b).collect(),
                window: base_schedule.window.clone(),
            },
        ));

        // --- one (item, schedule) run: prefill + GEN greedy tokens + a KV snapshot ---
        let run = |schedule: &ResidentLayerSchedule,
                   prompt: &[u32]|
         -> (Vec<u32>, crate::kv_equivalence::KvSnapshot) {
            let n = prompt.len();
            let mut session = ResidentDecodeState::new(
                row.n_layers,
                row.n_heads,
                row.n_kv,
                row.head_dim,
                row.hidden,
                row.ffn,
                n + GEN + 1,
                n + GEN + 1,
                row.eps,
                row.split_half_pairing,
                Some(schedule.clone()),
            )
            .expect("resident session");
            let forward = |session: &mut ResidentDecodeState,
                           tok: u32,
                           pos: usize,
                           want_logits: bool|
             -> Option<Vec<f32>> {
                let (cos_g, sin_g) = crate::inference::gemma3_rope_tables(
                    pos,
                    row.rope_dim,
                    row.g3.rope_freq_base_global,
                );
                let (cos_l, sin_l) = crate::inference::gemma3_rope_tables(
                    pos,
                    row.rope_dim,
                    row.g3.rope_freq_base_local,
                );
                let stage = want_logits.then_some(LogitsStage {
                    final_norm: &row.output_norm,
                    output_weight_blocks: ResidentWeightBytes::Blocks36(&row.token_embd),
                    vocab_size: row.vocab,
                });
                match session
                    .forward_token(
                        &row.embed(tok),
                        &weights,
                        &cos_g,
                        &sin_g,
                        Some((&cos_l, &sin_l)),
                        pos,
                        row.scale,
                        stage,
                        None,
                        0,
                        None,
                        None,
                    )
                    .expect("resident forward")
                {
                    ResidentTokenOut::Data(v) => Some(v),
                    ResidentTokenOut::Sampled(_) => panic!("unexpected sampled output"),
                }
            };
            for (i, &tok) in prompt.iter().enumerate().take(n - 1) {
                forward(&mut session, tok, i, false);
            }
            let mut generated = Vec::with_capacity(GEN);
            let mut next = *prompt.last().expect("non-empty prompt");
            let mut snapshot = None;
            for (step, pos) in (n - 1..).take(GEN).enumerate() {
                let logits = forward(&mut session, next, pos, true).expect("logits");
                if step == 0 {
                    // Every prompt position is now written; snapshot BEFORE any
                    // generated token perturbs the cache, so the comparison covers
                    // the PREFILL state alone — exactly what a batched prefill
                    // produces. The snapshot's `final_hidden` slot carries the
                    // first-token LOGITS (all 262 144 of them): they are the
                    // downstream of the last layer's attention, which reaches no KV
                    // cache and would otherwise be unobservable.
                    snapshot = Some(session.kv_snapshot(n).with_final_hidden(logits.clone()));
                }
                let mut best = 0usize;
                let mut best_v = f32::NEG_INFINITY;
                for (i, &x) in logits.iter().enumerate() {
                    if x > best_v {
                        best_v = x;
                        best = i;
                    }
                }
                let tok = best as u32;
                generated.push(tok);
                // gemma3 EOG ids: <eos> = 1, <end_of_turn> = 106.
                if tok == 1 || tok == 106 {
                    break;
                }
                next = tok;
            }
            (generated, snapshot.expect("snapshot"))
        };

        // --- determinism positive control on the cheapest item ---
        let (control_id, control_prompt) = items
            .iter()
            .min_by_key(|(_, p)| p.len())
            .expect("non-empty subset");
        let (a_tokens, a_kv) = run(&base_schedule, control_prompt);
        let (b_tokens, b_kv) = run(&base_schedule, control_prompt);
        assert_eq!(
            a_tokens, b_tokens,
            "positive control {control_id}: two baseline runs must generate the same tokens"
        );
        compare(&a_kv, &b_kv)
            .expect("compare")
            .assert_bit_identical(&format!("positive control {control_id}"));
        eprintln!(
            "[mutation] positive control {control_id} ({} tok): two baseline runs bit-identical, \
             kv digest {}",
            control_prompt.len(),
            &a_kv.digest()[..16]
        );

        // --- the matrix ---
        let mut receipt_items = Vec::new();
        let mut caught_by_tokens: std::collections::BTreeMap<&str, Vec<String>> =
            std::collections::BTreeMap::new();
        let mut caught_by_kv: std::collections::BTreeMap<&str, Vec<String>> =
            std::collections::BTreeMap::new();
        for (id, prompt) in &items {
            let (base_tokens, base_kv) = run(&base_schedule, prompt);
            eprintln!(
                "\n[mutation] === {id} ({} prompt tokens) baseline {:?} kv {} ===",
                prompt.len(),
                base_tokens,
                &base_kv.digest()[..16]
            );
            let mut per_mutant = Vec::new();
            for (name, why, schedule) in schedules.iter().skip(1) {
                let (tokens, kv) = run(schedule, prompt);
                let v = compare(&base_kv, &kv).expect("compare");
                let token_caught = tokens != base_tokens;
                let kv_caught = !v.bit_identical;
                let first_divergence = base_tokens
                    .iter()
                    .zip(&tokens)
                    .position(|(a, b)| a != b)
                    .or_else(|| (tokens.len() != base_tokens.len()).then_some(base_tokens.len()));
                if token_caught {
                    caught_by_tokens.entry(name).or_default().push(id.clone());
                }
                if kv_caught {
                    caught_by_kv.entry(name).or_default().push(id.clone());
                }
                eprintln!(
                    "[mutation]   {:28} tokens {:6} kv {:6}  {}",
                    name,
                    if token_caught { "CAUGHT" } else { "missed" },
                    if kv_caught { "CAUGHT" } else { "MISSED" },
                    v.summary()
                );
                per_mutant.push(serde_json::json!({
                    "mutant": name,
                    "defect": why,
                    "token_identity_caught": token_caught,
                    "kv_equivalence_caught": kv_caught,
                    "first_token_divergence_index": first_divergence,
                    "generated_token_ids": tokens,
                    "kv_digest": kv.digest(),
                    "kv_differing_elements": v.differing_elements,
                    "kv_compared_elements": v.compared_elements(),
                    "kv_max_abs_diff": v.max_abs_diff,
                    "kv_median_position_max_abs": v.median_position_max_abs(),
                    "final_hidden_max_abs_diff": v.hidden_max_abs_diff,
                    "kv_first_difference": v.first_difference.map(|s| s.to_string()),
                }));
            }
            receipt_items.push(serde_json::json!({
                "item": id,
                "prompt_tokens": prompt.len(),
                "baseline_generated_token_ids": base_tokens,
                "baseline_kv_digest": base_kv.digest(),
                "mutants": per_mutant,
            }));
        }

        // --- the gate: every mutant must be caught by at least one item ---
        let mut survivors = Vec::new();
        for (name, _, _) in schedules.iter().skip(1) {
            let by_tokens = caught_by_tokens.get(name).map(Vec::len).unwrap_or(0);
            let by_kv = caught_by_kv.get(name).map(Vec::len).unwrap_or(0);
            eprintln!(
                "[mutation] {name:28} caught by tokens on {by_tokens}/{} items, by KV on \
                 {by_kv}/{} items",
                items.len(),
                items.len()
            );
            if by_tokens == 0 && by_kv == 0 {
                survivors.push(*name);
            }
        }
        let receipt = serde_json::json!({
            "schema": "camelid.gemma3.window_mutation_harness/v1",
            "pack": "qa/prompt-packs/gemma3-window-edge-pack-v1.json",
            "pack_id": pack["pack_id"],
            "row": "gemma_3_1b_it_q8_0",
            "lane": "metal_resident_token_by_token (ResidentDecodeState driven directly)",
            "generated_tokens_per_leg": GEN,
            "mutants": schedules.iter().skip(1).map(|(n, w, _)| serde_json::json!({"mutant": n, "defect": w})).collect::<Vec<_>>(),
            "caught_by_token_identity": caught_by_tokens,
            "caught_by_kv_equivalence": caught_by_kv,
            "survivors": survivors,
            "items": receipt_items,
        });
        if let Some(out) = std::env::var_os("CAMELID_GEMMA3_MUTATION_OUT") {
            std::fs::write(&out, serde_json::to_string_pretty(&receipt).expect("json"))
                .expect("write mutation receipt");
            eprintln!("[mutation] wrote {}", out.to_string_lossy());
        }
        assert!(
            survivors.is_empty(),
            "MUTANTS SURVIVED THE PACK: {survivors:?}. The pack is not a gate for these defects \
             and Tier B must not start until it is (campaign stopping rule 2)."
        );
        eprintln!(
            "\n[mutation] PASS: all {} mutants caught on the {}-item subset",
            schedules.len() - 1,
            items.len()
        );
    }

    // gemma3→Metal Phase 3a hazard H2 gate: the SESSION-level token-by-token
    // prefill. The Phase 2 final gate above drives ResidentDecodeState
    // directly; this test drives the production entry —
    // LlamaInferenceSession::generate_next_token_with_history_diagnostics —
    // over a MULTI-TOKEN prompt and requires the same token-identical greedy
    // continuation against the runnable oracle. What it proves is the ROUTING:
    // `session_prefill_chunk_tokens` forces the single-token lane for the
    // windowed arch, so every prompt token reaches
    // `try_resident_decode_forward` and the resident windowed forward (whose
    // correctness the Phase 2 gate already proves at depth 50) serves the
    // whole prompt and decode. Short depth deliberately: the forward is
    // proven, the routing is the claim.
    //
    // The production arch disqualifier stays up until Phase 3b; the cfg(test)
    // seam `TEST_ADMIT_WINDOWED_ARCH_RESIDENT` stands in for the flip for the
    // duration of this test only (drop guard restores fail-closed).
    //
    // Run targeted, gates armed from the SHELL (they are process-latched; see
    // the Phase 2 gate test comment above):
    // CAMELID_METAL_RESIDENT_DECODE=1 CAMELID_METAL_F32Y=1 \
    // CAMELID_METAL_WIRE=1 CAMELID_METAL_WIRE_NSG8=1 \
    // CAMELID_GEMMA3_GGUF=/path/gemma-3-1b-it-Q8_0.gguf \
    //   cargo test --release --lib gemma3_session_level -- --nocapture
    #[cfg(target_os = "macos")]
    #[test]
    fn gemma3_session_level_token_by_token_prefill_matches_runnable_oracle() {
        if !detect_metal_device().available {
            return;
        }
        let Some(path) = std::env::var_os("CAMELID_GEMMA3_GGUF") else {
            eprintln!(
                "SKIP gemma3_session_level_token_by_token_prefill_matches_runnable_oracle: \
                 set CAMELID_GEMMA3_GGUF to the gemma-3-1b-it-Q8_0 GGUF"
            );
            return;
        };
        if !(f32y_gemv_enabled() && wire_weights_enabled() && wire_nsg8_enabled()) {
            eprintln!(
                "SKIP gemma3_session_level_token_by_token_prefill_matches_runnable_oracle: \
                 the production GEMV gates (f32y/wire/NSG8) are not armed; arm them from the \
                 shell (never from inside a test — they are process-wide OnceLocks)"
            );
            return;
        }
        // The session-level resident decode gate reads its env live (not
        // latched), but the same shell discipline applies — require the caller
        // to arm it rather than mutating process env from a test.
        let resident_armed = std::env::var("CAMELID_METAL_RESIDENT_DECODE")
            .map(|v| {
                let v = v.trim().to_ascii_lowercase();
                matches!(v.as_str(), "1" | "true" | "on" | "enabled" | "yes")
            })
            .unwrap_or(false);
        if !resident_armed {
            eprintln!(
                "SKIP gemma3_session_level_token_by_token_prefill_matches_runnable_oracle: \
                 set CAMELID_METAL_RESIDENT_DECODE=1 (from the shell) to arm the session-level \
                 resident decode lane"
            );
            return;
        }

        use std::sync::atomic::Ordering;
        // Admit the windowed arch past the Phase 3b disqualifier for THIS test
        // only; the drop guard restores fail-closed even on panic.
        struct AdmitGuard;
        impl Drop for AdmitGuard {
            fn drop(&mut self) {
                crate::inference::TEST_ADMIT_WINDOWED_ARCH_RESIDENT.store(false, Ordering::SeqCst);
            }
        }
        crate::inference::TEST_ADMIT_WINDOWED_ARCH_RESIDENT.store(true, Ordering::SeqCst);
        let _admit = AdmitGuard;

        let path = path.to_string_lossy().to_string();
        let gguf = crate::gguf::read_metadata(&path).expect("gguf metadata");
        let config = crate::model::LlamaModelConfig::from_gguf(&gguf).expect("config");
        assert!(
            crate::model::arch_has_windowed_attention(&config),
            "the fixture must be a windowed arch"
        );
        let binding = crate::model::LlamaTensorBinding::bind(&gguf, &config).expect("binding");
        let store = crate::tensor::TensorStore::open(&path, &gguf);
        let weights =
            crate::inference::LlamaLoadedWeights::load(&store, &binding, None).expect("weights");
        let mut session =
            crate::inference::LlamaInferenceSession::new(config, weights).expect("session");

        eprintln!("[session-level] loading the runnable oracle");
        let oracle = crate::runnable::RunnableModel::load(&path).expect("runnable oracle");

        fn argmax(v: &[f32]) -> u32 {
            let mut best = 0usize;
            let mut best_v = f32::NEG_INFINITY;
            for (i, &x) in v.iter().enumerate() {
                if x > best_v {
                    best_v = x;
                    best = i;
                }
            }
            best as u32
        }

        let prompt: Vec<u32> = vec![2, 2364, 1077, 4056, 9062, 578, 6146, 236881];
        let gen_tokens = 5usize;
        let mut seq = prompt.clone();
        let mut max_abs_diff_overall = 0.0f32;
        for step in 0..gen_tokens {
            // Step 0 feeds the whole multi-token prompt through the session
            // entry (the H2 routing under test); later steps feed one token.
            let step_input: Vec<u32> = if step == 0 {
                prompt.clone()
            } else {
                vec![*seq.last().expect("non-empty")]
            };
            let out = session
                .generate_next_token_with_history_diagnostics(
                    &step_input,
                    crate::inference::LlamaSampler::Greedy,
                    &seq,
                    false,
                    None,
                )
                .expect("session step");
            let oracle_logits = oracle.forward_logits(&seq).expect("oracle forward");
            assert_eq!(out.logits.data.len(), oracle_logits.len());
            let o_tok = argmax(&oracle_logits);
            let mut max_diff = 0.0f32;
            for (a, b) in out.logits.data.iter().zip(&oracle_logits) {
                max_diff = max_diff.max((a - b).abs());
            }
            max_abs_diff_overall = max_abs_diff_overall.max(max_diff);
            let depth = step + 1;
            eprintln!(
                "[session-level] depth {depth}: argmax session={} oracle={o_tok}, \
                 max |logit diff| = {max_diff:.3e}",
                out.next_token_id
            );
            if out.next_token_id != o_tok {
                let gap = oracle_logits[o_tok as usize] - oracle_logits[out.next_token_id as usize];
                panic!(
                    "depth {depth}: argmax diverged (session {} vs oracle {o_tok}, \
                     oracle logit gap {gap:.6}, max |logit diff| {max_diff:.3e})",
                    out.next_token_id
                );
            }
            seq.push(o_tok);
        }
        // Routing proof, not just parity: the resident lane served the whole
        // prompt. A CPU dense prefill — chunked, layer-major, OR single-token —
        // materializes the CPU KV history as it goes; the resident lane leaves
        // it hollow (F32 primary, no mirror requested), so authority here means
        // some prompt token fell back to the window-less CPU forward.
        assert_eq!(session.kv_position(), prompt.len() + gen_tokens - 1);
        assert!(
            !session.cpu_kv_authoritative(),
            "the CPU KV must stay hollow: every prompt token must be served by the resident \
             lane, never the CPU dense prefill"
        );
        eprintln!(
            "[session-level] PASS: {gen_tokens}/{gen_tokens} greedy tokens identical to the \
             runnable oracle via the session-level token-by-token prefill; overall \
             max |logit diff| = {max_abs_diff_overall:.3e}"
        );
    }

    // gemma3→Metal merge gate H7 (recorded in GEMMA3_METAL_CONDUCTOR.md §9c).
    // The Phase 2e window self-parity fixture runs 10 tokens and the real-row
    // final gate asserts `total < 512`, so NEITHER exercises the sliding window
    // past the row's real 512-position boundary — the depth at which
    // `window_start` stops being a rounding detail and becomes the whole read
    // range. This pins a windowed decode at `filled` up to 600 bit-for-bit
    // against a full-causal oracle seeded with exactly the window's rows, so a
    // `kv_base_offset` pinned to 0 (or scaled in the wrong units) diverges
    // loudly instead of silently reading the OLDEST positions.
    //
    // The history is SEEDED, not decoded: `MetalLinearKernel` owns one shared
    // serial command queue, so a test that walks 600 tokens holds it for
    // hundreds of gated command buffers and starves every other Metal test in
    // the binary (observed: unrelated one-dispatch kernel tests returning their
    // untouched input). Two command buffers per checkpoint is the same proof at
    // 1/300th of the queue occupancy.
    //
    // head_dim 64 deliberately: it admits the v2/split-K decode-attention
    // geometry (head_dim % 32 == 0 && <= 128) that the gemma3-1B shape
    // (head_dim 256) can never reach, so the window base offset is proven on
    // the fast kernels too, not only on the v1 fallback the 1B row runs. That
    // also makes the Q8 primary KV reachable, where `kv_base_offset` is a BYTE
    // offset — `CAMELID_METAL_KV_DTYPE=q8 cargo test --lib
    // metal_resident_window_start_beyond_512` is the run that distinguishes
    // `window_start * kv_position_stride` from `window_start * head_dim`
    // (the format override is process-latched, so it cannot be set from here).
    // Sensitivity verified by temporarily breaking the packed word: pinning
    // byte 28 to 0 fails this test and the Phase 2e self-parity; using element
    // units fails this test under `CAMELID_METAL_KV_DTYPE=q8`. Green on all
    // three primaries (f32 default, q8, f16).
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_resident_window_start_beyond_512_matches_seeded_window_oracle() {
        if !detect_metal_device().available {
            return;
        }
        let n_heads = 4usize;
        let n_kv = 1usize;
        let head_dim = 64usize;
        let hidden = 256usize;
        let ffn = 64usize;
        let window = 512usize; // the gemma3 row's real window
        let cap = 600usize;
        let eps = 1.0e-6f32;
        let scale = 1.0 / (head_dim as f32).sqrt();
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv * head_dim;
        let bpr_hidden = hidden / 32;
        let bpr_q = q_dim / 32;
        let bpr_ffn = ffn / 32;

        struct LW {
            attn_norm: Vec<f32>,
            ffn_norm: Vec<f32>,
            q_norm: Vec<f32>,
            k_norm: Vec<f32>,
            post_attn_norm: Vec<f32>,
            post_ffw_norm: Vec<f32>,
            q: Vec<u8>,
            k: Vec<u8>,
            v: Vec<u8>,
            o: Vec<u8>,
            gate: Vec<u8>,
            up: Vec<u8>,
            down: Vec<u8>,
        }
        let data = LW {
            attn_norm: (0..hidden).map(|i| 0.5 + (i as f32 % 3.0) * 0.1).collect(),
            ffn_norm: (0..hidden).map(|i| 0.4 + (i as f32 % 5.0) * 0.07).collect(),
            q_norm: (0..head_dim)
                .map(|i| 0.7 + (i as f32 % 11.0) * 0.02)
                .collect(),
            k_norm: (0..head_dim)
                .map(|i| 0.6 + (i as f32 % 7.0) * 0.03)
                .collect(),
            post_attn_norm: (0..hidden).map(|i| 0.9 + (i as f32 % 3.0) * 0.03).collect(),
            post_ffw_norm: (0..hidden)
                .map(|i| 0.95 + (i as f32 % 6.0) * 0.02)
                .collect(),
            q: mk_w36(q_dim, bpr_hidden, 1),
            k: mk_w36(kv_dim, bpr_hidden, 2),
            v: mk_w36(kv_dim, bpr_hidden, 3),
            o: mk_w36(hidden, bpr_q, 4),
            gate: mk_w36(ffn, bpr_hidden, 5),
            up: mk_w36(ffn, bpr_hidden, 6),
            down: mk_w36(hidden, bpr_ffn, 7),
        };
        let weights = vec![ResidentLayerWeights {
            attn_norm: &data.attn_norm,
            ffn_norm: &data.ffn_norm,
            q_norm: Some(&data.q_norm),
            k_norm: Some(&data.k_norm),
            post_attn_norm: Some(&data.post_attn_norm),
            post_ffw_norm: Some(&data.post_ffw_norm),
            ffn_geglu: false,
            q_weight_blocks: ResidentWeightBytes::Blocks36(&data.q),
            k_weight_blocks: ResidentWeightBytes::Blocks36(&data.k),
            v_weight_blocks: ResidentWeightBytes::Blocks36(&data.v),
            o_weight_blocks: ResidentWeightBytes::Blocks36(&data.o),
            gate_weight_blocks: ResidentWeightBytes::Blocks36(&data.gate),
            up_weight_blocks: ResidentWeightBytes::Blocks36(&data.up),
            down_weight_blocks: ResidentWeightBytes::Blocks36(&data.down),
        }];

        // Deterministic already-roped K / raw V history, indexed by ABSOLUTE
        // position so both sessions see byte-identical rows for the positions
        // they share.
        let hist = |from: usize, to: usize, salt: usize| -> Vec<f32> {
            let mut out = Vec::with_capacity((to - from) * kv_dim);
            for p in from..to {
                for d in 0..kv_dim {
                    out.push(((((p * 31 + d * 7 + salt) % 41) as f32) - 20.0) * 0.037);
                }
            }
            out
        };
        let run = |s: &mut ResidentDecodeState,
                   emb: &[f32],
                   cos: &[f32],
                   sin: &[f32],
                   pos: usize|
         -> Vec<f32> {
            match s
                .forward_token(
                    emb,
                    &weights,
                    cos,
                    sin,
                    Some((cos, sin)),
                    pos,
                    scale,
                    None,
                    None,
                    0,
                    None,
                    None,
                )
                .unwrap()
            {
                ResidentTokenOut::Data(v) => v,
                ResidentTokenOut::Sampled(_) => panic!("unexpected sampled output"),
            }
        };

        // 512 is the last unclipped depth; 513 is the first clipped one; 600
        // puts the window 88 positions off the base of the cache.
        let depths = [256usize, 512, 513, 561, 600];
        let mut clipped = 0usize;
        for filled in depths {
            let position = filled - 1; // the token being decoded
            let ws = filled.saturating_sub(window);
            let count = filled - ws;
            let seed = count - 1; // history rows inside the window
            let emb: Vec<f32> = (0..hidden)
                .map(|i| ((((i * 7 + filled * 13) % 23) as f32) - 11.0) * 0.13)
                .collect();
            let (cos_l, sin_l) = crate::inference::gemma3_rope_tables(position, head_dim, 1.0e4);

            // A: windowed layer, full history seeded, decoding at `position`.
            let mut a = ResidentDecodeState::new(
                1,
                n_heads,
                n_kv,
                head_dim,
                hidden,
                ffn,
                cap,
                cap,
                eps,
                true,
                Some(ResidentLayerSchedule {
                    use_alt_rope: vec![true],
                    window: vec![Some(window)],
                }),
            )
            .unwrap();
            assert!(
                a.seed_layer(0, &hist(0, position, 5), &hist(0, position, 9), position),
                "windowed seed at filled {filled}"
            );
            a.set_filled(position);

            // B: full causal, seeded with ONLY the window's rows [ws, position).
            let mut b = ResidentDecodeState::new(
                1, n_heads, n_kv, head_dim, hidden, ffn, window, window, eps, true, None,
            )
            .unwrap();
            assert!(
                b.seed_layer(
                    0,
                    &hist(ws, position, 5),
                    &hist(ws, position, 9),
                    position - ws
                ),
                "oracle seed at filled {filled}"
            );
            b.set_filled(seed);

            let got_a = run(&mut a, &emb, &cos_l, &sin_l, position);
            let got_b = run(&mut b, &emb, &cos_l, &sin_l, seed);
            for (i, (av, bv)) in got_a.iter().zip(&got_b).enumerate() {
                assert_eq!(
                    av.to_bits(),
                    bv.to_bits(),
                    "filled {filled} (window_start {ws}, position_count {count}) element {i}: \
                     the windowed decode must be BIT-identical to the seeded-window oracle \
                     ({av} vs {bv}) — kv_base_offset wrong"
                );
            }
            assert_eq!(a.filled(), filled);
            if ws > 0 {
                clipped += 1;
            }
        }
        // Non-vacuity: the point of this test is the clipped regime.
        assert!(
            clipped >= 3,
            "expected at least three depths past the window boundary, got {clipped}"
        );
        eprintln!(
            "[h7-window] windowed decode bit-identical to the seeded-window oracle at filled \
             {depths:?} (window {window}, max window_start {})",
            cap - window
        );
    }

    // gemma3→Metal merge gate MR2/H9 (recorded in GEMMA3_METAL_CONDUCTOR.md §9c). Appliance mode (2+ active
    // slots) sets `resident_encode_ahead_enabled = false`, which reaches the
    // engine as `next_rope: None` and suppresses the pre-encode pipeline
    // entirely. The merge nests the gemma3 dual-theta table build INSIDE that
    // gate, so the two configurations must be observationally identical — this
    // pins that claim on a gemma3-shaped session (dual theta + sliding window +
    // QK/sandwich norms) bit-for-bit, at every token.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_resident_gemma3_decode_is_identical_with_encode_ahead_off() {
        if !detect_metal_device().available {
            return;
        }
        let n_layers = 2usize;
        let n_heads = 4usize;
        let n_kv = 1usize;
        let head_dim = 256usize;
        let hidden = 1152usize;
        let ffn = 288usize;
        let tokens = 12usize;
        let window = 4usize;
        let eps = 1.0e-6f32;
        let scale = 1.0 / (head_dim as f32).sqrt();
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv * head_dim;
        let bpr_hidden = hidden / 32;
        let bpr_q = q_dim / 32;
        let bpr_ffn = ffn / 32;

        struct LW {
            attn_norm: Vec<f32>,
            ffn_norm: Vec<f32>,
            q_norm: Vec<f32>,
            k_norm: Vec<f32>,
            post_attn_norm: Vec<f32>,
            post_ffw_norm: Vec<f32>,
            q: Vec<u8>,
            k: Vec<u8>,
            v: Vec<u8>,
            o: Vec<u8>,
            gate: Vec<u8>,
            up: Vec<u8>,
            down: Vec<u8>,
        }
        let data: Vec<LW> = (0..n_layers)
            .map(|li| {
                let s = li * 100;
                LW {
                    attn_norm: (0..hidden)
                        .map(|i| 0.5 + ((i + li) as f32 % 3.0) * 0.1)
                        .collect(),
                    ffn_norm: (0..hidden)
                        .map(|i| 0.4 + ((i + li) as f32 % 5.0) * 0.07)
                        .collect(),
                    q_norm: (0..head_dim)
                        .map(|i| 0.7 + ((i + li) as f32 % 11.0) * 0.02)
                        .collect(),
                    k_norm: (0..head_dim)
                        .map(|i| 0.6 + ((i + li) as f32 % 7.0) * 0.03)
                        .collect(),
                    post_attn_norm: (0..hidden)
                        .map(|i| 0.9 + ((i + li) as f32 % 3.0) * 0.03)
                        .collect(),
                    post_ffw_norm: (0..hidden)
                        .map(|i| 0.95 + ((i + li) as f32 % 6.0) * 0.02)
                        .collect(),
                    q: mk_w36(q_dim, bpr_hidden, s + 1),
                    k: mk_w36(kv_dim, bpr_hidden, s + 2),
                    v: mk_w36(kv_dim, bpr_hidden, s + 3),
                    o: mk_w36(hidden, bpr_q, s + 4),
                    gate: mk_w36(ffn, bpr_hidden, s + 5),
                    up: mk_w36(ffn, bpr_hidden, s + 6),
                    down: mk_w36(hidden, bpr_ffn, s + 7),
                }
            })
            .collect();
        let weights: Vec<ResidentLayerWeights> = data
            .iter()
            .map(|d| ResidentLayerWeights {
                attn_norm: &d.attn_norm,
                ffn_norm: &d.ffn_norm,
                q_norm: Some(&d.q_norm),
                k_norm: Some(&d.k_norm),
                post_attn_norm: Some(&d.post_attn_norm),
                post_ffw_norm: Some(&d.post_ffw_norm),
                ffn_geglu: true,
                q_weight_blocks: ResidentWeightBytes::Blocks36(&d.q),
                k_weight_blocks: ResidentWeightBytes::Blocks36(&d.k),
                v_weight_blocks: ResidentWeightBytes::Blocks36(&d.v),
                o_weight_blocks: ResidentWeightBytes::Blocks36(&d.o),
                gate_weight_blocks: ResidentWeightBytes::Blocks36(&d.gate),
                up_weight_blocks: ResidentWeightBytes::Blocks36(&d.up),
                down_weight_blocks: ResidentWeightBytes::Blocks36(&d.down),
            })
            .collect();
        let schedule = ResidentLayerSchedule {
            use_alt_rope: vec![true, false],
            window: vec![Some(window), None],
        };
        let mk = || {
            ResidentDecodeState::new(
                n_layers,
                n_heads,
                n_kv,
                head_dim,
                hidden,
                ffn,
                tokens,
                tokens,
                eps,
                true,
                Some(schedule.clone()),
            )
            .unwrap()
        };
        let take = |out: Option<ResidentTokenOut>| -> Vec<f32> {
            match out.unwrap() {
                ResidentTokenOut::Data(v) => v,
                ResidentTokenOut::Sampled(_) => panic!("unexpected sampled output"),
            }
        };
        // The two sessions run SEQUENTIALLY, never interleaved: encode-ahead
        // leaves a committed-but-gated command buffer parked on the kernel's
        // ONE shared serial queue between iterations, so a second live session
        // would sit behind it (and so would every concurrently running Metal
        // test). Each session is also dropped before the next starts, which is
        // what releases a trailing pending graph.
        let sweep = |encode_ahead: bool| -> Vec<Vec<f32>> {
            let mut session = mk();
            let mut outs = Vec::with_capacity(tokens);
            for t in 0..tokens {
                let emb: Vec<f32> = (0..hidden)
                    .map(|i| ((((i * 11 + t * 17) % 29) as f32) - 14.0) * 0.11)
                    .collect();
                let (cos_g, sin_g) = crate::inference::gemma3_rope_tables(t, head_dim, 1.0e6);
                let (cos_l, sin_l) = crate::inference::gemma3_rope_tables(t, head_dim, 1.0e4);
                let (ncos_g, nsin_g) = crate::inference::gemma3_rope_tables(t + 1, head_dim, 1.0e6);
                let (ncos_l, nsin_l) = crate::inference::gemma3_rope_tables(t + 1, head_dim, 1.0e4);
                let (next_primary, next_alt) = if encode_ahead {
                    (
                        Some((ncos_g.as_slice(), nsin_g.as_slice())),
                        Some((ncos_l.as_slice(), nsin_l.as_slice())),
                    )
                } else {
                    (None, None)
                };
                outs.push(take(session.forward_token(
                    &emb,
                    &weights,
                    &cos_g,
                    &sin_g,
                    Some((&cos_l, &sin_l)),
                    t,
                    scale,
                    None,
                    None,
                    0,
                    next_primary,
                    next_alt,
                )));
            }
            assert_eq!(session.filled(), tokens);
            outs
        };
        let ahead = sweep(true);
        let inline = sweep(false);
        for (t, (a, b)) in ahead.iter().zip(&inline).enumerate() {
            for (i, (av, bv)) in a.iter().zip(b).enumerate() {
                assert_eq!(
                    av.to_bits(),
                    bv.to_bits(),
                    "token {t} element {i}: encode-ahead must not change the decode \
                     ({av} vs {bv})"
                );
            }
        }
        eprintln!(
            "[mr2] {tokens}/{tokens} gemma3 tokens bit-identical with encode-ahead on and off"
        );
    }

    // gemma3→Metal merge gate H6 (recorded in GEMMA3_METAL_CONDUCTOR.md §9c). `embed_row_gather_q8_wire` is
    // the ONLY gather that reads `embed_scale` at buffer(4); the K-quant
    // gathers declare buffers 0..3, so binding the scale there is legal and
    // silently inert. Part 1 proves the inertness on the device; part 2 pins
    // the host fail-closed that keeps a non-unit scale off those kernels.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_kquant_embed_gather_drops_embed_scale_so_gpu_sampling_fails_closed() {
        // Part 2 first: the guard is pure arithmetic and needs no device.
        let g3 = (1152.0f32).sqrt();
        for format in [
            ResidentWeightFormat::Q8_0,
            ResidentWeightFormat::Q4K,
            ResidentWeightFormat::Q6K,
        ] {
            assert!(
                gpu_sampling_tail_is_scale_safe(format, 1.0),
                "a unit scale is a no-op on every gather ({format:?})"
            );
        }
        assert!(
            gpu_sampling_tail_is_scale_safe(ResidentWeightFormat::Q8_0, g3),
            "the Q8_0 wire gather applies embed_scale"
        );
        assert!(
            !gpu_sampling_tail_is_scale_safe(ResidentWeightFormat::Q4K, g3),
            "a gemma3-style embed scale must refuse the Q4_K gather"
        );
        assert!(
            !gpu_sampling_tail_is_scale_safe(ResidentWeightFormat::Q6K, g3),
            "a gemma3-style embed scale must refuse the Q6_K gather"
        );

        if !detect_metal_device().available {
            return;
        }
        let k = metal_linear_kernel().expect("metal");
        let vocab = 4usize;
        let n_sb = 1usize; // one 256-weight super-block per row
        let hidden = n_sb * 256;
        // Deterministic non-degenerate Q4_K super-blocks: real d/dmin halves in
        // bytes 0..4, arbitrary but fixed scale/min and quant nibbles after.
        let mut blocks = vec![0u8; vocab * n_sb * 144];
        for (b, blk) in blocks.chunks_mut(144).enumerate() {
            blk[..2].copy_from_slice(&f32_to_f16_bits(0.05 + b as f32 * 0.003).to_le_bytes());
            blk[2..4].copy_from_slice(&f32_to_f16_bits(0.01 + b as f32 * 0.001).to_le_bytes());
            for (j, byte) in blk[4..].iter_mut().enumerate() {
                *byte = ((j * 37 + b * 11) % 251) as u8;
            }
        }
        let wb = k.device.new_buffer_with_data(
            blocks.as_ptr() as *const _,
            blocks.len() as u64,
            MTLResourceOptions::StorageModeShared,
        );
        let ib = k
            .device
            .new_buffer(4, MTLResourceOptions::StorageModeShared);
        unsafe { *(ib.contents() as *mut u32) = 2u32 };
        let ob = k
            .device
            .new_buffer((hidden * 4) as u64, MTLResourceOptions::StorageModeShared);
        let gather = |embed_scale: f32| -> Vec<f32> {
            let sc = k
                .device
                .new_buffer(8, MTLResourceOptions::StorageModeShared);
            unsafe {
                let p = sc.contents() as *mut u8;
                *(p as *mut u32) = n_sb as u32;
                *(p.add(4) as *mut f32) = embed_scale;
            }
            let cb = k.queue.new_command_buffer();
            let e = cb.new_compute_command_encoder();
            e.set_compute_pipeline_state(&k.embed_row_gather_q4k_pipeline);
            e.set_buffer(0, Some(&wb), 0);
            e.set_buffer(1, Some(&ib), 0);
            e.set_buffer(2, Some(&ob), 0);
            e.set_buffer(3, Some(&sc), 0);
            // Legal on a kernel that never declared it — this is the hazard.
            e.set_buffer(4, Some(&sc), 4);
            dispatch_1d(e, &k.embed_row_gather_q4k_pipeline, hidden);
            e.end_encoding();
            cb.commit();
            cb.wait_until_completed();
            let mut got = vec![0.0f32; hidden];
            read_buffer_f32(&ob, &mut got);
            got
        };
        let plain = gather(1.0);
        let scaled = gather(g3);
        assert!(
            plain.iter().any(|v| v.abs() > 1.0e-6),
            "fixture must produce a non-trivial row"
        );
        for (i, (a, b)) in scaled.iter().zip(&plain).enumerate() {
            assert_eq!(
                a.to_bits(),
                b.to_bits(),
                "element {i}: the Q4_K gather must be BIT-identical with and without a \
                 buffer(4) embed_scale ({a} vs {b}) — if this now differs the kernel gained \
                 the parameter and `gpu_sampling_tail_is_scale_safe` should be relaxed"
            );
        }
        eprintln!(
            "[h6] Q4_K gather ignores buffer(4) embed_scale; GPU sampling fails closed instead"
        );
    }

    /// WIN2METAL Phase 3 C2/C3 gate. `verify_batch` over `k` rows at positions
    /// `[base, base+k)` must be BIT-IDENTICAL — exact u32 `to_bits`, not epsilon — to `k`
    /// independent `forward_token` decodes seeded with the same KV history. The straddle
    /// windows cross the split-K routing boundaries: `base=126,k=6` (rows pc 127..132 — the
    /// first row takes the v2 f32-cache path, the rest the split-K f16-mirror path) and
    /// `base=510,k=6` (rows pc 511..516, deep split-K with a varying split count). Logits are
    /// compared by exact bits (an offset/stride bug that doesn't flip the argmax would slip
    /// past an argmax-only check); the argmax ids are asserted too.
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_spec_verify_bit_identical() {
        if !detect_metal_device().available {
            return;
        }
        // Production GEMV stack + tiled/split-K attention. These gates must be armed BY THE
        // CALLER, never with an in-test `set_var`: they are process-wide OnceLocks read by
        // every other Metal test in this binary, so setting them here latches whichever
        // siblings have not read them yet onto the wire path and NaNs them (the five measured
        // casualties are listed on metal_verify_gemv_batched_bit_identical).
        // Requiring ATTN2 + split-K as well keeps the straddle-126 / deep-510 windows on the
        // split-K verify kernels instead of silently falling to the v2 path. Unarmed this test
        // is a no-op — which is what a shared run already got, since a sibling latches the
        // gates first — and a green --all-targets does NOT exercise these byte-exact
        // assertions. The enforced proof lane is qa/speed/verify-gates.sh (--test-threads=1),
        // which exports the gates and runs each one in its own process.
        if !(f32y_gemv_enabled()
            && wire_weights_enabled()
            && wire_nsg8_enabled()
            && attn2_enabled()
            && splitk_attention_enabled())
        {
            eprintln!(
                "SKIP metal_spec_verify_bit_identical: the f32y/wire/nsg8/attn2/split-K gates are \
                 not armed. Run targeted: qa/speed/verify-gates.sh (or CAMELID_METAL_F32Y=1 \
                 CAMELID_METAL_WIRE=1 CAMELID_METAL_WIRE_NSG8=1 CAMELID_METAL_ATTN2=1 cargo test \
                 --release --lib metal_spec_verify_bit_identical -- --nocapture, leaving \
                 CAMELID_METAL_ATTN_SPLITK unset — split-K is default-on)"
            );
            return;
        }

        let n_layers = 2usize;
        let n_heads = 4usize;
        let n_kv = 2usize; // group = 2
        let head_dim = 32usize;
        let hidden = 128usize;
        let ffn = 256usize;
        let vocab = 256usize;
        let eps = 1.0e-5f32;
        let scale = 1.0 / (head_dim as f32).sqrt();
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv * head_dim;
        let half = head_dim / 2;
        let bpr_hidden = hidden / 32;
        let bpr_q = q_dim / 32;
        let bpr_ffn = ffn / 32;
        let mkw = |rows: usize, bpr: usize, seed: usize| {
            let mut w: Vec<u8> = Vec::new();
            for r in 0..rows {
                for b in 0..bpr {
                    let s = 0.05 + ((r * bpr + b + seed) as f32 % 7.0) * 0.01;
                    w.extend_from_slice(&s.to_le_bytes());
                    for l in 0..32 {
                        w.push((((r * 5 + b * 3 + l + seed) as i32 % 17) - 8) as i8 as u8);
                    }
                }
            }
            w
        };
        struct LW {
            attn_norm: Vec<f32>,
            ffn_norm: Vec<f32>,
            q: Vec<u8>,
            k: Vec<u8>,
            v: Vec<u8>,
            o: Vec<u8>,
            gate: Vec<u8>,
            up: Vec<u8>,
            down: Vec<u8>,
        }
        let data: Vec<LW> = (0..n_layers)
            .map(|li| {
                let s = li * 100;
                LW {
                    attn_norm: (0..hidden)
                        .map(|i| 0.5 + ((i + li) as f32 % 3.0) * 0.1)
                        .collect(),
                    ffn_norm: (0..hidden)
                        .map(|i| 0.4 + ((i + li) as f32 % 5.0) * 0.07)
                        .collect(),
                    q: mkw(q_dim, bpr_hidden, s + 1),
                    k: mkw(kv_dim, bpr_hidden, s + 2),
                    v: mkw(kv_dim, bpr_hidden, s + 3),
                    o: mkw(hidden, bpr_q, s + 4),
                    gate: mkw(ffn, bpr_hidden, s + 5),
                    up: mkw(ffn, bpr_hidden, s + 6),
                    down: mkw(hidden, bpr_ffn, s + 7),
                }
            })
            .collect();
        let weights: Vec<ResidentLayerWeights> = data
            .iter()
            .map(|d| ResidentLayerWeights {
                attn_norm: &d.attn_norm,
                ffn_norm: &d.ffn_norm,
                q_weight_blocks: ResidentWeightBytes::Blocks36(&d.q),
                k_weight_blocks: ResidentWeightBytes::Blocks36(&d.k),
                v_weight_blocks: ResidentWeightBytes::Blocks36(&d.v),
                o_weight_blocks: ResidentWeightBytes::Blocks36(&d.o),
                gate_weight_blocks: ResidentWeightBytes::Blocks36(&d.gate),
                up_weight_blocks: ResidentWeightBytes::Blocks36(&d.up),
                down_weight_blocks: ResidentWeightBytes::Blocks36(&d.down),
                q_norm: None,
                k_norm: None,
                post_attn_norm: None,
                post_ffw_norm: None,
                ffn_geglu: false,
            })
            .collect();
        // Output projection + final norm (the LogitsStage).
        let final_norm: Vec<f32> = (0..hidden)
            .map(|i| 0.45 + (i as f32 % 4.0) * 0.05)
            .collect();
        let out_w = mkw(vocab, bpr_hidden, 777);
        let make_stage = || LogitsStage {
            final_norm: &final_norm,
            output_weight_blocks: ResidentWeightBytes::Blocks36(&out_w),
            vocab_size: vocab,
        };

        // Deterministic synthetic K/V seeding the `base` history positions (identical for
        // both sessions). Layout per layer: [kv_head][base][head_dim].
        let synth_kv = |base: usize, layer: usize, is_v: bool| -> Vec<f32> {
            let mut out = vec![0.0f32; n_kv * base * head_dim];
            for h in 0..n_kv {
                for p in 0..base {
                    for d in 0..head_dim {
                        let idx = (h * base + p) * head_dim + d;
                        let t = (layer * 7 + h * 13 + p * 3 + d + usize::from(is_v) * 5) as f32;
                        out[idx] = ((t % 19.0) - 9.0) * 0.05;
                    }
                }
            }
            out
        };

        let run = |base: usize, k: usize| {
            let cap = base + k + 16;
            let max_positions = cap; // no growth: identical strides in both sessions
            let mut cos_all = vec![0.0f32; k * half];
            let mut sin_all = vec![0.0f32; k * half];
            let mut emb_all = vec![0.0f32; k * hidden];
            for i in 0..k {
                for p in 0..half {
                    let theta = 0.2 + ((base + i) as f32) * 0.05 + p as f32 * 0.1;
                    cos_all[i * half + p] = theta.cos();
                    sin_all[i * half + p] = theta.sin();
                }
                for j in 0..hidden {
                    emb_all[i * hidden + j] = (((i + j + base) as f32 % 11.0) - 5.0) * 0.2;
                }
            }

            let mk_session = || {
                let mut s = ResidentDecodeState::new(
                    n_layers,
                    n_heads,
                    n_kv,
                    head_dim,
                    hidden,
                    ffn,
                    max_positions,
                    cap,
                    eps,
                    false,
                    None,
                )
                .unwrap();
                for layer in 0..n_layers {
                    let ck = synth_kv(base, layer, false);
                    let cv = synth_kv(base, layer, true);
                    assert!(s.seed_layer(layer, &ck, &cv, base), "seed_layer");
                }
                s.set_filled(base);
                s
            };

            // Reference: k sequential forward_token decodes (logits path -> full per-row
            // logits + CPU argmax with the sampler's first-max tie-break).
            let mut ref_session = mk_session();
            let mut ref_logits: Vec<Vec<f32>> = Vec::with_capacity(k);
            for i in 0..k {
                let emb = &emb_all[i * hidden..(i + 1) * hidden];
                let cos_i = &cos_all[i * half..(i + 1) * half];
                let sin_i = &sin_all[i * half..(i + 1) * half];
                let out = ref_session
                    .forward_token(
                        emb,
                        &weights,
                        cos_i,
                        sin_i,
                        None,
                        base + i,
                        scale,
                        Some(make_stage()),
                        None,
                        0,
                        None,
                        None,
                    )
                    .expect("reference forward_token");
                match out {
                    ResidentTokenOut::Data(v) => {
                        assert_eq!(v.len(), vocab);
                        ref_logits.push(v);
                    }
                    ResidentTokenOut::Sampled(_) => panic!("unexpected sampled output"),
                }
            }
            let ref_argmax: Vec<u32> = ref_logits
                .iter()
                .map(|row| {
                    let mut best = f32::NEG_INFINITY;
                    let mut best_i = 0u32;
                    for (j, &v) in row.iter().enumerate() {
                        if v > best {
                            best = v;
                            best_i = j as u32;
                        }
                    }
                    best_i
                })
                .collect();

            // Candidate: verify_batch on the identically-seeded session.
            let mut cand_session = mk_session();
            let stage = make_stage();
            let (preds, cand_logits) = cand_session
                .verify_batch_logits(
                    &emb_all, &cos_all, &sin_all, &weights, &stage, base, k, scale,
                )
                .expect("verify_batch eligible");
            assert_eq!(preds.len(), k);
            assert_eq!(cand_logits.len(), k * vocab);

            // Hard gate: exact u32 bit identity for every row/element + argmax id equality.
            for i in 0..k {
                let pc = base + i + 1;
                for v in 0..vocab {
                    let a = cand_logits[i * vocab + v];
                    let b = ref_logits[i][v];
                    assert_eq!(
                        a.to_bits(),
                        b.to_bits(),
                        "base={base} k={k} row {i} (pc={pc}) vocab {v}: verify {a} ({:#010x}) \
                         != forward {b} ({:#010x})",
                        a.to_bits(),
                        b.to_bits(),
                    );
                }
                assert_eq!(
                    preds[i], ref_argmax[i],
                    "base={base} k={k} row {i} (pc={pc}): argmax verify {} != forward {}",
                    preds[i], ref_argmax[i]
                );
            }
            eprintln!(
                "metal_spec_verify_bit_identical: base={base} k={k} BIT-IDENTICAL \
                 (split_k_engaged={})",
                splitk_attention_enabled() && attn2_enabled()
            );
        };

        // C2: straddle the 128 split-K boundary (rows pc in [127..132]).
        run(126, 6);
        // C3: deep split-K (rows pc in [511..516], n_splits varies).
        run(510, 6);
    }

    /// WIN2METAL Phase 4 gate. The slot-indirected TREE verify path must reproduce the
    /// Phase-3 linear verify byte-for-byte on a single-branch tree (the ANCHOR), and on a
    /// genuinely branching tree the accepted-path KV after compaction must equal an
    /// independent linear `forward_token` decode of that path (byte-identical), with every
    /// emitted token == the reference greedy argmax (Parity-class A).
    ///
    /// Same synthetic 2-layer / 4-head / group-2 / head_dim-32 / vocab-256 model and seeded
    /// `base` history as `metal_spec_verify_bit_identical`. The LINEAR anchor straddles the
    /// split-K boundary at base 126 AND deep split-K at base 510 (both mandatory).
    #[cfg(target_os = "macos")]
    #[test]
    fn metal_tree_verify_bit_identical() {
        use crate::inference::spec_tree::TokenTree;
        if !detect_metal_device().available {
            return;
        }
        // Same contract as metal_spec_verify_bit_identical: the production GEMV + tiled/split-K
        // attention gates are armed BY THE CALLER, never with an in-test `set_var` (those gates
        // are process-wide OnceLocks; setting them here latches siblings onto the wire path and
        // NaNs them). Requiring split-K too keeps the linear-anchor straddle-126 / deep-510
        // windows on the split-K kernels. Unarmed this test is a no-op; the enforced proof lane
        // is qa/speed/verify-gates.sh (--test-threads=1).
        if !(f32y_gemv_enabled()
            && wire_weights_enabled()
            && wire_nsg8_enabled()
            && attn2_enabled()
            && splitk_attention_enabled())
        {
            eprintln!(
                "SKIP metal_tree_verify_bit_identical: the f32y/wire/nsg8/attn2/split-K gates are \
                 not armed. Run targeted: qa/speed/verify-gates.sh (or CAMELID_METAL_F32Y=1 \
                 CAMELID_METAL_WIRE=1 CAMELID_METAL_WIRE_NSG8=1 CAMELID_METAL_ATTN2=1 cargo test \
                 --release --lib metal_tree_verify_bit_identical -- --nocapture, leaving \
                 CAMELID_METAL_ATTN_SPLITK unset — split-K is default-on)"
            );
            return;
        }

        let n_layers = 2usize;
        let n_heads = 4usize;
        let n_kv = 2usize; // group = 2
        let head_dim = 32usize;
        let hidden = 128usize;
        let ffn = 256usize;
        let vocab = 256usize;
        let eps = 1.0e-5f32;
        let scale = 1.0 / (head_dim as f32).sqrt();
        let q_dim = n_heads * head_dim;
        let kv_dim = n_kv * head_dim;
        let half = head_dim / 2;
        let bpr_hidden = hidden / 32;
        let bpr_q = q_dim / 32;
        let bpr_ffn = ffn / 32;
        let mkw = |rows: usize, bpr: usize, seed: usize| {
            let mut w: Vec<u8> = Vec::new();
            for r in 0..rows {
                for b in 0..bpr {
                    let s = 0.05 + ((r * bpr + b + seed) as f32 % 7.0) * 0.01;
                    w.extend_from_slice(&s.to_le_bytes());
                    for l in 0..32 {
                        w.push((((r * 5 + b * 3 + l + seed) as i32 % 17) - 8) as i8 as u8);
                    }
                }
            }
            w
        };
        struct LW {
            attn_norm: Vec<f32>,
            ffn_norm: Vec<f32>,
            q: Vec<u8>,
            k: Vec<u8>,
            v: Vec<u8>,
            o: Vec<u8>,
            gate: Vec<u8>,
            up: Vec<u8>,
            down: Vec<u8>,
        }
        let data: Vec<LW> = (0..n_layers)
            .map(|li| {
                let s = li * 100;
                LW {
                    attn_norm: (0..hidden)
                        .map(|i| 0.5 + ((i + li) as f32 % 3.0) * 0.1)
                        .collect(),
                    ffn_norm: (0..hidden)
                        .map(|i| 0.4 + ((i + li) as f32 % 5.0) * 0.07)
                        .collect(),
                    q: mkw(q_dim, bpr_hidden, s + 1),
                    k: mkw(kv_dim, bpr_hidden, s + 2),
                    v: mkw(kv_dim, bpr_hidden, s + 3),
                    o: mkw(hidden, bpr_q, s + 4),
                    gate: mkw(ffn, bpr_hidden, s + 5),
                    up: mkw(ffn, bpr_hidden, s + 6),
                    down: mkw(hidden, bpr_ffn, s + 7),
                }
            })
            .collect();
        let weights: Vec<ResidentLayerWeights> = data
            .iter()
            .map(|d| ResidentLayerWeights {
                attn_norm: &d.attn_norm,
                ffn_norm: &d.ffn_norm,
                q_weight_blocks: ResidentWeightBytes::Blocks36(&d.q),
                k_weight_blocks: ResidentWeightBytes::Blocks36(&d.k),
                v_weight_blocks: ResidentWeightBytes::Blocks36(&d.v),
                o_weight_blocks: ResidentWeightBytes::Blocks36(&d.o),
                gate_weight_blocks: ResidentWeightBytes::Blocks36(&d.gate),
                up_weight_blocks: ResidentWeightBytes::Blocks36(&d.up),
                down_weight_blocks: ResidentWeightBytes::Blocks36(&d.down),
                q_norm: None,
                k_norm: None,
                post_attn_norm: None,
                post_ffw_norm: None,
                ffn_geglu: false,
            })
            .collect();
        let final_norm: Vec<f32> = (0..hidden)
            .map(|i| 0.45 + (i as f32 % 4.0) * 0.05)
            .collect();
        let out_w = mkw(vocab, bpr_hidden, 777);
        let make_stage = || LogitsStage {
            final_norm: &final_norm,
            output_weight_blocks: ResidentWeightBytes::Blocks36(&out_w),
            vocab_size: vocab,
        };
        let synth_kv = |base: usize, layer: usize, is_v: bool| -> Vec<f32> {
            let mut out = vec![0.0f32; n_kv * base * head_dim];
            for h in 0..n_kv {
                for p in 0..base {
                    for d in 0..head_dim {
                        let idx = (h * base + p) * head_dim + d;
                        let t = (layer * 7 + h * 13 + p * 3 + d + usize::from(is_v) * 5) as f32;
                        out[idx] = ((t % 19.0) - 9.0) * 0.05;
                    }
                }
            }
            out
        };
        // Absolute-position RoPE table entry and per-node embedding — shared by the tree pass
        // and the reference so node `x` at position `pos` is identical in both.
        let cos_at =
            |pos: usize, p: usize| -> f32 { (0.2 + (pos as f32) * 0.05 + p as f32 * 0.1).cos() };
        let sin_at =
            |pos: usize, p: usize| -> f32 { (0.2 + (pos as f32) * 0.05 + p as f32 * 0.1).sin() };
        let emb_of = |node: usize, j: usize| -> f32 { (((node + j) as f32 % 11.0) - 5.0) * 0.2 };

        // ---------- LINEAR ANCHOR: tree verify == linear verify, bit-for-bit ----------
        let linear_anchor = |base: usize| {
            let k = 6usize; // 6 nodes (anchor + 5 drafts) — straddles the split-K boundary
            let cap = base + k + 16;
            let max_positions = cap;
            // Per-row tables at position base+i (a linear tree has depth[i] == i).
            let mut cos_all = vec![0.0f32; k * half];
            let mut sin_all = vec![0.0f32; k * half];
            let mut emb_all = vec![0.0f32; k * hidden];
            for i in 0..k {
                for p in 0..half {
                    cos_all[i * half + p] = cos_at(base + i, p);
                    sin_all[i * half + p] = sin_at(base + i, p);
                }
                for j in 0..hidden {
                    emb_all[i * hidden + j] = emb_of(i, j);
                }
            }
            let mk_session = || {
                let mut s = ResidentDecodeState::new(
                    n_layers,
                    n_heads,
                    n_kv,
                    head_dim,
                    hidden,
                    ffn,
                    max_positions,
                    cap,
                    eps,
                    false,
                    None,
                )
                .unwrap();
                for layer in 0..n_layers {
                    let ck = synth_kv(base, layer, false);
                    let cv = synth_kv(base, layer, true);
                    assert!(s.seed_layer(layer, &ck, &cv, base), "seed_layer");
                }
                s.set_filled(base);
                s
            };

            // Reference: the proven Phase-3 linear verify.
            let mut lin_session = mk_session();
            let stage = make_stage();
            let (lin_preds, lin_logits) = lin_session
                .verify_batch_logits(
                    &emb_all, &cos_all, &sin_all, &weights, &stage, base, k, scale,
                )
                .expect("verify_batch eligible");

            // Candidate: the TREE verify on a single-branch (linear) tree. Token ids are
            // irrelevant to the forward pass (only the structure drives ancestor_bits /
            // node_kvslot), so any chain of k nodes works.
            let drafts: Vec<u32> = (1..k as u32).collect();
            let tree = TokenTree::linear(0, &drafts);
            assert_eq!(tree.nodes(), k);
            let node_kvslot = tree.node_kvslot(base);
            let (ancestor_bits, words) = tree.ancestor_bitset();
            let mut tree_session = mk_session();
            let stage = make_stage();
            let (tree_preds, tree_logits) = tree_session
                .verify_batch_tree_logits(
                    &emb_all,
                    &cos_all,
                    &sin_all,
                    &weights,
                    &stage,
                    &node_kvslot,
                    &ancestor_bits,
                    words,
                    base,
                    k,
                    scale,
                )
                .expect("verify_batch_tree eligible");

            assert_eq!(tree_preds.len(), k);
            assert_eq!(tree_logits.len(), k * vocab);
            for i in 0..k {
                let pc = base + i + 1;
                for v in 0..vocab {
                    let a = tree_logits[i * vocab + v];
                    let b = lin_logits[i * vocab + v];
                    assert_eq!(
                        a.to_bits(),
                        b.to_bits(),
                        "LINEAR base={base} node {i} (pc={pc}) vocab {v}: tree {a} ({:#010x}) != \
                         linear {b} ({:#010x})",
                        a.to_bits(),
                        b.to_bits(),
                    );
                }
                assert_eq!(
                    tree_preds[i], lin_preds[i],
                    "LINEAR base={base} node {i} (pc={pc}): argmax tree {} != linear {}",
                    tree_preds[i], lin_preds[i]
                );
            }
            eprintln!("metal_tree_verify_bit_identical: LINEAR base={base} k={k} BIT-IDENTICAL");
        };
        linear_anchor(126); // straddle the split-K boundary (pc 127..132)
        linear_anchor(510); // deep split-K (pc 511..516)

        // ---------- BRANCHING: compaction == linear decode + Parity-class A ----------
        // Tree (BFS):     0
        //                / \
        //               1   2
        //              /   / \
        //             3   4   5
        let branching = |base: usize| {
            let parent = [-1i32, 0, 0, 1, 2, 2];
            let depth = [0u16, 1, 1, 2, 2, 2];
            let n = 6usize;
            let cap = base + n + 16;
            let max_positions = cap;
            // Per-NODE tables at position base+depth[i]; per-node embeddings.
            let node_pos: Vec<usize> = (0..n).map(|i| base + depth[i] as usize).collect();
            let mut cos_all = vec![0.0f32; n * half];
            let mut sin_all = vec![0.0f32; n * half];
            let mut emb_node = vec![0.0f32; n * hidden];
            for i in 0..n {
                for p in 0..half {
                    cos_all[i * half + p] = cos_at(node_pos[i], p);
                    sin_all[i * half + p] = sin_at(node_pos[i], p);
                }
                for j in 0..hidden {
                    emb_node[i * hidden + j] = emb_of(i, j);
                }
            }
            let mk_session = || {
                let mut s = ResidentDecodeState::new(
                    n_layers,
                    n_heads,
                    n_kv,
                    head_dim,
                    hidden,
                    ffn,
                    max_positions,
                    cap,
                    eps,
                    false,
                    None,
                )
                .unwrap();
                for layer in 0..n_layers {
                    let ck = synth_kv(base, layer, false);
                    let cv = synth_kv(base, layer, true);
                    assert!(s.seed_layer(layer, &ck, &cv, base), "seed_layer");
                }
                s.set_filled(base);
                s
            };

            // Provisional tree (tokens set after we see `predicted`, to force a real branch).
            let provisional = TokenTree {
                tokens: vec![0, 0, 0, 0, 0, 0],
                parent: parent.to_vec(),
                depth: depth.to_vec(),
            };
            let node_kvslot = provisional.node_kvslot(base);
            let (ancestor_bits, words) = provisional.ancestor_bitset();

            let mut tree_session = mk_session();
            let stage = make_stage();
            let predicted = tree_session
                .verify_batch_tree(
                    &emb_node,
                    &cos_all,
                    &sin_all,
                    &weights,
                    &stage,
                    &node_kvslot,
                    &ancestor_bits,
                    words,
                    base,
                    n,
                    scale,
                )
                .expect("verify_batch_tree eligible");
            assert_eq!(predicted.len(), n);

            // Craft tokens so accept_longest_path follows the right branch 0 -> 2 -> 5 (a
            // genuine reorder: path[1]=2!=1 and path[2]=5!=2, so compaction does real work).
            // accept picks the FIRST child (index order) whose token == predicted[parent], so
            // make node 1 / node 4 mismatch and node 2 / node 5 match.
            let mut tokens = vec![7u32, 0, 0, 3, 0, 0];
            tokens[1] = (predicted[0] + 1) % vocab as u32; // sibling of node 2: must NOT match
            tokens[2] = predicted[0]; // accepted child of root
            tokens[4] = (predicted[2] + 1) % vocab as u32; // sibling of node 5: must NOT match
            tokens[5] = predicted[2]; // accepted child of node 2
            let tree = TokenTree {
                tokens,
                parent: parent.to_vec(),
                depth: depth.to_vec(),
            };
            let (emitted, leaf) = tree.accept_longest_path(&predicted);
            assert_eq!(leaf, 5, "branch should accept down to node 5");
            let path = tree.path_to(leaf);
            assert_eq!(path, vec![0, 2, 5], "accepted path");
            assert_eq!(
                emitted,
                vec![predicted[0], predicted[2], predicted[5]],
                "emitted == target argmax along the accepted path"
            );

            // Compact the accepted path into contiguous slots [base, base+3).
            tree_session
                .compact_tree_kv_path(&path, base)
                .expect("compact");

            // Independent reference: a fresh session that linearly decodes the path tokens
            // (nodes 0, 2, 5) at positions base, base+1, base+2.
            let mut ref_session = mk_session();
            let mut ref_argmax = vec![0u32; path.len()];
            for (r, &node) in path.iter().enumerate() {
                let pos = base + r; // == node_pos[node] since depth[node] == r
                let emb = &emb_node[node * hidden..(node + 1) * hidden];
                let cos_i = &cos_all[node * half..(node + 1) * half];
                let sin_i = &sin_all[node * half..(node + 1) * half];
                let out = ref_session
                    .forward_token(
                        emb,
                        &weights,
                        cos_i,
                        sin_i,
                        None,
                        pos,
                        scale,
                        Some(make_stage()),
                        None,
                        0,
                        None,
                        None,
                    )
                    .expect("reference forward_token");
                let v = match out {
                    ResidentTokenOut::Data(v) => v,
                    ResidentTokenOut::Sampled(_) => panic!("unexpected sampled output"),
                };
                assert_eq!(v.len(), vocab);
                let mut best = f32::NEG_INFINITY;
                let mut best_i = 0u32;
                for (j, &x) in v.iter().enumerate() {
                    if x > best {
                        best = x;
                        best_i = j as u32;
                    }
                }
                ref_argmax[r] = best_i;
            }

            // (a) Compacted accepted-path KV == the linear decode's KV, byte-for-byte, in both
            //     the f32 caches and the f16 mirrors.
            let read_row =
                |s: &ResidentDecodeState, kbuf: bool, f16: bool, l: usize, slot: usize| {
                    let mut k_out = vec![0u32; n_kv * head_dim];
                    unsafe {
                        if f16 {
                            let buf = if kbuf {
                                &s.cache_k16[l]
                            } else {
                                &s.cache_v16[l]
                            };
                            let p = buf.contents() as *const u16;
                            for h in 0..n_kv {
                                let off = (h * max_positions + slot) * head_dim;
                                for d in 0..head_dim {
                                    k_out[h * head_dim + d] = *p.add(off + d) as u32;
                                }
                            }
                        } else {
                            let buf = if kbuf { &s.cache_k[l] } else { &s.cache_v[l] };
                            let p = buf.contents() as *const f32;
                            for h in 0..n_kv {
                                let off = (h * max_positions + slot) * head_dim;
                                for d in 0..head_dim {
                                    k_out[h * head_dim + d] = (*p.add(off + d)).to_bits();
                                }
                            }
                        }
                    }
                    k_out
                };
            for l in 0..n_layers {
                for r in 0..path.len() {
                    let slot = base + r;
                    for kbuf in [true, false] {
                        for f16 in [false, true] {
                            let a = read_row(&tree_session, kbuf, f16, l, slot);
                            let b = read_row(&ref_session, kbuf, f16, l, slot);
                            assert_eq!(
                                a, b,
                                "BRANCH base={base} layer {l} slot {slot} (rank {r}) \
                                 kbuf={kbuf} f16={f16}: compacted KV != linear-decode KV"
                            );
                        }
                    }
                }
            }

            // (b) Parity-class A: the tree's argmax at each accepted node == the reference
            //     greedy argmax along the path.
            for (r, &node) in path.iter().enumerate() {
                assert_eq!(
                    predicted[node], ref_argmax[r],
                    "BRANCH base={base} class-A: tree predicted[node {node}] {} != reference \
                     argmax[rank {r}] {}",
                    predicted[node], ref_argmax[r]
                );
            }
            eprintln!(
                "metal_tree_verify_bit_identical: BRANCH base={base} path={path:?} \
                 compaction==linear-decode + class-A PASS"
            );
        };
        branching(126);
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn metal_argmax_greedy_matches_cpu_first_max() {
        if !detect_metal_device().available {
            return;
        }
        let k = metal_linear_kernel().expect("metal");
        // Shapes around the real vocab plus tie/edge cases; CPU reference is the
        // sampler's exact semantics: ascending scan, strict greater-than.
        let cases: Vec<Vec<f32>> = vec![
            (0..128256)
                .map(|i| ((i * 2654435761u64 as usize) % 9973) as f32 * 0.001)
                .collect(),
            vec![1.0, 5.0, 5.0, 3.0, 5.0], // tie -> lowest index (1)
            vec![7.0, 1.0, 2.0],           // max at 0
            vec![-3.0, -1.5, -2.0],        // all negative
            (0..1000)
                .map(|i| if i == 999 { 10.0 } else { 0.0 })
                .collect(), // max at end
            vec![42.0],                    // single element
        ];
        for logits in cases {
            let mut best_idx = 0usize;
            let mut best = f32::NEG_INFINITY;
            for (i, &v) in logits.iter().enumerate() {
                if v > best {
                    best = v;
                    best_idx = i;
                }
            }
            let lb = k.device.new_buffer_with_data(
                logits.as_ptr() as *const _,
                (logits.len() * 4) as u64,
                MTLResourceOptions::StorageModeShared,
            );
            let ib = k
                .device
                .new_buffer(4, MTLResourceOptions::StorageModeShared);
            let cb_scalar = k
                .device
                .new_buffer(4, MTLResourceOptions::StorageModeShared);
            unsafe { *(cb_scalar.contents() as *mut u32) = logits.len() as u32 };
            let cb = k.queue.new_command_buffer();
            let e = cb.new_compute_command_encoder();
            e.set_compute_pipeline_state(&k.argmax_f32_greedy_pipeline);
            e.set_buffer(0, Some(&lb), 0);
            e.set_buffer(1, Some(&ib), 0);
            e.set_buffer(2, Some(&cb_scalar), 0);
            e.dispatch_thread_groups(
                metal::MTLSize {
                    width: 1,
                    height: 1,
                    depth: 1,
                },
                metal::MTLSize {
                    width: 1024,
                    height: 1,
                    depth: 1,
                },
            );
            e.end_encoding();
            cb.commit();
            cb.wait_until_completed();
            let got = unsafe { *(ib.contents() as *const u32) };
            assert_eq!(got as usize, best_idx, "len {}", logits.len());
        }
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn metal_gumbel_sampler_matches_stateless_reference() {
        if !detect_metal_device().available {
            return;
        }
        let k = metal_linear_kernel().expect("metal");
        let logits = vec![0.0_f32; 4096];

        let reference = |seed: u64| {
            let mut best_uniform = f32::NEG_INFINITY;
            let mut best_idx = 0_u32;
            for idx in 0..logits.len() {
                let mut z =
                    seed.wrapping_add(0x9E37_79B9_7F4A_7C15u64.wrapping_mul(idx as u64 + 1));
                z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
                z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
                z ^= z >> 31;
                // Gumbel is monotonic in the uniform draw. Comparing the
                // exact 24-bit uniforms avoids any CPU/GPU log approximation
                // becoming part of this stateless-RNG and reduction test.
                let uniform = ((z >> 40) as u32) as f32;
                if uniform > best_uniform {
                    best_uniform = uniform;
                    best_idx = idx as u32;
                }
            }
            best_idx
        };

        let logits_buf = k.device.new_buffer_with_data(
            logits.as_ptr() as *const _,
            (logits.len() * 4) as u64,
            MTLResourceOptions::StorageModeShared,
        );
        let out_buf = k
            .device
            .new_buffer(4, MTLResourceOptions::StorageModeShared);
        let count_buf = k
            .device
            .new_buffer(4, MTLResourceOptions::StorageModeShared);
        let temperature_buf = k
            .device
            .new_buffer(4, MTLResourceOptions::StorageModeShared);
        let seed_buf = k
            .device
            .new_buffer(8, MTLResourceOptions::StorageModeShared);
        unsafe {
            *(count_buf.contents() as *mut u32) = logits.len() as u32;
            *(temperature_buf.contents() as *mut f32) = 1.0;
        }

        let mut sampled = Vec::new();
        for seed in [0_u64, 1, 7, 42, u32::MAX as u64, u64::MAX] {
            unsafe {
                *(seed_buf.contents() as *mut u64) = seed;
            }
            let cb = k.queue.new_command_buffer();
            let e = cb.new_compute_command_encoder();
            e.set_compute_pipeline_state(&k.sample_gumbel_f32_pipeline);
            e.set_buffer(0, Some(&logits_buf), 0);
            e.set_buffer(1, Some(&out_buf), 0);
            e.set_buffer(2, Some(&count_buf), 0);
            e.set_buffer(3, Some(&temperature_buf), 0);
            e.set_buffer(4, Some(&seed_buf), 0);
            e.dispatch_thread_groups(
                metal::MTLSize {
                    width: 1,
                    height: 1,
                    depth: 1,
                },
                metal::MTLSize {
                    width: 1024,
                    height: 1,
                    depth: 1,
                },
            );
            e.end_encoding();
            cb.commit();
            cb.wait_until_completed();
            let got = unsafe { *(out_buf.contents() as *const u32) };
            assert_eq!(got, reference(seed), "seed {seed}");
            sampled.push(got);
        }
        sampled.sort_unstable();
        sampled.dedup();
        assert!(
            sampled.len() > 1,
            "different seeds should not collapse to one sampled token"
        );
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn metal_embed_gather_matches_cpu_dequant() {
        if !detect_metal_device().available {
            return;
        }
        let k = metal_linear_kernel().expect("metal");
        let vocab = 7usize;
        let hidden = 96usize; // 3 blocks per row
        let bpr = hidden / 32;
        // Wire blocks: f16 scale + 32 i8 quants, 34 bytes per block.
        let mut wire = vec![0u8; vocab * bpr * 34];
        for (b, chunk) in wire.chunks_mut(34).enumerate() {
            let scale = f32_to_f16_bits(0.013 + b as f32 * 0.0007);
            chunk[..2].copy_from_slice(&scale.to_le_bytes());
            for (j, q) in chunk[2..].iter_mut().enumerate() {
                *q = (((b * 31 + j * 7) % 255) as i32 - 127) as i8 as u8;
            }
        }
        let token: u32 = 5;
        // CPU reference: f16 scale -> f32, times the i8 quant.
        let mut expected = vec![0.0f32; hidden];
        for blk in 0..bpr {
            let base = (token as usize * bpr + blk) * 34;
            let scale_bits = u16::from_le_bytes([wire[base], wire[base + 1]]);
            let scale = f32::from_bits({
                // same conversion the GPU's float(half) performs
                let h = scale_bits as u32;
                let sign = (h & 0x8000) << 16;
                let exp = (h >> 10) & 0x1f;
                let man = h & 0x3ff;
                if exp == 0 && man == 0 {
                    sign
                } else if exp == 0 {
                    let mut e = 127 - 15 + 1;
                    let mut m = man;
                    while m & 0x400 == 0 {
                        m <<= 1;
                        e -= 1;
                    }
                    sign | ((e as u32) << 23) | ((m & 0x3ff) << 13)
                } else {
                    sign | ((exp + 127 - 15) << 23) | (man << 13)
                }
            });
            for j in 0..32 {
                expected[blk * 32 + j] = (wire[base + 2 + j] as i8) as f32 * scale;
            }
        }
        let eb = k.device.new_buffer_with_data(
            wire.as_ptr() as *const _,
            wire.len() as u64,
            MTLResourceOptions::StorageModeShared,
        );
        let ib = k
            .device
            .new_buffer(4, MTLResourceOptions::StorageModeShared);
        unsafe { *(ib.contents() as *mut u32) = token };
        let ob = k
            .device
            .new_buffer((hidden * 4) as u64, MTLResourceOptions::StorageModeShared);
        let run_gather = |embed_scale: f32| -> Vec<f32> {
            let sc = k
                .device
                .new_buffer(8, MTLResourceOptions::StorageModeShared);
            unsafe {
                let p = sc.contents() as *mut u8;
                *(p as *mut u32) = bpr as u32;
                *(p.add(4) as *mut f32) = embed_scale;
            }
            let cb = k.queue.new_command_buffer();
            let e = cb.new_compute_command_encoder();
            e.set_compute_pipeline_state(&k.embed_row_gather_q8_wire_pipeline);
            e.set_buffer(0, Some(&eb), 0);
            e.set_buffer(1, Some(&ib), 0);
            e.set_buffer(2, Some(&ob), 0);
            e.set_buffer(3, Some(&sc), 0);
            e.set_buffer(4, Some(&sc), 4);
            dispatch_1d(e, &k.embed_row_gather_q8_wire_pipeline, hidden);
            e.end_encoding();
            cb.commit();
            cb.wait_until_completed();
            let mut got = vec![0.0f32; hidden];
            read_buffer_f32(&ob, &mut got);
            got
        };
        // embed_scale = 1.0 is exact (x * 1.0f): bit-identical to the plain
        // CPU dequant.
        assert_eq!(run_gather(1.0), expected);
        // gemma3 embed scale (sqrt(1152)): each element is dequant * scale.
        let g3 = (1152.0f32).sqrt();
        let got_scaled = run_gather(g3);
        for (i, (a, b)) in got_scaled.iter().zip(&expected).enumerate() {
            let want = b * g3;
            assert!(
                (a - want).abs() <= want.abs() * 1.0e-6 + 1.0e-6,
                "element {i}: {a} != {want}"
            );
        }
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn metal_quantized_matmul_resident_matches_two_step() {
        if !detect_metal_device().available {
            return;
        }
        // The resident quantize->matmul chain (one command buffer, GPU buffers passed
        // between kernels) must equal running the two standalone kernels separately
        // (each already parity-checked vs CPU). This validates resident buffer chaining.
        let input_width = 64usize; // 2 blocks
        let output_width = 5usize;
        let blocks_per_row = input_width / 32;
        let input: Vec<f32> = (0..input_width)
            .map(|i| ((i as f32 % 13.0) - 6.0) * 0.3)
            .collect();
        let mut weight_blocks: Vec<u8> = Vec::new();
        for r in 0..output_width {
            for b in 0..blocks_per_row {
                let scale = 0.1 + (r * blocks_per_row + b) as f32 * 0.02;
                weight_blocks.extend_from_slice(&scale.to_le_bytes());
                for l in 0..32 {
                    weight_blocks.push((((r * 7 + b * 3 + l) as i32 % 19) - 9) as i8 as u8);
                }
            }
        }
        let (scales, quants) = try_quantize_q8_0_f32(&input).expect("quantize");
        let mut expected = vec![0.0f32; output_width];
        assert!(try_q8_0_block_linear_row(
            &scales,
            &quants,
            &weight_blocks,
            output_width,
            blocks_per_row,
            &mut expected,
        ));
        let got = try_quantized_matmul_resident(&input, &weight_blocks, output_width)
            .expect("resident chain");
        for (a, b) in got.iter().zip(&expected) {
            assert!((a - b).abs() < 1.0e-4, "{a} != {b}");
        }
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn metal_quantize_q8_0_matches_reference() {
        if !detect_metal_device().available {
            return;
        }
        // Two blocks chosen so max|v|/127 is f16-exact (127 -> 1.0, 254 -> 2.0),
        // isolating the kernel's max/round/clamp logic from f16-rounding subtleties.
        let mut input = vec![0.0f32; 64];
        for (i, v) in input.iter_mut().enumerate().take(32) {
            *v = ((i as i32 % 9) - 4) as f32; // small ints
        }
        input[7] = 127.0; // sets block-0 max_abs to 127 -> scale 1.0
        for (i, v) in input.iter_mut().enumerate().skip(32) {
            *v = (((i as i32) % 5) * 2 - 4) as f32; // even ints
        }
        input[40] = 254.0; // block-1 max_abs 254 -> scale 2.0
                           // Reference
        let mut exp_scales = [0.0f32; 2];
        let mut exp_quants = [0i8; 64];
        for b in 0..2 {
            let blk = &input[b * 32..b * 32 + 32];
            let max_abs = blk.iter().fold(0.0f32, |m, v| m.max(v.abs()));
            let unrounded = max_abs / 127.0; // f16-exact here (1.0 / 2.0)
            exp_scales[b] = unrounded;
            let inv = if unrounded == 0.0 {
                0.0
            } else {
                1.0 / unrounded
            };
            for (i, v) in blk.iter().enumerate() {
                let q = (v * inv).round() as i32;
                exp_quants[b * 32 + i] = q.clamp(-127, 127) as i8;
            }
        }
        let (scales, quants) = try_quantize_q8_0_f32(&input).expect("metal quantize");
        for (a, b) in scales.iter().zip(&exp_scales) {
            assert!((a - b).abs() < 1.0e-6, "scale {a} != {b}");
        }
        assert_eq!(quants.as_slice(), &exp_quants[..], "quants mismatch");
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn metal_attention_decode_matches_reference() {
        if !detect_metal_device().available {
            return;
        }
        // MHA (n_kv_heads == n_heads), contiguous KV cache.
        let n_heads = 2usize;
        let head_dim = 4usize;
        let positions = 3usize;
        let scale = 1.0 / (head_dim as f32).sqrt();
        let query: Vec<f32> = (0..n_heads * head_dim)
            .map(|i| ((i as f32 % 5.0) - 2.0) * 0.3)
            .collect();
        let keys: Vec<f32> = (0..n_heads * positions * head_dim)
            .map(|i| ((i as f32 % 7.0) - 3.0) * 0.2)
            .collect();
        let values: Vec<f32> = (0..n_heads * positions * head_dim)
            .map(|i| ((i as f32 % 4.0) - 1.0) * 0.5)
            .collect();
        // Reference: per head, softmax(dot(q,k)*scale) then weighted V sum.
        let mut expected = vec![0.0f32; n_heads * head_dim];
        for h in 0..n_heads {
            let qb = h * head_dim;
            let kvb = h * positions * head_dim;
            let mut scores = vec![0.0f32; positions];
            for (p, score) in scores.iter_mut().enumerate() {
                let kb = kvb + p * head_dim;
                let mut s = 0.0;
                for d in 0..head_dim {
                    s += query[qb + d] * keys[kb + d];
                }
                *score = s * scale;
            }
            let m = scores.iter().copied().fold(f32::NEG_INFINITY, f32::max);
            let mut sum = 0.0;
            for s in scores.iter_mut() {
                *s = (*s - m).exp();
                sum += *s;
            }
            for (p, s) in scores.iter().enumerate() {
                let prob = s / sum;
                let vb = kvb + p * head_dim;
                for d in 0..head_dim {
                    expected[qb + d] += prob * values[vb + d];
                }
            }
        }
        let got = try_attention_decode_f32(
            &query, &keys, &values, n_heads, n_heads, head_dim, positions, scale,
        )
        .expect("metal attention");
        for (a, b) in got.iter().zip(&expected) {
            assert!((a - b).abs() < 1.0e-4, "{a} != {b}");
        }
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn metal_rope_rotate_matches_reference() {
        if !detect_metal_device().available {
            return;
        }
        let head_count = 4usize;
        let head_dim = 8usize;
        let half = head_dim / 2;
        let data: Vec<f32> = (0..head_count * head_dim)
            .map(|i| (i as f32 % 9.0) - 4.0)
            .collect();
        let cos_t: Vec<f32> = (0..half).map(|p| (0.3 + p as f32 * 0.2).cos()).collect();
        let sin_t: Vec<f32> = (0..half).map(|p| (0.3 + p as f32 * 0.2).sin()).collect();
        // Reference: adjacent even/odd forward rotation, same as apply_rope_to_row.
        let mut expected = data.clone();
        for head in 0..head_count {
            let hs = head * head_dim;
            for pair in 0..half {
                let d0 = hs + pair * 2;
                let d1 = d0 + 1;
                let (x0, x1) = (data[d0], data[d1]);
                expected[d0] = x0 * cos_t[pair] - x1 * sin_t[pair];
                expected[d1] = x0 * sin_t[pair] + x1 * cos_t[pair];
            }
        }
        let got = try_rope_rotate_f32(&data, &cos_t, &sin_t, head_count, head_dim, half, false)
            .expect("metal rope");
        for (a, b) in got.iter().zip(&expected) {
            assert!((a - b).abs() < 1.0e-4, "{a} != {b}");
        }
    }

